-- Everwake Clinic · the whole database in one paste (Supabase SQL editor).
-- Generated by database/tools/build_setup.sh — do not edit; edit database/migrations/ and run it again.

-- ================= 001_schema.sql =================

-- =====================================================================
-- Everwake Clinic · 001 · clinics, the team, and the shared helpers
--
-- One engine, every clinic. A clinic (one doctor, or a polyclinic with
-- many) is a row in `tenants`; every other table carries tenant_id. The
-- dashboard, the WhatsApp agent and the reports all read the same rows.
--
-- The patterns are Everwake Orders' (EVERWAKE-ORDERS/database): who is
-- calling (current_user_id), roles checked inside SECURITY DEFINER
-- functions (require_role), row level security from my_tenant_ids(),
-- an audit trail of every dashboard edit, and a revision number that
-- makes a saved change reach the agent on its very next message.
--
-- Roles in a clinic:
--   owner         everything (usually the doctor who owns the clinic)
--   manager       everything but the team
--   doctor        their patients' records, the schedule, prices and rules
--   nurse         the day, check-in, vitals, reading the records
--   receptionist  bookings, patients' contact details, the inbox — never
--                 the medical record
-- `clinical` on each member decides who reads medical records; it starts
-- from the role and the owner can change it.
-- =====================================================================

create schema if not exists clinic;
create extension if not exists btree_gist;

-- ---------------------------------------------------------------------
-- Clinics
-- ---------------------------------------------------------------------
create table clinic.tenants (
  id                 uuid primary key default gen_random_uuid(),
  slug               text not null unique check (slug ~ '^[a-z][a-z0-9_]{1,40}$'),
  name_ar            text not null default '',
  name_en            text not null default '',
  status             text not null default 'onboarding'
                     check (status in ('onboarding', 'live', 'suspended', 'cancelled')),
  plan               text not null default 'pilot',
  country            text not null default 'EG',
  timezone           text not null default 'Africa/Cairo',
  currency           text not null default 'EGP',
  currency_symbol_ar text not null default 'ج',
  default_language   text not null default 'ar' check (default_language in ('ar', 'en')),
  specialty          text not null default 'general',      -- the main one; doctors carry their own
  ref_prefix         text not null default 'CL' check (ref_prefix ~ '^[A-Z0-9]{1,6}$'),
  appt_seq           bigint not null default 1000,
  service_seq        int not null default 0,
  patient_seq        bigint not null default 1000,
  agent_enabled      boolean not null default true,
  current_pause_id   bigint,
  -- what the agent knows (Settings → Agent): about, contacts, insurance, persona
  profile            jsonb not null default '{}'::jsonb,
  -- how the clinic runs (booking rules, reminders, templates…), merged over default_settings()
  settings           jsonb not null default '{}'::jsonb,
  -- bumped by anything the agent reads; the catalogue snapshot rebuilds from it
  catalog_rev        bigint not null default 1,
  catalog_rev_txid   bigint,
  live_at            timestamptz,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);
comment on table clinic.tenants is 'One row per clinic or polyclinic.';

create table clinic.platform_admins (
  user_id    uuid primary key,
  email      text,
  created_at timestamptz not null default now()
);

create table clinic.tenant_members (
  tenant_id    uuid not null references clinic.tenants(id) on delete cascade,
  user_id      uuid not null,
  role         text not null default 'receptionist'
               check (role in ('owner', 'manager', 'doctor', 'nurse', 'receptionist')),
  clinical     boolean not null default false,   -- may read medical records
  doctor_id    uuid,                              -- the doctor this member is (002 adds the key)
  location_ids uuid[],                            -- null = every location
  phone        text,                              -- their own WhatsApp: staff commands to the agent
  display_name text,
  email        text,
  created_at   timestamptz not null default now(),
  primary key (tenant_id, user_id)
);
create index tenant_members_user_idx on clinic.tenant_members (user_id);
create index tenant_members_phone_idx on clinic.tenant_members (phone) where phone is not null;

create table clinic.tenant_invites (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references clinic.tenants(id) on delete cascade,
  email        text not null check (email = lower(email)),
  role         text not null default 'receptionist'
               check (role in ('owner', 'manager', 'doctor', 'nurse', 'receptionist')),
  clinical     boolean,
  doctor_id    uuid,
  location_ids uuid[],
  invited_by   uuid,
  created_at   timestamptz not null default now(),
  accepted_at  timestamptz,
  accepted_by  uuid,
  unique (tenant_id, email)
);

create table clinic.audit_log (
  id         bigint generated always as identity primary key,
  tenant_id  uuid references clinic.tenants(id) on delete cascade,
  user_id    uuid,
  action     text not null,
  entity     text,
  entity_id  text,
  detail     jsonb,
  created_at timestamptz not null default now()
);
create index audit_log_tenant_idx on clinic.audit_log (tenant_id, created_at desc);

-- ---------------------------------------------------------------------
-- Who is calling. PostgREST puts the JWT in request.jwt.claims; the n8n
-- engine connects as a database role and has no user (null).
-- ---------------------------------------------------------------------
create or replace function clinic.current_user_id()
returns uuid language sql stable as $$
  select nullif(coalesce(
           nullif(current_setting('request.jwt.claim.sub', true), ''),
           nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub'), '')::uuid
$$;

-- Arabic-aware matching key: the same rules as normalizeArabic() in the engine
create or replace function clinic.norm(t text)
returns text language sql immutable parallel safe as $$
  select btrim(regexp_replace(
           regexp_replace(
             translate(lower(coalesce(t, '')), 'أإآىةٱ٠١٢٣٤٥٦٧٨٩', 'ااايها0123456789'),
             '[ً-ٰٟـ]', '', 'g'),
           '[^a-z0-9ء-ي]+', ' ', 'g'))
$$;

create or replace function clinic.digits(t text)
returns text language sql immutable parallel safe as $$
  select regexp_replace(translate(coalesce(t, ''), '٠١٢٣٤٥٦٧٨٩', '0123456789'), '\D', '', 'g')
$$;

create or replace function clinic.fmt_money(n numeric)
returns text language sql immutable parallel safe as $$
  select case when n is null then null
              when n >= 1000 and n = round(n) then to_char(n, 'FM999,999,999')
              else trim_scale(round(n, 2))::text end
$$;

-- a phone number as WhatsApp writes it: 01xxxxxxxxx → 201xxxxxxxxx
create or replace function clinic.wa_phone(p text, p_country text default 'EG')
returns text language plpgsql immutable as $$
declare d text := clinic.digits(p);
begin
  if d like '00%' then d := substr(d, 3); end if;
  if coalesce(p_country, 'EG') = 'EG' then
    if d ~ '^01[0125][0-9]{8}$' then d := '2' || d;
    elsif d ~ '^1[0125][0-9]{8}$' then d := '20' || d;
    end if;
  end if;
  return case when length(d) between 8 and 15 then d end;
end $$;

create or replace function clinic.random_token()
returns text language sql volatile as $$
  select replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '')
$$;

create or replace function clinic.slugify(p text)
returns text language sql immutable as $$
  select left(regexp_replace(regexp_replace(regexp_replace(lower(coalesce(p, '')), '[^a-z0-9]+', '_', 'g'),
                                            '^_+|_+$', '', 'g'), '^([0-9])', 'c\1'), 40)
$$;

create or replace function clinic.currency_symbol(p_currency text)
returns text language sql immutable as $$
  select case upper(p_currency)
    when 'EGP' then 'ج' when 'SAR' then 'ر.س' when 'AED' then 'د.إ' when 'QAR' then 'ر.ق'
    when 'KWD' then 'د.ك' when 'USD' then '$' when 'EUR' then '€' else upper(p_currency) end
$$;

-- ---------------------------------------------------------------------
-- Defaults. Stored settings are merged over these, so a new clinic works
-- on day one and every value can be changed from the dashboard.
-- Template placeholders: {name} the person we write to · {for} whose
-- appointment ("حضرتك" or the patient's first name) · {when} the day and
-- time in words · {doctor} · {location} · {link} the manage page · …
-- ---------------------------------------------------------------------
create or replace function clinic.default_settings()
returns jsonb language sql immutable as $$
  select jsonb_build_object(
    'booking', jsonb_build_object(
      'lead_minutes', 60,          -- the soonest a patient can book from now
      'days_ahead', 45,            -- how far ahead
      'hold_minutes', 15,          -- a slot offered and chosen is kept this long while the patient confirms
      'new_patient_fields', jsonb_build_array('full_name', 'age'),
      'queue_minutes', 15,         -- the average visit, for the estimated time of a queue number
      'cancel_hours', 0),          -- the cancellation policy, in hours before (0 = any time)
    'reminders', jsonb_build_array(
      jsonb_build_object('key', 'day_before', 'kind', 'day_before', 'at', '19:00'),
      jsonb_build_object('key', 'hours_before', 'kind', 'hours_before', 'hours', 3)),
    'reminder_min_lead_minutes', 45,   -- a reminder closer than this to the visit is skipped
    'at_risk_after_minutes', 45,       -- unconfirmed this long after the last reminder → an alert
    'auto_no_show', true,
    'no_show_grace_minutes', 60,
    'delay', jsonb_build_object('reply_share', 0.4, 'reply_min_minutes', 10, 'reply_max_minutes', 90,
                                'before_start_minutes', 30),
    'emergency', jsonb_build_object('whatsapp_doctor', true, 'ambulance', '123'),
    'human_auto_release_minutes', 30,
    'phone_reply_takes_over', true,
    'auto_takeover_on_handoff', false,
    'aftercare_messages', true,
    'test_numbers', jsonb_build_array(),
    'allowed_links', jsonb_build_array(),
    'templates', jsonb_build_object(
      'reminder_day_before_ar', E'أهلاً {name} 👋 تذكير بميعاد {for} {when} مع {doctor} — {location}.\nلو تمام ابعت 1 ✅\nلو عايز تغيّر الميعاد ابعت 2\nولو هتلغي ابعت 3{link}',
      'reminder_day_before_en', E'Hi {name} 👋 A reminder of {for} appointment {when} with {doctor} — {location}.\nReply 1 to confirm ✅\nReply 2 to change the time\nReply 3 to cancel{link}',
      'reminder_hours_before_ar', E'أهلاً {name} 🌿 ميعاد {for} النهارده {when} مع {doctor} — {location}. مستنيينك.\nلو حصل أي ظرف ابعت 2 نغيّر الميعاد أو 3 للإلغاء{link}',
      'reminder_hours_before_en', E'Hi {name} 🌿 {for} appointment is today {when} with {doctor} — {location}. See you soon.\nIf something came up, reply 2 to change it or 3 to cancel{link}',
      'delay_notice_ar', E'أهلاً {name} 🙏 {doctor} هيتأخر النهارده حوالي {minutes} دقيقة، فميعاد {for} بقى {new_time} بدل {old_time}.\nيناسبك؟ ابعت:\n1 تمام ✅\n2 عايز ميعاد تاني\n3 إلغاء الحجز{link}',
      'delay_notice_en', E'Hi {name} 🙏 {doctor} is running about {minutes} minutes late today, so {for} appointment is now at {new_time} instead of {old_time}.\nDoes that work? Reply:\n1 OK ✅\n2 Another time\n3 Cancel{link}',
      'delay_followup_ar', E'{name}، محتاجين نتأكد بس 🙏 الميعاد الجديد {new_time} مناسب؟ ابعت 1 لو تمام، 2 لو عايز ميعاد تاني، أو 3 للإلغاء.',
      'delay_followup_en', E'{name}, just checking 🙏 does the new time {new_time} work? Reply 1 if OK, 2 for another time, or 3 to cancel.',
      'session_cancelled_ar', E'أهلاً {name} 🙏 بنعتذر جداً، {doctor} مش هيقدر يكشف {when}{reason}.\nنقدر نحجز لـ {for} أقرب ميعاد: {options}\nابعت رقم الميعاد اللي يناسبك أو قولنا يوم تاني.',
      'session_cancelled_en', E'Hi {name} 🙏 We are very sorry, {doctor} cannot see patients {when}{reason}.\nWe can book {for} the nearest time: {options}\nReply with the option that suits you, or tell us another day.',
      'booking_confirmed_ar', E'أهلاً {name} ✅ اتحجز لـ {for} {when} مع {doctor} — {location}. رقم الحجز {ref_no}.{prep}{link}',
      'booking_confirmed_en', E'Hi {name} ✅ {for} appointment is booked {when} with {doctor} — {location}. Booking number {ref_no}.{prep}{link}',
      'booking_moved_ar', E'أهلاً {name} 🗓️ ميعاد {for} مع {doctor} اتغيّر لـ {when}. لو مش مناسب ابعت 2 ونختار ميعاد تاني.{link}',
      'booking_moved_en', E'Hi {name} 🗓️ {for} appointment with {doctor} has moved to {when}. If that does not suit you, reply 2 and we will find another time.{link}',
      'booking_cancelled_by_clinic_ar', E'أهلاً {name} 🙏 بنعتذر، ميعاد {for} {when} مع {doctor} اتلغى{reason}. تحب نحجزلك ميعاد تاني؟',
      'booking_cancelled_by_clinic_en', E'Hi {name} 🙏 We are sorry, {for} appointment {when} with {doctor} was cancelled{reason}. Would you like another time?',
      'waitlist_offer_ar', E'أهلاً {name} 👋 فضي ميعاد أقرب مع {doctor}: {when}. تحب نحجزه لـ {for}؟ ابعت 1 للحجز.',
      'waitlist_offer_en', E'Hi {name} 👋 An earlier time opened up with {doctor}: {when}. Shall we book it for {for}? Reply 1 to book.',
      'aftercare_ar', E'ألف سلامة على {for} 🌿 دي تعليمات ما بعد {service}:\n{aftercare}\nلو في أي حاجة مقلقاك ابعتلنا هنا.',
      'aftercare_en', E'Get well soon 🌿 Here are the instructions after {service}:\n{aftercare}\nIf anything worries you, message us here.',
      'pause_apology_ar', 'أهلاً {name} 🙏 خط الحجز على الواتساب واقف شوية. أول ما يرجع هنبعتلك هنا على طول. لو الموضوع طارئ اتصل بالإسعاف 123 أو روح أقرب طوارئ.',
      'pause_apology_en', 'Hi {name} 🙏 Our WhatsApp booking line is paused for a little while. We will message you here as soon as it is back. If it is urgent, call an ambulance (123) or go to the nearest emergency room.',
      'resume_notice_ar', 'أهلاً {name} 👋 رجعنا نستقبل الحجوزات على الواتساب. ابعتلنا وإحنا معاك.',
      'resume_notice_en', 'Hi {name} 👋 We are back and taking bookings on WhatsApp. Just message us.'))
$$;

create or replace function clinic.default_profile()
returns jsonb language sql immutable as $$
  select jsonb_build_object(
    'agent_name', jsonb_build_object('ar', 'نور', 'en', 'Nour'),
    'agent_gender', 'female',
    'about_ar', '', 'about_en', '', 'tone', '',
    'insurance', jsonb_build_array(),
    'contacts', jsonb_build_object('phone', '', 'whatsapp', '', 'emergency', '', 'email', ''),
    'website', '', 'instagram', '', 'facebook', '', 'google_maps_url', '', 'google_review_url', '',
    'emergency_text_ar', 'لو الحالة طارئة متستناش الميعاد: اتصل بالإسعاف 123 أو روح أقرب طوارئ فوراً.',
    'emergency_text_en', 'If this is an emergency, do not wait for an appointment: call an ambulance (123) or go to the nearest emergency room now.')
$$;

create or replace function clinic.merged_settings(p_settings jsonb)
returns jsonb language sql immutable as $$
  select clinic.default_settings()
         || coalesce(p_settings, '{}'::jsonb)
         || jsonb_build_object(
              'templates', (clinic.default_settings() -> 'templates') || coalesce(p_settings -> 'templates', '{}'::jsonb),
              'booking', (clinic.default_settings() -> 'booking') || coalesce(p_settings -> 'booking', '{}'::jsonb),
              'delay', (clinic.default_settings() -> 'delay') || coalesce(p_settings -> 'delay', '{}'::jsonb),
              'emergency', (clinic.default_settings() -> 'emergency') || coalesce(p_settings -> 'emergency', '{}'::jsonb))
$$;

create or replace function clinic.merged_profile(p_profile jsonb)
returns jsonb language sql immutable as $$
  select clinic.default_profile()
         || coalesce(p_profile, '{}'::jsonb)
         || jsonb_build_object(
              'agent_name', (clinic.default_profile() -> 'agent_name') || coalesce(p_profile -> 'agent_name', '{}'::jsonb),
              'contacts', (clinic.default_profile() -> 'contacts') || coalesce(p_profile -> 'contacts', '{}'::jsonb))
$$;

-- {name} style placeholders; an empty value leaves no stray space behind
create or replace function clinic.render_template(tpl text, vars jsonb)
returns text language plpgsql immutable as $$
declare
  k text; v text; out text := coalesce(tpl, '');
begin
  for k, v in select key, value from jsonb_each_text(coalesce(vars, '{}'::jsonb)) loop
    out := replace(out, '{' || k || '}', coalesce(v, ''));
  end loop;
  out := regexp_replace(out, '\{[a-z_]+\}', '', 'g');
  out := regexp_replace(out, '[ \t]+([،,.!؟?])', '\1', 'g');
  out := regexp_replace(out, '[ \t]{2,}', ' ', 'g');
  return btrim(out);
end $$;

-- a first name for a greeting: the given name, never a long WhatsApp nickname
create or replace function clinic.first_name(full_name text, display_name text)
returns text language sql immutable as $$
  select coalesce(
    nullif(split_part(btrim(coalesce(full_name, '')), ' ', 1), ''),
    case when length(btrim(coalesce(display_name, ''))) between 2 and 20
              and btrim(display_name) ~ '^[ء-يA-Za-z ]+$'
         then split_part(btrim(display_name), ' ', 1) end,
    '')
$$;

-- ---------------------------------------------------------------------
-- Triggers
-- ---------------------------------------------------------------------
create or replace function clinic.touch_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end $$;

-- anything the agent reads changed → the clinic's revision goes up once per transaction
create or replace function clinic.bump_catalog_rev()
returns trigger language plpgsql security definer set search_path = clinic, pg_temp as $$
declare
  t uuid := case when tg_op = 'DELETE' then old.tenant_id else new.tenant_id end;
begin
  update clinic.tenants
     set catalog_rev = catalog_rev + 1, catalog_rev_txid = txid_current()
   where id = t and catalog_rev_txid is distinct from txid_current();
  return null;
end $$;

create or replace function clinic.tenants_before_update()
returns trigger language plpgsql as $$
begin
  if (new.profile, new.settings, new.name_ar, new.name_en, new.timezone, new.currency, new.currency_symbol_ar,
      new.default_language, new.status, new.specialty)
     is distinct from
     (old.profile, old.settings, old.name_ar, old.name_en, old.timezone, old.currency, old.currency_symbol_ar,
      old.default_language, old.status, old.specialty)
     and new.catalog_rev = old.catalog_rev then
    new.catalog_rev := old.catalog_rev + 1;
    new.catalog_rev_txid := txid_current();
  end if;
  new.updated_at := now();
  return new;
end $$;

create trigger tenants_before_update before update on clinic.tenants
  for each row execute function clinic.tenants_before_update();

-- who changed what, from the dashboard (the engine has no user and is not audited here)
create or replace function clinic.audit_change()
returns trigger language plpgsql security definer set search_path = clinic, pg_temp as $$
declare
  uid  uuid := clinic.current_user_id();
  diff jsonb;
  rid  text;
  tid  uuid;
  rowj jsonb := to_jsonb(case when tg_op = 'DELETE' then old else new end);
begin
  if uid is null then return null; end if;
  if tg_op = 'UPDATE' then
    select jsonb_object_agg(n.key, jsonb_build_array(to_jsonb(old) -> n.key, n.value))
      into diff
      from jsonb_each(to_jsonb(new)) n
     where n.key not in ('updated_at', 'catalog_rev', 'catalog_rev_txid', 'appt_seq', 'service_seq', 'patient_seq',
                         'api_key', 'cloud_access_token', 'webhook_token')
       and (to_jsonb(old) -> n.key) is distinct from n.value;
    if diff is null then return null; end if;
  else
    diff := rowj - 'api_key' - 'cloud_access_token' - 'webhook_token';
  end if;
  rid := coalesce(rowj ->> 'id', rowj ->> 'patient_id');
  tid := case when tg_table_name = 'tenants' then (rowj ->> 'id')::uuid else (rowj ->> 'tenant_id')::uuid end;
  insert into clinic.audit_log (tenant_id, user_id, action, entity, entity_id, detail)
  values (tid, uid, lower(tg_op), tg_table_name, rid, diff);
  return null;
end $$;

-- ---------------------------------------------------------------------
-- Who may do what
-- ---------------------------------------------------------------------
create or replace function clinic.is_platform_admin()
returns boolean language sql stable security definer set search_path = clinic, pg_temp as $$
  select exists (select 1 from clinic.platform_admins a where a.user_id = clinic.current_user_id())
$$;

create or replace function clinic.member_role(p_tenant uuid)
returns text language sql stable security definer set search_path = clinic, pg_temp as $$
  select case
    when clinic.current_user_id() is null then null
    when clinic.is_platform_admin() then 'owner'
    else (select m.role from clinic.tenant_members m
           where m.tenant_id = p_tenant and m.user_id = clinic.current_user_id())
  end
$$;

-- no JWT (the engine, scripts) = trusted 'system'; a user without the role is refused
create or replace function clinic.require_role(p_tenant uuid, p_roles text[])
returns text language plpgsql stable security definer set search_path = clinic, pg_temp as $$
declare r text;
begin
  if clinic.current_user_id() is null then
    return 'system';
  end if;
  r := clinic.member_role(p_tenant);
  if r is null or not (r = any(p_roles)) then
    raise exception 'not allowed for this clinic' using errcode = '42501';
  end if;
  return r;
end $$;

-- medical records: members marked clinical (and the engine)
create or replace function clinic.can_see_clinical(p_tenant uuid)
returns boolean language sql stable security definer set search_path = clinic, pg_temp as $$
  select clinic.current_user_id() is null
      or clinic.is_platform_admin()
      or exists (select 1 from clinic.tenant_members m
                  where m.tenant_id = p_tenant and m.user_id = clinic.current_user_id() and m.clinical)
$$;

create or replace function clinic.require_clinical(p_tenant uuid)
returns void language plpgsql stable security definer set search_path = clinic, pg_temp as $$
begin
  if not clinic.can_see_clinical(p_tenant) then
    raise exception 'medical records are for the clinical team' using errcode = '42501';
  end if;
end $$;

create or replace function clinic.my_tenant_ids()
returns uuid[] language sql stable security definer set search_path = clinic, pg_temp as $$
  select case
    when clinic.current_user_id() is null then '{}'::uuid[]
    when clinic.is_platform_admin() then coalesce((select array_agg(id) from clinic.tenants), '{}')
    else coalesce((select array_agg(tenant_id) from clinic.tenant_members where user_id = clinic.current_user_id()), '{}')
  end
$$;

-- who changes the set-up: owners, managers and doctors
create or replace function clinic.my_editor_tenant_ids()
returns uuid[] language sql stable security definer set search_path = clinic, pg_temp as $$
  select case
    when clinic.current_user_id() is null then '{}'::uuid[]
    when clinic.is_platform_admin() then coalesce((select array_agg(id) from clinic.tenants), '{}')
    else coalesce((select array_agg(tenant_id) from clinic.tenant_members
                    where user_id = clinic.current_user_id() and role in ('owner', 'manager', 'doctor')), '{}')
  end
$$;

create or replace function clinic.my_clinical_tenant_ids()
returns uuid[] language sql stable security definer set search_path = clinic, pg_temp as $$
  select case
    when clinic.current_user_id() is null then '{}'::uuid[]
    when clinic.is_platform_admin() then coalesce((select array_agg(id) from clinic.tenants), '{}')
    else coalesce((select array_agg(tenant_id) from clinic.tenant_members
                    where user_id = clinic.current_user_id() and clinical), '{}')
  end
$$;

create or replace function clinic.my_name(p_tenant uuid)
returns text language sql stable security definer set search_path = clinic, pg_temp as $$
  select coalesce(m.display_name, m.email) from clinic.tenant_members m
   where m.tenant_id = p_tenant and m.user_id = clinic.current_user_id()
$$;

-- ================= 002_practice.sql =================

-- =====================================================================
-- Everwake Clinic · 002 · the practice: doctors, places, schedules, and
-- the catalogue the agent answers from
--
--   doctors              each with a speciality, a follow-up window and
--                        their own WhatsApp for staff commands
--   locations            where they see patients (a doctor can work at
--                        several on different days)
--   resources            dental chairs, rooms, a laser: a service can
--                        need one, and booking takes the doctor and a
--                        free one together
--   schedules            doctor × location × weekday windows, each in
--                        `slots` (fixed times), `queue` (a number, الدور,
--                        with an estimated time) or `both`
--   schedule_exceptions  a day off, an extra session, changed hours
--
-- The catalogue (one per clinic, per doctor where it differs):
--   services             every visit type, test and procedure with its
--                        price shape (fixed · a range · from · after the
--                        check-up · free), the unit it is priced per
--                        (visit, tooth, canal, jaw, session, area…),
--                        sessions, preparation and aftercare, who does
--                        it, on which days, for which ages
--   service_prices       a price for one doctor and/or one location
--   offers               dated discounts and packages
--   knowledge_entries    FAQs and policies
--   agent_rules          the doctor's rules: some enforced in code
--                        (new patients until a time, children under an
--                        age only with a doctor), and a free-text note
--   catalog_changes      every change the AI (or the editor) made, with
--                        before and after, so it can be undone
--   catalog_snapshot     what the agent reads every turn, rebuilt when
--                        catalog_rev moves (save → the next message knows)
-- =====================================================================

-- ---------------------------------------------------------------------
-- Specialities: shipped presets (020 fills them). Global, not per clinic.
-- ---------------------------------------------------------------------
create table clinic.specialty_presets (
  code             text primary key check (code ~ '^[a-z_]{2,30}$'),
  name_ar          text not null,
  name_en          text not null,
  group_name       text not null default 'medical',
  keywords         text[] not null default '{}',       -- how patients describe a problem for this speciality
  starter_services jsonb not null default '[]'::jsonb,  -- [{name_ar,name_en,category,duration,price_kind,unit,sessions,session_gap_days,aliases[],aftercare_ar,resource_kind}]
  form_template    jsonb not null default '{}'::jsonb,  -- {sections:[{key,title_ar,title_en,fields:[{key,label_ar,label_en,type,unit,options[]}]}]}
  triage           jsonb not null default '[]'::jsonb,  -- [{level:'emergency'|'urgent', words:[…], why}]
  pre_visit        jsonb not null default '[]'::jsonb,  -- [{key, ask_ar, ask_en, on_file?, sex?}] asked after booking, skipped when known
  is_custom        boolean not null default false,
  sort             int not null default 100
);

-- ---------------------------------------------------------------------
-- Doctors and places
-- ---------------------------------------------------------------------
create table clinic.doctors (
  id               uuid primary key default gen_random_uuid(),
  tenant_id        uuid not null references clinic.tenants(id) on delete cascade,
  code             text not null check (code ~ '^D[0-9]{1,3}$'),
  user_id          uuid,                       -- their dashboard login, when they have one
  name_ar          text not null,
  name_en          text,
  title_ar         text not null default 'د.',
  title_en         text not null default 'Dr.',
  gender           text check (gender in ('male', 'female')),
  specialty        text not null default 'general',
  sub_specialty_ar text,
  sub_specialty_en text,
  bio_ar           text,
  bio_en           text,
  photo_url        text,
  languages        text[] not null default '{ar}',
  color            text,                        -- their tint in the calendar
  ops_whatsapp     text,                        -- their own number: emergencies and staff commands
  follow_up_days   int not null default 14,     -- a visit within this many days of the last is a follow-up
  accepts_new      boolean not null default true,
  is_active        boolean not null default true,
  sort             int not null default 0,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (tenant_id, code)
);
create index doctors_tenant_idx on clinic.doctors (tenant_id, is_active);

alter table clinic.tenant_members
  add constraint tenant_members_doctor_fk foreign key (doctor_id) references clinic.doctors(id) on delete set null;

create table clinic.locations (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references clinic.tenants(id) on delete cascade,
  code          text not null check (code ~ '^[a-z0-9_]{2,30}$'),
  name_ar       text not null,
  name_en       text,
  aliases       text[] not null default '{}',
  area_ar       text,
  address_ar    text,
  address_en    text,
  directions_ar text,                 -- "الدور التالت فوق صيدلية…"
  lat           double precision,
  lng           double precision,
  maps_url      text,
  phone         text,
  ops_whatsapp  text,
  is_active     boolean not null default true,
  sort          int not null default 0,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  unique (tenant_id, code)
);

create table clinic.resources (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references clinic.tenants(id) on delete cascade,
  location_id uuid not null references clinic.locations(id) on delete cascade,
  kind        text not null default 'chair' check (kind ~ '^[a-z_]{2,20}$'),   -- chair · room · laser · bed …
  name_ar     text not null,
  name_en     text,
  is_active   boolean not null default true,
  sort        int not null default 0,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index resources_location_idx on clinic.resources (location_id, kind) where is_active;

create table clinic.schedules (
  id             uuid primary key default gen_random_uuid(),
  tenant_id      uuid not null references clinic.tenants(id) on delete cascade,
  doctor_id      uuid not null references clinic.doctors(id) on delete cascade,
  location_id    uuid not null references clinic.locations(id) on delete cascade,
  weekday        smallint not null check (weekday between 0 and 6),   -- 0 = Sunday … 6 = Saturday
  start_time     time not null,
  end_time       time not null,                                       -- at or before start = past midnight
  mode           text not null default 'slots' check (mode in ('slots', 'queue', 'both')),
  slot_minutes   int not null default 15 check (slot_minutes between 5 and 240),
  capacity       int check (capacity is null or capacity > 0),        -- the most patients in the session
  online_booking boolean not null default true,                       -- the agent may book it
  valid_from     date,
  valid_to       date,
  is_active      boolean not null default true,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
create index schedules_doctor_idx on clinic.schedules (doctor_id, weekday) where is_active;

create table clinic.schedule_exceptions (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references clinic.tenants(id) on delete cascade,
  doctor_id    uuid not null references clinic.doctors(id) on delete cascade,
  location_id  uuid references clinic.locations(id) on delete cascade,   -- null = everywhere
  on_date      date not null,
  kind         text not null check (kind in ('off', 'extra', 'changed')),
  start_time   time,                -- 'off' with times = only that part of the day
  end_time     time,
  mode         text check (mode in ('slots', 'queue', 'both')),
  slot_minutes int,
  capacity     int,
  reason       text,
  created_by   uuid,
  created_at   timestamptz not null default now()
);
create index schedule_exceptions_idx on clinic.schedule_exceptions (doctor_id, on_date);

-- ---------------------------------------------------------------------
-- The catalogue
-- ---------------------------------------------------------------------
create table clinic.services (
  id               uuid primary key default gen_random_uuid(),
  tenant_id        uuid not null references clinic.tenants(id) on delete cascade,
  code             text not null check (code ~ '^S[0-9]{3,5}$'),   -- what the agent uses: S001…
  category         text not null default 'consultation'
                   check (category in ('consultation', 'follow_up', 'diagnostic', 'procedure', 'cosmetic', 'package', 'other')),
  specialty        text,                         -- null = any doctor of the clinic
  name_ar          text not null,
  name_en          text,
  aliases          text[] not null default '{}',
  description_ar   text,
  description_en   text,
  duration_min     int not null default 15 check (duration_min between 5 and 600),
  price_kind       text not null default 'fixed' check (price_kind in ('fixed', 'range', 'from', 'after_exam', 'free')),
  price            numeric(12, 2),               -- null with 'fixed' = not set yet: the agent asks the doctor
  price_max        numeric(12, 2),
  price_unit       text not null default 'visit'
                   check (price_unit in ('visit', 'tooth', 'canal', 'jaw', 'session', 'area', 'course', 'unit')),
  price_note_ar    text,                         -- "حسب نوع الزرعة والعظم"
  price_note_en    text,
  sessions         int not null default 1 check (sessions between 1 and 60),
  session_gap_days int,
  prep_ar          text,                         -- sent with the booking
  prep_en          text,
  aftercare_ar     text,                         -- sent when the visit is marked done
  aftercare_en     text,
  doctor_ids       uuid[] not null default '{}', -- empty = every doctor (of `specialty` when set)
  location_ids     uuid[] not null default '{}', -- empty = every location
  days             smallint[] not null default '{}',  -- weekdays it is offered; empty = every day
  min_age          numeric(5, 2),
  max_age          numeric(5, 2),
  needs_consult_first boolean not null default false,
  resource_kind    text,                         -- needs a free chair / room / laser
  deposit          numeric(12, 2),
  pay_online       text not null default 'off' check (pay_online in ('off', 'optional', 'deposit', 'full')),
  installments     boolean not null default false,
  agent_visible    boolean not null default true, -- the agent may mention it and its price
  bookable         boolean not null default true, -- the agent may book it directly
  is_active        boolean not null default true,
  sort             int not null default 0,
  source_import_id uuid,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (tenant_id, code),
  check (price_kind <> 'range' or price_max is null or price is null or price_max >= price)
);
create index services_tenant_idx on clinic.services (tenant_id, is_active, sort);

create table clinic.service_prices (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references clinic.tenants(id) on delete cascade,
  service_id  uuid not null references clinic.services(id) on delete cascade,
  doctor_id   uuid references clinic.doctors(id) on delete cascade,
  location_id uuid references clinic.locations(id) on delete cascade,
  price_kind  text check (price_kind in ('fixed', 'range', 'from', 'after_exam', 'free')),
  price       numeric(12, 2),
  price_max   numeric(12, 2),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  check (doctor_id is not null or location_id is not null)
);
create unique index service_prices_uidx on clinic.service_prices (service_id, doctor_id, location_id) nulls not distinct;

create table clinic.offers (
  id             uuid primary key default gen_random_uuid(),
  tenant_id      uuid not null references clinic.tenants(id) on delete cascade,
  title_ar       text not null,
  title_en       text,
  description_ar text,
  description_en text,
  kind           text not null default 'percent_off'
                 check (kind in ('percent_off', 'amount_off', 'fixed_price', 'package', 'free')),
  value          numeric(12, 2) not null default 0,
  service_ids    uuid[] not null default '{}',
  doctor_ids     uuid[] not null default '{}',
  starts_at      timestamptz,
  ends_at        timestamptz,
  days           smallint[] not null default '{}',
  is_active      boolean not null default true,
  sort           int not null default 0,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
create index offers_tenant_idx on clinic.offers (tenant_id, is_active);

create table clinic.knowledge_entries (
  id         uuid primary key default gen_random_uuid(),
  tenant_id  uuid not null references clinic.tenants(id) on delete cascade,
  doctor_id  uuid references clinic.doctors(id) on delete cascade,
  topic      text not null,
  content_ar text,
  content_en text,
  is_active  boolean not null default true,
  sort       int not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index knowledge_entries_tenant_idx on clinic.knowledge_entries (tenant_id);

-- kind:
--   note                params {}                       the agent reads text_ar under its fixed safety rules
--   new_patients_until  params {"time":"21:00"}         no first visits after this local time
--   age_doctor          params {"max_age":6}            patients under max_age only with doctor_id
--   no_booking_days     params {"days":[5]}             the agent books nobody on these weekdays (doctor_id or all)
create table clinic.agent_rules (
  id         uuid primary key default gen_random_uuid(),
  tenant_id  uuid not null references clinic.tenants(id) on delete cascade,
  kind       text not null default 'note' check (kind in ('note', 'new_patients_until', 'age_doctor', 'no_booking_days')),
  doctor_id  uuid references clinic.doctors(id) on delete cascade,
  service_id uuid references clinic.services(id) on delete cascade,
  params     jsonb not null default '{}'::jsonb,
  text_ar    text,
  text_en    text,
  is_active  boolean not null default true,
  sort       int not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index agent_rules_tenant_idx on clinic.agent_rules (tenant_id) where is_active;

create table clinic.catalog_imports (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references clinic.tenants(id) on delete cascade,
  doctor_id    uuid references clinic.doctors(id) on delete set null,
  source_kind  text not null check (source_kind in ('pdf', 'image', 'url', 'text', 'csv')),
  source_url   text,
  files        jsonb not null default '[]'::jsonb,
  raw_text     text,
  status       text not null default 'uploaded' check (status in ('uploaded', 'extracting', 'review', 'published', 'failed')),
  extracted    jsonb,
  error        text,
  model        text,
  usage        jsonb,
  created_by   uuid,
  published_by uuid,
  published_at timestamptz,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

create table clinic.catalog_changes (
  id          bigint generated always as identity primary key,
  tenant_id   uuid not null references clinic.tenants(id) on delete cascade,
  source      text not null default 'dashboard' check (source in ('dashboard', 'whatsapp', 'assistant', 'import')),
  request     jsonb not null default '[]'::jsonb,   -- what was asked
  entries     jsonb not null default '[]'::jsonb,   -- [{op, table, id, label, before, after}]
  summary_ar  text,
  status      text not null default 'pending' check (status in ('pending', 'applied', 'undone', 'discarded')),
  created_by  uuid,
  created_by_name text,
  created_at  timestamptz not null default now(),
  applied_at  timestamptz,
  undone_at   timestamptz
);
create index catalog_changes_tenant_idx on clinic.catalog_changes (tenant_id, created_at desc);

create table clinic.catalog_snapshot (
  tenant_id    uuid primary key references clinic.tenants(id) on delete cascade,
  digest_text  text not null default '',
  lookup       jsonb not null default '{}'::jsonb,
  version_hash text not null default '',
  source_rev   bigint not null default 0,
  built_at     timestamptz not null default now(),
  valid_until  timestamptz
);

-- ---------------------------------------------------------------------
-- Codes, triggers
-- ---------------------------------------------------------------------
create or replace function clinic.assign_service_code()
returns trigger language plpgsql security definer set search_path = clinic, pg_temp as $$
declare s int;
begin
  if new.code is null or btrim(new.code) = '' then
    loop
      update clinic.tenants set service_seq = service_seq + 1 where id = new.tenant_id returning service_seq into s;
      new.code := 'S' || lpad(s::text, 3, '0');
      exit when not exists (select 1 from clinic.services where tenant_id = new.tenant_id and code = new.code);
    end loop;
  end if;
  new.code := upper(btrim(new.code));
  return new;
end $$;
create trigger services_assign_code before insert on clinic.services
  for each row execute function clinic.assign_service_code();

create or replace function clinic.assign_doctor_code()
returns trigger language plpgsql as $$
declare n int;
begin
  if new.code is null or btrim(new.code) = '' then
    select coalesce(max(substr(code, 2)::int), 0) + 1 into n from clinic.doctors where tenant_id = new.tenant_id;
    new.code := 'D' || n;
  end if;
  return new;
end $$;
create trigger doctors_assign_code before insert on clinic.doctors
  for each row execute function clinic.assign_doctor_code();

do $$
declare t text;
begin
  foreach t in array array['doctors', 'locations', 'resources', 'schedules', 'services', 'service_prices', 'offers',
                           'knowledge_entries', 'agent_rules', 'catalog_imports'] loop
    execute format('create trigger %I before update on clinic.%I for each row execute function clinic.touch_updated_at()',
                   t || '_touch', t);
  end loop;
  foreach t in array array['doctors', 'locations', 'resources', 'schedules', 'schedule_exceptions', 'services',
                           'service_prices', 'offers', 'knowledge_entries', 'agent_rules'] loop
    execute format('create trigger %I after insert or update or delete on clinic.%I for each row execute function clinic.bump_catalog_rev()',
                   t || '_rev', t);
  end loop;
  foreach t in array array['tenants', 'doctors', 'locations', 'resources', 'schedules', 'schedule_exceptions', 'services',
                           'service_prices', 'offers', 'knowledge_entries', 'agent_rules', 'tenant_members'] loop
    execute format('create trigger %I after insert or update or delete on clinic.%I for each row execute function clinic.audit_change()',
                   t || '_audit', t);
  end loop;
end $$;

-- ---------------------------------------------------------------------
-- Words the agent and the dashboard share
-- ---------------------------------------------------------------------
create or replace function clinic.doctor_label(p_doctor uuid, p_lang text default 'ar')
returns text language sql stable as $$
  select case when p_lang = 'en' then concat_ws(' ', nullif(d.title_en, ''), coalesce(nullif(d.name_en, ''), d.name_ar))
              else concat_ws(' ', nullif(d.title_ar, ''), d.name_ar) end
    from clinic.doctors d where d.id = p_doctor
$$;

create or replace function clinic.location_label(p_location uuid, p_lang text default 'ar')
returns text language sql stable as $$
  select case when p_lang = 'en' then coalesce(nullif(l.name_en, ''), l.name_ar) else l.name_ar end
    from clinic.locations l where l.id = p_location
$$;

create or replace function clinic.day_name(p_dow int, p_lang text default 'ar')
returns text language sql immutable as $$
  select case when p_lang = 'en'
              then (array['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'])[p_dow + 1]
              else (array['الأحد','الاتنين','التلات','الأربع','الخميس','الجمعة','السبت'])[p_dow + 1] end
$$;

-- 17:30 → "5:30 م" / "5:30 pm"
create or replace function clinic.clock_text(p_time time, p_lang text default 'ar')
returns text language sql immutable as $$
  select case when p_time is null then null else
    ((extract(hour from p_time)::int + 11) % 12 + 1)::text
    || case when extract(minute from p_time)::int = 0 then '' else ':' || lpad(extract(minute from p_time)::int::text, 2, '0') end
    || case when p_lang = 'en' then case when extract(hour from p_time) < 12 then ' am' else ' pm' end
            else case when extract(hour from p_time) < 12 then ' ص' else ' م' end end end
$$;

create or replace function clinic.unit_text(p_unit text, p_lang text default 'ar')
returns text language sql immutable as $$
  select case when p_lang = 'en' then case p_unit
           when 'tooth' then 'per tooth' when 'canal' then 'per canal' when 'jaw' then 'per jaw'
           when 'session' then 'per session' when 'area' then 'per area' when 'course' then 'for the full course'
           when 'unit' then 'per unit' else '' end
         else case p_unit
           when 'tooth' then 'للسنة' when 'canal' then 'للقناة' when 'jaw' then 'للفك'
           when 'session' then 'للجلسة' when 'area' then 'للمنطقة' when 'course' then 'للكورس كامل'
           when 'unit' then 'للوحدة' else '' end end
$$;

-- the price as a patient hears it
create or replace function clinic.price_words(p_kind text, p_price numeric, p_max numeric, p_unit text,
                                              p_lang text default 'ar', p_symbol text default 'ج')
returns text language sql immutable as $$
  select btrim(case
    when p_kind = 'free' then case when p_lang = 'en' then 'free' else 'مجاناً' end
    when p_kind = 'after_exam' then case when p_lang = 'en' then 'priced after the check-up' else 'السعر بيتحدد بعد الكشف' end
    when p_price is null then case when p_lang = 'en' then 'price not on file' else 'السعر مش متسجل' end
    when p_kind = 'range' and p_max is not null then
      case when p_lang = 'en' then 'from ' || clinic.fmt_money(p_price) || ' to ' || clinic.fmt_money(p_max) || ' EGP'
           else 'من ' || clinic.fmt_money(p_price) || ' لـ ' || clinic.fmt_money(p_max) || ' ' || p_symbol end
    when p_kind in ('from', 'range') then
      case when p_lang = 'en' then 'from ' || clinic.fmt_money(p_price) || ' EGP'
           else 'يبدأ من ' || clinic.fmt_money(p_price) || ' ' || p_symbol end
    else case when p_lang = 'en' then clinic.fmt_money(p_price) || ' EGP' else clinic.fmt_money(p_price) || ' ' || p_symbol end
  end || ' ' || case when p_kind in ('free', 'after_exam') or p_price is null then '' else clinic.unit_text(p_unit, p_lang) end)
$$;

-- does this doctor (at this location) do this service?
create or replace function clinic.service_offered(p_service uuid, p_doctor uuid, p_location uuid default null)
returns boolean language sql stable as $$
  select exists (
    select 1 from clinic.services s
      join clinic.doctors d on d.id = p_doctor and d.tenant_id = s.tenant_id
     where s.id = p_service and s.is_active and d.is_active
       and (case when cardinality(s.doctor_ids) > 0 then p_doctor = any(s.doctor_ids)
                 else s.specialty is null or s.specialty = d.specialty end)
       and (p_location is null or cardinality(s.location_ids) = 0 or p_location = any(s.location_ids)))
$$;

-- the price for one doctor at one place: the most specific row wins
create or replace function clinic.service_price(p_service uuid, p_doctor uuid default null, p_location uuid default null)
returns jsonb language sql stable as $$
  with s as (select * from clinic.services where id = p_service),
  o as (
    select sp.* from clinic.service_prices sp
     where sp.service_id = p_service
       and (sp.doctor_id is null or sp.doctor_id = p_doctor)
       and (sp.location_id is null or sp.location_id = p_location)
       and (sp.doctor_id is not null or sp.location_id is not null)
     order by (sp.doctor_id is not null and sp.location_id is not null) desc, (sp.doctor_id is not null) desc
     limit 1)
  select jsonb_build_object(
           'kind', coalesce(o.price_kind, s.price_kind),
           'price', case when o.id is not null and (o.price is not null or o.price_kind is not null) then o.price else s.price end,
           'price_max', case when o.id is not null and (o.price is not null or o.price_kind is not null) then o.price_max else s.price_max end,
           'unit', s.price_unit,
           'note_ar', s.price_note_ar, 'note_en', s.price_note_en,
           'text_ar', clinic.price_words(coalesce(o.price_kind, s.price_kind),
                                         case when o.id is not null and (o.price is not null or o.price_kind is not null) then o.price else s.price end,
                                         case when o.id is not null and (o.price is not null or o.price_kind is not null) then o.price_max else s.price_max end,
                                         s.price_unit, 'ar', t.currency_symbol_ar),
           'text_en', clinic.price_words(coalesce(o.price_kind, s.price_kind),
                                         case when o.id is not null and (o.price is not null or o.price_kind is not null) then o.price else s.price end,
                                         case when o.id is not null and (o.price is not null or o.price_kind is not null) then o.price_max else s.price_max end,
                                         s.price_unit, 'en', t.currency_symbol_ar))
    from s join clinic.tenants t on t.id = s.tenant_id left join o on true
$$;

-- a service named in words (code, name, alias, or a close match)
create or replace function clinic.match_service(p_tenant uuid, p_text text, p_doctor uuid default null)
returns uuid language sql stable as $$
  with q as (select clinic.norm(p_text) as n, upper(btrim(coalesce(p_text, ''))) as code)
  select s.id
    from clinic.services s, q
   where s.tenant_id = p_tenant and s.is_active and q.n <> ''
     and (p_doctor is null or clinic.service_offered(s.id, p_doctor))
     and (s.code = q.code
          or clinic.norm(s.name_ar) = q.n or clinic.norm(coalesce(s.name_en, '')) = q.n
          or q.n = any (select clinic.norm(a) from unnest(s.aliases) a)
          or (length(q.n) >= 3 and (clinic.norm(s.name_ar) like '%' || q.n || '%'
                                    or clinic.norm(coalesce(s.name_en, '')) like '%' || q.n || '%'
                                    or q.n like '%' || clinic.norm(s.name_ar) || '%'
                                    or exists (select 1 from unnest(s.aliases) a where length(a) >= 3 and q.n like '%' || clinic.norm(a) || '%'))))
   order by (s.code = q.code) desc,
            (clinic.norm(s.name_ar) = q.n or clinic.norm(coalesce(s.name_en, '')) = q.n) desc,
            (q.n = any (select clinic.norm(a) from unnest(s.aliases) a)) desc,
            length(s.name_ar), s.sort
   limit 1
$$;

create or replace function clinic.match_doctor(p_tenant uuid, p_text text)
returns uuid language sql stable as $$
  with q as (select btrim(regexp_replace(clinic.norm(p_text), '^(د|دكتور|دكتوره|الدكتور|الدكتوره|dr|doctor)\s+', '')) as n,
                    upper(btrim(coalesce(p_text, ''))) as code)
  select d.id
    from clinic.doctors d, q
   where d.tenant_id = p_tenant and d.is_active and q.n <> ''
     and (d.code = q.code or clinic.norm(d.name_ar) = q.n or clinic.norm(coalesce(d.name_en, '')) = q.n
          or clinic.norm(d.name_ar) like q.n || '%' or clinic.norm(coalesce(d.name_en, '')) like q.n || '%'
          or (length(q.n) >= 3 and clinic.norm(d.name_ar) like '%' || q.n || '%')
          or d.specialty = q.n
          or exists (select 1 from clinic.specialty_presets sp where sp.code = d.specialty
                      and (clinic.norm(sp.name_ar) like '%' || q.n || '%' or lower(sp.name_en) like '%' || q.n || '%')))
   order by (d.code = q.code) desc, (clinic.norm(d.name_ar) = q.n) desc, d.sort
   limit 1
$$;

create or replace function clinic.match_location(p_tenant uuid, p_text text)
returns uuid language sql stable as $$
  with q as (select clinic.norm(p_text) as n)
  select l.id from clinic.locations l, q
   where l.tenant_id = p_tenant and l.is_active and q.n <> ''
     and (clinic.norm(l.code) = q.n or clinic.norm(l.name_ar) = q.n or clinic.norm(coalesce(l.name_en, '')) = q.n
          or q.n = any (select clinic.norm(a) from unnest(l.aliases) a)
          or (length(q.n) >= 3 and (clinic.norm(l.name_ar) like '%' || q.n || '%' or q.n like '%' || clinic.norm(l.name_ar) || '%'
                                    or clinic.norm(coalesce(l.area_ar, '')) like '%' || q.n || '%')))
   order by (clinic.norm(l.name_ar) = q.n) desc, l.sort
   limit 1
$$;

-- an offer running at a moment (in the clinic's time)
create or replace function clinic.offer_live(o clinic.offers, p_at timestamptz, p_tz text)
returns boolean language sql stable as $$
  select o.is_active
     and (o.starts_at is null or o.starts_at <= p_at)
     and (o.ends_at is null or o.ends_at > p_at)
     and (cardinality(o.days) = 0 or extract(dow from (p_at at time zone p_tz))::smallint = any(o.days))
$$;

-- ---------------------------------------------------------------------
-- The snapshot: what the agent reads every turn
-- ---------------------------------------------------------------------
create or replace function clinic.rebuild_snapshot(p_tenant uuid)
returns jsonb language plpgsql as $$
declare
  t        clinic.tenants%rowtype;
  lines    text[] := '{}';
  d        record;
  s        record;
  r        record;
  v_pr     jsonb;
  v_who    text;
  v_amounts numeric[] := '{}';
  v_services jsonb := '{}'::jsonb;
  v_doctors  jsonb := '{}'::jsonb;
  v_offers   jsonb := '[]'::jsonb;
  v_digest text;
  v_rows   text;
  v_until  timestamptz;
begin
  select * into t from clinic.tenants where id = p_tenant;
  if not found then return null; end if;

  -- doctors and when they see patients ---------------------------------
  lines := lines || 'DOCTORS'::text;
  for d in select * from clinic.doctors where tenant_id = p_tenant and is_active order by sort, code loop
    select string_agg(format('%s %s %s–%s (%s%s)',
                             l.name_ar, clinic.day_name(sc.weekday), to_char(sc.start_time, 'HH24:MI'), to_char(sc.end_time, 'HH24:MI'),
                             case sc.mode when 'slots' then 'by appointment' when 'queue' then 'by queue number' else 'appointment or queue' end,
                             case when not sc.online_booking then ', NOT bookable here — by phone' else '' end), '; '
                      order by l.sort, (sc.weekday + 1) % 7, sc.start_time)
      into v_rows
      from clinic.schedules sc join clinic.locations l on l.id = sc.location_id
     where sc.doctor_id = d.id and sc.is_active and l.is_active
       and (sc.valid_to is null or sc.valid_to >= (now() at time zone t.timezone)::date);
    lines := lines || format('- %s %s · %s%s%s · sees patients: %s',
                             d.code, clinic.doctor_label(d.id, 'ar'),
                             coalesce((select name_ar from clinic.specialty_presets where code = d.specialty), d.specialty),
                             coalesce(' (' || nullif(d.sub_specialty_ar, '') || ')', ''),
                             case when not d.accepts_new then ' · NOT taking new patients' else '' end,
                             coalesce(v_rows, 'no schedule on file'));
    v_doctors := v_doctors || jsonb_build_object(d.code, jsonb_build_object(
                   'id', d.id, 'name_ar', clinic.doctor_label(d.id, 'ar'), 'name_en', clinic.doctor_label(d.id, 'en'),
                   'specialty', d.specialty, 'follow_up_days', d.follow_up_days, 'accepts_new', d.accepts_new));
  end loop;

  lines := lines || ''::text || 'LOCATIONS'::text;
  for r in select * from clinic.locations where tenant_id = p_tenant and is_active order by sort loop
    lines := lines || format('- %s%s%s%s', r.name_ar,
                             coalesce(' — ' || nullif(r.address_ar, ''), ''),
                             coalesce(' (' || nullif(r.directions_ar, '') || ')', ''),
                             coalesce(' · map: ' || nullif(r.maps_url, ''), ''));
  end loop;

  -- services and prices --------------------------------------------------
  lines := lines || ''::text || ('SERVICES AND PRICES (' || t.currency || ') — the ONLY prices you may say'::text);
  for s in select * from clinic.services where tenant_id = p_tenant and is_active and agent_visible
            order by case category when 'consultation' then 0 when 'follow_up' then 1 when 'diagnostic' then 2 else 3 end, sort, code loop
    v_pr := clinic.service_price(s.id, null, null);
    v_amounts := v_amounts || array_remove(array[(v_pr ->> 'price')::numeric, (v_pr ->> 'price_max')::numeric, s.deposit], null);
    select string_agg(clinic.doctor_label(x, 'ar'), '، ') into v_who
      from unnest(s.doctor_ids) x;
    lines := lines || format('[%s] %s%s — %s%s · %s min%s%s%s%s%s%s',
      s.code, s.name_ar, coalesce(' / ' || nullif(s.name_en, ''), ''),
      v_pr ->> 'text_ar', coalesce(' (' || nullif(s.price_note_ar, '') || ')', ''),
      s.duration_min,
      case when s.sessions > 1 then format(' · %s sessions%s', s.sessions, coalesce(', ' || s.session_gap_days || ' days apart', '')) else '' end,
      case when v_who is not null then ' · only ' || v_who
           when s.specialty is not null then ' · ' || coalesce((select name_ar from clinic.specialty_presets where code = s.specialty), s.specialty) || ' doctors'
           else '' end,
      case when cardinality(s.days) > 0 then ' · only on ' || (select string_agg(clinic.day_name(x), '، ') from unnest(s.days) x) else '' end,
      case when s.min_age is not null or s.max_age is not null then format(' · ages %s–%s', coalesce(trim_scale(s.min_age)::text, '0'), coalesce(trim_scale(s.max_age)::text, 'any')) else '' end,
      case when s.needs_consult_first then ' · needs a check-up first' when not s.bookable then ' · NOT booked by you — the team arranges it after the check-up' else '' end,
      coalesce(' · aliases: ' || nullif(array_to_string(s.aliases, '، '), ''), ''));
    if coalesce(s.description_ar, '') <> '' then lines := lines || ('    ' || left(s.description_ar, 300)); end if;
    -- a doctor's or a place's own price
    for r in select sp.*, clinic.doctor_label(sp.doctor_id, 'ar') as dname, clinic.location_label(sp.location_id, 'ar') as lname
               from clinic.service_prices sp where sp.service_id = s.id loop
      v_pr := clinic.service_price(s.id, r.doctor_id, r.location_id);
      v_amounts := v_amounts || array_remove(array[(v_pr ->> 'price')::numeric, (v_pr ->> 'price_max')::numeric], null);
      lines := lines || format('    with %s: %s', concat_ws(' at ', r.dname, r.lname), v_pr ->> 'text_ar');
    end loop;
    v_services := v_services || jsonb_build_object(s.code, jsonb_build_object(
                    'id', s.id, 'name_ar', s.name_ar, 'name_en', s.name_en, 'category', s.category,
                    'duration', s.duration_min, 'price', clinic.service_price(s.id, null, null),
                    'sessions', s.sessions, 'bookable', s.bookable, 'resource_kind', s.resource_kind,
                    'prep_ar', s.prep_ar, 'aftercare_ar', s.aftercare_ar));
  end loop;

  -- offers running now (the snapshot expires when the next one starts or ends) --
  lines := lines || ''::text || 'OFFERS RUNNING NOW'::text;
  for r in select o.* from clinic.offers o where o.tenant_id = p_tenant and clinic.offer_live(o, now(), t.timezone) order by o.sort loop
    lines := lines || format('- %s%s%s%s', r.title_ar,
                             case r.kind when 'percent_off' then ' — ' || clinic.fmt_money(r.value) || '% off'
                                         when 'amount_off' then ' — ' || clinic.fmt_money(r.value) || ' ' || t.currency_symbol_ar || ' off'
                                         when 'fixed_price' then ' — for ' || clinic.fmt_money(r.value) || ' ' || t.currency_symbol_ar
                                         when 'package' then ' — package price ' || clinic.fmt_money(r.value) || ' ' || t.currency_symbol_ar
                                         else ' — free' end,
                             case when cardinality(r.service_ids) > 0 then ' on ' || (select string_agg(x.code || ' ' || x.name_ar, '، ') from clinic.services x where x.id = any(r.service_ids)) else '' end,
                             coalesce(' · until ' || to_char((r.ends_at at time zone t.timezone) - interval '1 second', 'YYYY-MM-DD'), '') || coalesce(' · ' || nullif(r.description_ar, ''), ''));
    v_amounts := v_amounts || r.value;
    -- the price after the offer, for each service it covers
    if r.kind in ('percent_off', 'amount_off') then
      v_amounts := v_amounts || coalesce((select array_agg(case r.kind when 'percent_off' then round(x.price * (100 - r.value) / 100, 2) else x.price - r.value end)
                                            from clinic.services x where x.id = any(r.service_ids) and x.price is not null), '{}');
    end if;
    v_offers := v_offers || jsonb_build_object('id', r.id, 'title_ar', r.title_ar, 'kind', r.kind, 'value', r.value);
  end loop;
  if lines[array_length(lines, 1)] = 'OFFERS RUNNING NOW' then lines := lines || '- none'::text; end if;
  select min(x) into v_until from (
    select starts_at as x from clinic.offers where tenant_id = p_tenant and is_active and starts_at > now()
    union all select ends_at from clinic.offers where tenant_id = p_tenant and is_active and ends_at > now()
    union all select date_trunc('day', now() at time zone t.timezone) at time zone t.timezone + interval '1 day') z;

  -- answers and policies ---------------------------------------------------
  lines := lines || ''::text || 'THE CLINIC''S OWN ANSWERS (use these words'' facts, never invent beyond them)'::text;
  for r in select * from clinic.knowledge_entries where tenant_id = p_tenant and is_active order by sort, topic loop
    lines := lines || format('- %s%s: %s', r.topic,
                             coalesce(' (' || clinic.doctor_label(r.doctor_id, 'ar') || ')', ''),
                             coalesce(nullif(r.content_ar, ''), r.content_en, ''));
  end loop;

  lines := lines || ''::text || 'THE DOCTORS'' RULES FOR YOU'::text;
  for r in select * from clinic.agent_rules where tenant_id = p_tenant and is_active order by sort, created_at loop
    lines := lines || ('- ' || case r.kind
      when 'note' then coalesce(r.text_ar, r.text_en, '')
      when 'new_patients_until' then format('no NEW patients after %s%s (enforced)', r.params ->> 'time',
                                            coalesce(' for ' || clinic.doctor_label(r.doctor_id, 'ar'), ''))
      when 'age_doctor' then format('patients younger than %s years only with %s (enforced)', r.params ->> 'max_age',
                                    coalesce(clinic.doctor_label(r.doctor_id, 'ar'), '?'))
      when 'no_booking_days' then format('no bookings on %s%s (enforced)',
                                         (select string_agg(clinic.day_name(x::int), '، ') from jsonb_array_elements_text(r.params -> 'days') x),
                                         coalesce(' for ' || clinic.doctor_label(r.doctor_id, 'ar'), ''))
      else '' end || coalesce(case when r.kind <> 'note' and coalesce(r.text_ar, '') <> '' then ' — ' || r.text_ar end, ''));
  end loop;

  v_digest := array_to_string(lines, E'\n');
  insert into clinic.catalog_snapshot as cs (tenant_id, digest_text, lookup, version_hash, source_rev, built_at, valid_until)
  values (p_tenant, v_digest,
          jsonb_build_object('services', v_services, 'doctors', v_doctors, 'offers', v_offers,
                             'amounts', coalesce((select jsonb_agg(distinct x) from unnest(v_amounts) x where x is not null), '[]'::jsonb)),
          md5(v_digest), t.catalog_rev, now(), v_until)
  on conflict (tenant_id) do update
    set digest_text = excluded.digest_text, lookup = excluded.lookup, version_hash = excluded.version_hash,
        source_rev = excluded.source_rev, built_at = now(), valid_until = excluded.valid_until;
  return jsonb_build_object('rev', t.catalog_rev, 'chars', length(v_digest));
end $$;

create or replace function clinic.ensure_snapshot(p_tenant uuid)
returns void language plpgsql as $$
begin
  if not exists (select 1 from clinic.catalog_snapshot s join clinic.tenants t on t.id = s.tenant_id
                  where s.tenant_id = p_tenant and s.source_rev >= t.catalog_rev
                    and (s.valid_until is null or s.valid_until > now())) then
    perform clinic.rebuild_snapshot(p_tenant);
  end if;
end $$;

-- ---------------------------------------------------------------------
-- Changing the catalogue in words: the doctor's WhatsApp (staff mode),
-- the dashboard assistant, or the editor. A change is shown first
-- (p_apply = false keeps it 'pending' with its before/after), then
-- applied by its id, and can be undone.
--
-- p_changes = [ {op, …}, … ]
--   set_price       service, price?, price_max?, price_kind?, unit?, doctor?, location?
--   add_service     name_ar, name_en?, category?, price?, price_max?, price_kind?, unit?, duration?,
--                   sessions?, session_gap_days?, description_ar?, aliases?, specialty?, doctor?
--   update_service  service, fields {any column}
--   remove_service  service                          (archived; undo brings it back)
--   add_faq / update_faq   topic, content_ar, content_en?
--   remove_faq      topic
--   add_offer       title_ar, kind?, value, services?, ends_at?, starts_at?
--   end_offer       offer (its title)
--   add_rule        text_ar  (or kind + params + doctor?)
--   remove_rule     text (words in it)
-- ---------------------------------------------------------------------
create or replace function clinic.catalog_put(p_table text, p_row jsonb)
returns void language plpgsql security definer set search_path = clinic, pg_temp as $$
declare cols text; ex text;
begin
  if p_table not in ('services', 'service_prices', 'offers', 'knowledge_entries', 'agent_rules') then
    raise exception 'not a catalogue table: %', p_table;
  end if;
  select string_agg(format('%I', a.attname), ', ' order by a.attnum),
         string_agg(format('excluded.%I', a.attname), ', ' order by a.attnum)
    into cols, ex
    from pg_attribute a
   where a.attrelid = ('clinic.' || p_table)::regclass and a.attnum > 0 and not a.attisdropped
     and a.attname not in ('created_at', 'updated_at') and a.attidentity = '' and a.attgenerated = ''
     and (p_row ? a.attname);
  execute format('insert into clinic.%I (%s) select %s from jsonb_populate_record(null::clinic.%I, $1)
                  on conflict (id) do update set (%s) = row(%s)', p_table, cols, cols, p_table, cols, ex)
    using p_row;
end $$;

create or replace function clinic.catalog_change(p_tenant uuid, p_changes jsonb, p_apply boolean default false,
                                                 p_source text default 'dashboard')
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare
  t        clinic.tenants%rowtype;
  c        jsonb;
  v_op     text;
  v_entries jsonb := '[]'::jsonb;
  v_problems jsonb := '[]'::jsonb;
  v_lines  text[] := '{}';
  s        clinic.services%rowtype;
  k        clinic.knowledge_entries%rowtype;
  o        clinic.offers%rowtype;
  ru       clinic.agent_rules%rowtype;
  sp       clinic.service_prices%rowtype;
  v_sid    uuid;
  v_doc    uuid;
  v_loc    uuid;
  v_before jsonb;
  v_after  jsonb;
  v_id     bigint;
  v_kind   text;
begin
  perform clinic.require_role(p_tenant, array['owner', 'manager', 'doctor']);
  select * into t from clinic.tenants where id = p_tenant;
  if jsonb_typeof(p_changes) = 'object' then p_changes := jsonb_build_array(p_changes); end if;
  if jsonb_typeof(p_changes) <> 'array' or jsonb_array_length(p_changes) = 0 then
    return jsonb_build_object('ok', false, 'error', 'NO_CHANGES', 'fact', 'send changes as a list of {op, …}');
  end if;

  for c in select * from jsonb_array_elements(p_changes) loop
    v_op := lower(coalesce(c ->> 'op', ''));
    v_sid := null; v_doc := null; v_loc := null; v_before := null; v_after := null;
    if nullif(c ->> 'service', '') is not null then
      v_sid := clinic.match_service(p_tenant, c ->> 'service');
    end if;
    if nullif(c ->> 'doctor', '') is not null then v_doc := clinic.match_doctor(p_tenant, c ->> 'doctor'); end if;
    if nullif(c ->> 'location', '') is not null then v_loc := clinic.match_location(p_tenant, c ->> 'location'); end if;

    if v_op in ('set_price', 'update_service', 'remove_service') and v_sid is null then
      v_problems := v_problems || jsonb_build_object('op', v_op, 'problem', 'SERVICE_NOT_FOUND', 'said', c ->> 'service');
      continue;
    end if;
    if nullif(c ->> 'doctor', '') is not null and v_doc is null then
      v_problems := v_problems || jsonb_build_object('op', v_op, 'problem', 'DOCTOR_NOT_FOUND', 'said', c ->> 'doctor');
      continue;
    end if;

    if v_op = 'set_price' then
      select * into s from clinic.services where id = v_sid;
      v_kind := coalesce(nullif(c ->> 'price_kind', ''),
                         case when nullif(c ->> 'price_max', '') is not null then 'range'
                              when s.price_kind in ('after_exam', 'free') and nullif(c ->> 'price', '') is not null then 'fixed'
                              else null end);
      if v_doc is null and v_loc is null then
        v_before := to_jsonb(s);
        v_after := v_before || jsonb_strip_nulls(jsonb_build_object(
                     'price', (c ->> 'price')::numeric, 'price_max', (c ->> 'price_max')::numeric,
                     'price_kind', v_kind, 'price_unit', nullif(c ->> 'unit', '')));
        if v_kind is not null and v_kind <> 'range' and c ->> 'price_max' is null then v_after := v_after || '{"price_max": null}'; end if;
        v_entries := v_entries || jsonb_build_object('op', v_op, 'table', 'services', 'id', s.id,
                       'label', s.code || ' ' || s.name_ar, 'before', v_before, 'after', v_after);
        v_lines := v_lines || format('%s: %s ← %s', s.name_ar,
                     clinic.price_words(v_after ->> 'price_kind', (v_after ->> 'price')::numeric, (v_after ->> 'price_max')::numeric, v_after ->> 'price_unit', 'ar', t.currency_symbol_ar),
                     clinic.price_words(s.price_kind, s.price, s.price_max, s.price_unit, 'ar', t.currency_symbol_ar));
      else
        select * into sp from clinic.service_prices x
         where x.service_id = v_sid and x.doctor_id is not distinct from v_doc and x.location_id is not distinct from v_loc;
        v_before := case when sp.id is null then null else to_jsonb(sp) end;
        v_after := coalesce(v_before, jsonb_build_object('id', gen_random_uuid(), 'tenant_id', p_tenant, 'service_id', v_sid,
                                                         'doctor_id', v_doc, 'location_id', v_loc))
                   || jsonb_build_object('price', (c ->> 'price')::numeric, 'price_max', (c ->> 'price_max')::numeric,
                                         'price_kind', v_kind);
        v_entries := v_entries || jsonb_build_object('op', v_op, 'table', 'service_prices', 'id', v_after ->> 'id',
                       'label', (select code || ' ' || name_ar from clinic.services where id = v_sid), 'before', v_before, 'after', v_after);
        v_lines := v_lines || format('%s (%s): %s', (select name_ar from clinic.services where id = v_sid),
                     concat_ws(' · ', clinic.doctor_label(v_doc, 'ar'), clinic.location_label(v_loc, 'ar')),
                     clinic.price_words(coalesce(v_kind, 'fixed'), (c ->> 'price')::numeric, (c ->> 'price_max')::numeric,
                                        (select price_unit from clinic.services where id = v_sid), 'ar', t.currency_symbol_ar));
      end if;

    elsif v_op = 'add_service' then
      if coalesce(btrim(c ->> 'name_ar'), btrim(c ->> 'name_en'), '') = '' then
        v_problems := v_problems || jsonb_build_object('op', v_op, 'problem', 'NAME_NEEDED'); continue;
      end if;
      if clinic.match_service(p_tenant, coalesce(c ->> 'name_ar', c ->> 'name_en')) is not null
         and (select clinic.norm(name_ar) from clinic.services where id = clinic.match_service(p_tenant, coalesce(c ->> 'name_ar', c ->> 'name_en')))
             = clinic.norm(coalesce(c ->> 'name_ar', c ->> 'name_en')) then
        v_problems := v_problems || jsonb_build_object('op', v_op, 'problem', 'ALREADY_EXISTS', 'said', coalesce(c ->> 'name_ar', c ->> 'name_en'),
                                                       'fact', 'a service with this name exists — use set_price or update_service');
        continue;
      end if;
      v_after := jsonb_strip_nulls(jsonb_build_object(
        'id', gen_random_uuid(), 'tenant_id', p_tenant,
        'name_ar', coalesce(nullif(btrim(c ->> 'name_ar'), ''), btrim(c ->> 'name_en')),
        'name_en', nullif(btrim(c ->> 'name_en'), ''),
        'category', coalesce(nullif(c ->> 'category', ''), 'procedure'),
        'price', (c ->> 'price')::numeric, 'price_max', (c ->> 'price_max')::numeric,
        'price_kind', coalesce(nullif(c ->> 'price_kind', ''),
                               case when nullif(c ->> 'price_max', '') is not null then 'range'
                                    when nullif(c ->> 'price', '') is null then 'after_exam' else 'fixed' end),
        'price_unit', coalesce(nullif(c ->> 'unit', ''), 'visit'),
        'duration_min', coalesce((c ->> 'duration')::int, 30),
        'sessions', coalesce((c ->> 'sessions')::int, 1),
        'session_gap_days', (c ->> 'session_gap_days')::int,
        'description_ar', nullif(c ->> 'description_ar', ''),
        'specialty', coalesce(nullif(c ->> 'specialty', ''), (select specialty from clinic.doctors where id = v_doc)),
        'aliases', case when jsonb_typeof(c -> 'aliases') = 'array' then c -> 'aliases' end,
        'doctor_ids', case when v_doc is not null then jsonb_build_array(v_doc) end,
        'sort', (select coalesce(max(sort), 0) + 10 from clinic.services where tenant_id = p_tenant)));
      v_entries := v_entries || jsonb_build_object('op', v_op, 'table', 'services', 'id', v_after ->> 'id',
                     'label', v_after ->> 'name_ar', 'before', null, 'after', v_after);
      v_lines := v_lines || format('+ %s — %s', v_after ->> 'name_ar',
                   clinic.price_words(v_after ->> 'price_kind', (v_after ->> 'price')::numeric, (v_after ->> 'price_max')::numeric, v_after ->> 'price_unit', 'ar', t.currency_symbol_ar));

    elsif v_op = 'update_service' then
      select * into s from clinic.services where id = v_sid;
      v_before := to_jsonb(s);
      v_after := v_before || (coalesce(c -> 'fields', '{}'::jsonb) - 'id' - 'tenant_id' - 'code' - 'created_at');
      v_entries := v_entries || jsonb_build_object('op', v_op, 'table', 'services', 'id', s.id,
                     'label', s.code || ' ' || s.name_ar, 'before', v_before, 'after', v_after);
      v_lines := v_lines || format('%s: %s', s.name_ar, (select string_agg(key, '، ') from jsonb_object_keys(coalesce(c -> 'fields', '{}'::jsonb)) key));

    elsif v_op = 'remove_service' then
      select * into s from clinic.services where id = v_sid;
      v_before := to_jsonb(s);
      v_after := v_before || '{"is_active": false}'::jsonb;
      v_entries := v_entries || jsonb_build_object('op', v_op, 'table', 'services', 'id', s.id,
                     'label', s.code || ' ' || s.name_ar, 'before', v_before, 'after', v_after);
      v_lines := v_lines || ('− ' || s.name_ar);

    elsif v_op in ('add_faq', 'update_faq', 'remove_faq') then
      select * into k from clinic.knowledge_entries x
       where x.tenant_id = p_tenant and x.is_active
         and (clinic.norm(x.topic) = clinic.norm(c ->> 'topic')
              or (length(clinic.norm(c ->> 'topic')) >= 3 and clinic.norm(x.topic) like '%' || clinic.norm(c ->> 'topic') || '%'))
       order by (clinic.norm(x.topic) = clinic.norm(c ->> 'topic')) desc limit 1;
      if v_op = 'remove_faq' then
        if k.id is null then v_problems := v_problems || jsonb_build_object('op', v_op, 'problem', 'ANSWER_NOT_FOUND', 'said', c ->> 'topic'); continue; end if;
        v_before := to_jsonb(k); v_after := v_before || '{"is_active": false}'::jsonb;
        v_lines := v_lines || ('− ' || k.topic);
      elsif k.id is not null then
        v_before := to_jsonb(k);
        v_after := v_before || jsonb_strip_nulls(jsonb_build_object('content_ar', nullif(c ->> 'content_ar', ''), 'content_en', nullif(c ->> 'content_en', '')));
        v_lines := v_lines || format('%s: %s', k.topic, left(coalesce(v_after ->> 'content_ar', ''), 120));
      else
        if coalesce(btrim(c ->> 'topic'), '') = '' then
          v_problems := v_problems || jsonb_build_object('op', v_op, 'problem', 'TOPIC_NEEDED'); continue;
        end if;
        v_after := jsonb_build_object('id', gen_random_uuid(), 'tenant_id', p_tenant, 'topic', btrim(c ->> 'topic'),
                                      'content_ar', nullif(c ->> 'content_ar', ''), 'content_en', nullif(c ->> 'content_en', ''),
                                      'doctor_id', v_doc);
        v_lines := v_lines || format('+ %s: %s', c ->> 'topic', left(coalesce(c ->> 'content_ar', c ->> 'content_en', ''), 120));
      end if;
      v_entries := v_entries || jsonb_build_object('op', v_op, 'table', 'knowledge_entries', 'id', v_after ->> 'id',
                     'label', v_after ->> 'topic', 'before', v_before, 'after', v_after);

    elsif v_op = 'add_offer' then
      v_after := jsonb_strip_nulls(jsonb_build_object(
        'id', gen_random_uuid(), 'tenant_id', p_tenant, 'title_ar', coalesce(nullif(c ->> 'title_ar', ''), c ->> 'title'),
        'kind', coalesce(nullif(c ->> 'kind', ''), 'percent_off'), 'value', coalesce((c ->> 'value')::numeric, 0),
        'description_ar', nullif(c ->> 'description_ar', ''),
        'service_ids', (select jsonb_agg(clinic.match_service(p_tenant, x)) from jsonb_array_elements_text(
                          case jsonb_typeof(c -> 'services') when 'array' then c -> 'services' else '[]'::jsonb end) x
                         where clinic.match_service(p_tenant, x) is not null),
        'starts_at', nullif(c ->> 'starts_at', '')::timestamptz,
        'ends_at', case when nullif(c ->> 'ends_at', '') ~ '^\d{4}-\d{2}-\d{2}$'
                        then ((c ->> 'ends_at')::date + 1)::timestamp at time zone t.timezone
                        else nullif(c ->> 'ends_at', '')::timestamptz end));
      if coalesce(v_after ->> 'title_ar', '') = '' then
        v_problems := v_problems || jsonb_build_object('op', v_op, 'problem', 'TITLE_NEEDED'); continue;
      end if;
      v_entries := v_entries || jsonb_build_object('op', v_op, 'table', 'offers', 'id', v_after ->> 'id',
                     'label', v_after ->> 'title_ar', 'before', null, 'after', v_after);
      v_lines := v_lines || ('+ عرض: ' || (v_after ->> 'title_ar'));

    elsif v_op = 'end_offer' then
      select * into o from clinic.offers x
       where x.tenant_id = p_tenant and x.is_active
         and clinic.norm(x.title_ar) like '%' || clinic.norm(coalesce(c ->> 'offer', c ->> 'title', '')) || '%'
       order by x.created_at desc limit 1;
      if o.id is null then v_problems := v_problems || jsonb_build_object('op', v_op, 'problem', 'OFFER_NOT_FOUND', 'said', coalesce(c ->> 'offer', c ->> 'title')); continue; end if;
      v_before := to_jsonb(o); v_after := v_before || '{"is_active": false}'::jsonb;
      v_entries := v_entries || jsonb_build_object('op', v_op, 'table', 'offers', 'id', o.id, 'label', o.title_ar, 'before', v_before, 'after', v_after);
      v_lines := v_lines || ('− عرض: ' || o.title_ar);

    elsif v_op = 'add_rule' then
      v_after := jsonb_strip_nulls(jsonb_build_object('id', gen_random_uuid(), 'tenant_id', p_tenant,
                   'kind', coalesce(nullif(c ->> 'kind', ''), 'note'), 'doctor_id', v_doc,
                   'params', coalesce(c -> 'params', '{}'::jsonb), 'text_ar', nullif(c ->> 'text_ar', ''), 'text_en', nullif(c ->> 'text_en', '')));
      if v_after ->> 'kind' = 'note' and coalesce(v_after ->> 'text_ar', v_after ->> 'text_en', '') = '' then
        v_problems := v_problems || jsonb_build_object('op', v_op, 'problem', 'TEXT_NEEDED'); continue;
      end if;
      v_entries := v_entries || jsonb_build_object('op', v_op, 'table', 'agent_rules', 'id', v_after ->> 'id',
                     'label', coalesce(v_after ->> 'text_ar', v_after ->> 'kind'), 'before', null, 'after', v_after);
      v_lines := v_lines || ('+ قاعدة: ' || coalesce(v_after ->> 'text_ar', v_after ->> 'kind'));

    elsif v_op = 'remove_rule' then
      select * into ru from clinic.agent_rules x
       where x.tenant_id = p_tenant and x.is_active
         and clinic.norm(coalesce(x.text_ar, x.text_en, '')) like '%' || clinic.norm(coalesce(c ->> 'text', c ->> 'text_ar', '')) || '%'
       order by x.created_at desc limit 1;
      if ru.id is null then v_problems := v_problems || jsonb_build_object('op', v_op, 'problem', 'RULE_NOT_FOUND', 'said', c ->> 'text'); continue; end if;
      v_before := to_jsonb(ru); v_after := v_before || '{"is_active": false}'::jsonb;
      v_entries := v_entries || jsonb_build_object('op', v_op, 'table', 'agent_rules', 'id', ru.id, 'label', coalesce(ru.text_ar, ru.kind), 'before', v_before, 'after', v_after);
      v_lines := v_lines || ('− قاعدة: ' || coalesce(ru.text_ar, ru.kind));
    else
      v_problems := v_problems || jsonb_build_object('op', v_op, 'problem', 'UNKNOWN_OP',
        'fact', 'op is one of set_price, add_service, update_service, remove_service, add_faq, update_faq, remove_faq, add_offer, end_offer, add_rule, remove_rule');
    end if;
  end loop;

  if jsonb_array_length(v_entries) = 0 then
    return jsonb_build_object('ok', false, 'error', 'NOTHING_TO_CHANGE', 'problems', v_problems);
  end if;

  insert into clinic.catalog_changes (tenant_id, source, request, entries, summary_ar, created_by, created_by_name)
  values (p_tenant, coalesce(p_source, 'dashboard'), p_changes, v_entries, array_to_string(v_lines, E'\n'),
          clinic.current_user_id(), clinic.my_name(p_tenant))
  returning id into v_id;

  if p_apply then
    return clinic.catalog_apply(v_id) || jsonb_build_object('problems', v_problems);
  end if;
  return jsonb_build_object('ok', true, 'status', 'PREVIEW', 'change_id', v_id, 'summary_ar', array_to_string(v_lines, E'\n'),
                            'entries', v_entries, 'problems', v_problems,
                            'fact', 'shown, not applied: apply it with the change_id once the doctor agrees');
end $$;

create or replace function clinic.catalog_apply(p_change bigint)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare
  ch clinic.catalog_changes%rowtype;
  e  jsonb;
begin
  select * into ch from clinic.catalog_changes where id = p_change for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'CHANGE_NOT_FOUND'); end if;
  perform clinic.require_role(ch.tenant_id, array['owner', 'manager', 'doctor']);
  if ch.status <> 'pending' then
    return jsonb_build_object('ok', false, 'error', 'ALREADY_' || upper(ch.status), 'change_id', ch.id);
  end if;
  for e in select * from jsonb_array_elements(ch.entries) loop
    perform clinic.catalog_put(e ->> 'table', e -> 'after');
  end loop;
  update clinic.catalog_changes set status = 'applied', applied_at = now() where id = ch.id;
  insert into clinic.audit_log (tenant_id, user_id, action, entity, entity_id, detail)
  values (ch.tenant_id, clinic.current_user_id(), 'catalog_change', 'catalog_changes', ch.id::text,
          jsonb_build_object('source', ch.source, 'summary', ch.summary_ar));
  return jsonb_build_object('ok', true, 'status', 'APPLIED', 'change_id', ch.id, 'summary_ar', ch.summary_ar,
                            'fact', 'saved — the agent uses it from the next message');
end $$;

create or replace function clinic.catalog_undo(p_change bigint)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare
  ch clinic.catalog_changes%rowtype;
  e  jsonb;
begin
  select * into ch from clinic.catalog_changes where id = p_change for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'CHANGE_NOT_FOUND'); end if;
  perform clinic.require_role(ch.tenant_id, array['owner', 'manager', 'doctor']);
  if ch.status = 'pending' then
    update clinic.catalog_changes set status = 'discarded' where id = ch.id;
    return jsonb_build_object('ok', true, 'status', 'DISCARDED', 'change_id', ch.id);
  end if;
  if ch.status <> 'applied' then return jsonb_build_object('ok', false, 'error', 'ALREADY_' || upper(ch.status)); end if;
  for e in select x from jsonb_array_elements(ch.entries) with ordinality as a(x, n) order by n desc loop
    if e -> 'before' is null or jsonb_typeof(e -> 'before') = 'null' then
      execute format('delete from clinic.%I where id = $1', e ->> 'table') using (e ->> 'id')::uuid;
    else
      perform clinic.catalog_put(e ->> 'table', e -> 'before');
    end if;
  end loop;
  update clinic.catalog_changes set status = 'undone', undone_at = now() where id = ch.id;
  return jsonb_build_object('ok', true, 'status', 'UNDONE', 'change_id', ch.id, 'summary_ar', ch.summary_ar);
end $$;

-- ================= 003_messaging.sql =================

-- =====================================================================
-- Everwake Clinic · 003 · WhatsApp: numbers, people who write, chats,
-- the outbox, and the engine's turn plumbing
--
-- The Everwake Orders engine (EVERWAKE-ORDERS/database/migrations 004,
-- 005, 014, 015), adapted:
--   · a customer is a `contact`: the WhatsApp person who writes. One
--     contact can book for several patients (a mother for her children);
--     004 links them.
--   · intake() finds the clinic from the Evolution instance (and its
--     token), the contact by any identity (number or private id), logs
--     the message once, and routes it: agent · human · paused · not_live
--     · staff (a team member's own number: the doctor's commands, e.g.
--     "هتأخر 20 دقيقة") · team_answer · from_me · duplicate · ignore
--   · claim_window() debounces (only the run holding the newest message
--     answers, and it bundles them), persist_turn() saves memory, asks
--     the team, raises alerts, unlocks; a reply is dropped when the
--     patient wrote again meanwhile, unless the turn did something final
--   · everything the clinic sends (reminders, delay notices, staff
--     replies…) goes through `outbox`, spaced with not_before
-- =====================================================================

create table clinic.whatsapp_channels (
  id                    uuid primary key default gen_random_uuid(),
  tenant_id             uuid not null references clinic.tenants(id) on delete cascade,
  provider              text not null default 'evolution' check (provider in ('evolution', 'cloud_api')),
  label                 text,
  phone_number          text,
  instance_name         text,
  base_url              text,
  api_key               text,             -- secret: never readable from the dashboard
  cloud_phone_number_id text,
  cloud_access_token    text,             -- secret
  webhook_token         text not null default clinic.random_token(),
  status                text not null default 'pending' check (status in ('pending', 'connected', 'disconnected')),
  is_active             boolean not null default true,
  last_inbound_at       timestamptz,
  connected_at          timestamptz,
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now()
);
create unique index whatsapp_channels_instance_uidx on clinic.whatsapp_channels (instance_name)
  where provider = 'evolution' and instance_name is not null;
create unique index whatsapp_channels_cloud_uidx on clinic.whatsapp_channels (cloud_phone_number_id)
  where provider = 'cloud_api' and cloud_phone_number_id is not null;

create table clinic.contacts (
  id            bigint generated always as identity primary key,
  tenant_id     uuid not null references clinic.tenants(id) on delete cascade,
  wa_id         text not null,          -- the conversation key: real number, else the lid digits
  reply_to      text,                   -- where replies go (number, or the full "…@lid")
  phone         text,
  lid           text,
  phone_hidden  boolean not null default false,
  display_name  text,                   -- WhatsApp profile name
  full_name     text,
  language      text,
  notes         text,
  tags          text[] not null default '{}',
  is_blocked    boolean not null default false,
  first_seen_at timestamptz not null default now(),
  last_seen_at  timestamptz not null default now(),
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  unique (tenant_id, wa_id)
);
create index contacts_phone_idx on clinic.contacts (tenant_id, phone) where phone is not null;

create table clinic.contact_identities (
  tenant_id  uuid not null references clinic.tenants(id) on delete cascade,
  kind       text not null check (kind in ('phone', 'lid')),
  value      text not null,
  contact_id bigint not null references clinic.contacts(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (tenant_id, kind, value)
);
create index contact_identities_contact_idx on clinic.contact_identities (contact_id);

create table clinic.conversations (
  id                     bigint generated always as identity primary key,
  tenant_id              uuid not null references clinic.tenants(id) on delete cascade,
  contact_id             bigint references clinic.contacts(id) on delete set null,
  wa_id                  text not null,
  kind                   text not null default 'patient' check (kind in ('patient', 'staff')),
  -- the engine's working memory (contact, patient, last offered slots, pending reminder, ledger, notes)
  state                  jsonb not null default '{}'::jsonb,
  mode                   text not null default 'agent' check (mode in ('agent', 'human')),
  assigned_user_id       uuid,
  human_since            timestamptz,
  human_last_activity_at timestamptz,
  human_reason           text,
  needs_attention        boolean not null default false,
  attention_reason       text,
  attention_at           timestamptz,
  urgency                text check (urgency in ('emergency', 'urgent')),   -- the last red flag, until resolved
  questions_open         int not null default 0,
  unread_count           int not null default 0,
  last_message_at        timestamptz,
  last_inbound_at        timestamptz,
  last_outbound_at       timestamptz,
  last_message_preview   text,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  unique (tenant_id, wa_id)
);
create index conversations_inbox_idx on clinic.conversations (tenant_id, last_message_at desc);

create table clinic.messages (
  id              bigint generated always as identity primary key,
  tenant_id       uuid not null references clinic.tenants(id) on delete cascade,
  conversation_id bigint references clinic.conversations(id) on delete cascade,
  wa_id           text not null,
  direction       text not null check (direction in ('inbound', 'outbound')),
  sender          text not null check (sender in ('patient', 'agent', 'staff', 'system')),
  staff_user_id   uuid,
  kind            text not null default 'text',
  body            text,
  media_url       text,
  media_mime      text,
  external_id     text,
  status          text not null default 'received'
                  check (status in ('received', 'queued', 'sending', 'sent', 'delivered', 'read', 'failed', 'cancelled')),
  error           text,
  run_id          text,
  meta            jsonb not null default '{}'::jsonb,
  raw_payload     jsonb,
  created_at      timestamptz not null default now(),
  sent_at         timestamptz
);
create unique index messages_external_uidx on clinic.messages (tenant_id, external_id) where external_id is not null;
create index messages_thread_idx on clinic.messages (tenant_id, wa_id, created_at desc);
create index messages_conversation_idx on clinic.messages (conversation_id, created_at desc);

create table clinic.outbox (
  id           bigint generated always as identity primary key,
  tenant_id    uuid not null references clinic.tenants(id) on delete cascade,
  channel_id   uuid references clinic.whatsapp_channels(id) on delete set null,
  to_jid       text not null,
  wa_id        text,
  message_id   bigint references clinic.messages(id) on delete set null,
  purpose      text not null check (purpose ~ '^[a-z_]{2,40}$'),
  template_key text,                     -- the approved template it maps to on the Cloud API
  kind         text not null default 'text' check (kind in ('text', 'image', 'document', 'location')),
  body         text,
  media_url    text,
  media_mime   text,
  file_name    text,
  meta         jsonb not null default '{}'::jsonb,
  status       text not null default 'queued' check (status in ('queued', 'sending', 'sent', 'failed', 'cancelled')),
  attempts     int not null default 0,
  last_error   text,
  not_before   timestamptz not null default now(),
  claimed_at   timestamptz,
  claimed_by   text,
  sent_at      timestamptz,
  external_id  text,
  created_by   uuid,
  created_at   timestamptz not null default now()
);
create index outbox_pending_idx on clinic.outbox (not_before) where status in ('queued', 'sending');
create index outbox_tenant_idx on clinic.outbox (tenant_id, created_at desc);

create table clinic.inbound_buffer (
  id                bigint generated always as identity primary key,
  tenant_id         uuid not null references clinic.tenants(id) on delete cascade,
  wa_id             text not null,
  message_text      text,
  has_location      boolean not null default false,
  location          jsonb,
  media_pending     boolean not null default false,
  received_at       timestamptz not null default now(),
  claimed_by_run_id text
);
create index inbound_buffer_wa_idx on clinic.inbound_buffer (tenant_id, wa_id, claimed_by_run_id);

create table clinic.conversation_locks (
  tenant_id  uuid not null references clinic.tenants(id) on delete cascade,
  wa_id      text not null,
  run_id     text not null,
  locked_at  timestamptz not null default now(),
  expires_at timestamptz not null,
  primary key (tenant_id, wa_id)
);

create table clinic.team_questions (
  id               bigint generated always as identity primary key,
  tenant_id        uuid not null references clinic.tenants(id) on delete cascade,
  conversation_id  bigint not null references clinic.conversations(id) on delete cascade,
  wa_id            text not null,
  question         text not null,
  run_id           text,
  asked_at         timestamptz not null default now(),
  status           text not null default 'open' check (status in ('open', 'answered', 'dismissed')),
  answer_kind      text check (answer_kind in ('yes', 'no', 'text')),
  answer           text,
  answered_by      uuid,
  answered_by_name text,
  answered_at      timestamptz,
  told_at          timestamptz
);
create index team_questions_chat_idx on clinic.team_questions (tenant_id, wa_id, asked_at desc);
create index team_questions_open_idx on clinic.team_questions (tenant_id, status) where status = 'open';

create table clinic.agent_pauses (
  id               bigint generated always as identity primary key,
  tenant_id        uuid not null references clinic.tenants(id) on delete cascade,
  started_at       timestamptz not null default now(),
  ended_at         timestamptz,
  started_by       uuid,
  ended_by         uuid,
  reason           text,
  notify_on_resume boolean not null default true,
  contacts_count   int not null default 0,
  notified_count   int not null default 0
);
alter table clinic.tenants add constraint tenants_current_pause_fk foreign key (current_pause_id)
  references clinic.agent_pauses(id) on delete set null;

create table clinic.pause_contacts (
  pause_id           bigint not null references clinic.agent_pauses(id) on delete cascade,
  tenant_id          uuid not null references clinic.tenants(id) on delete cascade,
  wa_id              text not null,
  reply_to           text,
  channel_id         uuid references clinic.whatsapp_channels(id) on delete set null,
  contact_id         bigint references clinic.contacts(id) on delete set null,
  first_message_at   timestamptz not null default now(),
  last_message_at    timestamptz not null default now(),
  messages_count     int not null default 1,
  apologized_at      timestamptz,
  resume_notified_at timestamptz,
  primary key (pause_id, wa_id)
);

create table clinic.agent_events (
  id                bigint generated always as identity primary key,
  tenant_id         uuid not null references clinic.tenants(id) on delete cascade,
  wa_id             text,
  run_id            text,
  stage             text,
  booking_stage     text,
  tool_action       text,
  qa_passed         boolean,
  repair_used       boolean,
  llm_calls         int,
  duration_total_ms int,
  duration_llm_ms   int,
  prompt_tokens     int,
  completion_tokens int,
  cached_tokens     int,
  input             jsonb,
  output            jsonb,
  created_at        timestamptz not null default now()
);
create index agent_events_tenant_idx on clinic.agent_events (tenant_id, created_at desc);

do $$
declare t text;
begin
  foreach t in array array['whatsapp_channels', 'contacts', 'conversations'] loop
    execute format('create trigger %I before update on clinic.%I for each row execute function clinic.touch_updated_at()', t || '_touch', t);
  end loop;
  execute 'create trigger whatsapp_channels_audit after insert or update or delete on clinic.whatsapp_channels
             for each row execute function clinic.audit_change()';
end $$;

-- ---------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------
create or replace function clinic.contact_language(p_tenant uuid, p_wa text)
returns text language sql stable as $$
  select coalesce(nullif(c.state ->> 'last_language', ''), co.language, t.default_language, 'ar')
    from clinic.tenants t
    left join clinic.conversations c on c.tenant_id = t.id and c.wa_id = p_wa
    left join clinic.contacts co on co.id = c.contact_id
   where t.id = p_tenant
$$;

-- the Test Runner's pretend numbers: 200000000001 … 200000000099
create or replace function clinic.is_test_number(p_wa text)
returns boolean language sql immutable as $$
  select coalesce(p_wa ~ '^20000000000[0-9]$|^2000000000[1-9][0-9]$', false)
$$;

-- a contact the clinic can write to (also one added from the dashboard by phone)
create or replace function clinic.ensure_contact(p_tenant uuid, p_phone text, p_name text default null)
returns clinic.contacts language plpgsql as $$
declare
  v_phone text := clinic.wa_phone(p_phone, (select country from clinic.tenants where id = p_tenant));
  v_id    bigint;
  c       clinic.contacts%rowtype;
begin
  if v_phone is null then return null; end if;
  select ci.contact_id into v_id from clinic.contact_identities ci
   where ci.tenant_id = p_tenant and ci.kind = 'phone' and ci.value = v_phone;
  if v_id is null then
    insert into clinic.contacts (tenant_id, wa_id, reply_to, phone, full_name)
    values (p_tenant, v_phone, v_phone, v_phone, nullif(btrim(coalesce(p_name, '')), ''))
    on conflict (tenant_id, wa_id) do update set last_seen_at = clinic.contacts.last_seen_at
    returning id into v_id;
    insert into clinic.contact_identities (tenant_id, kind, value, contact_id)
    values (p_tenant, 'phone', v_phone, v_id) on conflict do nothing;
  end if;
  select * into c from clinic.contacts where id = v_id;
  return c;
end $$;

create or replace function clinic.ensure_conversation(p_tenant uuid, p_wa text)
returns clinic.conversations language plpgsql as $$
declare
  conv clinic.conversations%rowtype;
  co   clinic.contacts%rowtype;
begin
  select * into conv from clinic.conversations where tenant_id = p_tenant and wa_id = p_wa;
  if found then return conv; end if;
  select * into co from clinic.contacts where tenant_id = p_tenant and wa_id = p_wa;
  if not found then return null; end if;
  insert into clinic.conversations (tenant_id, contact_id, wa_id, state)
  values (p_tenant, co.id, co.wa_id, jsonb_build_object('contact', jsonb_build_object('reply_to', co.reply_to, 'phone_hidden', co.phone_hidden)))
  on conflict (tenant_id, wa_id) do update set updated_at = now()
  returning * into conv;
  return conv;
end $$;

-- ---------------------------------------------------------------------
-- The outbox
-- ---------------------------------------------------------------------
create or replace function clinic.queue_message(
  p_tenant uuid, p_wa text, p_purpose text, p_body text,
  p_kind text default 'text', p_media_url text default null, p_media_mime text default null,
  p_file_name text default null, p_sender text default 'system', p_user uuid default null,
  p_not_before timestamptz default now(), p_template text default null, p_meta jsonb default '{}'::jsonb)
returns jsonb language plpgsql as $$
declare
  conv  clinic.conversations%rowtype;
  co    clinic.contacts%rowtype;
  v_ch  uuid;
  v_to  text;
  v_msg bigint;
  v_out bigint;
begin
  conv := clinic.ensure_conversation(p_tenant, p_wa);
  if conv.id is null then
    return jsonb_build_object('skipped', true, 'reason', 'no_contact');
  end if;
  select * into co from clinic.contacts where id = conv.contact_id;
  if coalesce(co.is_blocked, false) then return jsonb_build_object('skipped', true, 'reason', 'blocked'); end if;
  select ch.id into v_ch
    from clinic.whatsapp_channels ch
   where ch.tenant_id = p_tenant and ch.is_active
   order by (ch.id::text = conv.state -> 'contact' ->> 'channel_id') desc, ch.created_at
   limit 1;
  v_to := coalesce(nullif(conv.state -> 'contact' ->> 'reply_to', ''), co.reply_to, p_wa);

  insert into clinic.messages (tenant_id, conversation_id, wa_id, direction, sender, staff_user_id, kind, body,
                               media_url, media_mime, status, meta)
  values (p_tenant, conv.id, p_wa, 'outbound', p_sender, p_user, p_kind, p_body, p_media_url, p_media_mime, 'queued',
          jsonb_build_object('purpose', p_purpose) || coalesce(p_meta, '{}'::jsonb))
  returning id into v_msg;

  insert into clinic.outbox (tenant_id, channel_id, to_jid, wa_id, message_id, purpose, template_key, kind, body, media_url,
                             media_mime, file_name, meta, not_before, created_by)
  values (p_tenant, v_ch, v_to, p_wa, v_msg, p_purpose, p_template, p_kind, p_body, p_media_url, p_media_mime, p_file_name,
          coalesce(p_meta, '{}'::jsonb), p_not_before, p_user)
  returning id into v_out;

  update clinic.conversations
     set last_message_at = greatest(coalesce(last_message_at, now()), now()),
         last_message_preview = left(coalesce(p_body, '[' || p_kind || ']'), 160)
   where id = conv.id;
  return jsonb_build_object('outbox_id', v_out, 'message_id', v_msg);
end $$;

-- a message to a team member's own WhatsApp (an emergency, a doctor's alert) — not a chat
create or replace function clinic.queue_ops_message(p_tenant uuid, p_phone text, p_purpose text, p_body text)
returns boolean language plpgsql as $$
declare
  v_ch uuid;
  v_to text := clinic.wa_phone(p_phone, (select country from clinic.tenants where id = p_tenant));
begin
  if v_to is null or coalesce(btrim(p_body), '') = '' then return false; end if;
  select id into v_ch from clinic.whatsapp_channels where tenant_id = p_tenant and is_active order by created_at limit 1;
  insert into clinic.outbox (tenant_id, channel_id, to_jid, purpose, body) values (p_tenant, v_ch, v_to, p_purpose, p_body);
  return true;
end $$;

create or replace function clinic.outbox_claim(p_limit int default 20, p_worker text default 'n8n')
returns jsonb language plpgsql as $$
declare v jsonb;
begin
  update clinic.outbox o
     set status = 'failed', last_error = 'No WhatsApp number is connected for this clinic.'
   where o.status = 'queued' and o.not_before <= now()
     and not exists (select 1 from clinic.whatsapp_channels ch where ch.id = o.channel_id and ch.is_active);
  update clinic.messages m set status = 'failed', error = 'No WhatsApp number is connected.'
    from clinic.outbox o
   where o.message_id = m.id and o.status = 'failed' and m.status = 'queued';

  with c as (
    select o.id from clinic.outbox o
     where o.status = 'queued' and o.not_before <= now()
     order by o.not_before, o.id
     for update skip locked
     limit greatest(1, least(p_limit, 100))
  ), u as (
    update clinic.outbox o
       set status = 'sending', claimed_at = now(), claimed_by = p_worker, attempts = o.attempts + 1
      from c where o.id = c.id
    returning o.*
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', u.id, 'tenant_id', u.tenant_id, 'wa_id', u.wa_id, 'to', u.to_jid, 'purpose', u.purpose,
           'kind', u.kind, 'body', u.body, 'media_url', u.media_url, 'media_mime', u.media_mime,
           'file_name', u.file_name, 'meta', u.meta, 'attempts', u.attempts,
           'channel', jsonb_build_object('id', ch.id, 'provider', ch.provider, 'base_url', rtrim(ch.base_url, '/'),
                                         'instance', ch.instance_name, 'api_key', ch.api_key))
         order by u.id), '[]'::jsonb)
    into v
    from u join clinic.whatsapp_channels ch on ch.id = u.channel_id;

  update clinic.messages m set status = 'sending'
    from clinic.outbox o
   where o.message_id = m.id and o.status = 'sending' and m.status = 'queued';
  return v;
end $$;

create or replace function clinic.outbox_result(p jsonb)
returns jsonb language plpgsql as $$
declare
  o     clinic.outbox%rowtype;
  v_ok  boolean := coalesce((p ->> 'ok')::boolean, false);
  v_fin boolean;
begin
  select * into o from clinic.outbox where id = (p ->> 'id')::bigint for update;
  if not found then return jsonb_build_object('updated', false); end if;
  v_fin := v_ok or o.attempts >= 3;
  update clinic.outbox
     set status = case when v_ok then 'sent' when v_fin then 'failed' else 'queued' end,
         sent_at = case when v_ok then now() end,
         external_id = nullif(p ->> 'external_id', ''),
         last_error = case when v_ok then null else left(coalesce(p ->> 'error', 'send failed'), 500) end,
         not_before = case when v_ok or v_fin then not_before else now() + make_interval(secs => 30 * o.attempts) end
   where id = o.id;
  if o.message_id is not null then
    update clinic.messages
       set status = case when v_ok then 'sent' when v_fin then 'failed' else 'queued' end,
           external_id = coalesce(nullif(p ->> 'external_id', ''), external_id),
           sent_at = case when v_ok then now() else sent_at end,
           error = case when v_ok then null else left(coalesce(p ->> 'error', 'send failed'), 500) end
     where id = o.message_id
       and not exists (select 1 from clinic.messages x
                        where x.tenant_id = o.tenant_id and x.external_id = nullif(p ->> 'external_id', '') and x.id <> o.message_id);
  end if;
  if v_ok and o.wa_id is not null then
    update clinic.conversations set last_outbound_at = now() where tenant_id = o.tenant_id and wa_id = o.wa_id;
  end if;
  return jsonb_build_object('updated', true, 'final', v_fin, 'ok', v_ok);
end $$;

-- ---------------------------------------------------------------------
-- Intake: one inbound WhatsApp message
-- ---------------------------------------------------------------------
create or replace function clinic.staff_by_phone(p_tenant uuid, p_phone text)
returns jsonb language sql stable as $$
  select coalesce(
    (select jsonb_build_object('kind', 'member', 'user_id', m.user_id, 'role', m.role, 'doctor_id', m.doctor_id,
                               'clinical', m.clinical, 'name', coalesce(m.display_name, m.email))
       from clinic.tenant_members m
      where m.tenant_id = p_tenant and p_phone is not null and m.phone = p_phone
      order by (m.role = 'owner') desc limit 1),
    (select jsonb_build_object('kind', 'doctor', 'user_id', d.user_id, 'role', 'doctor', 'doctor_id', d.id,
                               'clinical', true, 'name', clinic.doctor_label(d.id, 'ar'))
       from clinic.doctors d
      where d.tenant_id = p_tenant and d.is_active and p_phone is not null and clinic.wa_phone(d.ops_whatsapp) = p_phone
      limit 1))
$$;

create or replace function clinic.intake(p jsonb)
returns jsonb language plpgsql as $$
declare
  ch        clinic.whatsapp_channels%rowtype;
  t         clinic.tenants%rowtype;
  s         jsonb;
  co        clinic.contacts%rowtype;
  conv      clinic.conversations%rowtype;
  v_phone   text := nullif(clinic.digits(p ->> 'phone'), '');
  v_lid     text := nullif(clinic.digits(p ->> 'lid'), '');
  v_wa      text := nullif(btrim(p ->> 'wa_id'), '');
  v_reply   text := nullif(btrim(p ->> 'reply_to'), '');
  v_text    text := coalesce(p ->> 'text', '');
  v_cid     bigint;
  v_msg     bigint;
  v_buf     bigint;
  v_lang    text;
  v_release int;
  v_pc      clinic.pause_contacts%rowtype;
  v_pause   bigint;
  v_send    boolean := false;
  v_apology text;
  base      jsonb;
  v_q       clinic.messages%rowtype;
  v_quote   text;
  v_staff   jsonb;
begin
  select * into ch from clinic.whatsapp_channels
   where provider = coalesce(nullif(p ->> 'provider', ''), 'evolution')
     and instance_name = p ->> 'instance' and is_active;
  if not found then return jsonb_build_object('route', 'ignore', 'reason', 'unknown_channel'); end if;
  if coalesce(p ->> 'token', '') <> ch.webhook_token then
    return jsonb_build_object('route', 'ignore', 'reason', 'bad_token');
  end if;
  select * into t from clinic.tenants where id = ch.tenant_id;
  if t.status in ('suspended', 'cancelled') then
    return jsonb_build_object('route', 'ignore', 'reason', 'tenant_' || t.status);
  end if;
  update clinic.whatsapp_channels
     set last_inbound_at = now(), status = 'connected', connected_at = coalesce(connected_at, now())
   where id = ch.id;
  s := clinic.merged_settings(t.settings);

  base := jsonb_build_object(
    'tenant_id', t.id, 'tenant_slug', t.slug, 'tenant_status', t.status, 'timezone', t.timezone,
    'channel', jsonb_build_object('id', ch.id, 'provider', ch.provider, 'base_url', rtrim(ch.base_url, '/'),
                                  'instance', ch.instance_name, 'api_key', ch.api_key));

  if coalesce((p ->> 'from_me')::boolean, false) then
    return base || jsonb_build_object('route', 'from_me');
  end if;
  if v_wa is null then return base || jsonb_build_object('route', 'ignore', 'reason', 'no_sender'); end if;

  -- the team answered a question the agent asked: the agent passes it on
  if p ->> 'kind' = 'team_answer' then
    select * into conv from clinic.conversations where tenant_id = t.id and wa_id = v_wa;
    if not found or not exists (select 1 from clinic.team_questions q
                                 where q.tenant_id = t.id and q.wa_id = v_wa and q.status = 'answered' and q.told_at is null) then
      return base || jsonb_build_object('route', 'ignore', 'reason', 'no_new_answer');
    end if;
    select * into co from clinic.contacts where id = conv.contact_id;
    base := base || jsonb_build_object('contact_id', co.id, 'conversation_id', conv.id, 'wa_id', co.wa_id,
                                       'reply_to', co.reply_to, 'phone_hidden', co.phone_hidden, 'team_answer', true);
    if co.is_blocked or conv.mode = 'human' or not t.agent_enabled then
      return base || jsonb_build_object('route', 'ignore', 'reason', 'agent_not_answering');
    end if;
    insert into clinic.inbound_buffer (tenant_id, wa_id, message_text) values (t.id, co.wa_id, '') returning id into v_buf;
    return base || jsonb_build_object('route', 'agent', 'buffer_id', v_buf);
  end if;

  -- the contact, by any identity -------------------------------------------
  select ci.contact_id into v_cid
    from clinic.contact_identities ci
   where ci.tenant_id = t.id
     and ((ci.kind = 'phone' and ci.value = v_phone) or (ci.kind = 'lid' and ci.value = v_lid))
   order by (ci.kind = 'phone') desc
   limit 1;
  if v_cid is null then
    select id into v_cid from clinic.contacts where tenant_id = t.id and wa_id = v_wa;
  end if;
  if v_cid is null then
    insert into clinic.contacts (tenant_id, wa_id, reply_to, phone, lid, phone_hidden, display_name)
    values (t.id, v_wa, coalesce(v_reply, v_wa), v_phone, v_lid, v_phone is null, nullif(btrim(p ->> 'push_name'), ''))
    on conflict (tenant_id, wa_id) do update set last_seen_at = now()
    returning id into v_cid;
  end if;
  update clinic.contacts c
     set phone        = coalesce(c.phone, v_phone),
         lid          = coalesce(c.lid, v_lid),
         phone_hidden = coalesce(c.phone, v_phone) is null,
         reply_to     = case when v_phone is not null then v_phone else coalesce(v_reply, c.reply_to) end,
         display_name = coalesce(nullif(btrim(p ->> 'push_name'), ''), c.display_name),
         last_seen_at = now()
   where c.id = v_cid
  returning * into co;
  if v_phone is not null then
    insert into clinic.contact_identities (tenant_id, kind, value, contact_id) values (t.id, 'phone', v_phone, v_cid) on conflict do nothing;
  end if;
  if v_lid is not null then
    insert into clinic.contact_identities (tenant_id, kind, value, contact_id) values (t.id, 'lid', v_lid, v_cid) on conflict do nothing;
  end if;

  -- a swipe-reply: what they replied to, in words
  if jsonb_typeof(p -> 'quoted') = 'object' then
    select * into v_q from clinic.messages m
     where m.tenant_id = t.id and m.external_id = nullif(p -> 'quoted' ->> 'id', '') limit 1;
    v_quote := case
      when v_q.id is null then
        case when coalesce(p -> 'quoted' ->> 'text', '') <> '' then 'replying to: "' || left(p -> 'quoted' ->> 'text', 300) || '"'
             when coalesce(p -> 'quoted' ->> 'kind', '') <> '' then 'replying to a ' || (p -> 'quoted' ->> 'kind') end
      when v_q.direction = 'inbound' then 'replying to their own earlier message: "' || left(coalesce(v_q.body, '[' || v_q.kind || ']'), 300) || '"'
      when v_q.meta ->> 'purpose' in ('reminder', 'delay_notice', 'delay_followup', 'session_cancelled', 'waitlist_offer', 'booking_moved')
        then 'replying to the clinic''s ' || replace(v_q.meta ->> 'purpose', '_', ' ') || ': "' || left(coalesce(v_q.body, ''), 300) || '"'
      else 'replying to ' || case v_q.sender when 'agent' then 'your message' when 'staff' then 'the team''s message' else 'the automatic message' end
           || ': "' || left(coalesce(v_q.body, ''), 300) || '"' end;
  end if;

  v_staff := case when v_phone is not null and not coalesce((p ->> 'test_run')::boolean, false)
                  then clinic.staff_by_phone(t.id, v_phone) end;

  -- the message, exactly once (Evolution can deliver twice)
  insert into clinic.messages (tenant_id, wa_id, direction, sender, kind, body, external_id, raw_payload, meta)
  values (t.id, co.wa_id, 'inbound', case when v_staff is not null then 'staff' else 'patient' end,
          coalesce(nullif(p ->> 'message_type', ''), 'text'), v_text,
          nullif(p ->> 'external_id', ''), p -> 'raw',
          jsonb_strip_nulls(jsonb_build_object('location', p -> 'location', 'push_name', p ->> 'push_name',
                                               'channel_id', ch.id, 'reply_to', v_quote,
                                               'staff', case when v_staff is not null then true end)))
  on conflict (tenant_id, external_id) where external_id is not null do nothing
  returning id into v_msg;
  if v_msg is null then return base || jsonb_build_object('route', 'duplicate', 'wa_id', co.wa_id); end if;

  insert into clinic.conversations as c
    (tenant_id, contact_id, wa_id, kind, state, last_message_at, last_inbound_at, unread_count, last_message_preview)
  values (t.id, v_cid, co.wa_id, case when v_staff is not null then 'staff' else 'patient' end,
          jsonb_build_object('contact', jsonb_build_object('reply_to', co.reply_to, 'phone_hidden', co.phone_hidden,
                                                           'channel_id', ch.id)),
          now(), now(), 1, left(v_text, 160))
  on conflict (tenant_id, wa_id) do update
    set state = c.state || jsonb_build_object('contact', coalesce(c.state -> 'contact', '{}'::jsonb) || (excluded.state -> 'contact')),
        contact_id = coalesce(c.contact_id, excluded.contact_id),
        kind = excluded.kind,
        last_message_at = now(), last_inbound_at = now(),
        unread_count = c.unread_count + 1,
        last_message_preview = excluded.last_message_preview
  returning * into conv;
  update clinic.messages set conversation_id = conv.id where id = v_msg;

  base := base || jsonb_build_object('contact_id', co.id, 'conversation_id', conv.id, 'message_id', v_msg,
                                     'wa_id', co.wa_id, 'reply_to', co.reply_to, 'phone_hidden', co.phone_hidden);

  if co.is_blocked then return base || jsonb_build_object('route', 'ignore', 'reason', 'blocked'); end if;

  -- a team member's own number: their commands go to the staff assistant
  if v_staff is not null then
    if conv.mode = 'human' then return base || jsonb_build_object('route', 'human'); end if;
    insert into clinic.inbound_buffer (tenant_id, wa_id, message_text, media_pending)
    values (t.id, co.wa_id, case when v_quote is not null then '[' || v_quote || '] ' || v_text else v_text end,
            coalesce(jsonb_typeof(p -> 'media') = 'object', false))
    returning id into v_buf;
    return base || jsonb_build_object('route', 'staff', 'buffer_id', v_buf, 'staff', v_staff);
  end if;

  -- a person took over: the agent stays quiet unless the person went idle
  if conv.mode = 'human' then
    v_release := coalesce((s ->> 'human_auto_release_minutes')::int, 0);
    if v_release > 0 and coalesce(conv.human_last_activity_at, conv.human_since, now())
                         < now() - make_interval(mins => v_release) then
      update clinic.conversations
         set mode = 'agent', assigned_user_id = null, human_since = null, human_reason = null,
             state = state || jsonb_build_object('handback', jsonb_build_object('at', now(), 'by', 'auto', 'human_since', conv.human_since))
       where id = conv.id;
    else
      return base || jsonb_build_object('route', 'human');
    end if;
  end if;

  -- the agent is OFF: one apology, remembered for "we're back"
  if not t.agent_enabled then
    v_pause := t.current_pause_id;
    if v_pause is null then
      insert into clinic.agent_pauses (tenant_id, reason) values (t.id, 'switched off') returning id into v_pause;
      update clinic.tenants set current_pause_id = v_pause where id = t.id;
    end if;
    insert into clinic.pause_contacts as pc (pause_id, tenant_id, wa_id, reply_to, channel_id, contact_id)
    values (v_pause, t.id, co.wa_id, co.reply_to, ch.id, co.id)
    on conflict (pause_id, wa_id) do update
      set last_message_at = now(), messages_count = pc.messages_count + 1, reply_to = excluded.reply_to, channel_id = excluded.channel_id
    returning * into v_pc;
    if v_pc.apologized_at is null then
      update clinic.pause_contacts set apologized_at = now() where pause_id = v_pc.pause_id and wa_id = v_pc.wa_id;
      update clinic.agent_pauses set contacts_count = contacts_count + 1 where id = v_pause;
      v_lang := case when v_text ~ '[ء-ي]' then 'ar' when v_text ~ '[A-Za-z]' then 'en' else coalesce(co.language, t.default_language) end;
      v_apology := clinic.render_template(s -> 'templates' ->> ('pause_apology_' || v_lang),
                                          jsonb_build_object('name', clinic.first_name(co.full_name, co.display_name)));
      v_send := true;
    end if;
    return base || jsonb_build_object('route', 'paused', 'send_apology', v_send, 'apology_text', v_apology, 'pause_id', v_pause);
  end if;

  -- still onboarding: only the clinic's test numbers (and the Test Runner) reach the agent
  if t.status = 'onboarding'
     and not (coalesce((p ->> 'test_run')::boolean, false) and clinic.is_test_number(co.wa_id))
     and not (coalesce(s -> 'test_numbers', '[]'::jsonb) ? co.wa_id
              or (co.phone is not null and coalesce(s -> 'test_numbers', '[]'::jsonb) ? co.phone)) then
    return base || jsonb_build_object('route', 'not_live');
  end if;

  insert into clinic.inbound_buffer (tenant_id, wa_id, message_text, has_location, location, media_pending)
  values (t.id, co.wa_id, case when v_quote is not null then '[' || v_quote || '] ' || v_text else v_text end,
          coalesce((p ->> 'has_location')::boolean, false), p -> 'location',
          coalesce(jsonb_typeof(p -> 'media') = 'object', false) and not coalesce((p ->> 'test_run')::boolean, false))
  returning id into v_buf;
  return base || jsonb_build_object('route', 'agent', 'buffer_id', v_buf);
end $$;

-- a message the clinic typed on the phone itself (fromMe), a few seconds later
create or replace function clinic.log_phone_reply(p jsonb)
returns jsonb language plpgsql as $$
declare
  ch     clinic.whatsapp_channels%rowtype;
  t      clinic.tenants%rowtype;
  s      jsonb;
  v_wa   text;
  v_cid  bigint;
  v_conv bigint;
  v_text text := coalesce(p ->> 'text', '');
  v_msg  bigint;
  v_take boolean;
begin
  select * into ch from clinic.whatsapp_channels
   where provider = coalesce(nullif(p ->> 'provider', ''), 'evolution') and instance_name = p ->> 'instance' and is_active;
  if not found or coalesce(p ->> 'token', '') <> ch.webhook_token then
    return jsonb_build_object('logged', false, 'reason', 'unknown_channel');
  end if;
  select * into t from clinic.tenants where id = ch.tenant_id;
  s := clinic.merged_settings(t.settings);
  v_take := coalesce((s ->> 'phone_reply_takes_over')::boolean, true);
  if nullif(p ->> 'external_id', '') is not null
     and exists (select 1 from clinic.messages where tenant_id = t.id and external_id = p ->> 'external_id') then
    return jsonb_build_object('logged', false, 'reason', 'already_logged');
  end if;
  select ci.contact_id into v_cid
    from clinic.contact_identities ci
   where ci.tenant_id = t.id
     and ((ci.kind = 'phone' and ci.value = nullif(clinic.digits(p ->> 'phone'), ''))
       or (ci.kind = 'lid' and ci.value = nullif(clinic.digits(p ->> 'lid'), '')))
   limit 1;
  if v_cid is null then select id into v_cid from clinic.contacts where tenant_id = t.id and wa_id = p ->> 'wa_id'; end if;
  if v_cid is null then return jsonb_build_object('logged', false, 'reason', 'unknown_contact'); end if;
  select wa_id into v_wa from clinic.contacts where id = v_cid;
  if exists (select 1 from clinic.messages
              where tenant_id = t.id and wa_id = v_wa and direction = 'outbound'
                and created_at > now() - interval '3 minutes'
                and btrim(coalesce(body, '')) = btrim(v_text) and v_text <> '') then
    return jsonb_build_object('logged', false, 'reason', 'engine_echo');
  end if;
  select id into v_conv from clinic.conversations where tenant_id = t.id and wa_id = v_wa;
  insert into clinic.messages (tenant_id, conversation_id, wa_id, direction, sender, kind, body, external_id, status, sent_at, meta)
  values (t.id, v_conv, v_wa, 'outbound', 'staff', coalesce(nullif(p ->> 'message_type', ''), 'text'), v_text,
          nullif(p ->> 'external_id', ''), 'sent', now(), jsonb_build_object('via', 'phone'))
  on conflict (tenant_id, external_id) where external_id is not null do nothing
  returning id into v_msg;
  if v_msg is null then return jsonb_build_object('logged', false, 'reason', 'already_logged'); end if;
  update clinic.conversations
     set last_message_at = now(), last_outbound_at = now(), last_message_preview = left(v_text, 160),
         mode = case when v_take then 'human' else mode end,
         human_since = case when v_take then coalesce(human_since, now()) else human_since end,
         human_last_activity_at = case when v_take then now() else human_last_activity_at end,
         human_reason = case when v_take and mode = 'agent' then 'replied from the phone' else human_reason end
   where id = v_conv;
  return jsonb_build_object('logged', true, 'message_id', v_msg, 'wa_id', v_wa);
end $$;

-- ---------------------------------------------------------------------
-- Debounce window: only the run holding the newest buffered message
-- answers; it takes a lock and drains every buffered message into one turn
-- ---------------------------------------------------------------------
create or replace function clinic.claim_window(p_tenant uuid, p_wa text, p_run text, p_buffer bigint)
returns jsonb language plpgsql as $$
declare
  v_mode    text;
  v_kind    text;
  v_enabled boolean;
  v_newest  bigint;
  v_lock    text;
  r         record;
begin
  select c.mode, c.kind into v_mode, v_kind from clinic.conversations c where c.tenant_id = p_tenant and c.wa_id = p_wa;
  select t.agent_enabled into v_enabled from clinic.tenants t where t.id = p_tenant;
  if v_mode = 'human' or (not v_enabled and v_kind <> 'staff') then
    delete from clinic.inbound_buffer where tenant_id = p_tenant and wa_id = p_wa and claimed_by_run_id is null;
    return jsonb_build_object('is_newest', false, 'lock_acquired', false,
                              'blocked_reason', case when v_mode = 'human' then 'human' else 'paused' end);
  end if;
  select b.id into v_newest
    from clinic.inbound_buffer b
   where b.tenant_id = p_tenant and b.wa_id = p_wa and b.claimed_by_run_id is null
   order by b.received_at desc, b.id desc
   limit 1;
  if v_newest is distinct from p_buffer then
    return jsonb_build_object('is_newest', false, 'lock_acquired', false);
  end if;
  if exists (select 1 from clinic.inbound_buffer b
              where b.tenant_id = p_tenant and b.wa_id = p_wa and b.claimed_by_run_id is null
                and b.media_pending and b.received_at > now() - interval '60 seconds') then
    return jsonb_build_object('is_newest', true, 'lock_acquired', false, 'waiting_for_media', true);
  end if;
  insert into clinic.conversation_locks as l (tenant_id, wa_id, run_id, locked_at, expires_at)
  values (p_tenant, p_wa, p_run, now(), now() + interval '300 seconds')
  on conflict (tenant_id, wa_id) do update
    set run_id = excluded.run_id, locked_at = now(), expires_at = excluded.expires_at
    where l.expires_at < now()
  returning run_id into v_lock;
  if v_lock is null then return jsonb_build_object('is_newest', true, 'lock_acquired', false); end if;

  with drained as (
    update clinic.inbound_buffer b set claimed_by_run_id = p_run
     where b.tenant_id = p_tenant and b.wa_id = p_wa and b.claimed_by_run_id is null
    returning b.message_text, b.has_location, b.location, b.received_at
  )
  select coalesce(string_agg(nullif(d.message_text, ''), E'\n' order by d.received_at), '') as combined_text,
         coalesce(bool_or(d.has_location), false) as has_location,
         (array_remove(array_agg(d.location order by d.received_at desc), null))[1] as location,
         count(*) as buffered_count
    into r from drained d;
  return jsonb_build_object('is_newest', true, 'lock_acquired', true, 'combined_text', r.combined_text,
                            'has_location', r.has_location, 'location', r.location, 'buffered_count', r.buffered_count);
end $$;

-- a photo or voice note, understood: written into the buffer and the message
create or replace function clinic.media_understood(p jsonb)
returns jsonb language plpgsql as $$
declare
  v_text   text := nullif(btrim(p ->> 'text'), '');
  v_marker text := coalesce(p ->> 'marker', '');
  n int;
begin
  update clinic.inbound_buffer b
     set message_text = case when v_text is null then b.message_text
                             when v_marker <> '' and position(v_marker in coalesce(b.message_text, '')) > 0
                             then replace(b.message_text, v_marker, v_text)
                             else concat_ws(' ', nullif(b.message_text, ''), v_text) end,
         media_pending = false
   where b.id = (p ->> 'buffer_id')::bigint;
  get diagnostics n = row_count;
  if v_text is not null and nullif(p ->> 'message_id', '') is not null then
    update clinic.messages
       set meta = meta || jsonb_build_object('understood', v_text, 'understood_by', p ->> 'model')
     where id = (p ->> 'message_id')::bigint;
  end if;
  return jsonb_build_object('buffer_rows', n);
end $$;

-- ---------------------------------------------------------------------
-- The turn's own record: memory, the team's questions, alerts, unlock
-- ---------------------------------------------------------------------
create or replace function clinic.persist_turn(p jsonb)
returns jsonb language plpgsql as $$
declare
  v_tenant  uuid := (p ->> 'tenant_id')::uuid;
  v_wa      text := p ->> 'wa_id';
  v_run     text := p ->> 'run_id';
  v_handoff boolean := coalesce((p -> 'handoff' ->> 'needed')::boolean, false);
  v_final   boolean := coalesce((p ->> 'final')::boolean, false);
  v_take    boolean;
  v_since   timestamptz;
  v_alert   jsonb;
  n_state int; n_unlock int; n_clean int;
begin
  select l.locked_at into v_since from clinic.conversation_locks l
   where l.tenant_id = v_tenant and l.wa_id = v_wa and l.run_id = v_run;
  if not v_final and v_since is not null and exists (
       select 1 from clinic.inbound_buffer b
        where b.tenant_id = v_tenant and b.wa_id = v_wa and b.claimed_by_run_id is null and b.received_at > v_since) then
    update clinic.inbound_buffer set claimed_by_run_id = null
     where tenant_id = v_tenant and wa_id = v_wa and claimed_by_run_id = v_run;
    get diagnostics n_clean = row_count;
    delete from clinic.conversation_locks where tenant_id = v_tenant and wa_id = v_wa and run_id = v_run;
    get diagnostics n_unlock = row_count;
    insert into clinic.agent_events (tenant_id, wa_id, run_id, stage, input, output)
    values (v_tenant, v_wa, v_run, 'superseded', coalesce(p -> 'log_row' -> 'input', '{}'::jsonb),
            jsonb_build_object('dropped_reply', p -> 'log_row' -> 'output' -> 'messages'));
    return jsonb_build_object('superseded', true, 'state_written', 0, 'locks_released', n_unlock, 'buffer_rows_returned', n_clean);
  end if;

  select coalesce((clinic.merged_settings(settings) ->> 'auto_takeover_on_handoff')::boolean, false)
    into v_take from clinic.tenants where id = v_tenant;

  update clinic.conversations c
     set state = coalesce(c.state, '{}'::jsonb)
                 || coalesce(p -> 'state_patch', '{}'::jsonb)
                 || jsonb_build_object('ledger', coalesce(c.state -> 'ledger', '{}'::jsonb) || coalesce(p -> 'ledger_patch', '{}'::jsonb)),
         needs_attention  = c.needs_attention or v_handoff,
         attention_reason = case when v_handoff then nullif(p -> 'handoff' ->> 'reason', '') else c.attention_reason end,
         attention_at     = case when v_handoff then now() else c.attention_at end,
         mode             = case when v_handoff and v_take then 'human' else c.mode end,
         human_since      = case when v_handoff and v_take and c.mode = 'agent' then now() else c.human_since end,
         human_reason     = case when v_handoff and v_take and c.mode = 'agent' then 'the agent asked for a person: ' || coalesce(p -> 'handoff' ->> 'reason', '') else c.human_reason end
   where c.tenant_id = v_tenant and c.wa_id = v_wa;
  get diagnostics n_state = row_count;

  -- the agent asked the doctor or the team
  insert into clinic.team_questions (tenant_id, conversation_id, wa_id, question, run_id)
  select distinct v_tenant, c.id, v_wa, left(btrim(x), 500), v_run
    from clinic.conversations c,
         jsonb_array_elements_text(case jsonb_typeof(p -> 'ask_team') when 'array' then p -> 'ask_team'
                                        when 'string' then jsonb_build_array(p -> 'ask_team') else '[]'::jsonb end) x
   where c.tenant_id = v_tenant and c.wa_id = v_wa and btrim(x) <> ''
     and not exists (select 1 from clinic.team_questions q
                      where q.conversation_id = c.id and q.status = 'open' and q.question = left(btrim(x), 500));
  update clinic.team_questions q set told_at = now()
   where q.tenant_id = v_tenant and q.wa_id = v_wa and q.status = 'answered' and q.told_at is null
     and q.id in (select (x #>> '{}')::bigint from jsonb_array_elements(coalesce(p -> 'answers_told', '[]'::jsonb)) x);
  update clinic.conversations c
     set questions_open = (select count(*) from clinic.team_questions q where q.conversation_id = c.id and q.status = 'open')
   where c.tenant_id = v_tenant and c.wa_id = v_wa;

  -- an urgent or emergency message the engine flagged
  if jsonb_typeof(p -> 'alert') = 'object' then
    v_alert := clinic.raise_alert(p -> 'alert' || jsonb_build_object('tenant_id', v_tenant, 'wa_id', v_wa));
  end if;

  if nullif(p ->> 'language', '') is not null then
    update clinic.contacts set language = p ->> 'language'
     where tenant_id = v_tenant and wa_id = v_wa and language is distinct from p ->> 'language';
  end if;

  insert into clinic.agent_events
    (tenant_id, wa_id, run_id, stage, booking_stage, tool_action, qa_passed, repair_used, llm_calls,
     duration_total_ms, duration_llm_ms, prompt_tokens, completion_tokens, cached_tokens, input, output)
  select v_tenant, v_wa, v_run, coalesce(l ->> 'stage', 'turn_complete'), l ->> 'booking_stage', l ->> 'tool_action',
         (l ->> 'qa_passed')::boolean, (l ->> 'repair_used')::boolean, (l ->> 'llm_calls')::int,
         (l ->> 'duration_total_ms')::int, (l ->> 'duration_llm_ms')::int, (l ->> 'prompt_tokens')::int,
         (l ->> 'completion_tokens')::int, coalesce((l ->> 'cached_tokens')::int, 0),
         coalesce(l -> 'input', '{}'::jsonb), coalesce(l -> 'output', '{}'::jsonb)
    from (select coalesce(p -> 'log_row', '{}'::jsonb) as l) x;

  delete from clinic.conversation_locks where tenant_id = v_tenant and wa_id = v_wa and run_id = v_run;
  get diagnostics n_unlock = row_count;
  delete from clinic.inbound_buffer where tenant_id = v_tenant and wa_id = v_wa and claimed_by_run_id = v_run;
  get diagnostics n_clean = row_count;

  return jsonb_build_object('state_written', n_state, 'locks_released', n_unlock, 'buffer_rows_cleared', n_clean,
                            'alert', v_alert,
                            'mode', (select mode from clinic.conversations where tenant_id = v_tenant and wa_id = v_wa),
                            'agent_enabled', (select agent_enabled from clinic.tenants where id = v_tenant));
end $$;

create or replace function clinic.release_lock(p_tenant uuid, p_wa text, p_run text)
returns void language sql as $$
  delete from clinic.conversation_locks where tenant_id = p_tenant and wa_id = p_wa and run_id = p_run;
$$;

create or replace function clinic.log_outbound(p jsonb)
returns jsonb language plpgsql as $$
declare
  v_tenant uuid := (p ->> 'tenant_id')::uuid;
  v_wa     text := p ->> 'wa_id';
  v_conv   bigint;
  v_id     bigint;
  v_ok     boolean := coalesce((p ->> 'ok')::boolean, true);
begin
  select id into v_conv from clinic.conversations where tenant_id = v_tenant and wa_id = v_wa;
  insert into clinic.messages (tenant_id, conversation_id, wa_id, direction, sender, kind, body, media_url, media_mime,
                               external_id, status, error, run_id, meta, sent_at)
  values (v_tenant, v_conv, v_wa, 'outbound', coalesce(nullif(p ->> 'sender', ''), 'agent'),
          coalesce(nullif(p ->> 'kind', ''), 'text'), p ->> 'body', nullif(p ->> 'media_url', ''),
          nullif(p ->> 'media_mime', ''), nullif(p ->> 'external_id', ''),
          case when v_ok then 'sent' else 'failed' end, nullif(p ->> 'error', ''), p ->> 'run_id',
          coalesce(p -> 'meta', '{}'::jsonb), case when v_ok then now() end)
  on conflict (tenant_id, external_id) where external_id is not null do nothing
  returning id into v_id;
  if v_ok then
    update clinic.conversations
       set last_outbound_at = now(), last_message_at = now(),
           last_message_preview = left(coalesce(p ->> 'body', '[' || coalesce(p ->> 'kind', 'media') || ']'), 160)
     where id = v_conv;
  end if;
  return jsonb_build_object('message_id', v_id);
end $$;

-- ---------------------------------------------------------------------
-- The agent switch, takeover, staff replies, the team's answers
-- ---------------------------------------------------------------------
create or replace function clinic.set_agent_enabled(p_tenant uuid, p_enabled boolean,
                                                     p_reason text default null, p_notify boolean default true)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare
  t       clinic.tenants%rowtype;
  s       jsonb;
  v_pause bigint;
  pc      record;
  n       int := 0;
  v_lang  text;
  v_uid   uuid := clinic.current_user_id();
begin
  perform clinic.require_role(p_tenant, array['owner', 'manager', 'doctor', 'receptionist', 'nurse']);
  select * into t from clinic.tenants where id = p_tenant for update;
  s := clinic.merged_settings(t.settings);
  if not p_enabled then
    if not t.agent_enabled then return jsonb_build_object('agent_enabled', false, 'changed', false); end if;
    insert into clinic.agent_pauses (tenant_id, started_by, reason, notify_on_resume)
    values (p_tenant, v_uid, nullif(btrim(coalesce(p_reason, '')), ''), coalesce(p_notify, true))
    returning id into v_pause;
    update clinic.tenants set agent_enabled = false, current_pause_id = v_pause where id = p_tenant;
    insert into clinic.audit_log (tenant_id, user_id, action, entity, entity_id, detail)
    values (p_tenant, v_uid, 'agent_off', 'tenants', p_tenant::text, jsonb_build_object('reason', p_reason));
    return jsonb_build_object('agent_enabled', false, 'pause_id', v_pause, 'changed', true);
  end if;
  if t.agent_enabled then return jsonb_build_object('agent_enabled', true, 'changed', false, 'notified', 0); end if;
  v_pause := t.current_pause_id;
  update clinic.agent_pauses set ended_at = now(), ended_by = v_uid where id = v_pause;
  update clinic.tenants set agent_enabled = true, current_pause_id = null where id = p_tenant;
  if coalesce(p_notify, true) and v_pause is not null then
    for pc in select x.*, co.full_name, co.display_name
                from clinic.pause_contacts x left join clinic.contacts co on co.id = x.contact_id
               where x.pause_id = v_pause and x.resume_notified_at is null and not coalesce(co.is_blocked, false)
               order by x.first_message_at loop
      v_lang := clinic.contact_language(p_tenant, pc.wa_id);
      perform clinic.queue_message(p_tenant, pc.wa_id, 'resume_notice',
                                   clinic.render_template(s -> 'templates' ->> ('resume_notice_' || v_lang),
                                                          jsonb_build_object('name', clinic.first_name(pc.full_name, pc.display_name))),
                                   p_not_before => now() + make_interval(secs => n * 3));
      update clinic.pause_contacts set resume_notified_at = now() where pause_id = v_pause and wa_id = pc.wa_id;
      n := n + 1;
    end loop;
  end if;
  update clinic.agent_pauses set notified_count = n where id = v_pause;
  insert into clinic.audit_log (tenant_id, user_id, action, entity, entity_id, detail)
  values (p_tenant, v_uid, 'agent_on', 'tenants', p_tenant::text, jsonb_build_object('notified', n));
  return jsonb_build_object('agent_enabled', true, 'changed', true, 'notified', n);
end $$;

create or replace function clinic.take_over(p_conversation bigint, p_reason text default null)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare c clinic.conversations%rowtype;
begin
  select * into c from clinic.conversations where id = p_conversation for update;
  if not found then raise exception 'conversation not found'; end if;
  perform clinic.require_role(c.tenant_id, array['owner', 'manager', 'doctor', 'receptionist', 'nurse']);
  update clinic.conversations
     set mode = 'human', assigned_user_id = coalesce(clinic.current_user_id(), assigned_user_id),
         human_since = coalesce(human_since, now()), human_last_activity_at = now(),
         human_reason = coalesce(nullif(p_reason, ''), human_reason, 'taken over from the dashboard'),
         needs_attention = false
   where id = c.id returning * into c;
  delete from clinic.inbound_buffer where tenant_id = c.tenant_id and wa_id = c.wa_id and claimed_by_run_id is null;
  return jsonb_build_object('mode', c.mode, 'human_since', c.human_since);
end $$;

create or replace function clinic.hand_back(p_conversation bigint)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare c clinic.conversations%rowtype;
begin
  select * into c from clinic.conversations where id = p_conversation for update;
  if not found then raise exception 'conversation not found'; end if;
  perform clinic.require_role(c.tenant_id, array['owner', 'manager', 'doctor', 'receptionist', 'nurse']);
  update clinic.conversations
     set mode = 'agent', assigned_user_id = null, human_reason = null, human_last_activity_at = null,
         state = state || jsonb_build_object('handback', jsonb_build_object(
                   'at', now(), 'by', coalesce(clinic.current_user_id()::text, 'system'), 'human_since', c.human_since)),
         human_since = null
   where id = c.id returning * into c;
  return jsonb_build_object('mode', c.mode);
end $$;

create or replace function clinic.send_staff_message(p_conversation bigint, p_body text, p_kind text default 'text',
                                                      p_media_url text default null, p_media_mime text default null,
                                                      p_file_name text default null)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare c clinic.conversations%rowtype;
begin
  select * into c from clinic.conversations where id = p_conversation for update;
  if not found then raise exception 'conversation not found'; end if;
  perform clinic.require_role(c.tenant_id, array['owner', 'manager', 'doctor', 'receptionist', 'nurse']);
  if coalesce(btrim(p_body), '') = '' and p_media_url is null then raise exception 'empty message'; end if;
  update clinic.conversations
     set mode = 'human', assigned_user_id = coalesce(assigned_user_id, clinic.current_user_id()),
         human_since = coalesce(human_since, now()), human_last_activity_at = now(),
         human_reason = coalesce(human_reason, 'replied from the dashboard'),
         needs_attention = false, unread_count = 0
   where id = c.id;
  delete from clinic.inbound_buffer where tenant_id = c.tenant_id and wa_id = c.wa_id and claimed_by_run_id is null;
  return clinic.queue_message(c.tenant_id, c.wa_id, 'staff_reply', nullif(btrim(p_body), ''),
                              coalesce(p_kind, 'text'), p_media_url, p_media_mime, p_file_name, 'staff', clinic.current_user_id());
end $$;

create or replace function clinic.mark_read(p_conversation bigint)
returns void language plpgsql security definer set search_path = clinic, pg_temp as $$
declare v_tenant uuid;
begin
  select tenant_id into v_tenant from clinic.conversations where id = p_conversation;
  perform clinic.require_role(v_tenant, array['owner', 'manager', 'doctor', 'receptionist', 'nurse']);
  update clinic.conversations set unread_count = 0 where id = p_conversation;
end $$;

create or replace function clinic.resolve_attention(p_conversation bigint)
returns void language plpgsql security definer set search_path = clinic, pg_temp as $$
declare v_tenant uuid;
begin
  select tenant_id into v_tenant from clinic.conversations where id = p_conversation;
  perform clinic.require_role(v_tenant, array['owner', 'manager', 'doctor', 'receptionist', 'nurse']);
  update clinic.conversations set needs_attention = false, attention_reason = null, urgency = null where id = p_conversation;
end $$;

create or replace function clinic.answer_team_question(p_question bigint, p_kind text, p_answer text default null)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare
  q      clinic.team_questions%rowtype;
  v_kind text := lower(btrim(coalesce(p_kind, '')));
  v_text text := nullif(btrim(coalesce(p_answer, '')), '');
begin
  select * into q from clinic.team_questions where id = p_question for update;
  if not found then raise exception 'no such question'; end if;
  perform clinic.require_role(q.tenant_id, array['owner', 'manager', 'doctor', 'receptionist', 'nurse']);
  if v_kind not in ('yes', 'no', 'text') then raise exception 'the answer is yes, no or text'; end if;
  if v_kind = 'text' and v_text is null then raise exception 'write the answer'; end if;
  if q.status = 'dismissed' then raise exception 'this question was closed'; end if;
  update clinic.team_questions
     set status = 'answered', answer_kind = v_kind, answer = left(v_text, 1000), told_at = null,
         answered_at = now(), answered_by = clinic.current_user_id(), answered_by_name = clinic.my_name(q.tenant_id)
   where id = q.id;
  update clinic.conversations c
     set questions_open = (select count(*) from clinic.team_questions x where x.conversation_id = c.id and x.status = 'open')
   where c.id = q.conversation_id;
  return jsonb_build_object('ok', true, 'tenant_id', q.tenant_id, 'wa_id', q.wa_id, 'conversation_id', q.conversation_id,
                            'mode', (select mode from clinic.conversations where id = q.conversation_id));
end $$;

create or replace function clinic.dismiss_team_question(p_question bigint)
returns void language plpgsql security definer set search_path = clinic, pg_temp as $$
declare q clinic.team_questions%rowtype;
begin
  select * into q from clinic.team_questions where id = p_question;
  if not found then raise exception 'no such question'; end if;
  perform clinic.require_role(q.tenant_id, array['owner', 'manager', 'doctor', 'receptionist', 'nurse']);
  update clinic.team_questions set status = 'dismissed' where id = q.id and status = 'open';
  update clinic.conversations c
     set questions_open = (select count(*) from clinic.team_questions x where x.conversation_id = c.id and x.status = 'open')
   where c.id = q.conversation_id;
end $$;

-- ---------------------------------------------------------------------
-- The WhatsApp number
-- ---------------------------------------------------------------------
create or replace function clinic.save_channel(p_tenant uuid, p jsonb)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare
  v_id uuid := nullif(p ->> 'id', '')::uuid;
  c    clinic.whatsapp_channels%rowtype;
begin
  perform clinic.require_role(p_tenant, array['owner', 'manager']);
  if v_id is null then
    insert into clinic.whatsapp_channels (tenant_id, provider, label, phone_number, instance_name, base_url, api_key,
                                          cloud_phone_number_id, cloud_access_token)
    values (p_tenant, coalesce(nullif(p ->> 'provider', ''), 'evolution'), nullif(p ->> 'label', ''),
            nullif(clinic.digits(p ->> 'phone_number'), ''), nullif(btrim(p ->> 'instance_name'), ''),
            nullif(rtrim(btrim(p ->> 'base_url'), '/'), ''), nullif(btrim(p ->> 'api_key'), ''),
            nullif(btrim(p ->> 'cloud_phone_number_id'), ''), nullif(btrim(p ->> 'cloud_access_token'), ''))
    returning * into c;
  else
    update clinic.whatsapp_channels
       set label = coalesce(p ->> 'label', label),
           phone_number = coalesce(nullif(clinic.digits(p ->> 'phone_number'), ''), phone_number),
           instance_name = coalesce(nullif(btrim(p ->> 'instance_name'), ''), instance_name),
           base_url = coalesce(nullif(rtrim(btrim(p ->> 'base_url'), '/'), ''), base_url),
           api_key = coalesce(nullif(btrim(p ->> 'api_key'), ''), api_key),
           cloud_phone_number_id = coalesce(nullif(btrim(p ->> 'cloud_phone_number_id'), ''), cloud_phone_number_id),
           cloud_access_token = coalesce(nullif(btrim(p ->> 'cloud_access_token'), ''), cloud_access_token),
           is_active = coalesce((p ->> 'is_active')::boolean, is_active),
           webhook_token = case when coalesce((p ->> 'rotate_token')::boolean, false) then clinic.random_token() else webhook_token end
     where id = v_id and tenant_id = p_tenant
    returning * into c;
    if not found then raise exception 'number not found'; end if;
  end if;
  return jsonb_build_object('id', c.id, 'instance_name', c.instance_name, 'webhook_token', c.webhook_token,
                            'has_api_key', c.api_key is not null, 'status', c.status);
end $$;

create or replace function clinic.remove_channel(p_channel uuid)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare
  c       clinic.whatsapp_channels%rowtype;
  v_other uuid;
  n       int := 0;
begin
  select * into c from clinic.whatsapp_channels where id = p_channel;
  if not found then raise exception 'number not found'; end if;
  perform clinic.require_role(c.tenant_id, array['owner', 'manager']);
  select id into v_other from clinic.whatsapp_channels where tenant_id = c.tenant_id and id <> c.id and is_active order by created_at limit 1;
  if v_other is not null then
    update clinic.outbox set channel_id = v_other where channel_id = c.id and status = 'queued';
    get diagnostics n = row_count;
  end if;
  delete from clinic.whatsapp_channels where id = c.id;
  return jsonb_build_object('removed', c.id, 'other_number', v_other is not null, 'queued_moved', n);
end $$;

create or replace function clinic.channel_webhook_token(p_channel uuid)
returns text language plpgsql stable security definer set search_path = clinic, pg_temp as $$
declare c clinic.whatsapp_channels%rowtype;
begin
  select * into c from clinic.whatsapp_channels where id = p_channel;
  if not found then raise exception 'number not found'; end if;
  perform clinic.require_role(c.tenant_id, array['owner', 'manager']);
  return c.webhook_token;
end $$;

-- ================= 004_patients.sql =================

-- =====================================================================
-- Everwake Clinic · 004 · patients and their records
--
--   patients            the people seen (a file number, age, sex…); one
--                       WhatsApp contact can book for several of them
--   patient_contacts    who books for whom (self, child, parent, spouse…)
--
-- The medical record — clinical team only (row level security, 009):
--   conditions, allergies, medications      the running lists
--   patient_history     surgeries, family, social, obstetric, vaccines…
--   vitals              each measurement
--   documents           lab reports, X-rays, prescriptions, photos —
--                       from WhatsApp (read by the model) or uploaded
--   form_templates      a speciality's history form, copied per doctor
--   encounters          one visit's record against a form (draft → signed)
--   dental_chart        one row per tooth (FDI 11–48, children 51–85)
--   treatment_plans     teeth × services × prices, quoted on WhatsApp,
--   treatment_plan_items  then booked session by session (005)
--   record_access_log   who opened which record, when
-- =====================================================================

create table clinic.patients (
  id                   bigint generated always as identity primary key,
  tenant_id            uuid not null references clinic.tenants(id) on delete cascade,
  file_no              text not null,
  full_name            text not null,
  sex                  text check (sex in ('male', 'female')),
  birth_date           date,
  birth_date_estimated boolean not null default false,   -- only the age was given
  phone                text,
  national_id          text,
  blood_group          text check (blood_group in ('A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-')),
  marital_status       text,
  occupation           text,
  address              text,
  insurance            text,
  tags                 text[] not null default '{}',
  notes                text,                               -- the front desk's note (not medical)
  preferences          jsonb not null default '{}'::jsonb, -- {"band":"evening","doctor_id":…,"location_id":…}
  first_visit_at       timestamptz,
  last_visit_at        timestamptz,
  visits_count         int not null default 0,
  no_show_count        int not null default 0,
  created_via          text not null default 'dashboard' check (created_via in ('dashboard', 'whatsapp', 'import', 'web')),
  is_active            boolean not null default true,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  unique (tenant_id, file_no)
);
create index patients_tenant_idx on clinic.patients (tenant_id, last_visit_at desc nulls last);
create index patients_name_idx on clinic.patients (tenant_id, (clinic.norm(full_name)));
create index patients_phone_idx on clinic.patients (tenant_id, phone) where phone is not null;

create table clinic.patient_contacts (
  patient_id bigint not null references clinic.patients(id) on delete cascade,
  contact_id bigint not null references clinic.contacts(id) on delete cascade,
  tenant_id  uuid not null references clinic.tenants(id) on delete cascade,
  relation   text not null default 'self' check (relation in ('self', 'child', 'parent', 'spouse', 'sibling', 'relative', 'other')),
  created_at timestamptz not null default now(),
  primary key (patient_id, contact_id)
);
create index patient_contacts_contact_idx on clinic.patient_contacts (contact_id);

-- ---------------------------------------------------------------------
-- The medical record
-- ---------------------------------------------------------------------
create table clinic.form_templates (
  id         uuid primary key default gen_random_uuid(),
  tenant_id  uuid not null references clinic.tenants(id) on delete cascade,
  doctor_id  uuid references clinic.doctors(id) on delete cascade,
  specialty  text not null,
  name       text not null,
  version    int not null default 1,
  schema     jsonb not null,         -- {sections:[{key,title_ar,title_en,fields:[{key,label_ar,label_en,type,unit,options}]}]}
  is_default boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index form_templates_tenant_idx on clinic.form_templates (tenant_id, specialty);

create table clinic.encounters (
  id              bigint generated always as identity primary key,
  tenant_id       uuid not null references clinic.tenants(id) on delete cascade,
  patient_id      bigint not null references clinic.patients(id) on delete cascade,
  appointment_id  bigint,                                  -- 005 adds the key
  doctor_id       uuid references clinic.doctors(id) on delete set null,
  template_id     uuid references clinic.form_templates(id) on delete set null,
  status          text not null default 'draft' check (status in ('draft', 'signed')),
  chief_complaint text,
  data            jsonb not null default '{}'::jsonb,      -- {section_key:{field_key:value}}
  sources         jsonb not null default '{}'::jsonb,      -- where each value came from (manual · scribe quote · assistant)
  assessment      text,
  plan            text,
  diagnoses       jsonb not null default '[]'::jsonb,      -- [{name, icd10}]
  follow_up_date  date,
  started_at      timestamptz not null default now(),
  ended_at        timestamptz,
  signed_at       timestamptz,
  signed_by       uuid,
  created_by      uuid,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);
create index encounters_patient_idx on clinic.encounters (patient_id, started_at desc);

create table clinic.conditions (
  id           bigint generated always as identity primary key,
  tenant_id    uuid not null references clinic.tenants(id) on delete cascade,
  patient_id   bigint not null references clinic.patients(id) on delete cascade,
  name         text not null,
  icd10        text,
  status       text not null default 'active' check (status in ('active', 'chronic', 'resolved')),
  since        text,
  notes        text,
  source       text not null default 'manual' check (source in ('manual', 'scribe', 'assistant', 'agent', 'import')),
  encounter_id bigint references clinic.encounters(id) on delete set null,
  created_by   uuid,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
create index conditions_patient_idx on clinic.conditions (patient_id);

create table clinic.allergies (
  id           bigint generated always as identity primary key,
  tenant_id    uuid not null references clinic.tenants(id) on delete cascade,
  patient_id   bigint not null references clinic.patients(id) on delete cascade,
  substance    text not null,
  reaction     text,
  severity     text check (severity in ('mild', 'moderate', 'severe')),
  status       text not null default 'active' check (status in ('active', 'inactive')),
  source       text not null default 'manual' check (source in ('manual', 'scribe', 'assistant', 'agent', 'import')),
  encounter_id bigint references clinic.encounters(id) on delete set null,
  created_by   uuid,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
create index allergies_patient_idx on clinic.allergies (patient_id);

create table clinic.medications (
  id           bigint generated always as identity primary key,
  tenant_id    uuid not null references clinic.tenants(id) on delete cascade,
  patient_id   bigint not null references clinic.patients(id) on delete cascade,
  name         text not null,
  dose         text,
  route        text,
  frequency    text,
  duration     text,
  status       text not null default 'active' check (status in ('active', 'stopped')),
  started_on   date,
  stopped_on   date,
  prescribed_here boolean not null default false,
  notes        text,
  source       text not null default 'manual' check (source in ('manual', 'scribe', 'assistant', 'agent', 'import')),
  encounter_id bigint references clinic.encounters(id) on delete set null,
  created_by   uuid,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
create index medications_patient_idx on clinic.medications (patient_id);

create table clinic.patient_history (
  id           bigint generated always as identity primary key,
  tenant_id    uuid not null references clinic.tenants(id) on delete cascade,
  patient_id   bigint not null references clinic.patients(id) on delete cascade,
  kind         text not null check (kind in ('surgery', 'family', 'social', 'obstetric', 'vaccination', 'hospitalization', 'other')),
  title        text not null,
  detail       text,
  data         jsonb not null default '{}'::jsonb,
  source       text not null default 'manual' check (source in ('manual', 'scribe', 'assistant', 'agent', 'import')),
  encounter_id bigint references clinic.encounters(id) on delete set null,
  created_by   uuid,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
create index patient_history_patient_idx on clinic.patient_history (patient_id, kind);

create table clinic.vitals (
  id           bigint generated always as identity primary key,
  tenant_id    uuid not null references clinic.tenants(id) on delete cascade,
  patient_id   bigint not null references clinic.patients(id) on delete cascade,
  encounter_id bigint references clinic.encounters(id) on delete set null,
  taken_at     timestamptz not null default now(),
  bp_sys       int, bp_dia int, pulse int, temp_c numeric(4, 1), spo2 int, resp_rate int,
  weight_kg    numeric(6, 2), height_cm numeric(5, 1), glucose numeric(6, 1),
  head_cm      numeric(5, 1),
  notes        text,
  created_by   uuid,
  created_at   timestamptz not null default now()
);
create index vitals_patient_idx on clinic.vitals (patient_id, taken_at desc);

create table clinic.documents (
  id             bigint generated always as identity primary key,
  tenant_id      uuid not null references clinic.tenants(id) on delete cascade,
  patient_id     bigint references clinic.patients(id) on delete cascade,
  contact_id     bigint references clinic.contacts(id) on delete set null,
  appointment_id bigint,
  message_id     bigint references clinic.messages(id) on delete set null,
  kind           text not null default 'other' check (kind in ('lab', 'imaging', 'prescription', 'photo', 'report', 'referral', 'other')),
  title          text,
  storage_path   text,
  url            text,
  mime           text,
  source         text not null default 'whatsapp' check (source in ('whatsapp', 'upload', 'scribe')),
  ai_summary     text,
  ai_values      jsonb,                -- lab values read from a report: [{name, value, unit, flag}]
  created_by     uuid,
  created_at     timestamptz not null default now()
);
create index documents_patient_idx on clinic.documents (patient_id, created_at desc);
create index documents_contact_idx on clinic.documents (contact_id, created_at desc);

create table clinic.dental_chart (
  tenant_id  uuid not null references clinic.tenants(id) on delete cascade,
  patient_id bigint not null references clinic.patients(id) on delete cascade,
  tooth      smallint not null check ((tooth / 10 between 1 and 4 and tooth % 10 between 1 and 8)
                                   or (tooth / 10 between 5 and 8 and tooth % 10 between 1 and 5)),   -- FDI
  condition  text not null default 'healthy'
             check (condition in ('healthy', 'caries', 'filled', 'root_canal', 'crown', 'bridge', 'implant', 'missing',
                                  'extraction_needed', 'impacted', 'fractured', 'sensitive', 'veneer', 'watch')),
  surfaces   text[] not null default '{}',     -- M O D B L (I for front teeth)
  planned    text,                             -- what is planned for it, in words
  notes      text,
  updated_by uuid,
  updated_at timestamptz not null default now(),
  primary key (patient_id, tooth)
);

create table clinic.treatment_plans (
  id          bigint generated always as identity primary key,
  tenant_id   uuid not null references clinic.tenants(id) on delete cascade,
  patient_id  bigint not null references clinic.patients(id) on delete cascade,
  doctor_id   uuid references clinic.doctors(id) on delete set null,
  title       text not null default 'خطة العلاج',
  status      text not null default 'draft' check (status in ('draft', 'quoted', 'accepted', 'in_progress', 'done', 'cancelled')),
  discount    numeric(12, 2) not null default 0,
  notes       text,
  quoted_at   timestamptz,
  accepted_at timestamptz,
  created_by  uuid,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index treatment_plans_patient_idx on clinic.treatment_plans (patient_id, created_at desc);

create table clinic.treatment_plan_items (
  id               bigint generated always as identity primary key,
  tenant_id        uuid not null references clinic.tenants(id) on delete cascade,
  plan_id          bigint not null references clinic.treatment_plans(id) on delete cascade,
  seq              int not null default 1,
  tooth            smallint check (tooth is null or (tooth / 10 between 1 and 4 and tooth % 10 between 1 and 8)
                                  or (tooth / 10 between 5 and 8 and tooth % 10 between 1 and 5)),
  service_id       uuid references clinic.services(id) on delete set null,
  label            text not null,
  price            numeric(12, 2),
  sessions         int not null default 1,
  session_gap_days int,
  done_sessions    int not null default 0,
  status           text not null default 'planned' check (status in ('planned', 'booked', 'in_progress', 'done', 'cancelled')),
  notes            text,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);
create index treatment_plan_items_plan_idx on clinic.treatment_plan_items (plan_id, seq);

create table clinic.record_access_log (
  id         bigint generated always as identity primary key,
  tenant_id  uuid not null references clinic.tenants(id) on delete cascade,
  user_id    uuid,
  patient_id bigint references clinic.patients(id) on delete cascade,
  action     text not null default 'view' check (action in ('view', 'edit', 'export', 'print')),
  detail     text,
  at         timestamptz not null default now()
);
create index record_access_log_idx on clinic.record_access_log (tenant_id, at desc);

do $$
declare t text;
begin
  foreach t in array array['patients', 'form_templates', 'encounters', 'conditions', 'allergies', 'medications',
                           'patient_history', 'treatment_plans', 'treatment_plan_items'] loop
    execute format('create trigger %I before update on clinic.%I for each row execute function clinic.touch_updated_at()', t || '_touch', t);
  end loop;
  foreach t in array array['patients', 'encounters', 'conditions', 'allergies', 'medications', 'patient_history',
                           'treatment_plans', 'treatment_plan_items', 'form_templates'] loop
    execute format('create trigger %I after insert or update or delete on clinic.%I for each row execute function clinic.audit_change()', t || '_audit', t);
  end loop;
end $$;

create or replace function clinic.assign_file_no()
returns trigger language plpgsql security definer set search_path = clinic, pg_temp as $$
declare s bigint;
begin
  if new.file_no is null or btrim(new.file_no) = '' then
    loop
      update clinic.tenants set patient_seq = patient_seq + 1 where id = new.tenant_id returning patient_seq into s;
      new.file_no := s::text;
      exit when not exists (select 1 from clinic.patients where tenant_id = new.tenant_id and file_no = new.file_no);
    end loop;
  end if;
  return new;
end $$;
create trigger patients_file_no before insert on clinic.patients
  for each row execute function clinic.assign_file_no();

-- ---------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------
create or replace function clinic.age_years(p_birth date, p_on date default current_date)
returns numeric language sql immutable as $$
  select case when p_birth is null then null
              else round((extract(year from age(p_on, p_birth)) + extract(month from age(p_on, p_birth)) / 12.0)::numeric, 1) end
$$;

create or replace function clinic.age_text(p_birth date, p_lang text default 'ar')
returns text language sql stable as $$
  select case
    when p_birth is null then null
    when age(current_date, p_birth) < interval '2 years' then
      (extract(year from age(current_date, p_birth)) * 12 + extract(month from age(current_date, p_birth)))::int::text
      || case when p_lang = 'en' then ' months' else ' شهر' end
    else extract(year from age(current_date, p_birth))::int::text || case when p_lang = 'en' then ' years' else ' سنة' end end
$$;

-- "30" / "30 سنة" / "8 شهور" / "1990-05-03" → a birth date (estimated when only an age)
create or replace function clinic.parse_birth(p text, p_today date default current_date)
returns table (birth_date date, estimated boolean) language plpgsql immutable as $$
declare
  s text := btrim(translate(coalesce(p, ''), '٠١٢٣٤٥٦٧٨٩', '0123456789'));
  n numeric;
begin
  if s ~ '^\d{4}-\d{1,2}-\d{1,2}$' then
    birth_date := s::date; estimated := false; return next; return;
  end if;
  n := nullif(substring(s from '(\d+(?:\.\d+)?)'), '')::numeric;
  if n is null then return; end if;
  if s ~* '(شهر|شهور|month)' then
    birth_date := (p_today - make_interval(months => n::int))::date;
  elsif s ~* '(اسبوع|أسبوع|week)' then
    birth_date := (p_today - make_interval(days => (n * 7)::int))::date;
  elsif s ~* '(يوم|ايام|أيام|day)' then
    birth_date := (p_today - make_interval(days => n::int))::date;
  else
    if n > 120 then return; end if;
    birth_date := (p_today - make_interval(years => floor(n)::int, months => ((n - floor(n)) * 12)::int))::date;
  end if;
  estimated := true;
  return next;
end $$;

-- a patient as the agent sees them: never the medical record
create or replace function clinic.patient_brief(p_patient bigint)
returns jsonb language plpgsql stable as $$
begin
  return (
    select jsonb_build_object(
      'id', p.id, 'file_no', p.file_no, 'full_name', p.full_name, 'first_name', split_part(p.full_name, ' ', 1),
      'sex', p.sex, 'age', clinic.age_text(p.birth_date, 'ar'), 'age_years', clinic.age_years(p.birth_date),
      'last_visit_at', p.last_visit_at, 'visits_count', p.visits_count, 'preferences', p.preferences,
      'last_doctor', (select clinic.doctor_label(a.doctor_id, 'ar') from clinic.appointments a
                       where a.patient_id = p.id and a.status = 'done' order by a.starts_at desc limit 1),
      'last_doctor_id', (select a.doctor_id from clinic.appointments a
                          where a.patient_id = p.id and a.status = 'done' order by a.starts_at desc limit 1))
      from clinic.patients p where p.id = p_patient);
end $$;

-- record that someone opened a medical record
create or replace function clinic.log_record_access(p_patient bigint, p_action text default 'view', p_detail text default null)
returns void language plpgsql security definer set search_path = clinic, pg_temp as $$
declare v_tenant uuid;
begin
  select tenant_id into v_tenant from clinic.patients where id = p_patient;
  if v_tenant is null then return; end if;
  perform clinic.require_role(v_tenant, array['owner', 'manager', 'doctor', 'nurse', 'receptionist']);
  insert into clinic.record_access_log (tenant_id, user_id, patient_id, action, detail)
  values (v_tenant, clinic.current_user_id(), p_patient, coalesce(p_action, 'view'), p_detail);
end $$;

-- the patient a contact means: themself, or a family member by name
create or replace function clinic.contact_patients(p_contact bigint)
returns jsonb language sql stable as $$
  select coalesce(jsonb_agg(clinic.patient_brief(pc.patient_id) || jsonb_build_object('relation', pc.relation)
                            order by (pc.relation = 'self') desc, p.last_visit_at desc nulls last), '[]'::jsonb)
    from clinic.patient_contacts pc join clinic.patients p on p.id = pc.patient_id and p.is_active
   where pc.contact_id = p_contact
$$;

-- find or create the patient behind a booking
create or replace function clinic.resolve_patient(p_tenant uuid, p_contact bigint, p jsonb)
returns bigint language plpgsql as $$
declare
  v_id    bigint := nullif(p ->> 'patient_id', '')::bigint;
  v_name  text := nullif(btrim(coalesce(p ->> 'full_name', '')), '');
  v_rel   text := coalesce(nullif(p ->> 'relation', ''), 'self');
  v_birth date;
  v_est   boolean;
  co      clinic.contacts%rowtype;
begin
  select * into co from clinic.contacts where id = p_contact;
  if v_id is not null and exists (select 1 from clinic.patients where id = v_id and tenant_id = p_tenant) then
    return v_id;
  end if;
  -- the same name among this contact's patients
  if v_name is not null then
    select pc.patient_id into v_id
      from clinic.patient_contacts pc join clinic.patients x on x.id = pc.patient_id
     where pc.contact_id = p_contact and (clinic.norm(x.full_name) = clinic.norm(v_name)
                                          or split_part(clinic.norm(x.full_name), ' ', 1) = split_part(clinic.norm(v_name), ' ', 1))
     order by (clinic.norm(x.full_name) = clinic.norm(v_name)) desc limit 1;
    if v_id is not null then return v_id; end if;
  elsif v_rel = 'self' then
    select pc.patient_id into v_id from clinic.patient_contacts pc where pc.contact_id = p_contact and pc.relation = 'self' limit 1;
    if v_id is not null then return v_id; end if;
  end if;
  if v_name is null then return null; end if;
  select b.birth_date, b.estimated into v_birth, v_est from clinic.parse_birth(p ->> 'age') b;
  insert into clinic.patients (tenant_id, full_name, sex, birth_date, birth_date_estimated, phone, created_via)
  values (p_tenant, left(v_name, 120), nullif(p ->> 'sex', ''), v_birth, coalesce(v_est, false),
          case when v_rel = 'self' then co.phone end, coalesce(nullif(p ->> 'created_via', ''), 'whatsapp'))
  returning id into v_id;
  if p_contact is not null then
    insert into clinic.patient_contacts (patient_id, contact_id, tenant_id, relation)
    values (v_id, p_contact, p_tenant, case when v_rel in ('self', 'child', 'parent', 'spouse', 'sibling', 'relative', 'other') then v_rel else 'other' end)
    on conflict do nothing;
  end if;
  if v_rel = 'self' and co.id is not null and coalesce(co.full_name, '') = '' then
    update clinic.contacts set full_name = left(v_name, 120) where id = co.id;
  end if;
  return v_id;
end $$;

-- ================= 005_scheduling.sql =================

-- =====================================================================
-- Everwake Clinic · 005 · appointments
--
--   appointments        held → booked → confirmed → arrived → in_visit
--                       → done | no_show | cancelled. A `slot` booking is
--                       a fixed time; a `queue` booking is a number in a
--                       session (الدور) with an estimated time.
--                       Two exclusion constraints make double booking
--                       impossible: one doctor, one time — and one chair
--                       (or room, or laser), one time.
--   appointment_events  every step, by whom
--   booking_drafts      the booking a WhatsApp chat is putting together
--   waitlist            people who want an earlier time
--
--   doctor_sessions()   the sessions on given days: schedules, then the
--                       day's exceptions (off · changed · extra)
--   available_slots()   the one place free times are worked out — the
--                       agent, the dashboard and the checks all use it
--   book_appointment()  the one place an appointment is made or held
--   booking_tool()      the agent's tool (find_slots · update · summary ·
--                       book · cancel · reschedule · confirm ·
--                       accept_delay · status · join_waitlist · take_offer
--                       · next_plan_session · accept_plan)
-- =====================================================================

create table clinic.appointments (
  id                 bigint generated always as identity primary key,
  tenant_id          uuid not null references clinic.tenants(id) on delete cascade,
  ref_no             text,
  doctor_id          uuid not null references clinic.doctors(id) on delete restrict,
  location_id        uuid not null references clinic.locations(id) on delete restrict,
  resource_id        uuid references clinic.resources(id) on delete set null,
  service_id         uuid references clinic.services(id) on delete set null,
  patient_id         bigint references clinic.patients(id) on delete set null,
  contact_id         bigint references clinic.contacts(id) on delete set null,
  wa_id              text,
  conversation_id    bigint references clinic.conversations(id) on delete set null,
  status             text not null default 'booked'
                     check (status in ('held', 'booked', 'confirmed', 'arrived', 'in_visit', 'done', 'no_show', 'cancelled')),
  source             text not null default 'dashboard' check (source in ('whatsapp', 'dashboard', 'phone', 'walk_in', 'web', 'plan')),
  mode               text not null default 'slot' check (mode in ('slot', 'queue')),
  session_date       date not null,
  starts_at          timestamptz not null,   -- slot: the visit · queue: when the session starts
  ends_at            timestamptz not null,   -- slot: the visit's end · queue: when the session ends
  queue_no           int,
  est_at             timestamptz,            -- when they will likely go in (slot: = starts_at)
  original_starts_at timestamptz,            -- before any delay or move
  delay_minutes      int not null default 0,
  reason             text,                   -- in the patient's own words
  urgency            text not null default 'routine' check (urgency in ('routine', 'soon', 'urgent', 'emergency')),
  is_new_patient     boolean not null default false,
  is_follow_up       boolean not null default false,
  price              numeric(12, 2),
  price_max          numeric(12, 2),
  price_kind         text,
  price_text         text,
  plan_item_id       bigint references clinic.treatment_plan_items(id) on delete set null,
  hold_expires_at    timestamptz,
  confirmed_at       timestamptz,
  arrived_at         timestamptz,
  visit_started_at   timestamptz,
  visit_ended_at     timestamptz,
  cancelled_at       timestamptz,
  cancel_reason      text,
  cancelled_by       text check (cancelled_by in ('patient', 'clinic', 'system')),
  at_risk_alerted_at timestamptz,
  manage_token       text not null unique default clinic.random_token(),
  payment_status     text not null default 'none' check (payment_status in ('none', 'pending', 'paid', 'refunded')),
  staff_notes        text,
  pre_visit          jsonb not null default '{}'::jsonb,
  created_by         uuid,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  unique (tenant_id, ref_no),
  check (ends_at > starts_at),
  constraint appointments_doctor_free exclude using gist
    (doctor_id with =, tstzrange(starts_at, ends_at, '[)') with &&)
    where (mode = 'slot' and status in ('held', 'booked', 'confirmed', 'arrived', 'in_visit'))
    deferrable initially immediate,
  constraint appointments_resource_free exclude using gist
    (resource_id with =, tstzrange(starts_at, ends_at, '[)') with &&)
    where (resource_id is not null and mode = 'slot' and status in ('held', 'booked', 'confirmed', 'arrived', 'in_visit'))
    deferrable initially immediate
);
create unique index appointments_queue_uidx on clinic.appointments (doctor_id, location_id, session_date, queue_no)
  where queue_no is not null and status in ('held', 'booked', 'confirmed', 'arrived', 'in_visit');
create index appointments_day_idx on clinic.appointments (tenant_id, session_date, doctor_id);
create index appointments_patient_idx on clinic.appointments (patient_id, starts_at desc);
create index appointments_wa_idx on clinic.appointments (tenant_id, wa_id, starts_at desc);

alter table clinic.encounters add constraint encounters_appointment_fk
  foreign key (appointment_id) references clinic.appointments(id) on delete set null;
alter table clinic.documents add constraint documents_appointment_fk
  foreign key (appointment_id) references clinic.appointments(id) on delete set null;

create table clinic.appointment_events (
  id             bigint generated always as identity primary key,
  tenant_id      uuid not null references clinic.tenants(id) on delete cascade,
  appointment_id bigint not null references clinic.appointments(id) on delete cascade,
  kind           text not null,
  detail         jsonb not null default '{}'::jsonb,
  by_user        uuid,
  by_role        text not null default 'staff' check (by_role in ('agent', 'staff', 'system', 'patient')),
  created_at     timestamptz not null default now()
);
create index appointment_events_appt_idx on clinic.appointment_events (appointment_id, created_at);

create table clinic.booking_drafts (
  tenant_id   uuid not null references clinic.tenants(id) on delete cascade,
  wa_id       text not null,
  data        jsonb not null default '{}'::jsonb,   -- {patient{…}, doctor_id, location_id, service_id, reason, urgency, slot{…}, last_offered[…]}
  hold_id     bigint references clinic.appointments(id) on delete set null,
  changed_at  timestamptz not null default clock_timestamp(),
  summary_at  timestamptz,
  updated_at  timestamptz not null default now(),
  primary key (tenant_id, wa_id)
);

create table clinic.waitlist (
  id            bigint generated always as identity primary key,
  tenant_id     uuid not null references clinic.tenants(id) on delete cascade,
  patient_id    bigint references clinic.patients(id) on delete cascade,
  contact_id    bigint references clinic.contacts(id) on delete cascade,
  wa_id         text,
  doctor_id     uuid references clinic.doctors(id) on delete cascade,
  location_id   uuid references clinic.locations(id) on delete cascade,
  service_id    uuid references clinic.services(id) on delete set null,
  appointment_id bigint references clinic.appointments(id) on delete set null,  -- the later one they hold now
  from_date     date not null default current_date,
  to_date       date,
  band          text not null default 'any' check (band in ('any', 'morning', 'afternoon', 'evening')),
  status        text not null default 'waiting' check (status in ('waiting', 'offered', 'booked', 'expired', 'cancelled')),
  offered_slot  jsonb,
  offered_at    timestamptz,
  notes         text,
  created_by    uuid,
  created_at    timestamptz not null default now()
);
create index waitlist_tenant_idx on clinic.waitlist (tenant_id, status, doctor_id);

create trigger appointments_touch before update on clinic.appointments for each row execute function clinic.touch_updated_at();
create trigger appointments_audit after insert or update or delete on clinic.appointments for each row execute function clinic.audit_change();

-- ---------------------------------------------------------------------
-- Time
-- ---------------------------------------------------------------------
create or replace function clinic.tenant_tz(p_tenant uuid)
returns text language sql stable as $$
  select coalesce((select timezone from clinic.tenants where id = p_tenant), 'Africa/Cairo')
$$;

create or replace function clinic.local_today(p_tenant uuid)
returns date language sql stable as $$
  select (now() at time zone clinic.tenant_tz(p_tenant))::date
$$;

create or replace function clinic.band_of(p_local time)
returns text language sql immutable as $$
  select case when p_local < '12:00' then 'morning' when p_local < '17:00' then 'afternoon' else 'evening' end
$$;

-- "السبت 15/11 الساعة 5:30 م" · with relative words for today and tomorrow when asked
create or replace function clinic.when_words(p_at timestamptz, p_tz text, p_lang text default 'ar', p_relative boolean default false)
returns text language sql stable as $$
  with x as (select (p_at at time zone p_tz) as l, (now() at time zone p_tz)::date as today)
  select case
    when p_lang = 'en' then
      case when p_relative and x.l::date = x.today then 'today'
           when p_relative and x.l::date = x.today + 1 then 'tomorrow (' || clinic.day_name(extract(dow from x.l)::int, 'en') || ' ' || to_char(x.l, 'DD/MM') || ')'
           else clinic.day_name(extract(dow from x.l)::int, 'en') || ' ' || to_char(x.l, 'DD/MM') end
      || ' at ' || clinic.clock_text(x.l::time, 'en')
    else
      case when p_relative and x.l::date = x.today then 'النهارده'
           when p_relative and x.l::date = x.today + 1 then 'بكره ' || clinic.day_name(extract(dow from x.l)::int, 'ar') || ' ' || to_char(x.l, 'DD/MM')
           else clinic.day_name(extract(dow from x.l)::int, 'ar') || ' ' || to_char(x.l, 'DD/MM') end
      || ' الساعة ' || clinic.clock_text(x.l::time, 'ar') end
  from x
$$;

create or replace function clinic.appt_when(a clinic.appointments, p_lang text default 'ar', p_relative boolean default false)
returns text language plpgsql stable as $$
declare tz text := clinic.tenant_tz(a.tenant_id);
begin
  if a.mode = 'queue' then
    return case when p_lang = 'en'
      then clinic.when_words(a.starts_at, tz, 'en', p_relative) || ' session — queue number ' || a.queue_no
           || coalesce(', about ' || clinic.clock_text((coalesce(a.est_at, a.starts_at) at time zone tz)::time, 'en'), '')
      else replace(clinic.when_words(a.starts_at, tz, 'ar', p_relative), ' الساعة ', ' — بداية الكشف ')
           || '، دور رقم ' || a.queue_no
           || coalesce('، حوالي ' || clinic.clock_text((coalesce(a.est_at, a.starts_at) at time zone tz)::time, 'ar'), '') end;
  end if;
  return clinic.when_words(a.starts_at, tz, p_lang, p_relative);
end $$;

create or replace function clinic.manage_link(a clinic.appointments)
returns text language sql stable as $$
  select case when coalesce(clinic.merged_settings(t.settings) ->> 'public_url', '') <> ''
              then rtrim(clinic.merged_settings(t.settings) ->> 'public_url', '/') || '/a/' || a.manage_token end
    from clinic.tenants t where t.id = a.tenant_id
$$;

create or replace function clinic.appointment_view(a clinic.appointments, p_lang text default 'ar')
returns jsonb language plpgsql stable as $$
declare tz text := clinic.tenant_tz(a.tenant_id);
begin
  return jsonb_build_object(
    'id', a.id, 'ref_no', a.ref_no, 'status', a.status, 'mode', a.mode,
    'doctor_id', a.doctor_id, 'doctor', clinic.doctor_label(a.doctor_id, p_lang),
    'location_id', a.location_id, 'location', clinic.location_label(a.location_id, p_lang),
    'service_id', a.service_id, 'service', (select case when p_lang = 'en' then coalesce(s.name_en, s.name_ar) else s.name_ar end from clinic.services s where s.id = a.service_id),
    'patient_id', a.patient_id, 'patient', (select full_name from clinic.patients where id = a.patient_id),
    'starts_at', a.starts_at, 'ends_at', a.ends_at, 'est_at', a.est_at, 'queue_no', a.queue_no,
    'date', a.session_date, 'day', clinic.day_name(extract(dow from a.session_date)::int, p_lang),
    'time', to_char(coalesce(a.est_at, a.starts_at) at time zone tz, 'HH24:MI'),
    'when', clinic.appt_when(a, p_lang, false),
    'price_text', a.price_text, 'price', a.price, 'is_follow_up', a.is_follow_up,
    'delay_minutes', a.delay_minutes, 'original_time', case when a.original_starts_at is not null
                                                       then to_char(a.original_starts_at at time zone tz, 'HH24:MI') end,
    'hold_expires_at', a.hold_expires_at, 'link', clinic.manage_link(a));
end $$;

create or replace function clinic.log_appt(p_appt bigint, p_kind text, p_detail jsonb default '{}'::jsonb, p_role text default null)
returns void language sql as $$
  insert into clinic.appointment_events (tenant_id, appointment_id, kind, detail, by_user, by_role)
  select a.tenant_id, a.id, p_kind, coalesce(p_detail, '{}'::jsonb), clinic.current_user_id(),
         coalesce(p_role, case when clinic.current_user_id() is null then 'system' else 'staff' end)
    from clinic.appointments a where a.id = p_appt
$$;

-- ---------------------------------------------------------------------
-- Sessions on given days: the schedules, then each day's exceptions
-- ---------------------------------------------------------------------
create or replace function clinic.doctor_sessions(p_tenant uuid, p_from date, p_to date,
                                                  p_doctor uuid default null, p_location uuid default null)
returns table (doctor_id uuid, location_id uuid, schedule_id uuid, session_date date, starts_at timestamptz,
               ends_at timestamptz, mode text, slot_minutes int, capacity int, online boolean)
language plpgsql stable as $$
declare
  tz text := clinic.tenant_tz(p_tenant);
  d  date;
  sc record;
  ex record;
  v_start time; v_end time;
begin
  if p_to < p_from or p_to - p_from > 120 then return; end if;
  d := p_from;
  while d <= p_to loop
    -- regular sessions, unless a whole-day 'off' or a 'changed' replaces them
    for sc in
      select s.* from clinic.schedules s join clinic.doctors dr on dr.id = s.doctor_id
       where s.tenant_id = p_tenant and s.is_active and dr.is_active
         and (p_doctor is null or s.doctor_id = p_doctor)
         and (p_location is null or s.location_id = p_location)
         and s.weekday = extract(dow from d)::int
         and (s.valid_from is null or s.valid_from <= d) and (s.valid_to is null or s.valid_to >= d)
    loop
      if exists (select 1 from clinic.schedule_exceptions e
                  where e.doctor_id = sc.doctor_id and e.on_date = d and e.kind in ('off', 'changed')
                    and (e.location_id is null or e.location_id = sc.location_id)
                    and (e.kind = 'changed' or e.start_time is null)) then
        continue;
      end if;
      v_start := sc.start_time; v_end := sc.end_time;
      -- part of the day off: keep what is left before it (and after it, as a second piece)
      select * into ex from clinic.schedule_exceptions e
       where e.doctor_id = sc.doctor_id and e.on_date = d and e.kind = 'off' and e.start_time is not null
         and (e.location_id is null or e.location_id = sc.location_id)
         and e.start_time < case when v_end <= v_start then '24:00'::time else v_end end and e.end_time > v_start
       limit 1;
      if ex.id is not null then
        if ex.start_time > v_start then
          doctor_id := sc.doctor_id; location_id := sc.location_id; schedule_id := sc.id; session_date := d;
          starts_at := (d + v_start) at time zone tz; ends_at := (d + ex.start_time) at time zone tz;
          mode := sc.mode; slot_minutes := sc.slot_minutes; capacity := sc.capacity; online := sc.online_booking;
          return next;
        end if;
        if ex.end_time < (case when v_end <= v_start then '24:00'::time else v_end end) then
          doctor_id := sc.doctor_id; location_id := sc.location_id; schedule_id := sc.id; session_date := d;
          starts_at := (d + ex.end_time) at time zone tz;
          ends_at := (d + v_end + case when v_end <= v_start then interval '1 day' else interval '0' end) at time zone tz;
          mode := sc.mode; slot_minutes := sc.slot_minutes; capacity := sc.capacity; online := sc.online_booking;
          return next;
        end if;
        ex := null;
        continue;
      end if;
      doctor_id := sc.doctor_id; location_id := sc.location_id; schedule_id := sc.id; session_date := d;
      starts_at := (d + v_start) at time zone tz;
      ends_at := (d + v_end + case when v_end <= v_start then interval '1 day' else interval '0' end) at time zone tz;
      mode := sc.mode; slot_minutes := sc.slot_minutes; capacity := sc.capacity; online := sc.online_booking;
      return next;
    end loop;
    -- changed hours and extra sessions
    for ex in
      select e.*, (select s2.mode from clinic.schedules s2 where s2.doctor_id = e.doctor_id and s2.is_active
                    and (e.location_id is null or s2.location_id = e.location_id) order by s2.created_at limit 1) as base_mode,
             (select s2.slot_minutes from clinic.schedules s2 where s2.doctor_id = e.doctor_id and s2.is_active
                    and (e.location_id is null or s2.location_id = e.location_id) order by s2.created_at limit 1) as base_slot,
             coalesce(e.location_id, (select s2.location_id from clinic.schedules s2 where s2.doctor_id = e.doctor_id and s2.is_active
                                       order by s2.created_at limit 1)) as loc
        from clinic.schedule_exceptions e join clinic.doctors dr on dr.id = e.doctor_id and dr.is_active
       where e.tenant_id = p_tenant and e.on_date = d and e.kind in ('changed', 'extra')
         and e.start_time is not null and e.end_time is not null
         and (p_doctor is null or e.doctor_id = p_doctor)
         and (p_location is null or coalesce(e.location_id, p_location) = p_location)
    loop
      if ex.loc is null then continue; end if;
      doctor_id := ex.doctor_id; location_id := ex.loc; schedule_id := null; session_date := d;
      starts_at := (d + ex.start_time) at time zone tz;
      ends_at := (d + ex.end_time + case when ex.end_time <= ex.start_time then interval '1 day' else interval '0' end) at time zone tz;
      mode := coalesce(ex.mode, ex.base_mode, 'slots'); slot_minutes := coalesce(ex.slot_minutes, ex.base_slot, 15);
      capacity := ex.capacity; online := true;
      return next;
    end loop;
    d := d + 1;
  end loop;
end $$;

-- ---------------------------------------------------------------------
-- Price for a booking: a consultation inside the doctor's follow-up
-- window becomes the follow-up (إعادة / استشارة)
-- ---------------------------------------------------------------------
create or replace function clinic.booking_price(p_service uuid, p_doctor uuid, p_location uuid, p_patient bigint default null)
returns jsonb language plpgsql stable as $$
declare
  s     clinic.services%rowtype;
  d     clinic.doctors%rowtype;
  v_fu  uuid;
  v_last timestamptz;
  v_pr  jsonb;
begin
  select * into s from clinic.services where id = p_service;
  select * into d from clinic.doctors where id = p_doctor;
  if p_patient is not null and s.category = 'consultation' then
    select max(a.starts_at) into v_last from clinic.appointments a
     where a.patient_id = p_patient and a.doctor_id = p_doctor and a.status = 'done';
    if v_last is not null and v_last > now() - make_interval(days => d.follow_up_days) then
      select x.id into v_fu from clinic.services x
       where x.tenant_id = s.tenant_id and x.is_active and x.category = 'follow_up'
         and clinic.service_offered(x.id, p_doctor, p_location)
       order by x.sort limit 1;
      if v_fu is not null then
        v_pr := clinic.service_price(v_fu, p_doctor, p_location);
        return v_pr || jsonb_build_object('service_id', v_fu, 'is_follow_up', true, 'last_visit', v_last,
                                          'follow_up_until', (v_last + make_interval(days => d.follow_up_days))::date);
      end if;
    end if;
  end if;
  return clinic.service_price(p_service, p_doctor, p_location) || jsonb_build_object('service_id', p_service, 'is_follow_up', false);
end $$;

-- the doctor's usual first visit
create or replace function clinic.default_service(p_doctor uuid, p_follow_up boolean default false)
returns uuid language sql stable as $$
  select s.id from clinic.services s join clinic.doctors d on d.id = p_doctor and d.tenant_id = s.tenant_id
   where s.is_active and s.bookable and s.category = case when p_follow_up then 'follow_up' else 'consultation' end
     and clinic.service_offered(s.id, p_doctor)
   order by s.sort, s.code limit 1
$$;

-- ---------------------------------------------------------------------
-- Free times
-- p = {doctor_id?, location_id?, service_id?, patient_id?, from?, to?,
--      band?, after?, time_from?, time_to?, limit?, staff?, ignore_appointment?}
-- ---------------------------------------------------------------------
create or replace function clinic.available_slots(p_tenant uuid, p jsonb)
returns jsonb language plpgsql stable as $$
declare
  t         clinic.tenants%rowtype;
  st        jsonb;
  tz        text;
  v_staff   boolean := coalesce((p ->> 'staff')::boolean, false);
  v_doctor  uuid := nullif(p ->> 'doctor_id', '')::uuid;
  v_loc     uuid := nullif(p ->> 'location_id', '')::uuid;
  v_service uuid := nullif(p ->> 'service_id', '')::uuid;
  v_patient bigint := nullif(p ->> 'patient_id', '')::bigint;
  v_ignore  bigint := nullif(p ->> 'ignore_appointment', '')::bigint;
  v_band    text := coalesce(nullif(p ->> 'band', ''), 'any');
  v_after   timestamptz := nullif(p ->> 'after', '')::timestamptz;
  v_tfrom   time := nullif(p ->> 'time_from', '')::time;
  v_tto     time := nullif(p ->> 'time_to', '')::time;
  v_limit   int := least(coalesce((p ->> 'limit')::int, 40), 200);
  v_today   date;
  v_from    date;
  v_to      date;
  v_earliest timestamptz;
  s         clinic.services%rowtype;
  v_age     numeric;
  v_dur     int;
  ses       record;
  v_t       timestamptz;
  v_end     timestamptz;
  v_local   timestamp;
  v_res     uuid;
  v_new     boolean;
  v_count   int;
  v_queue   int;
  v_cap     int;
  v_est     timestamptz;
  v_delay   int;
  out_slots jsonb := '[]'::jsonb;
  n         int := 0;
  v_reasons text[] := '{}';
  v_qmin    int;
  v_day_n   int;
  v_days    date[] := '{}';
  v_sugg    jsonb := '[]'::jsonb;
  v_last    timestamptz;
  x         jsonb;
begin
  select * into t from clinic.tenants where id = p_tenant;
  st := clinic.merged_settings(t.settings);
  tz := t.timezone;
  v_today := (now() at time zone tz)::date;
  v_qmin := coalesce((st -> 'booking' ->> 'queue_minutes')::int, 15);
  v_from := greatest(coalesce(nullif(p ->> 'from', '')::date, v_today), v_today);
  v_to := least(coalesce(nullif(p ->> 'to', '')::date, v_from + 13),
                v_today + case when v_staff then 365 else coalesce((st -> 'booking' ->> 'days_ahead')::int, 45) end);
  if v_to < v_from then
    return jsonb_build_object('slots', '[]'::jsonb, 'suggested', '[]'::jsonb, 'count', 0,
                              'none_because', jsonb_build_array('TOO_FAR_AHEAD'), 'days_ahead', st -> 'booking' -> 'days_ahead');
  end if;
  v_earliest := now() + case when v_staff then interval '0' else make_interval(mins => coalesce((st -> 'booking' ->> 'lead_minutes')::int, 60)) end;
  if v_after is not null and v_after > v_earliest then v_earliest := v_after; end if;

  if v_service is not null then select * into s from clinic.services where id = v_service and tenant_id = p_tenant; end if;
  if v_patient is not null then
    select clinic.age_years(birth_date) into v_age from clinic.patients where id = v_patient;
  elsif nullif(p ->> 'age', '') is not null then
    v_age := clinic.age_years((select b.birth_date from clinic.parse_birth(p ->> 'age') b));
  end if;
  if s.id is not null and v_age is not null and ((s.min_age is not null and v_age < s.min_age) or (s.max_age is not null and v_age > s.max_age)) then
    return jsonb_build_object('slots', '[]'::jsonb, 'suggested', '[]'::jsonb, 'count', 0, 'none_because', jsonb_build_array('AGE_NOT_SERVED'),
                              'ages', jsonb_build_object('min', s.min_age, 'max', s.max_age));
  end if;

  for ses in
    select x.*, d.accepts_new, d.specialty
      from clinic.doctor_sessions(p_tenant, v_from, v_to, v_doctor, v_loc) x
      join clinic.doctors d on d.id = x.doctor_id
     order by x.starts_at
  loop
    exit when n >= v_limit;
    if not v_staff and not ses.online then v_reasons := v_reasons || 'NOT_BOOKABLE_ONLINE'::text; continue; end if;
    if s.id is not null then
      if not clinic.service_offered(s.id, ses.doctor_id, ses.location_id) then continue; end if;
      if cardinality(s.days) > 0 and not (extract(dow from ses.session_date)::smallint = any(s.days)) then
        v_reasons := v_reasons || 'SERVICE_NOT_THAT_DAY'::text; continue;
      end if;
    end if;
    -- the doctors' rules, enforced here (the staff may book anything)
    if not v_staff then
      if exists (select 1 from clinic.agent_rules r where r.tenant_id = p_tenant and r.is_active and r.kind = 'no_booking_days'
                  and (r.doctor_id is null or r.doctor_id = ses.doctor_id)
                  and r.params -> 'days' @> to_jsonb(extract(dow from ses.session_date)::int)) then
        v_reasons := v_reasons || 'RULE_NO_BOOKING_DAY'::text; continue;
      end if;
      if v_age is not null and exists (select 1 from clinic.agent_rules r where r.tenant_id = p_tenant and r.is_active and r.kind = 'age_doctor'
                  and v_age < (r.params ->> 'max_age')::numeric and r.doctor_id is distinct from ses.doctor_id) then
        v_reasons := v_reasons || 'RULE_AGE_DOCTOR'::text; continue;
      end if;
      v_new := v_patient is null or not exists (select 1 from clinic.appointments a where a.patient_id = v_patient
                                                  and a.doctor_id = ses.doctor_id and a.status = 'done');
      if v_new and not ses.accepts_new then v_reasons := v_reasons || 'NOT_TAKING_NEW_PATIENTS'::text; continue; end if;
    else
      v_new := false;
    end if;

    -- a delay announced for this session: nothing new inside the late minutes
    select coalesce(sum(dn.minutes), 0) into v_delay from clinic.delay_notices dn
     where dn.doctor_id = ses.doctor_id and dn.session_date = ses.session_date and dn.kind = 'delay' and dn.status = 'sent'
       and (dn.location_id is null or dn.location_id = ses.location_id);

    v_dur := coalesce(case when s.id is not null then s.duration_min end, ses.slot_minutes);

    -- fixed times ------------------------------------------------------------
    if ses.mode in ('slots', 'both') then
      -- a late doctor shifts the whole grid
      v_t := ses.starts_at + make_interval(mins => v_delay);
      while v_t + make_interval(mins => v_dur) <= ses.ends_at + make_interval(mins => v_delay) and n < v_limit loop
        v_end := v_t + make_interval(mins => v_dur);
        v_local := v_t at time zone tz;
        if v_t >= v_earliest
           and (v_band = 'any' or clinic.band_of(v_local::time) = v_band)
           and (v_tfrom is null or v_local::time >= v_tfrom)
           and (v_tto is null or v_local::time <= v_tto)
           and not (v_new and not v_staff and exists (
                 select 1 from clinic.agent_rules r where r.tenant_id = p_tenant and r.is_active and r.kind = 'new_patients_until'
                    and (r.doctor_id is null or r.doctor_id = ses.doctor_id) and v_local::time > (r.params ->> 'time')::time))
           and not exists (select 1 from clinic.appointments a
                            where a.doctor_id = ses.doctor_id and a.mode = 'slot'
                              and a.status in ('held', 'booked', 'confirmed', 'arrived', 'in_visit')
                              and (a.status <> 'held' or a.hold_expires_at > now())
                              and a.id is distinct from v_ignore
                              and tstzrange(a.starts_at, a.ends_at, '[)') && tstzrange(v_t, v_end, '[)')) then
          v_res := null;
          if s.resource_kind is not null then
            select r.id into v_res from clinic.resources r
             where r.location_id = ses.location_id and r.kind = s.resource_kind and r.is_active
               and not exists (select 1 from clinic.appointments a
                                where a.resource_id = r.id and a.mode = 'slot'
                                  and a.status in ('held', 'booked', 'confirmed', 'arrived', 'in_visit')
                                  and (a.status <> 'held' or a.hold_expires_at > now())
                                  and a.id is distinct from v_ignore
                                  and tstzrange(a.starts_at, a.ends_at, '[)') && tstzrange(v_t, v_end, '[)'))
             order by r.sort limit 1;
          end if;
          if s.resource_kind is null or v_res is not null then
            out_slots := out_slots || jsonb_build_object(
              'kind', 'slot', 'doctor_id', ses.doctor_id, 'doctor', clinic.doctor_label(ses.doctor_id, 'ar'),
              'location_id', ses.location_id, 'location', clinic.location_label(ses.location_id, 'ar'),
              'resource_id', v_res, 'starts_at', v_t, 'ends_at', v_end, 'date', v_local::date,
              'time', to_char(v_local, 'HH24:MI'), 'band', clinic.band_of(v_local::time),
              'label_ar', clinic.when_words(v_t, tz, 'ar'), 'label_en', clinic.when_words(v_t, tz, 'en'));
            n := n + 1;
          elsif s.resource_kind is not null then
            v_reasons := v_reasons || 'NO_FREE_CHAIR'::text;
          end if;
        end if;
        v_t := v_t + make_interval(mins => ses.slot_minutes);
      end loop;
    end if;

    -- a queue number -----------------------------------------------------------
    if ses.mode in ('queue', 'both') and n < v_limit then
      select count(*), coalesce(max(a.queue_no), 0) into v_count, v_queue
        from clinic.appointments a
       where a.doctor_id = ses.doctor_id and a.location_id = ses.location_id and a.session_date = ses.session_date
         and a.mode = 'queue' and a.status in ('held', 'booked', 'confirmed', 'arrived', 'in_visit', 'done')
         and (a.status <> 'held' or a.hold_expires_at > now()) and a.id is distinct from v_ignore;
      v_cap := ses.capacity;
      v_est := ses.starts_at + make_interval(mins => v_delay + v_count * v_qmin);
      v_local := v_est at time zone tz;
      if (v_cap is null or v_count < v_cap)
         and ses.ends_at > v_earliest
         and (v_after is null or ses.starts_at >= v_after)      -- "a later one": the next session, not this one again
         and v_est < ses.ends_at + make_interval(mins => v_delay)
         and (v_band = 'any' or clinic.band_of((ses.starts_at at time zone tz)::time) = v_band)
         and (v_tfrom is null or v_local::time >= v_tfrom or (ses.ends_at at time zone tz)::time >= v_tfrom)
         and (v_tto is null or (ses.starts_at at time zone tz)::time <= v_tto) then
        out_slots := out_slots || jsonb_build_object(
          'kind', 'queue', 'doctor_id', ses.doctor_id, 'doctor', clinic.doctor_label(ses.doctor_id, 'ar'),
          'location_id', ses.location_id, 'location', clinic.location_label(ses.location_id, 'ar'),
          'starts_at', ses.starts_at, 'ends_at', ses.ends_at, 'date', ses.session_date,
          'queue_no', v_queue + 1, 'est_at', greatest(v_est, now()), 'time', to_char(greatest(v_est, now()) at time zone tz, 'HH24:MI'),
          'band', clinic.band_of((ses.starts_at at time zone tz)::time),
          'session', to_char(ses.starts_at at time zone tz, 'HH24:MI') || '–' || to_char(ses.ends_at at time zone tz, 'HH24:MI'),
          'label_ar', replace(clinic.when_words(ses.starts_at, tz, 'ar'), ' الساعة ', ' — بداية الكشف ')
                      || '، دور رقم ' || (v_queue + 1) || '، حوالي ' || clinic.clock_text((greatest(v_est, now()) at time zone tz)::time, 'ar'),
          'label_en', clinic.when_words(ses.starts_at, tz, 'en') || ' session — number ' || (v_queue + 1)
                      || ', about ' || clinic.clock_text((greatest(v_est, now()) at time zone tz)::time, 'en'),
          'left', case when v_cap is null then null else v_cap - v_count end);
        n := n + 1;
      elsif v_cap is not null and v_count >= v_cap then
        v_reasons := v_reasons || 'SESSION_FULL'::text;
      end if;
    end if;
  end loop;

  -- three to suggest: the first, then the first on other days, then spread through the day
  for x in select * from jsonb_array_elements(out_slots) loop
    exit when jsonb_array_length(v_sugg) >= 3;
    if not ((x ->> 'date')::date = any(v_days)) then
      v_sugg := v_sugg || x; v_days := v_days || (x ->> 'date')::date; v_last := (x ->> 'starts_at')::timestamptz;
    end if;
  end loop;
  if jsonb_array_length(v_sugg) < 3 then
    for x in select * from jsonb_array_elements(out_slots) loop
      exit when jsonb_array_length(v_sugg) >= 3;
      if not (v_sugg @> jsonb_build_array(x))
         and not exists (select 1 from jsonb_array_elements(v_sugg) y
                          where abs(extract(epoch from (y ->> 'starts_at')::timestamptz - (x ->> 'starts_at')::timestamptz)) < 5400
                            and y ->> 'kind' = x ->> 'kind' and y ->> 'doctor_id' = x ->> 'doctor_id') then
        v_sugg := v_sugg || x;
      end if;
    end loop;
  end if;
  select coalesce(jsonb_agg(z order by (z ->> 'starts_at')::timestamptz, z ->> 'kind'), '[]'::jsonb) into v_sugg
    from jsonb_array_elements(v_sugg) z;

  return jsonb_build_object('slots', out_slots, 'suggested', v_sugg, 'count', n,
                            'from', v_from, 'to', v_to,
                            'none_because', case when n = 0 then to_jsonb(array(select distinct unnest(v_reasons))) end);
end $$;

-- ---------------------------------------------------------------------
-- Make (or hold) an appointment — the only place one is created
-- p = {doctor_id, location_id, service_id?, kind 'slot'|'queue', starts_at (slot) | date (queue),
--      patient_id? | patient{full_name, age, sex, relation}, contact_id?, wa_id?, conversation_id?,
--      source, reason?, urgency?, status 'held'|'booked', staff?, plan_item_id?, notes?}
-- ---------------------------------------------------------------------
create or replace function clinic.book_appointment(p_tenant uuid, p jsonb)
returns jsonb language plpgsql as $$
declare
  t        clinic.tenants%rowtype;
  st       jsonb;
  tz       text;
  v_staff  boolean := coalesce((p ->> 'staff')::boolean, false);
  v_status text := coalesce(nullif(p ->> 'status', ''), 'booked');
  v_kind   text := coalesce(nullif(p ->> 'kind', ''), 'slot');
  v_doc    uuid := nullif(p ->> 'doctor_id', '')::uuid;
  v_loc    uuid := nullif(p ->> 'location_id', '')::uuid;
  v_svc    uuid := nullif(p ->> 'service_id', '')::uuid;
  v_patient bigint := nullif(p ->> 'patient_id', '')::bigint;
  v_contact bigint := nullif(p ->> 'contact_id', '')::bigint;
  v_at     timestamptz := nullif(p ->> 'starts_at', '')::timestamptz;
  v_date   date := nullif(p ->> 'date', '')::date;
  v_avail  jsonb;
  v_slot   jsonb;
  v_price  jsonb;
  v_new    boolean;
  v_seq    bigint;
  v_ref    text;
  a        clinic.appointments%rowtype;
  v_wa     text := nullif(p ->> 'wa_id', '');
begin
  select * into t from clinic.tenants where id = p_tenant;
  st := clinic.merged_settings(t.settings);
  tz := t.timezone;
  if v_doc is null then return jsonb_build_object('ok', false, 'error', 'DOCTOR_NEEDED'); end if;
  if v_svc is null then v_svc := clinic.default_service(v_doc); end if;
  if v_kind = 'slot' and v_at is null then return jsonb_build_object('ok', false, 'error', 'TIME_NEEDED'); end if;
  if v_kind = 'queue' and v_date is null then v_date := (v_at at time zone tz)::date; end if;
  if v_kind = 'queue' and v_date is null then return jsonb_build_object('ok', false, 'error', 'DATE_NEEDED'); end if;

  if v_patient is null and jsonb_typeof(p -> 'patient') = 'object' and v_status <> 'held' then
    v_patient := clinic.resolve_patient(p_tenant, v_contact, (p -> 'patient') || jsonb_build_object('created_via',
                   case when p ->> 'source' = 'whatsapp' then 'whatsapp' else 'dashboard' end));
  end if;

  -- is it really free? (the same function the agent offered it from)
  v_avail := clinic.available_slots(p_tenant, jsonb_build_object(
               'doctor_id', v_doc, 'location_id', v_loc, 'service_id', v_svc, 'patient_id', v_patient,
               'age', p -> 'patient' ->> 'age',
               'from', coalesce(v_date, (v_at at time zone tz)::date), 'to', coalesce(v_date, (v_at at time zone tz)::date),
               'staff', v_staff, 'limit', 200, 'ignore_appointment', p ->> 'ignore_appointment'));
  select x into v_slot from jsonb_array_elements(v_avail -> 'slots') x
   where x ->> 'kind' = v_kind
     and (v_kind = 'queue' or (x ->> 'starts_at')::timestamptz = v_at)
     and (v_loc is null or (x ->> 'location_id')::uuid = v_loc)
   limit 1;
  if v_slot is null then
    -- the staff may squeeze a patient in outside the grid, as long as the doctor is free then
    if v_staff and v_kind = 'slot' and coalesce((p ->> 'force')::boolean, false) and v_loc is not null then
      v_slot := jsonb_build_object('kind', 'slot', 'location_id', v_loc, 'starts_at', v_at,
                  'ends_at', v_at + make_interval(mins => coalesce((select duration_min from clinic.services where id = v_svc), 15)),
                  'date', (v_at at time zone tz)::date);
    else
      return jsonb_build_object('ok', false, 'error', 'SLOT_NOT_AVAILABLE',
                                'fact', 'that time is no longer free (or not bookable) — offer the suggested ones',
                                'suggested', (clinic.available_slots(p_tenant, jsonb_build_object(
                                               'doctor_id', v_doc, 'location_id', v_loc, 'service_id', v_svc, 'patient_id', v_patient,
                                               'from', coalesce(v_date, (v_at at time zone tz)::date), 'staff', v_staff, 'limit', 30)) -> 'suggested'),
                                'none_because', v_avail -> 'none_because');
    end if;
  end if;
  v_loc := (v_slot ->> 'location_id')::uuid;
  v_price := clinic.booking_price(v_svc, v_doc, v_loc, v_patient);
  v_new := v_patient is null or not exists (select 1 from clinic.appointments x where x.patient_id = v_patient and x.status = 'done');

  if v_status <> 'held' then
    update clinic.tenants set appt_seq = appt_seq + 1 where id = p_tenant returning appt_seq into v_seq;
    v_ref := t.ref_prefix || '-' || v_seq;
  end if;
  if v_wa is null and v_contact is not null then select wa_id into v_wa from clinic.contacts where id = v_contact; end if;
  if v_contact is null and v_wa is not null then select id into v_contact from clinic.contacts where tenant_id = p_tenant and wa_id = v_wa; end if;

  begin
    insert into clinic.appointments (tenant_id, ref_no, doctor_id, location_id, resource_id, service_id, patient_id, contact_id,
                                     wa_id, conversation_id, status, source, mode, session_date, starts_at, ends_at, queue_no, est_at,
                                     reason, urgency, is_new_patient, is_follow_up, price, price_max, price_kind, price_text,
                                     plan_item_id, hold_expires_at, staff_notes, created_by)
    values (p_tenant, v_ref, v_doc, v_loc, nullif(v_slot ->> 'resource_id', '')::uuid, (v_price ->> 'service_id')::uuid,
            v_patient, v_contact, v_wa,
            coalesce(nullif(p ->> 'conversation_id', '')::bigint, (select id from clinic.conversations where tenant_id = p_tenant and wa_id = v_wa)),
            v_status, coalesce(nullif(p ->> 'source', ''), 'dashboard'), v_kind, (v_slot ->> 'date')::date,
            (v_slot ->> 'starts_at')::timestamptz, (v_slot ->> 'ends_at')::timestamptz,
            case when v_kind = 'queue' then (v_slot ->> 'queue_no')::int end,
            case when v_kind = 'queue' then (v_slot ->> 'est_at')::timestamptz else (v_slot ->> 'starts_at')::timestamptz end,
            left(nullif(btrim(coalesce(p ->> 'reason', '')), ''), 500), coalesce(nullif(p ->> 'urgency', ''), 'routine'),
            v_new, coalesce((v_price ->> 'is_follow_up')::boolean, false),
            (v_price ->> 'price')::numeric, (v_price ->> 'price_max')::numeric, v_price ->> 'kind',
            v_price ->> 'text_ar', nullif(p ->> 'plan_item_id', '')::bigint,
            case when v_status = 'held' then now() + make_interval(mins => coalesce((st -> 'booking' ->> 'hold_minutes')::int, 15)) end,
            nullif(p ->> 'notes', ''), clinic.current_user_id())
    returning * into a;
  exception when exclusion_violation or unique_violation then
    return jsonb_build_object('ok', false, 'error', 'SLOT_TAKEN', 'fact', 'someone took that time a moment ago — offer another');
  end;

  perform clinic.log_appt(a.id, case when v_status = 'held' then 'held' else 'booked' end,
                          jsonb_build_object('source', a.source, 'when', clinic.appt_when(a)),
                          case when a.source = 'whatsapp' then 'agent' end);
  if v_status <> 'held' then
    perform clinic.after_booked(a.id);
  end if;
  select * into a from clinic.appointments where id = a.id;
  return jsonb_build_object('ok', true, 'appointment', clinic.appointment_view(a), 'price', v_price);
end $$;

-- after a booking is final: the reminders, the waitlist entry it answers, the patient's preferences
create or replace function clinic.after_booked(p_appt bigint)
returns void language plpgsql as $$
declare a clinic.appointments%rowtype;
begin
  select * into a from clinic.appointments where id = p_appt;
  perform clinic.schedule_reminders(a.id);
  -- a treatment plan's session
  if a.plan_item_id is not null then
    update clinic.treatment_plan_items set status = 'booked' where id = a.plan_item_id and status = 'planned';
    update clinic.treatment_plans pl set status = 'in_progress'
      from clinic.treatment_plan_items i where i.id = a.plan_item_id and pl.id = i.plan_id and pl.status in ('accepted', 'quoted');
  end if;
  if a.patient_id is not null then
    update clinic.patients
       set preferences = preferences || jsonb_build_object('doctor_id', a.doctor_id, 'location_id', a.location_id,
                                                           'band', clinic.band_of((a.starts_at at time zone clinic.tenant_tz(a.tenant_id))::time))
     where id = a.patient_id;
    update clinic.waitlist set status = 'booked'
     where patient_id = a.patient_id and doctor_id = a.doctor_id and status in ('waiting', 'offered') and a.session_date >= from_date;
  end if;
end $$;

-- turn a hold into a booking (the agent's "book", once the summary was confirmed)
create or replace function clinic.confirm_hold(p_appt bigint, p_patient bigint, p_reason text default null)
returns jsonb language plpgsql as $$
declare
  a     clinic.appointments%rowtype;
  t     clinic.tenants%rowtype;
  v_seq bigint;
  v_pr  jsonb;
begin
  select * into a from clinic.appointments where id = p_appt for update;
  if not found or a.status <> 'held' then return jsonb_build_object('ok', false, 'error', 'HOLD_GONE'); end if;
  if a.hold_expires_at < now() then
    -- the hold lapsed: book it again only if it is still free
    update clinic.appointments set status = 'cancelled', cancelled_at = now(), cancel_reason = 'hold expired', cancelled_by = 'system' where id = a.id;
    return jsonb_build_object('ok', false, 'error', 'HOLD_EXPIRED');
  end if;
  select * into t from clinic.tenants where id = a.tenant_id;
  update clinic.tenants set appt_seq = appt_seq + 1 where id = t.id returning appt_seq into v_seq;
  v_pr := clinic.booking_price(a.service_id, a.doctor_id, a.location_id, p_patient);
  update clinic.appointments
     set status = 'booked', ref_no = t.ref_prefix || '-' || v_seq, patient_id = p_patient, hold_expires_at = null,
         service_id = (v_pr ->> 'service_id')::uuid, is_follow_up = (v_pr ->> 'is_follow_up')::boolean,
         price = (v_pr ->> 'price')::numeric, price_max = (v_pr ->> 'price_max')::numeric, price_kind = v_pr ->> 'kind',
         price_text = v_pr ->> 'text_ar',
         is_new_patient = not exists (select 1 from clinic.appointments x where x.patient_id = p_patient and x.status = 'done'),
         reason = coalesce(left(nullif(btrim(coalesce(p_reason, '')), ''), 500), reason)
   where id = a.id returning * into a;
  perform clinic.log_appt(a.id, 'booked', jsonb_build_object('when', clinic.appt_when(a), 'from_hold', true), 'agent');
  perform clinic.after_booked(a.id);
  return jsonb_build_object('ok', true, 'appointment', clinic.appointment_view(a), 'price', v_pr);
end $$;

-- cancel: who and why, the reminders stop, the waitlist hears of the free time
create or replace function clinic.cancel_appointment(p_appt bigint, p_by text, p_reason text default null, p_notify boolean default false)
returns jsonb language plpgsql as $$
declare
  a    clinic.appointments%rowtype;
  st   jsonb;
  v_lang text;
begin
  select * into a from clinic.appointments where id = p_appt for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'NOT_FOUND'); end if;
  if a.status in ('cancelled', 'done', 'no_show') then
    return jsonb_build_object('ok', false, 'error', 'ALREADY_' || upper(a.status), 'appointment', clinic.appointment_view(a));
  end if;
  update clinic.appointments
     set status = 'cancelled', cancelled_at = now(), cancelled_by = coalesce(p_by, 'clinic'),
         cancel_reason = left(nullif(btrim(coalesce(p_reason, '')), ''), 300), hold_expires_at = null
   where id = a.id returning * into a;
  update clinic.appointment_reminders set status = 'cancelled' where appointment_id = a.id and status = 'scheduled';
  update clinic.delay_notice_items set status = 'cancelled', replied_at = coalesce(replied_at, now())
   where appointment_id = a.id and status in ('queued', 'sent');
  perform clinic.log_appt(a.id, 'cancelled', jsonb_build_object('by', p_by, 'reason', p_reason),
                          case p_by when 'patient' then 'patient' when 'system' then 'system' end);
  if p_notify and a.wa_id is not null and coalesce(a.ref_no, '') <> '' then
    select clinic.merged_settings(settings) into st from clinic.tenants where id = a.tenant_id;
    v_lang := clinic.contact_language(a.tenant_id, a.wa_id);
    perform clinic.queue_message(a.tenant_id, a.wa_id, 'booking_cancelled',
      clinic.render_template(st -> 'templates' ->> ('booking_cancelled_by_clinic_' || v_lang), clinic.message_vars(a, v_lang)
        || jsonb_build_object('reason', case when coalesce(p_reason, '') <> '' then ' — ' || p_reason else '' end)),
      p_template => 'booking_cancelled', p_meta => jsonb_build_object('appointment_id', a.id));
  end if;
  if a.ref_no is not null and a.starts_at > now() then
    perform clinic.offer_waitlist(a.id);
  end if;
  return jsonb_build_object('ok', true, 'appointment', clinic.appointment_view(a));
end $$;

-- move to another free time (same doctor unless given); reminders follow
create or replace function clinic.reschedule_appointment(p_appt bigint, p jsonb)
returns jsonb language plpgsql as $$
declare
  a      clinic.appointments%rowtype;
  tz     text;
  v_kind text;
  v_at   timestamptz := nullif(p ->> 'starts_at', '')::timestamptz;
  v_date date := nullif(p ->> 'date', '')::date;
  v_doc  uuid;
  v_loc  uuid;
  v_avail jsonb;
  v_slot jsonb;
  v_old  text;
  st     jsonb;
  v_lang text;
begin
  select * into a from clinic.appointments where id = p_appt for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'NOT_FOUND'); end if;
  if a.status not in ('booked', 'confirmed', 'held') then
    return jsonb_build_object('ok', false, 'error', 'CANNOT_MOVE_' || upper(a.status));
  end if;
  tz := clinic.tenant_tz(a.tenant_id);
  v_doc := coalesce(nullif(p ->> 'doctor_id', '')::uuid, a.doctor_id);
  v_loc := nullif(p ->> 'location_id', '')::uuid;
  v_kind := coalesce(nullif(p ->> 'kind', ''), case when v_at is null and v_date is not null then 'queue' else 'slot' end);
  if v_kind = 'slot' and v_at is null then return jsonb_build_object('ok', false, 'error', 'TIME_NEEDED'); end if;
  v_old := clinic.appt_when(a);
  v_avail := clinic.available_slots(a.tenant_id, jsonb_build_object(
               'doctor_id', v_doc, 'location_id', v_loc, 'service_id', a.service_id, 'patient_id', a.patient_id,
               'from', coalesce(v_date, (v_at at time zone tz)::date), 'to', coalesce(v_date, (v_at at time zone tz)::date),
               'staff', coalesce((p ->> 'staff')::boolean, false), 'limit', 200, 'ignore_appointment', a.id));
  select x into v_slot from jsonb_array_elements(v_avail -> 'slots') x
   where x ->> 'kind' = v_kind and (v_kind = 'queue' or (x ->> 'starts_at')::timestamptz = v_at)
     and (v_loc is null or (x ->> 'location_id')::uuid = v_loc)
   limit 1;
  if v_slot is null and coalesce((p ->> 'staff')::boolean, false) and coalesce((p ->> 'force')::boolean, false) and v_kind = 'slot' then
    v_slot := jsonb_build_object('kind', 'slot', 'location_id', coalesce(v_loc, a.location_id), 'starts_at', v_at,
                                 'ends_at', v_at + (a.ends_at - a.starts_at), 'date', (v_at at time zone tz)::date);
  end if;
  if v_slot is null then
    return jsonb_build_object('ok', false, 'error', 'SLOT_NOT_AVAILABLE', 'fact', 'that time is not free — offer the suggested ones',
                              'suggested', (clinic.available_slots(a.tenant_id, jsonb_build_object(
                                 'doctor_id', v_doc, 'service_id', a.service_id, 'patient_id', a.patient_id,
                                 'from', coalesce(v_date, (v_at at time zone tz)::date), 'limit', 30, 'ignore_appointment', a.id)) -> 'suggested'));
  end if;
  begin
    update clinic.appointments
       set doctor_id = v_doc, location_id = (v_slot ->> 'location_id')::uuid,
           resource_id = nullif(v_slot ->> 'resource_id', '')::uuid, mode = v_kind,
           session_date = (v_slot ->> 'date')::date, starts_at = (v_slot ->> 'starts_at')::timestamptz,
           ends_at = (v_slot ->> 'ends_at')::timestamptz,
           queue_no = case when v_kind = 'queue' then (v_slot ->> 'queue_no')::int end,
           est_at = case when v_kind = 'queue' then (v_slot ->> 'est_at')::timestamptz else (v_slot ->> 'starts_at')::timestamptz end,
           original_starts_at = null, delay_minutes = 0, confirmed_at = null,
           status = case when status = 'held' then 'held' else 'booked' end,
           at_risk_alerted_at = null
     where id = a.id returning * into a;
  exception when exclusion_violation or unique_violation then
    return jsonb_build_object('ok', false, 'error', 'SLOT_TAKEN', 'fact', 'someone took that time a moment ago — offer another');
  end;
  update clinic.appointment_reminders set status = 'cancelled' where appointment_id = a.id and status = 'scheduled';
  update clinic.delay_notice_items set status = 'changed', replied_at = coalesce(replied_at, now())
   where appointment_id = a.id and status in ('queued', 'sent');
  if a.status <> 'held' then perform clinic.schedule_reminders(a.id); end if;
  perform clinic.log_appt(a.id, 'moved', jsonb_build_object('from', v_old, 'to', clinic.appt_when(a)),
                          case when clinic.current_user_id() is null then coalesce(p ->> 'by_role', 'agent') end);
  if coalesce((p ->> 'notify')::boolean, false) and a.wa_id is not null then
    select clinic.merged_settings(settings) into st from clinic.tenants where id = a.tenant_id;
    v_lang := clinic.contact_language(a.tenant_id, a.wa_id);
    perform clinic.queue_message(a.tenant_id, a.wa_id, 'booking_moved',
      clinic.render_template(st -> 'templates' ->> ('booking_moved_' || v_lang), clinic.message_vars(a, v_lang)),
      p_template => 'booking_moved', p_meta => jsonb_build_object('appointment_id', a.id));
  end if;
  return jsonb_build_object('ok', true, 'appointment', clinic.appointment_view(a), 'moved_from', v_old);
end $$;

-- the words every message about an appointment fills in
create or replace function clinic.message_vars(a clinic.appointments, p_lang text default 'ar')
returns jsonb language plpgsql stable as $$
declare
  co   clinic.contacts%rowtype;
  pt   clinic.patients%rowtype;
  rel  text;
  v_link text := clinic.manage_link(a);
  v_prep text;
begin
  select * into co from clinic.contacts where id = a.contact_id;
  select * into pt from clinic.patients where id = a.patient_id;
  select pc.relation into rel from clinic.patient_contacts pc where pc.patient_id = a.patient_id and pc.contact_id = a.contact_id;
  select case when p_lang = 'en' then coalesce(prep_en, prep_ar) else prep_ar end into v_prep from clinic.services where id = a.service_id;
  return jsonb_build_object(
    'name', clinic.first_name(coalesce(co.full_name, case when coalesce(rel, 'self') = 'self' then pt.full_name end), co.display_name),
    'for', case when pt.id is null or coalesce(rel, 'self') = 'self' then case when p_lang = 'en' then 'your' else 'حضرتك' end
                else split_part(pt.full_name, ' ', 1) || case when p_lang = 'en' then '''s' else '' end end,
    'patient', pt.full_name,
    'when', clinic.appt_when(a, p_lang, true),
    'doctor', clinic.doctor_label(a.doctor_id, p_lang),
    'location', clinic.location_label(a.location_id, p_lang),
    'service', (select case when p_lang = 'en' then coalesce(name_en, name_ar) else name_ar end from clinic.services where id = a.service_id),
    'ref_no', a.ref_no,
    'time', clinic.clock_text((coalesce(a.est_at, a.starts_at) at time zone clinic.tenant_tz(a.tenant_id))::time, p_lang),
    'prep', case when coalesce(v_prep, '') <> '' then E'\n' || v_prep else '' end,
    'link', case when v_link is not null then E'\n' || v_link else '' end);
end $$;

-- ---------------------------------------------------------------------
-- The waitlist: a freed time goes to the first person waiting for it
-- ---------------------------------------------------------------------
create or replace function clinic.offer_waitlist(p_appt bigint)
returns int language plpgsql as $$
declare
  a    clinic.appointments%rowtype;
  w    clinic.waitlist%rowtype;
  st   jsonb;
  v_lang text;
  tz   text;
  v_slot jsonb;
begin
  select * into a from clinic.appointments where id = p_appt;
  tz := clinic.tenant_tz(a.tenant_id);
  if a.starts_at < now() + interval '2 hours' then return 0; end if;
  select * into w from clinic.waitlist x
   where x.tenant_id = a.tenant_id and x.status = 'waiting' and x.wa_id is not null
     and (x.doctor_id is null or x.doctor_id = a.doctor_id)
     and (x.location_id is null or x.location_id = a.location_id)
     and a.session_date >= x.from_date and (x.to_date is null or a.session_date <= x.to_date)
     and (x.band = 'any' or x.band = clinic.band_of((a.starts_at at time zone tz)::time))
     and (x.patient_id is null or x.patient_id is distinct from a.patient_id)
   order by x.created_at limit 1 for update skip locked;
  if w.id is null then return 0; end if;
  v_slot := jsonb_build_object('kind', a.mode, 'doctor_id', a.doctor_id, 'location_id', a.location_id,
                               'service_id', coalesce(w.service_id, a.service_id), 'starts_at', a.starts_at,
                               'date', a.session_date, 'label_ar', clinic.appt_when(a, 'ar'));
  update clinic.waitlist set status = 'offered', offered_slot = v_slot, offered_at = now() where id = w.id;
  select clinic.merged_settings(settings) into st from clinic.tenants where id = a.tenant_id;
  v_lang := clinic.contact_language(a.tenant_id, w.wa_id);
  perform clinic.queue_message(a.tenant_id, w.wa_id, 'waitlist_offer',
    clinic.render_template(st -> 'templates' ->> ('waitlist_offer_' || v_lang),
      jsonb_build_object('name', (select clinic.first_name(full_name, display_name) from clinic.contacts where id = w.contact_id),
                         'for', coalesce((select split_part(full_name, ' ', 1) from clinic.patients where id = w.patient_id), 'حضرتك'),
                         'doctor', clinic.doctor_label(a.doctor_id, v_lang), 'when', clinic.appt_when(a, v_lang, true))),
    p_template => 'waitlist_offer', p_meta => jsonb_build_object('waitlist_id', w.id));
  update clinic.conversations set state = state || jsonb_build_object('pending_offer', jsonb_build_object(
           'waitlist_id', w.id, 'slot', v_slot, 'at', now()))
   where tenant_id = a.tenant_id and wa_id = w.wa_id;
  return 1;
end $$;

-- ---------------------------------------------------------------------
-- Treatment plans: the quote on WhatsApp, acceptance, one session at a time
-- ---------------------------------------------------------------------
create or replace function clinic.plan_total(p_plan bigint)
returns numeric language sql stable as $$
  select coalesce(sum(i.price), 0) - coalesce((select discount from clinic.treatment_plans where id = p_plan), 0)
    from clinic.treatment_plan_items i where i.plan_id = p_plan and i.status <> 'cancelled'
$$;

create or replace function clinic.plan_text(p_plan bigint, p_lang text default 'ar')
returns text language plpgsql stable as $$
declare
  pl  clinic.treatment_plans%rowtype;
  t   clinic.tenants%rowtype;
  i   record;
  out text[] := '{}';
  n   int := 0;
  v_sub numeric := 0;
begin
  select * into pl from clinic.treatment_plans where id = p_plan;
  select * into t from clinic.tenants where id = pl.tenant_id;
  out := out || format(case when p_lang = 'en' then 'Treatment plan for %s with %s:' else 'خطة العلاج لـ %s مع %s:' end,
                       (select split_part(full_name, ' ', 1) from clinic.patients where id = pl.patient_id),
                       clinic.doctor_label(pl.doctor_id, p_lang));
  for i in select * from clinic.treatment_plan_items where plan_id = p_plan and status <> 'cancelled' order by seq, id loop
    n := n + 1;
    v_sub := v_sub + coalesce(i.price, 0);
    out := out || format('%s) %s%s — %s%s', n,
                         case when i.tooth is not null then case when p_lang = 'en' then 'tooth ' else 'سنة ' end || i.tooth || ' · ' else '' end,
                         i.label,
                         case when i.price is null then case when p_lang = 'en' then 'price after the check-up' else 'السعر بعد الكشف' end
                              else clinic.fmt_money(i.price) || case when p_lang = 'en' then ' EGP' else ' ' || t.currency_symbol_ar end end,
                         case when i.sessions > 1 then format(case when p_lang = 'en' then ' (%s sessions)' else ' (%s جلسات)' end, i.sessions) else '' end);
  end loop;
  if pl.discount > 0 then
    out := out || format(case when p_lang = 'en' then 'Total %s, discount %s = %s EGP' else 'الإجمالي %s، خصم %s = %s %s' end,
                         clinic.fmt_money(v_sub), clinic.fmt_money(pl.discount), clinic.fmt_money(v_sub - pl.discount), t.currency_symbol_ar);
  else
    out := out || format(case when p_lang = 'en' then 'Total %s EGP' else 'الإجمالي %s %s' end, clinic.fmt_money(v_sub), t.currency_symbol_ar);
  end if;
  if coalesce(pl.notes, '') <> '' then out := out || pl.notes; end if;
  return array_to_string(out, E'\n');
end $$;

create or replace function clinic.plan_quote(p_plan bigint)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare
  pl     clinic.treatment_plans%rowtype;
  v_wa   text;
  v_lang text;
  r      jsonb;
begin
  select * into pl from clinic.treatment_plans where id = p_plan for update;
  if not found then raise exception 'no such plan'; end if;
  perform clinic.require_role(pl.tenant_id, array['owner', 'manager', 'doctor', 'nurse']);
  select c.wa_id into v_wa from clinic.patient_contacts pc join clinic.contacts c on c.id = pc.contact_id
   where pc.patient_id = pl.patient_id order by (pc.relation = 'self') desc, pc.created_at limit 1;
  if v_wa is null then return jsonb_build_object('ok', false, 'error', 'NO_WHATSAPP', 'fact', 'the patient has no WhatsApp on file'); end if;
  v_lang := clinic.contact_language(pl.tenant_id, v_wa);
  r := clinic.queue_message(pl.tenant_id, v_wa, 'plan_quote',
         clinic.plan_text(pl.id, v_lang) || E'\n\n' ||
         case when v_lang = 'en' then 'If you agree, reply "OK" and we will book the first session.'
              else 'لو موافق ابعت "موافق" ونحجزلك أول جلسة.' end,
         p_sender => 'staff', p_user => clinic.current_user_id(), p_template => 'plan_quote',
         p_meta => jsonb_build_object('plan_id', pl.id));
  update clinic.treatment_plans set status = 'quoted', quoted_at = now() where id = pl.id and status in ('draft', 'quoted');
  update clinic.conversations set state = state || jsonb_build_object('pending_plan', jsonb_build_object('plan_id', pl.id, 'at', now()))
   where tenant_id = pl.tenant_id and wa_id = v_wa;
  return jsonb_build_object('ok', true, 'sent_to', v_wa) || r;
end $$;

-- the next item of a plan that still needs a session, and the earliest day for it
create or replace function clinic.plan_next(p_plan bigint)
returns jsonb language plpgsql stable as $$
declare
  i      clinic.treatment_plan_items%rowtype;
  pl     clinic.treatment_plans%rowtype;
  v_last timestamptz;
begin
  select * into pl from clinic.treatment_plans where id = p_plan;
  select * into i from clinic.treatment_plan_items
   where plan_id = p_plan and status in ('planned', 'in_progress') and done_sessions < sessions
     and not exists (select 1 from clinic.appointments a where a.plan_item_id = treatment_plan_items.id
                      and a.status in ('booked', 'confirmed', 'arrived', 'in_visit'))
   order by seq, id limit 1;
  if i.id is null then return null; end if;
  select max(a.starts_at) into v_last from clinic.appointments a
    join clinic.treatment_plan_items x on x.id = a.plan_item_id where x.plan_id = p_plan and a.status = 'done';
  return jsonb_build_object('plan_id', p_plan, 'item_id', i.id, 'label', i.label, 'tooth', i.tooth, 'service_id', i.service_id,
                            'session', i.done_sessions + 1, 'of', i.sessions, 'doctor_id', pl.doctor_id,
                            'earliest', greatest(clinic.local_today(pl.tenant_id),
                                                 coalesce((v_last at time zone clinic.tenant_tz(pl.tenant_id))::date
                                                          + coalesce(i.session_gap_days, 7), clinic.local_today(pl.tenant_id))));
end $$;

-- ---------------------------------------------------------------------
-- The agent's tool
-- ---------------------------------------------------------------------
create or replace function clinic.booking_tool(p_tenant uuid, p_wa text, p_action text, p_details text)
returns jsonb language plpgsql as $$
declare
  t        clinic.tenants%rowtype;
  st       jsonb;
  tz       text;
  v        jsonb;
  v_action text := lower(btrim(coalesce(p_action, '')));
  conv     clinic.conversations%rowtype;
  co       clinic.contacts%rowtype;
  dr       clinic.booking_drafts%rowtype;
  d        jsonb;
  a        clinic.appointments%rowtype;
  problems jsonb := '[]'::jsonb;
  missing  text[] := '{}';
  upcoming jsonb;
  known    jsonb;
  v_changed boolean := false;
  v_doc    uuid; v_loc uuid; v_svc uuid; v_pat bigint;
  v_avail  jsonb;
  v_slot   jsonb;
  v_opt    int;
  v_at     timestamptz;
  v_date   date;
  v_txt    text;
  v_res    jsonb;
  v_lang   text;
  v_hold   jsonb;
  v_cands  int;
  v_plan   jsonb;
  v_item   record;
begin
  select * into t from clinic.tenants where id = p_tenant;
  st := clinic.merged_settings(t.settings);
  tz := t.timezone;
  v_lang := clinic.contact_language(p_tenant, p_wa);
  begin
    v := coalesce(nullif(btrim(coalesce(p_details, '')), '')::jsonb, '{}'::jsonb);
  exception when others then
    v := '{}'::jsonb;
    problems := problems || jsonb_build_object('problem', 'BAD_DETAILS_JSON', 'fact', 'details must be a JSON object');
  end;
  if jsonb_typeof(v) <> 'object' then v := '{}'::jsonb; end if;
  select * into conv from clinic.conversations where tenant_id = p_tenant and wa_id = p_wa;
  select * into co from clinic.contacts where id = conv.contact_id;
  known := clinic.contact_patients(co.id);
  upcoming := coalesce((select jsonb_agg(clinic.appointment_view(x, v_lang) order by x.starts_at)
                          from clinic.appointments x
                         where x.tenant_id = p_tenant and (x.wa_id = p_wa or x.contact_id = co.id)
                           and x.status in ('booked', 'confirmed') and x.ends_at > now()), '[]'::jsonb);

  if v_action not in ('find_slots', 'update', 'summary', 'book', 'cancel', 'reschedule', 'confirm', 'accept_delay',
                      'status', 'join_waitlist', 'take_offer', 'next_plan_session', 'accept_plan', 'pre_visit') then
    return jsonb_build_object('ok', false, 'error', 'UNKNOWN_ACTION',
      'fact', 'action is one of: find_slots, update, summary, book, cancel, reschedule, confirm, accept_delay, status, join_waitlist, take_offer, next_plan_session, accept_plan, pre_visit');
  end if;

  -- ---- pre_visit: the answers to the speciality's questions, saved on the visit for the doctor ----
  -- details: {answers: {<question key>: "<their words>"}, ref_no?}
  if v_action = 'pre_visit' then
    select * into a from clinic.appointments x
     where x.tenant_id = p_tenant and (x.wa_id = p_wa or x.contact_id = co.id)
       and x.status in ('booked', 'confirmed') and x.ends_at > now()
       and (nullif(v ->> 'ref_no', '') is null or x.ref_no = v ->> 'ref_no')
     order by x.starts_at limit 1;
    if a.id is null then return jsonb_build_object('ok', false, 'error', 'NO_UPCOMING_VISIT'); end if;
    if jsonb_typeof(v -> 'answers') is distinct from 'object' then
      return jsonb_build_object('ok', false, 'error', 'ANSWERS_NEEDED', 'fact', 'details.answers is an object of question key → their words');
    end if;
    -- kept under the question itself (in Arabic), so the doctor reads question and answer together
    update clinic.appointments x
       set pre_visit = x.pre_visit || coalesce((
             select jsonb_object_agg(coalesce(q ->> 'ask_ar', k.key), k.value)
               from jsonb_each(v -> 'answers') k
               left join lateral (select q from jsonb_array_elements(coalesce(
                          (select sp.pre_visit from clinic.specialty_presets sp join clinic.doctors d on d.specialty = sp.code where d.id = x.doctor_id),
                          (select pre_visit from clinic.specialty_presets where code = 'general'))) q
                          where q ->> 'key' = k.key limit 1) qq on true
              where coalesce(btrim(k.value #>> '{}'), '') <> ''), '{}'::jsonb)
     where x.id = a.id;
    perform clinic.log_appt(a.id, 'pre_visit', v -> 'answers', 'agent');
    return jsonb_build_object('ok', true, 'status', 'SAVED', 'still_to_ask', clinic.pre_visit_pending(a.id),
                              'fact', 'saved for the doctor; ask what is still_to_ask only if it fits, never more than one more question now');
  end if;

  -- the appointment a reply is about: by ref_no, else the one a reminder / delay notice asked about, else the next one
  if v_action in ('cancel', 'reschedule', 'confirm', 'accept_delay') then
    select * into a from clinic.appointments x
     where x.tenant_id = p_tenant and (x.wa_id = p_wa or x.contact_id = co.id)
       and x.status in ('booked', 'confirmed') and x.ends_at > now()
       and (nullif(v ->> 'ref_no', '') is null or upper(x.ref_no) = upper(btrim(v ->> 'ref_no')))
     order by (x.id::text = coalesce(conv.state -> 'pending_delay' ->> 'appointment_id', conv.state -> 'pending_reminder' ->> 'appointment_id', '')) desc,
              x.starts_at
     limit 1;
  end if;

  -- ---- confirm / accept a delay --------------------------------------------
  if v_action in ('confirm', 'accept_delay') then
    if a.id is null then return jsonb_build_object('ok', false, 'error', 'NO_UPCOMING_APPOINTMENT', 'upcoming', upcoming); end if;
    update clinic.appointments set status = 'confirmed', confirmed_at = coalesce(confirmed_at, now()) where id = a.id returning * into a;
    update clinic.delay_notice_items set status = 'accepted', replied_at = now() where appointment_id = a.id and status = 'sent';
    perform clinic.log_appt(a.id, case when v_action = 'accept_delay' then 'delay_accepted' else 'confirmed' end, '{}'::jsonb, 'patient');
    update clinic.conversations set state = state - 'pending_reminder' - 'pending_delay' where id = conv.id;
    return jsonb_build_object('ok', true, 'status', case when v_action = 'accept_delay' then 'DELAY_ACCEPTED' else 'CONFIRMED' end,
                              'appointment', clinic.appointment_view(a, v_lang),
                              'fact', case when v_action = 'accept_delay' then 'the new time is confirmed' else 'confirmed — the clinic sees it' end);
  end if;

  -- ---- cancel ------------------------------------------------------------------
  if v_action = 'cancel' then
    select * into dr from clinic.booking_drafts where tenant_id = p_tenant and wa_id = p_wa;
    if dr.wa_id is not null and nullif(v ->> 'ref_no', '') is null and (a.id is null or coalesce((v ->> 'draft')::boolean, false)) then
      if dr.hold_id is not null then
        update clinic.appointments set status = 'cancelled', cancelled_at = now(), cancelled_by = 'patient', cancel_reason = 'draft dropped'
         where id = dr.hold_id and status = 'held';
      end if;
      delete from clinic.booking_drafts where tenant_id = p_tenant and wa_id = p_wa;
      return jsonb_build_object('ok', true, 'status', 'DRAFT_DISCARDED', 'upcoming', upcoming);
    end if;
    if a.id is null then return jsonb_build_object('ok', false, 'error', 'NOTHING_TO_CANCEL', 'upcoming', upcoming); end if;
    v_res := clinic.cancel_appointment(a.id, 'patient', coalesce(nullif(v ->> 'reason', ''), 'cancelled by the patient on WhatsApp'));
    update clinic.conversations set state = state - 'pending_reminder' - 'pending_delay' where id = conv.id;
    return v_res || jsonb_build_object('status', 'CANCELLED', 'fact', 'cancelled; the clinic sees it');
  end if;

  -- ---- status ------------------------------------------------------------------
  if v_action = 'status' then
    select * into dr from clinic.booking_drafts where tenant_id = p_tenant and wa_id = p_wa;
    return jsonb_build_object('ok', true, 'upcoming', upcoming, 'draft', dr.data, 'known_patients', known,
                              'waitlist', (select jsonb_agg(jsonb_build_object('id', w.id, 'doctor', clinic.doctor_label(w.doctor_id, 'ar'),
                                                                               'status', w.status, 'to', w.to_date))
                                             from clinic.waitlist w where w.tenant_id = p_tenant and w.wa_id = p_wa and w.status in ('waiting', 'offered')));
  end if;

  -- ---- the draft ---------------------------------------------------------------
  insert into clinic.booking_drafts (tenant_id, wa_id) values (p_tenant, p_wa)
  on conflict (tenant_id, wa_id) do nothing;
  select * into dr from clinic.booking_drafts where tenant_id = p_tenant and wa_id = p_wa for update;
  d := dr.data;

  -- whatever the patient said about who, which doctor, what for (all actions take them)
  if jsonb_typeof(v -> 'patient') = 'object' then v := v || (v -> 'patient'); end if;
  if nullif(v ->> 'patient_id', '') is not null and exists (
       select 1 from jsonb_array_elements(known) k where k ->> 'id' = v ->> 'patient_id') then
    d := d || jsonb_build_object('patient', jsonb_build_object('patient_id', (v ->> 'patient_id')::bigint));
    v_changed := true;
  elsif v ? 'full_name' or v ? 'age' or v ? 'sex' or v ? 'relation' then
    d := d || jsonb_build_object('patient', coalesce(d -> 'patient', '{}'::jsonb) - 'patient_id' || jsonb_strip_nulls(jsonb_build_object(
           'full_name', nullif(btrim(v ->> 'full_name'), ''), 'age', nullif(btrim(v ->> 'age'), ''),
           'sex', case when v ->> 'sex' in ('male', 'female') then v ->> 'sex' end,
           'relation', nullif(v ->> 'relation', ''))));
    -- a known family member named again
    if nullif(btrim(v ->> 'full_name'), '') is not null then
      v_pat := (select (k ->> 'id')::bigint from jsonb_array_elements(known) k
                 where clinic.norm(k ->> 'full_name') = clinic.norm(v ->> 'full_name')
                    or clinic.norm(k ->> 'first_name') = split_part(clinic.norm(v ->> 'full_name'), ' ', 1) limit 1);
      if v_pat is not null then d := jsonb_set(d, '{patient,patient_id}', to_jsonb(v_pat)); end if;
    elsif v ->> 'relation' = 'self' then
      v_pat := (select (k ->> 'id')::bigint from jsonb_array_elements(known) k where k ->> 'relation' = 'self' limit 1);
      if v_pat is not null then d := jsonb_set(d, '{patient,patient_id}', to_jsonb(v_pat)); end if;
    end if;
    v_changed := true;
  end if;
  if nullif(v ->> 'doctor', '') is not null then
    v_doc := clinic.match_doctor(p_tenant, v ->> 'doctor');
    if v_doc is null then problems := problems || jsonb_build_object('problem', 'DOCTOR_UNKNOWN', 'said', v ->> 'doctor');
    elsif (d ->> 'doctor_id') is distinct from v_doc::text then d := d || jsonb_build_object('doctor_id', v_doc); v_changed := true; end if;
  end if;
  if nullif(v ->> 'location', '') is not null then
    v_loc := clinic.match_location(p_tenant, v ->> 'location');
    if v_loc is null then problems := problems || jsonb_build_object('problem', 'LOCATION_UNKNOWN', 'said', v ->> 'location');
    elsif (d ->> 'location_id') is distinct from v_loc::text then d := d || jsonb_build_object('location_id', v_loc); v_changed := true; end if;
  end if;
  if nullif(v ->> 'service', '') is not null then
    v_svc := clinic.match_service(p_tenant, v ->> 'service', nullif(d ->> 'doctor_id', '')::uuid);
    if v_svc is null then v_svc := clinic.match_service(p_tenant, v ->> 'service'); end if;
    if v_svc is null then problems := problems || jsonb_build_object('problem', 'SERVICE_UNKNOWN', 'said', v ->> 'service',
                                                                     'fact', 'not on the clinic''s list — offer a check-up, or ask the doctor (ask_team)');
    elsif not (select bookable from clinic.services where id = v_svc) then
      problems := problems || jsonb_build_object('problem', 'SERVICE_NOT_BOOKABLE', 'service', (select name_ar from clinic.services where id = v_svc),
                                                 'fact', 'this is arranged after a check-up — book the check-up');
    elsif (d ->> 'service_id') is distinct from v_svc::text then d := d || jsonb_build_object('service_id', v_svc); v_changed := true; end if;
  end if;
  if v ? 'reason' and nullif(btrim(v ->> 'reason'), '') is not null then d := d || jsonb_build_object('reason', left(btrim(v ->> 'reason'), 500)); v_changed := true; end if;
  if v ->> 'urgency' in ('routine', 'soon', 'urgent', 'emergency') then d := d || jsonb_build_object('urgency', v ->> 'urgency'); end if;
  if v ->> 'kind' in ('slot', 'queue') then d := d || jsonb_build_object('kind', v ->> 'kind'); end if;

  -- one doctor does it → that is the doctor; one place → that is the place
  v_svc := nullif(d ->> 'service_id', '')::uuid;
  if d ->> 'doctor_id' is null then
    select count(*), (array_agg(x.id))[1] into v_cands, v_doc from clinic.doctors x
     where x.tenant_id = p_tenant and x.is_active and (v_svc is null or clinic.service_offered(v_svc, x.id));
    if v_cands = 1 then d := d || jsonb_build_object('doctor_id', v_doc); end if;
  end if;
  v_doc := nullif(d ->> 'doctor_id', '')::uuid;
  if v_svc is null and v_doc is not null then v_svc := clinic.default_service(v_doc); end if;
  v_loc := nullif(d ->> 'location_id', '')::uuid;
  v_pat := nullif(d -> 'patient' ->> 'patient_id', '')::bigint;

  -- ---- accept a quoted treatment plan -------------------------------------------
  if v_action = 'accept_plan' then
    select pl.id into v_opt from clinic.treatment_plans pl
     where pl.tenant_id = p_tenant and pl.status = 'quoted'
       and pl.id = coalesce(nullif(v ->> 'plan_id', '')::bigint, nullif(conv.state -> 'pending_plan' ->> 'plan_id', '')::bigint,
                            (select x.id from clinic.treatment_plans x join clinic.patient_contacts pc on pc.patient_id = x.patient_id
                              where pc.contact_id = co.id and x.status = 'quoted' order by x.quoted_at desc limit 1));
    if v_opt is null then return jsonb_build_object('ok', false, 'error', 'NO_QUOTED_PLAN'); end if;
    update clinic.treatment_plans set status = 'accepted', accepted_at = now() where id = v_opt;
    update clinic.conversations set state = state - 'pending_plan' where id = conv.id;
    v_action := 'next_plan_session';
    v := v || jsonb_build_object('plan_id', v_opt);
  end if;

  -- ---- the next session of a treatment plan ---------------------------------------
  if v_action = 'next_plan_session' then
    select pl.id into v_opt from clinic.treatment_plans pl join clinic.patient_contacts pc on pc.patient_id = pl.patient_id
     where pl.tenant_id = p_tenant and pc.contact_id = co.id and pl.status in ('accepted', 'in_progress')
       and (nullif(v ->> 'plan_id', '') is null or pl.id = (v ->> 'plan_id')::bigint)
     order by pl.accepted_at desc nulls last limit 1;
    v_plan := case when v_opt is not null then clinic.plan_next(v_opt) end;
    if v_plan is null then return jsonb_build_object('ok', false, 'error', 'NO_PLAN_SESSION_DUE'); end if;
    d := d || jsonb_build_object('doctor_id', v_plan ->> 'doctor_id', 'service_id', v_plan ->> 'service_id',
                                 'plan_item_id', (v_plan ->> 'item_id')::bigint,
                                 'patient', jsonb_build_object('patient_id', (select patient_id from clinic.treatment_plans where id = v_opt)),
                                 'reason', (v_plan ->> 'label') || ' — ' || (v_plan ->> 'session') || '/' || (v_plan ->> 'of'));
    v_doc := (v_plan ->> 'doctor_id')::uuid; v_svc := nullif(v_plan ->> 'service_id', '')::uuid;
    v_pat := (select patient_id from clinic.treatment_plans where id = v_opt);
    v := v || jsonb_build_object('from', greatest(coalesce(nullif(v ->> 'from', '')::date, (v_plan ->> 'earliest')::date), (v_plan ->> 'earliest')::date));
    v_changed := true;
    v_action := 'find_slots';
  end if;

  -- ---- an offered waitlist time -----------------------------------------------------
  if v_action = 'take_offer' then
    v_slot := conv.state -> 'pending_offer' -> 'slot';
    if v_slot is null then return jsonb_build_object('ok', false, 'error', 'NO_OFFER'); end if;
    d := d || jsonb_build_object('doctor_id', v_slot ->> 'doctor_id', 'location_id', v_slot ->> 'location_id',
                                 'service_id', v_slot ->> 'service_id',
                                 'patient', coalesce(d -> 'patient', jsonb_build_object('patient_id',
                                              (select patient_id from clinic.waitlist where id = (conv.state -> 'pending_offer' ->> 'waitlist_id')::bigint))));
    v := v || jsonb_build_object('starts_at', v_slot ->> 'starts_at', 'kind', v_slot ->> 'kind', 'date', v_slot ->> 'date');
    v_doc := (v_slot ->> 'doctor_id')::uuid; v_loc := (v_slot ->> 'location_id')::uuid; v_svc := nullif(v_slot ->> 'service_id', '')::uuid;
    v_pat := nullif(d -> 'patient' ->> 'patient_id', '')::bigint;
    update clinic.conversations set state = state - 'pending_offer' where id = conv.id;
    v_action := 'update';
  end if;

  -- ---- free times ---------------------------------------------------------------
  if v_action = 'find_slots' or (v_action = 'reschedule' and coalesce(v ->> 'option', v ->> 'starts_at', v ->> 'time', '') = '') then
    if v_action = 'reschedule' then
      if a.id is null then return jsonb_build_object('ok', false, 'error', 'NOTHING_TO_MOVE', 'upcoming', upcoming); end if;
      v_doc := coalesce(v_doc, a.doctor_id); v_svc := coalesce(a.service_id, v_svc); v_pat := coalesce(a.patient_id, v_pat);
      d := d || jsonb_build_object('rescheduling', a.id);
    end if;
    if v_doc is null and v_svc is null then
      -- every doctor (polyclinic, no service named yet): ask which speciality instead of listing everyone's times
      if (select count(*) from clinic.doctors where tenant_id = p_tenant and is_active) > 1 then
        update clinic.booking_drafts set data = d, changed_at = case when v_changed then clock_timestamp() else changed_at end, updated_at = now()
         where tenant_id = p_tenant and wa_id = p_wa;
        return jsonb_build_object('ok', false, 'error', 'WHICH_DOCTOR',
          'fact', 'several doctors here — work out the speciality from the complaint, or ask which doctor',
          'doctors', (select jsonb_agg(jsonb_build_object('code', x.code, 'name', clinic.doctor_label(x.id, 'ar'), 'specialty', x.specialty))
                        from clinic.doctors x where x.tenant_id = p_tenant and x.is_active));
      end if;
    end if;
    v_at := null;
    if coalesce(v ->> 'after', '') = 'last_offered' then
      v_at := (select max((x ->> 'starts_at')::timestamptz) from jsonb_array_elements(coalesce(d -> 'last_offered', '[]'::jsonb)) x) + interval '1 minute';
    elsif nullif(v ->> 'after', '') is not null then
      begin v_at := (v ->> 'after')::timestamptz; exception when others then v_at := null; end;
    end if;
    v_avail := clinic.available_slots(p_tenant, jsonb_strip_nulls(jsonb_build_object(
                 'doctor_id', v_doc, 'location_id', v_loc, 'service_id', v_svc, 'patient_id', v_pat,
                 'age', d -> 'patient' ->> 'age',
                 'from', nullif(coalesce(v ->> 'from', v ->> 'date'), ''), 'to', nullif(coalesce(v ->> 'to', v ->> 'date'), ''),
                 'band', nullif(v ->> 'band', ''), 'after', v_at,
                 'time_from', nullif(v ->> 'time_from', ''), 'time_to', nullif(v ->> 'time_to', ''),
                 'ignore_appointment', case when v_action = 'reschedule' then a.id end, 'limit', 60)));
    -- nothing that day: the next days, so the agent always has something to offer
    if jsonb_array_length(v_avail -> 'suggested') = 0 and nullif(coalesce(v ->> 'to', v ->> 'date'), '') is not null then
      v_res := clinic.available_slots(p_tenant, jsonb_strip_nulls(jsonb_build_object(
                 'doctor_id', v_doc, 'location_id', v_loc, 'service_id', v_svc, 'patient_id', v_pat,
                 'from', (coalesce(v ->> 'to', v ->> 'date'))::date + 1, 'band', nullif(v ->> 'band', ''),
                 'ignore_appointment', case when v_action = 'reschedule' then a.id end, 'limit', 60)));
    end if;
    select coalesce(jsonb_agg(x || jsonb_build_object('option', n)), '[]'::jsonb) into v_res
      from jsonb_array_elements(case when jsonb_array_length(v_avail -> 'suggested') > 0 then v_avail -> 'suggested'
                                     else coalesce(v_res -> 'suggested', '[]'::jsonb) end) with ordinality as s(x, n);
    d := d || jsonb_build_object('last_offered', v_res);
    update clinic.booking_drafts set data = d, changed_at = case when v_changed then clock_timestamp() else changed_at end, updated_at = now()
     where tenant_id = p_tenant and wa_id = p_wa;
    update clinic.conversations set state = state || jsonb_build_object('last_offered', v_res) where id = conv.id;
    return jsonb_build_object('ok', true, 'status', case when jsonb_array_length(v_res) > 0 then 'OPTIONS' else 'NO_FREE_TIME' end,
                              'options', v_res, 'more_free_times', greatest((v_avail ->> 'count')::int - 3, 0),
                              'on_requested_day', jsonb_array_length(v_avail -> 'suggested') > 0,
                              'none_because', v_avail -> 'none_because',
                              'price', case when v_svc is not null and v_doc is not null then clinic.booking_price(v_svc, v_doc, v_loc, v_pat) end,
                              'plan_session', v_plan, 'rescheduling', case when a.id is not null and d ? 'rescheduling' then clinic.appointment_view(a, v_lang) end,
                              'fact', 'offer these (by their label) — nothing is held until the patient picks one');
  end if;

  -- ---- choosing a time (update / reschedule) -----------------------------------------
  v_slot := null;
  if nullif(v ->> 'option', '') is not null then
    v_opt := (v ->> 'option')::int;
    select x into v_slot from jsonb_array_elements(coalesce(d -> 'last_offered', conv.state -> 'last_offered', '[]'::jsonb)) x
     where (x ->> 'option')::int = v_opt;
    if v_slot is null then problems := problems || jsonb_build_object('problem', 'OPTION_UNKNOWN', 'said', v ->> 'option',
                                                                      'fact', 'that option was not offered — find_slots first'); end if;
  elsif nullif(v ->> 'starts_at', '') is not null or (nullif(v ->> 'date', '') is not null and nullif(v ->> 'time', '') is not null)
        or (v ->> 'kind' = 'queue' and nullif(v ->> 'date', '') is not null) then
    begin
      if nullif(v ->> 'starts_at', '') is not null then
        v_at := (v ->> 'starts_at')::timestamptz;
      elsif nullif(v ->> 'time', '') is not null then
        v_txt := btrim(v ->> 'time'); if v_txt ~ '^\d{1,2}$' then v_txt := v_txt || ':00'; end if;
        v_at := ((v ->> 'date')::date + v_txt::time) at time zone tz;
      end if;
      v_date := coalesce(nullif(v ->> 'date', '')::date, (v_at at time zone tz)::date);
      v_slot := jsonb_strip_nulls(jsonb_build_object('kind', coalesce(nullif(v ->> 'kind', ''), case when v_at is null then 'queue' else 'slot' end),
                                                     'starts_at', v_at, 'date', v_date,
                                                     'doctor_id', coalesce(v_doc, a.doctor_id), 'location_id', v_loc));
    exception when others then
      problems := problems || jsonb_build_object('problem', 'TIME_FORMAT', 'fact', 'send date YYYY-MM-DD and time HH:MM (24h), or option N');
    end;
  end if;

  if v_action = 'reschedule' then
    if a.id is null then return jsonb_build_object('ok', false, 'error', 'NOTHING_TO_MOVE', 'upcoming', upcoming); end if;
    if v_slot is null then return jsonb_build_object('ok', false, 'error', 'NEW_TIME_NEEDED', 'problems', problems); end if;
    v_res := clinic.reschedule_appointment(a.id, jsonb_build_object(
               'starts_at', v_slot ->> 'starts_at', 'date', v_slot ->> 'date', 'kind', v_slot ->> 'kind',
               'doctor_id', coalesce(v_slot ->> 'doctor_id', a.doctor_id::text), 'location_id', v_slot ->> 'location_id', 'by_role', 'patient'));
    if (v_res ->> 'ok')::boolean then
      update clinic.conversations set state = state - 'pending_reminder' - 'pending_delay' - 'last_offered' where id = conv.id;
      delete from clinic.booking_drafts where tenant_id = p_tenant and wa_id = p_wa and hold_id is null;
    end if;
    return v_res || jsonb_build_object('status', case when (v_res ->> 'ok')::boolean then 'MOVED' else 'NOT_MOVED' end);
  end if;

  -- a time picked → hold it (a new hold replaces the old one)
  if v_slot is not null then
    if v_slot ->> 'doctor_id' is not null then
      d := d || jsonb_build_object('doctor_id', v_slot ->> 'doctor_id'); v_doc := (v_slot ->> 'doctor_id')::uuid;
    end if;
    if v_slot ->> 'location_id' is not null then d := d || jsonb_build_object('location_id', v_slot ->> 'location_id'); end if;
    if v_doc is null then
      problems := problems || jsonb_build_object('problem', 'DOCTOR_NEEDED', 'fact', 'which doctor? (find_slots first)');
    else
      if v_svc is null then v_svc := clinic.default_service(v_doc); end if;
      if dr.hold_id is not null then
        update clinic.appointments set status = 'cancelled', cancelled_at = now(), cancelled_by = 'patient', cancel_reason = 'another time chosen'
         where id = dr.hold_id and status = 'held';
      end if;
      v_hold := clinic.book_appointment(p_tenant, jsonb_build_object(
                  'doctor_id', v_doc, 'location_id', v_slot ->> 'location_id', 'service_id', v_svc,
                  'kind', coalesce(v_slot ->> 'kind', 'slot'), 'starts_at', v_slot ->> 'starts_at', 'date', v_slot ->> 'date',
                  'patient_id', v_pat, 'patient', d -> 'patient', 'contact_id', co.id, 'wa_id', p_wa, 'conversation_id', conv.id,
                  'source', 'whatsapp', 'status', 'held', 'reason', d ->> 'reason', 'urgency', d ->> 'urgency',
                  'plan_item_id', d ->> 'plan_item_id'));
      if (v_hold ->> 'ok')::boolean then
        dr.hold_id := (v_hold -> 'appointment' ->> 'id')::bigint;
        d := d || jsonb_build_object('service_id', v_hold -> 'appointment' ->> 'service_id',
                                     'location_id', v_hold -> 'appointment' ->> 'location_id',
                                     'slot', jsonb_build_object('label_ar', v_hold -> 'appointment' ->> 'when',
                                                                'starts_at', v_hold -> 'appointment' ->> 'starts_at',
                                                                'kind', v_hold -> 'appointment' ->> 'mode'));
        v_changed := true;
      else
        dr.hold_id := null;
        d := d - 'slot';
        problems := problems || jsonb_build_object('problem', v_hold ->> 'error', 'fact', v_hold ->> 'fact',
                                                   'suggested', v_hold -> 'suggested', 'none_because', v_hold -> 'none_because');
      end if;
    end if;
  end if;

  update clinic.booking_drafts
     set data = d, hold_id = dr.hold_id, updated_at = now(),
         changed_at = case when v_changed then clock_timestamp() else changed_at end
   where tenant_id = p_tenant and wa_id = p_wa
  returning * into dr;

  -- ---- what is still missing ----------------------------------------------------------
  if dr.hold_id is not null then select * into a from clinic.appointments where id = dr.hold_id; end if;
  if a.id is not null and (a.status <> 'held' or a.hold_expires_at < now()) then
    a := null; d := d - 'slot';
    update clinic.booking_drafts set hold_id = null, data = d where tenant_id = p_tenant and wa_id = p_wa returning * into dr;
    problems := problems || jsonb_build_object('problem', 'HOLD_EXPIRED', 'fact', 'the time was held too long — find_slots again');
  end if;
  if (d -> 'patient' ->> 'patient_id') is null then
    if coalesce(d -> 'patient' ->> 'full_name', '') = '' then
      missing := missing || case when jsonb_array_length(known) > 0 then 'who_is_it_for (one of known_patients, or a new name)' else 'patient_full_name' end;
    end if;
    if (st -> 'booking' -> 'new_patient_fields') ? 'age' and coalesce(d -> 'patient' ->> 'age', '') = '' then missing := missing || 'patient_age'::text; end if;
  end if;
  if d ->> 'doctor_id' is null then missing := missing || 'doctor'::text; end if;
  if a.id is null then missing := missing || 'time (find_slots, then update with option)'::text; end if;

  -- ---- summary ----------------------------------------------------------------------
  if v_action = 'summary' then
    if cardinality(missing) > 0 then
      return jsonb_build_object('ok', false, 'error', 'NOT_READY', 'missing', to_jsonb(missing), 'problems', problems, 'draft', d);
    end if;
    update clinic.booking_drafts set summary_at = clock_timestamp() where tenant_id = p_tenant and wa_id = p_wa;
    v_res := clinic.booking_price(a.service_id, a.doctor_id, a.location_id, nullif(d -> 'patient' ->> 'patient_id', '')::bigint);
    return jsonb_build_object('ok', true, 'status', 'SUMMARY_READY',
      'summary_text', case when v_lang = 'en' then
           format(E'%s with %s\n%s — %s\nFor: %s\nPrice: %s%s', coalesce((select coalesce(name_en, name_ar) from clinic.services where id = (v_res ->> 'service_id')::uuid), 'Visit'),
                  clinic.doctor_label(a.doctor_id, 'en'), clinic.appt_when(a, 'en'), clinic.location_label(a.location_id, 'en'),
                  coalesce((select full_name from clinic.patients where id = nullif(d -> 'patient' ->> 'patient_id', '')::bigint), d -> 'patient' ->> 'full_name'),
                  v_res ->> 'text_en', case when (v_res ->> 'is_follow_up')::boolean then ' (follow-up)' else '' end)
         else
           format(E'%s مع %s\n%s — %s\nالحجز لـ: %s\nالسعر: %s%s', coalesce((select name_ar from clinic.services where id = (v_res ->> 'service_id')::uuid), 'كشف'),
                  clinic.doctor_label(a.doctor_id, 'ar'), clinic.appt_when(a, 'ar'), clinic.location_label(a.location_id, 'ar'),
                  coalesce((select full_name from clinic.patients where id = nullif(d -> 'patient' ->> 'patient_id', '')::bigint), d -> 'patient' ->> 'full_name'),
                  v_res ->> 'text_ar', case when (v_res ->> 'is_follow_up')::boolean then ' (إعادة)' else '' end) end,
      'price', v_res, 'hold_expires_at', a.hold_expires_at);
  end if;

  -- ---- book ---------------------------------------------------------------------------
  if v_action = 'book' then
    if cardinality(missing) > 0 then
      return jsonb_build_object('ok', false, 'error', 'NOT_READY', 'missing', to_jsonb(missing), 'problems', problems);
    end if;
    if dr.summary_at is null or dr.summary_at < dr.changed_at then
      return jsonb_build_object('ok', false, 'error', 'SUMMARY_NOT_CONFIRMED',
                                'fact', 'show the summary (action summary) and get a yes before booking');
    end if;
    v_pat := clinic.resolve_patient(p_tenant, co.id, coalesce(d -> 'patient', '{}'::jsonb) || jsonb_build_object('created_via', 'whatsapp'));
    if v_pat is null then return jsonb_build_object('ok', false, 'error', 'NOT_READY', 'missing', jsonb_build_array('patient_full_name')); end if;
    v_res := clinic.confirm_hold(a.id, v_pat, d ->> 'reason');
    if not (v_res ->> 'ok')::boolean then
      update clinic.booking_drafts set hold_id = null, data = d - 'slot' where tenant_id = p_tenant and wa_id = p_wa;
      return v_res || jsonb_build_object('fact', 'the held time lapsed — find_slots again and offer');
    end if;
    delete from clinic.booking_drafts where tenant_id = p_tenant and wa_id = p_wa;
    update clinic.conversations set state = state - 'last_offered' where id = conv.id;
    select * into a from clinic.appointments where id = a.id;
    return v_res || jsonb_build_object('status', 'BOOKED',
      'location', (select jsonb_build_object('name', l.name_ar, 'address', l.address_ar, 'directions', l.directions_ar,
                                             'maps_url', l.maps_url, 'lat', l.lat, 'lng', l.lng)
                     from clinic.locations l where l.id = a.location_id),
      'prep', (select case when v_lang = 'en' then coalesce(prep_en, prep_ar) else prep_ar end from clinic.services where id = a.service_id),
      'fact', 'booked — give the booking number, the day and time, the place; the reminders go out by themselves');
  end if;

  -- ---- join the waitlist -----------------------------------------------------------------
  if v_action = 'join_waitlist' then
    insert into clinic.waitlist (tenant_id, patient_id, contact_id, wa_id, doctor_id, location_id, service_id, to_date, band)
    values (p_tenant, v_pat, co.id, p_wa, v_doc, v_loc, v_svc, nullif(v ->> 'to', '')::date,
            case when v ->> 'band' in ('morning', 'afternoon', 'evening') then v ->> 'band' else 'any' end);
    return jsonb_build_object('ok', true, 'status', 'ON_WAITLIST', 'fact', 'they get a message the moment an earlier time frees up');
  end if;

  -- ---- update -----------------------------------------------------------------------------
  return jsonb_build_object('ok', jsonb_array_length(problems) = 0, 'status', case when v_changed then 'SAVED' else 'UNCHANGED' end,
                            'draft', d - 'last_offered', 'held', case when a.id is not null then clinic.appointment_view(a, v_lang) end,
                            'missing', to_jsonb(missing), 'problems', problems,
                            'ready_for_summary', cardinality(missing) = 0, 'known_patients', known, 'upcoming', upcoming);
end $$;

-- ================= 006_agent.sql =================

-- =====================================================================
-- Everwake Clinic · 006 · alerts, and what the agent reads each turn
--
--   alerts         what the dashboard must show now: an emergency (red
--                  banner, chime, a WhatsApp to the doctor's own number),
--                  something urgent, an unconfirmed visit, a patient who
--                  did not answer a delay notice…
--   raise_alert()  one per thing (repeats within 30 minutes update it)
--   turn_context() everything the Brain and the Agent need for one turn:
--                  the contact and the patients they book for, upcoming
--                  and past visits, the booking in progress, what a
--                  reminder or a delay notice asked them, the catalogue
--                  snapshot, the team's answers, the last messages
--   save_document() a photo or file a patient sent, kept on their record
-- =====================================================================

create table clinic.alerts (
  id                   bigint generated always as identity primary key,
  tenant_id            uuid not null references clinic.tenants(id) on delete cascade,
  kind                 text not null check (kind in ('emergency', 'urgent', 'attention', 'at_risk', 'no_reply', 'cancelled',
                                                     'waitlist', 'payment', 'team_question', 'system')),
  severity             text not null default 'normal' check (severity in ('critical', 'high', 'normal', 'low')),
  title                text not null,
  body                 text,
  patient_id           bigint references clinic.patients(id) on delete set null,
  contact_id           bigint references clinic.contacts(id) on delete set null,
  wa_id                text,
  conversation_id      bigint references clinic.conversations(id) on delete set null,
  appointment_id       bigint references clinic.appointments(id) on delete set null,
  doctor_id            uuid references clinic.doctors(id) on delete set null,
  data                 jsonb not null default '{}'::jsonb,
  status               text not null default 'open' check (status in ('open', 'acknowledged', 'resolved')),
  acknowledged_by      uuid,
  acknowledged_by_name text,
  acknowledged_at      timestamptz,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);
create index alerts_open_idx on clinic.alerts (tenant_id, status, created_at desc);
create trigger alerts_touch before update on clinic.alerts for each row execute function clinic.touch_updated_at();

-- p = {tenant_id, kind, severity?, title?, body?, wa_id?, appointment_id?, patient_id?, doctor_id?, data?, notify_doctor?}
create or replace function clinic.raise_alert(p jsonb)
returns jsonb language plpgsql as $$
declare
  v_tenant uuid := (p ->> 'tenant_id')::uuid;
  v_kind   text := coalesce(nullif(p ->> 'kind', ''), 'attention');
  v_sev    text := coalesce(nullif(p ->> 'severity', ''),
                            case v_kind when 'emergency' then 'critical' when 'urgent' then 'high' else 'normal' end);
  v_wa     text := nullif(p ->> 'wa_id', '');
  v_appt   bigint := nullif(p ->> 'appointment_id', '')::bigint;
  conv     clinic.conversations%rowtype;
  co       clinic.contacts%rowtype;
  al       clinic.alerts%rowtype;
  st       jsonb;
  v_doc    uuid := nullif(p ->> 'doctor_id', '')::uuid;
  v_pat    bigint := nullif(p ->> 'patient_id', '')::bigint;
  v_title  text;
  v_phones text[];
  v_ph     text;
  v_sent   int := 0;
  v_url    text;
begin
  if v_tenant is null then return null; end if;
  if v_wa is not null then
    select * into conv from clinic.conversations where tenant_id = v_tenant and wa_id = v_wa;
    select * into co from clinic.contacts where id = conv.contact_id;
  end if;
  if v_appt is not null then
    select coalesce(v_doc, a.doctor_id), coalesce(v_pat, a.patient_id), coalesce(v_wa, a.wa_id) into v_doc, v_pat, v_wa
      from clinic.appointments a where a.id = v_appt;
  end if;
  -- which doctor: the one named, else the one their next visit (or the booking in progress) is with
  if v_doc is null and v_wa is not null then
    select a.doctor_id into v_doc from clinic.appointments a
     where a.tenant_id = v_tenant and a.wa_id = v_wa and a.status in ('held', 'booked', 'confirmed') order by a.starts_at limit 1;
    if v_doc is null then
      select nullif(data ->> 'doctor_id', '')::uuid into v_doc from clinic.booking_drafts where tenant_id = v_tenant and wa_id = v_wa;
    end if;
  end if;
  -- a red flag of one speciality (a dental swelling) goes to that speciality's doctor
  if nullif(p ->> 'specialty', '') is not null
     and (v_doc is null or (select specialty from clinic.doctors where id = v_doc) is distinct from p ->> 'specialty') then
    v_doc := coalesce(
      (select a.doctor_id from clinic.appointments a join clinic.doctors d on d.id = a.doctor_id
        where a.tenant_id = v_tenant and a.wa_id = v_wa and a.status in ('held', 'booked', 'confirmed') and d.specialty = p ->> 'specialty'
        order by a.starts_at limit 1),
      (select d.id from clinic.doctors d where d.tenant_id = v_tenant and d.is_active and d.specialty = p ->> 'specialty' order by d.sort limit 1),
      v_doc);
  end if;
  v_title := coalesce(nullif(p ->> 'title', ''), case v_kind
    when 'emergency' then 'حالة طارئة محتملة'
    when 'urgent' then 'حالة محتاجة اهتمام سريع'
    when 'at_risk' then 'ميعاد لسه متأكدش'
    when 'no_reply' then 'مريض مردش على تغيير الميعاد'
    else 'محتاج متابعة' end);

  select * into al from clinic.alerts a
   where a.tenant_id = v_tenant and a.kind = v_kind and a.status = 'open'
     and ((v_wa is not null and a.wa_id = v_wa) or (v_appt is not null and a.appointment_id = v_appt))
     and a.created_at > now() - interval '30 minutes'
   order by a.created_at desc limit 1;
  if al.id is not null then
    update clinic.alerts set body = coalesce(nullif(p ->> 'body', ''), body), data = data || coalesce(p -> 'data', '{}'::jsonb),
                             severity = case when v_sev = 'critical' or severity = 'critical' then 'critical' else v_sev end
     where id = al.id returning * into al;
    return jsonb_build_object('alert_id', al.id, 'repeat', true);
  end if;

  insert into clinic.alerts (tenant_id, kind, severity, title, body, patient_id, contact_id, wa_id, conversation_id,
                             appointment_id, doctor_id, data)
  values (v_tenant, v_kind, v_sev, v_title, nullif(p ->> 'body', ''), v_pat, co.id, v_wa, conv.id, v_appt, v_doc,
          coalesce(p -> 'data', '{}'::jsonb))
  returning * into al;

  if v_kind in ('emergency', 'urgent') and conv.id is not null then
    update clinic.conversations
       set urgency = case when v_kind = 'emergency' or urgency = 'emergency' then 'emergency' else 'urgent' end,
           needs_attention = true, attention_reason = coalesce(nullif(p ->> 'body', ''), v_title), attention_at = now()
     where id = conv.id;
  end if;

  -- an emergency reaches the doctor's own WhatsApp too
  select clinic.merged_settings(settings) into st from clinic.tenants where id = v_tenant;
  if v_kind = 'emergency' and coalesce((st -> 'emergency' ->> 'whatsapp_doctor')::boolean, true)
     and coalesce((p ->> 'notify_doctor')::boolean, true) then
    v_phones := case
      when v_doc is not null then array_remove(array[(select clinic.wa_phone(ops_whatsapp) from clinic.doctors where id = v_doc)], null)
      else '{}' end;
    if cardinality(v_phones) = 0 and coalesce(st ->> 'ops_whatsapp', '') <> '' then v_phones := array[clinic.wa_phone(st ->> 'ops_whatsapp')]; end if;
    if cardinality(v_phones) = 0 then
      select array_agg(x) into v_phones from (select clinic.wa_phone(ops_whatsapp) x from clinic.doctors
                                               where tenant_id = v_tenant and is_active and ops_whatsapp is not null order by sort limit 3) z;
    end if;
    v_url := nullif(rtrim(coalesce(st ->> 'public_url', ''), '/'), '');
    foreach v_ph in array coalesce(v_phones, '{}') loop
      if v_ph is not null and clinic.queue_ops_message(v_tenant, v_ph, 'staff_alert',
           format(E'🚨 حالة طارئة محتملة\n%s%s كتب: «%s»\nالمساعد نصحه يتصل بالإسعاف أو يروح أقرب طوارئ.%s',
                  coalesce(nullif(clinic.first_name(co.full_name, co.display_name), ''), 'مريض'),
                  coalesce(' (' || case when co.phone is not null then '0' || substr(co.phone, 3) end || ')', ''),
                  left(coalesce(p ->> 'body', ''), 300),
                  coalesce(E'\n' || v_url || '/inbox?c=' || conv.id, ''))) then
        v_sent := v_sent + 1;
      end if;
    end loop;
  end if;
  return jsonb_build_object('alert_id', al.id, 'repeat', false, 'doctor_notified', v_sent);
end $$;

create or replace function clinic.acknowledge_alert(p_alert bigint, p_resolve boolean default false)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare al clinic.alerts%rowtype;
begin
  select * into al from clinic.alerts where id = p_alert for update;
  if not found then raise exception 'no such alert'; end if;
  perform clinic.require_role(al.tenant_id, array['owner', 'manager', 'doctor', 'nurse', 'receptionist']);
  update clinic.alerts
     set status = case when p_resolve then 'resolved' else 'acknowledged' end,
         acknowledged_by = coalesce(acknowledged_by, clinic.current_user_id()),
         acknowledged_by_name = coalesce(acknowledged_by_name, clinic.my_name(al.tenant_id)),
         acknowledged_at = coalesce(acknowledged_at, now())
   where id = al.id returning * into al;
  if p_resolve and al.conversation_id is not null and al.kind in ('emergency', 'urgent') then
    update clinic.conversations set urgency = null, needs_attention = false where id = al.conversation_id;
  end if;
  return jsonb_build_object('ok', true, 'status', al.status);
end $$;

-- ---------------------------------------------------------------------
-- A patient's photo or file, kept (the engine read it already)
-- p = {tenant_id, wa_id, message_id?, kind?, title?, summary?, values?, url?, mime?}
-- ---------------------------------------------------------------------
create or replace function clinic.save_document(p jsonb)
returns jsonb language plpgsql as $$
declare
  v_tenant uuid := (p ->> 'tenant_id')::uuid;
  v_wa     text := p ->> 'wa_id';
  co       clinic.contacts%rowtype;
  v_pat    bigint;
  v_appt   bigint;
  v_id     bigint;
begin
  select c.* into co from clinic.contacts c where c.tenant_id = v_tenant and c.wa_id = v_wa;
  -- the patient: the one with the next visit, else their only (or own) record
  select a.patient_id, a.id into v_pat, v_appt from clinic.appointments a
   where a.tenant_id = v_tenant and (a.wa_id = v_wa or a.contact_id = co.id) and a.status in ('booked', 'confirmed', 'held')
   order by a.starts_at limit 1;
  if v_pat is null then
    select pc.patient_id into v_pat from clinic.patient_contacts pc where pc.contact_id = co.id
     order by (pc.relation = 'self') desc limit 1;
  end if;
  insert into clinic.documents (tenant_id, patient_id, contact_id, appointment_id, message_id, kind, title, url, mime,
                                source, ai_summary, ai_values)
  values (v_tenant, v_pat, co.id, v_appt, nullif(p ->> 'message_id', '')::bigint,
          case when p ->> 'kind' in ('lab', 'imaging', 'prescription', 'photo', 'report', 'referral', 'other') then p ->> 'kind' else 'photo' end,
          left(nullif(p ->> 'title', ''), 200), nullif(p ->> 'url', ''), nullif(p ->> 'mime', ''), 'whatsapp',
          left(nullif(p ->> 'summary', ''), 4000), case when jsonb_typeof(p -> 'values') = 'array' then p -> 'values' end)
  returning id into v_id;
  return jsonb_build_object('document_id', v_id, 'patient_id', v_pat, 'appointment_id', v_appt);
end $$;

-- ---------------------------------------------------------------------
-- Everything the Brain and the Agent need for one turn
-- ---------------------------------------------------------------------
create or replace function clinic.turn_context(p_tenant uuid, p_wa text)
returns jsonb language plpgsql as $$
declare
  t      clinic.tenants%rowtype;
  st     jsonb;
  conv   clinic.conversations%rowtype;
  co     clinic.contacts%rowtype;
  snap   clinic.catalog_snapshot%rowtype;
  dr     clinic.booking_drafts%rowtype;
  hold   clinic.appointments%rowtype;
  v_lang text;
begin
  perform clinic.ensure_snapshot(p_tenant);
  select * into t from clinic.tenants where id = p_tenant;
  st := clinic.merged_settings(t.settings);
  select * into conv from clinic.conversations where tenant_id = p_tenant and wa_id = p_wa;
  select * into co from clinic.contacts where id = conv.contact_id;
  select * into snap from clinic.catalog_snapshot where tenant_id = p_tenant;
  select * into dr from clinic.booking_drafts where tenant_id = p_tenant and wa_id = p_wa;
  if dr.hold_id is not null then select * into hold from clinic.appointments where id = dr.hold_id; end if;
  v_lang := clinic.contact_language(p_tenant, p_wa);

  return jsonb_build_object(
    'tenant', jsonb_build_object('id', t.id, 'slug', t.slug, 'status', t.status, 'timezone', t.timezone,
                                 'name_ar', t.name_ar, 'name_en', t.name_en, 'currency', t.currency,
                                 'currency_symbol', t.currency_symbol_ar, 'country', t.country, 'specialty', t.specialty),
    'profile', clinic.merged_profile(t.profile),
    'booking_rules', st -> 'booking',
    'emergency', st -> 'emergency',
    'allowed_links', st -> 'allowed_links',
    'public_url', st ->> 'public_url',
    'state', coalesce(conv.state, '{}'::jsonb),
    'conversation', jsonb_build_object('id', conv.id, 'mode', conv.mode, 'needs_attention', conv.needs_attention,
                                       'urgency', conv.urgency, 'created_at', conv.created_at),
    'contact', jsonb_build_object('id', co.id, 'wa_id', co.wa_id, 'phone', co.phone, 'phone_hidden', co.phone_hidden,
                                  'display_name', co.display_name, 'full_name', co.full_name, 'language', co.language,
                                  'first_seen_at', co.first_seen_at),
    'known_patients', clinic.contact_patients(co.id),
    -- the speciality's few questions for the next visit, not yet answered and not on file
    'pre_visit_pending', (select jsonb_build_object('ref_no', x.ref_no, 'questions', clinic.pre_visit_pending(x.id))
                            from clinic.appointments x
                           where x.tenant_id = p_tenant and x.wa_id = p_wa and x.status in ('booked', 'confirmed')
                             and x.ends_at > now() and x.starts_at < now() + interval '14 days'
                             and jsonb_array_length(clinic.pre_visit_pending(x.id)) > 0
                           order by x.starts_at limit 1),
    'upcoming', coalesce((select jsonb_agg(clinic.appointment_view(a, v_lang) order by a.starts_at)
                            from clinic.appointments a
                           where a.tenant_id = p_tenant and (a.wa_id = p_wa or a.contact_id = co.id)
                             and a.status in ('booked', 'confirmed', 'arrived', 'in_visit') and a.ends_at > now() - interval '2 hours'), '[]'::jsonb),
    'past_visits', coalesce((select jsonb_agg(x order by x ->> 'starts_at' desc) from (
                               select clinic.appointment_view(a, v_lang) as x from clinic.appointments a
                                where a.tenant_id = p_tenant and (a.wa_id = p_wa or a.contact_id = co.id)
                                  and a.status in ('done', 'no_show', 'cancelled') and a.ref_no is not null
                                order by a.starts_at desc limit 4) q), '[]'::jsonb),
    'draft', case when dr.wa_id is not null then jsonb_build_object(
                'data', dr.data - 'last_offered', 'last_offered', dr.data -> 'last_offered',
                'held', case when hold.id is not null and hold.status = 'held' and hold.hold_expires_at > now()
                             then clinic.appointment_view(hold, v_lang) end,
                'summary_shown', dr.summary_at is not null and dr.summary_at >= dr.changed_at,
                'updated_at', dr.updated_at) end,
    'pending', jsonb_strip_nulls(jsonb_build_object(
                 'reminder', conv.state -> 'pending_reminder', 'delay', conv.state -> 'pending_delay',
                 'offer', conv.state -> 'pending_offer', 'plan', conv.state -> 'pending_plan',
                 'session_cancelled', conv.state -> 'pending_reschedule')),
    'delays_today', coalesce((select jsonb_agg(jsonb_build_object('doctor', clinic.doctor_label(dn.doctor_id, 'ar'), 'minutes', dn.minutes,
                                                                  'kind', dn.kind, 'reason', dn.reason, 'at', dn.sent_at))
                                from clinic.delay_notices dn
                               where dn.tenant_id = p_tenant and dn.session_date = clinic.local_today(p_tenant) and dn.status = 'sent'), '[]'::jsonb),
    'plans', coalesce((select jsonb_agg(jsonb_build_object('plan_id', pl.id, 'status', pl.status, 'patient', p.full_name,
                                                           'doctor', clinic.doctor_label(pl.doctor_id, 'ar'), 'total', clinic.plan_total(pl.id),
                                                           'next', clinic.plan_next(pl.id)))
                         from clinic.treatment_plans pl join clinic.patients p on p.id = pl.patient_id
                         join clinic.patient_contacts pc on pc.patient_id = pl.patient_id
                        where pc.contact_id = co.id and pl.status in ('quoted', 'accepted', 'in_progress')), '[]'::jsonb),
    'documents_recent', coalesce((select jsonb_agg(jsonb_build_object('kind', d.kind, 'title', d.title, 'summary', left(d.ai_summary, 300),
                                                                      'at', d.created_at) order by d.created_at desc)
                                    from (select * from clinic.documents where contact_id = co.id and created_at > now() - interval '3 days'
                                          order by created_at desc limit 3) d), '[]'::jsonb),
    'team_questions', coalesce((select jsonb_agg(jsonb_build_object('id', q.id, 'question', q.question, 'asked_at', q.asked_at,
                                                                    'status', q.status, 'answer_kind', q.answer_kind, 'answer', q.answer,
                                                                    'answered_by', q.answered_by_name, 'told', q.told_at is not null)
                                                 order by q.asked_at)
                                  from (select * from clinic.team_questions where tenant_id = p_tenant and wa_id = p_wa
                                          and status <> 'dismissed' and asked_at > now() - interval '24 hours'
                                        order by asked_at desc limit 6) q), '[]'::jsonb),
    'recent_messages', coalesce((select jsonb_agg(jsonb_build_object('direction', m.direction, 'sender', m.sender, 'kind', m.kind,
                                                                     'text', coalesce(m.meta ->> 'understood', m.body), 'at', m.created_at,
                                                                     'purpose', m.meta ->> 'purpose', 'reply_to', m.meta ->> 'reply_to')
                                                  order by m.created_at)
                                   from (select * from clinic.messages where tenant_id = p_tenant and wa_id = p_wa and status not in ('failed', 'cancelled')
                                         order by created_at desc limit 20) m), '[]'::jsonb),
    'pause', (select jsonb_build_object('apologized_at', pc.apologized_at, 'resume_notified_at', pc.resume_notified_at)
                from clinic.pause_contacts pc where pc.tenant_id = p_tenant and pc.wa_id = p_wa
                 and pc.last_message_at > now() - interval '24 hours' order by pc.last_message_at desc limit 1),
    'catalog_digest', coalesce(snap.digest_text, ''),
    'catalog_lookup', coalesce(snap.lookup, '{}'::jsonb),
    'catalog_version', coalesce(snap.version_hash, 'none'),
    'locations', coalesce((select jsonb_agg(jsonb_build_object('id', l.id, 'name', l.name_ar, 'address', l.address_ar,
                                                               'directions', l.directions_ar, 'maps_url', l.maps_url, 'lat', l.lat, 'lng', l.lng)
                                            order by l.sort)
                             from clinic.locations l where l.tenant_id = p_tenant and l.is_active), '[]'::jsonb),
    'specialty_triage', coalesce((select jsonb_agg(x || jsonb_build_object('specialty', sp.code))
                                    from clinic.specialty_presets sp, jsonb_array_elements(sp.triage) x
                                   where sp.code in (select d.specialty from clinic.doctors d where d.tenant_id = p_tenant and d.is_active)), '[]'::jsonb),
    -- the clinic's hours, for placing a time said without ص/م
    'hours', coalesce((select jsonb_agg(distinct jsonb_build_array(to_char(sc.start_time, 'HH24:MI'), to_char(sc.end_time, 'HH24:MI')))
                         from clinic.schedules sc where sc.tenant_id = p_tenant and sc.is_active), '[]'::jsonb),
    'doctors', coalesce((select jsonb_agg(jsonb_build_object('id', d.id, 'code', d.code, 'name', clinic.doctor_label(d.id, 'ar'),
                                                             'specialty', d.specialty, 'gender', d.gender) order by d.sort)
                           from clinic.doctors d where d.tenant_id = p_tenant and d.is_active), '[]'::jsonb),
    'specialty_keywords', coalesce((select jsonb_object_agg(sp.code, to_jsonb(sp.keywords)) from clinic.specialty_presets sp
                                     where sp.code in (select d.specialty from clinic.doctors d where d.tenant_id = p_tenant and d.is_active)), '{}'::jsonb));
end $$;

-- after the tools ran: what the reply is checked against
create or replace function clinic.read_back(p_tenant uuid, p_wa text)
returns jsonb language plpgsql as $$
declare
  dr   clinic.booking_drafts%rowtype;
  hold clinic.appointments%rowtype;
begin
  select * into dr from clinic.booking_drafts where tenant_id = p_tenant and wa_id = p_wa;
  if dr.hold_id is not null then select * into hold from clinic.appointments where id = dr.hold_id; end if;
  return jsonb_build_object(
    'state', coalesce((select state from clinic.conversations where tenant_id = p_tenant and wa_id = p_wa), '{}'::jsonb),
    'held', case when hold.id is not null and hold.status = 'held' then clinic.appointment_view(hold) end,
    'last_offered', dr.data -> 'last_offered',
    'last_booked', (select clinic.appointment_view(a) from clinic.appointments a
                     where a.tenant_id = p_tenant and a.wa_id = p_wa and a.ref_no is not null and a.created_at > now() - interval '1 day'
                     order by a.updated_at desc limit 1),
    'upcoming', coalesce((select jsonb_agg(clinic.appointment_view(a) order by a.starts_at) from clinic.appointments a
                           where a.tenant_id = p_tenant and a.wa_id = p_wa and a.status in ('booked', 'confirmed') and a.ends_at > now()), '[]'::jsonb));
end $$;

-- ================= 007_reminders_delays.sql =================

-- =====================================================================
-- Everwake Clinic · 007 · reminders, "the doctor is late", cancelled
-- sessions, the doctor's WhatsApp commands, and housekeeping
--
-- Reminders. Each booking gets its reminders when it is made (default:
-- the evening before at 19:00, and 3 hours before; Settings → Reminders).
-- They ask the patient to confirm (1), change (2) or cancel (3); the agent
-- reads the reply knowing which appointment it was about. Still not
-- confirmed a while after the last one → an "at risk" alert.
--
-- "I'll be 20 minutes late". announce_delay() first shows who is affected
-- (preview), then moves every appointment of that session that has not
-- arrived, tells each patient the new time (3 seconds apart) with the
-- choice to accept, pick another time or cancel, and blocks the late
-- minutes for new bookings. A patient who does not answer is reminded
-- once — sooner when their visit is near:
--     wait = clamp(0.4 × (time to their original start), 10, 90) minutes,
--            and never later than 30 minutes before that start
-- — then shown on the dashboard as "no reply". A second notice adds up.
--
-- cancel_session() does the same for a session that cannot happen: each
-- patient is offered their two nearest times, and "1" or "2" books it.
--
-- staff_tool() is what the doctor (or the front desk) reaches from their
-- own WhatsApp number: today's list, a delay, a cancelled session, time
-- off, and changes to services, prices, offers, answers and rules.
-- Everything is shown first and done only after "تمام".
-- =====================================================================

create table clinic.appointment_reminders (
  id             bigint generated always as identity primary key,
  tenant_id      uuid not null references clinic.tenants(id) on delete cascade,
  appointment_id bigint not null references clinic.appointments(id) on delete cascade,
  seq            int not null,
  key            text not null,
  due_at         timestamptz not null,
  status         text not null default 'scheduled' check (status in ('scheduled', 'sent', 'skipped', 'cancelled')),
  sent_at        timestamptz,
  created_at     timestamptz not null default now()
);
create index appointment_reminders_due_idx on clinic.appointment_reminders (due_at) where status = 'scheduled';
create index appointment_reminders_appt_idx on clinic.appointment_reminders (appointment_id);

create table clinic.delay_notices (
  id              bigint generated always as identity primary key,
  tenant_id       uuid not null references clinic.tenants(id) on delete cascade,
  doctor_id       uuid not null references clinic.doctors(id) on delete cascade,
  location_id     uuid references clinic.locations(id) on delete cascade,
  session_date    date not null,
  kind            text not null default 'delay' check (kind in ('delay', 'cancel_session')),
  minutes         int not null default 0,
  from_at         timestamptz,
  reason          text,
  status          text not null default 'sent' check (status in ('sent', 'cancelled')),
  via             text not null default 'dashboard' check (via in ('dashboard', 'whatsapp', 'assistant')),
  created_by      uuid,
  created_by_name text,
  counts          jsonb not null default '{}'::jsonb,
  created_at      timestamptz not null default now(),
  sent_at         timestamptz not null default now()
);
create index delay_notices_day_idx on clinic.delay_notices (tenant_id, session_date, doctor_id);

create table clinic.delay_notice_items (
  id             bigint generated always as identity primary key,
  tenant_id      uuid not null references clinic.tenants(id) on delete cascade,
  notice_id      bigint not null references clinic.delay_notices(id) on delete cascade,
  appointment_id bigint not null references clinic.appointments(id) on delete cascade,
  wa_id          text,
  old_at         timestamptz,
  new_at         timestamptz,
  status         text not null default 'sent'
                 check (status in ('sent', 'accepted', 'changed', 'cancelled', 'no_reply', 'skipped')),
  reply_due_at   timestamptz,
  followed_up_at timestamptz,
  replied_at     timestamptz,
  options        jsonb,
  created_at     timestamptz not null default now()
);
create index delay_notice_items_due_idx on clinic.delay_notice_items (reply_due_at) where status = 'sent';
create index delay_notice_items_notice_idx on clinic.delay_notice_items (notice_id);

-- ---------------------------------------------------------------------
-- Reminders
-- ---------------------------------------------------------------------
create or replace function clinic.schedule_reminders(p_appt bigint)
returns int language plpgsql as $$
declare
  a      clinic.appointments%rowtype;
  st     jsonb;
  tz     text;
  r      jsonb;
  v_due  timestamptz;
  v_at   timestamptz;
  v_min  int;
  n      int := 0;
  v_seq  int := 0;
begin
  select * into a from clinic.appointments where id = p_appt;
  if a.status not in ('booked', 'confirmed') then return 0; end if;
  select clinic.merged_settings(settings), timezone into st, tz from clinic.tenants where id = a.tenant_id;
  v_at := coalesce(a.est_at, a.starts_at);
  v_min := coalesce((st ->> 'reminder_min_lead_minutes')::int, 45);
  delete from clinic.appointment_reminders where appointment_id = a.id and status = 'scheduled';
  for r in select * from jsonb_array_elements(coalesce(st -> 'reminders', '[]'::jsonb)) loop
    v_seq := v_seq + 1;
    v_due := case r ->> 'kind'
               when 'day_before' then ((a.session_date - 1) + coalesce(nullif(r ->> 'at', ''), '19:00')::time) at time zone tz
               when 'hours_before' then v_at - make_interval(mins => (coalesce((r ->> 'hours')::numeric, 3) * 60)::int)
               when 'same_day' then (a.session_date + coalesce(nullif(r ->> 'at', ''), '09:00')::time) at time zone tz
             end;
    if v_due is null or v_due <= now() or v_at - v_due < make_interval(mins => v_min) then continue; end if;
    -- two reminders an hour apart help nobody: keep the later one
    if exists (select 1 from clinic.appointment_reminders x where x.appointment_id = a.id and x.status = 'scheduled'
                and abs(extract(epoch from x.due_at - v_due)) < 3600) then
      delete from clinic.appointment_reminders x where x.appointment_id = a.id and x.status = 'scheduled'
         and abs(extract(epoch from x.due_at - v_due)) < 3600 and x.due_at < v_due;
      if exists (select 1 from clinic.appointment_reminders x where x.appointment_id = a.id and x.status = 'scheduled'
                  and abs(extract(epoch from x.due_at - v_due)) < 3600) then continue; end if;
    end if;
    insert into clinic.appointment_reminders (tenant_id, appointment_id, seq, key, due_at)
    values (a.tenant_id, a.id, v_seq, coalesce(r ->> 'key', r ->> 'kind'), v_due);
    n := n + 1;
  end loop;
  return n;
end $$;

create or replace function clinic.reminders_due()
returns int language plpgsql as $$
declare
  r      record;
  st     jsonb;
  v_lang text;
  v_tpl  text;
  n      int := 0;
  q      jsonb;
begin
  for r in
    select ar.id as rid, ar.key, a.*
      from clinic.appointment_reminders ar join clinic.appointments a on a.id = ar.appointment_id
     where ar.status = 'scheduled' and ar.due_at <= now()
     order by ar.due_at
     for update of ar skip locked
     limit 200
  loop
    if r.status not in ('booked', 'confirmed') or r.wa_id is null
       or coalesce(r.est_at, r.starts_at) < now() + interval '15 minutes' then
      update clinic.appointment_reminders set status = 'skipped' where id = r.rid;
      continue;
    end if;
    select clinic.merged_settings(settings) into st from clinic.tenants where id = r.tenant_id;
    v_lang := clinic.contact_language(r.tenant_id, r.wa_id);
    v_tpl := st -> 'templates' ->> ('reminder_' || r.key || '_' || v_lang);
    if v_tpl is null then v_tpl := st -> 'templates' ->> ('reminder_day_before_' || v_lang); end if;
    q := clinic.queue_message(r.tenant_id, r.wa_id, 'reminder',
           clinic.render_template(v_tpl, clinic.message_vars((select x from clinic.appointments x where x.id = r.id), v_lang)),
           p_template => 'reminder_' || r.key, p_meta => jsonb_build_object('appointment_id', r.id, 'reminder_id', r.rid));
    update clinic.appointment_reminders set status = case when q ? 'outbox_id' then 'sent' else 'skipped' end, sent_at = now() where id = r.rid;
    if q ? 'outbox_id' then
      update clinic.conversations set state = state || jsonb_build_object('pending_reminder',
               jsonb_build_object('appointment_id', r.id, 'ref_no', r.ref_no, 'key', r.key, 'at', now()))
       where tenant_id = r.tenant_id and wa_id = r.wa_id;
      perform clinic.log_appt(r.id, 'reminder_sent', jsonb_build_object('key', r.key), 'system');
      n := n + 1;
    end if;
  end loop;

  -- not confirmed a while after the last reminder → "at risk"
  for r in
    select a.*, clinic.merged_settings(t.settings) as st
      from clinic.appointments a join clinic.tenants t on t.id = a.tenant_id
     where a.status = 'booked' and a.at_risk_alerted_at is null and a.starts_at > now()
       and exists (select 1 from clinic.appointment_reminders x where x.appointment_id = a.id and x.status = 'sent')
       and not exists (select 1 from clinic.appointment_reminders x where x.appointment_id = a.id and x.status = 'scheduled')
       and (select max(x.sent_at) from clinic.appointment_reminders x where x.appointment_id = a.id)
           < now() - make_interval(mins => coalesce((clinic.merged_settings(t.settings) ->> 'at_risk_after_minutes')::int, 45))
     limit 100
  loop
    update clinic.appointments set at_risk_alerted_at = now() where id = r.id;
    perform clinic.raise_alert(jsonb_build_object('tenant_id', r.tenant_id, 'kind', 'at_risk', 'appointment_id', r.id,
      'title', 'ميعاد لسه متأكدش', 'body', coalesce((select full_name from clinic.patients where id = r.patient_id), 'مريض') || ' — '
                                          || clinic.appt_when((select x from clinic.appointments x where x.id = r.id), 'ar', true)));
  end loop;
  return n;
end $$;

-- ---------------------------------------------------------------------
-- The doctor is late
-- p = {doctor_id | doctor, location_id?, date?, minutes, from_time?, reason?, preview?, via?, by_name?}
-- ---------------------------------------------------------------------
create or replace function clinic.resolve_doctor(p_tenant uuid, p jsonb)
returns uuid language plpgsql stable as $$
declare v uuid := nullif(p ->> 'doctor_id', '')::uuid;
begin
  if v is null and nullif(p ->> 'doctor', '') is not null then v := clinic.match_doctor(p_tenant, p ->> 'doctor'); end if;
  if v is null and (select count(*) from clinic.doctors where tenant_id = p_tenant and is_active) = 1 then
    select id into v from clinic.doctors where tenant_id = p_tenant and is_active;
  end if;
  return v;
end $$;

create or replace function clinic.reply_wait(p_tenant uuid, p_original timestamptz)
returns timestamptz language plpgsql stable as $$
declare
  st    jsonb := (select clinic.merged_settings(settings) -> 'delay' from clinic.tenants where id = p_tenant);
  v_left numeric := greatest(extract(epoch from p_original - now()) / 60, 0);
  v_wait numeric;
  v_due timestamptz;
begin
  v_wait := least(greatest(v_left * coalesce((st ->> 'reply_share')::numeric, 0.4), coalesce((st ->> 'reply_min_minutes')::numeric, 10)),
                  coalesce((st ->> 'reply_max_minutes')::numeric, 90));
  v_due := now() + make_interval(mins => v_wait::int);
  if v_due > p_original - make_interval(mins => coalesce((st ->> 'before_start_minutes')::int, 30)) then
    v_due := greatest(p_original - make_interval(mins => coalesce((st ->> 'before_start_minutes')::int, 30)),
                      now() + make_interval(mins => coalesce((st ->> 'reply_min_minutes')::int, 10)));
  end if;
  return v_due;
end $$;

create or replace function clinic.announce_delay(p_tenant uuid, p jsonb)
returns jsonb language plpgsql as $$
declare
  t        clinic.tenants%rowtype;
  st       jsonb;
  tz       text;
  v_doc    uuid := clinic.resolve_doctor(p_tenant, p);
  v_loc    uuid := nullif(p ->> 'location_id', '')::uuid;
  v_date   date := coalesce(nullif(p ->> 'date', '')::date, clinic.local_today(p_tenant));
  v_min    int := nullif(regexp_replace(coalesce(p ->> 'minutes', ''), '\D', '', 'g'), '')::int;
  v_from   timestamptz;
  v_prev   boolean := coalesce((p ->> 'preview')::boolean, false);
  a        clinic.appointments%rowtype;
  v_items  jsonb := '[]'::jsonb;
  v_notice bigint;
  v_item   bigint;
  v_lang   text;
  n        int := 0;
  v_sent   int := 0;
  v_old    timestamptz;
  v_due    timestamptz;
begin
  select * into t from clinic.tenants where id = p_tenant;
  st := clinic.merged_settings(t.settings);
  tz := t.timezone;
  if v_doc is null then
    return jsonb_build_object('ok', false, 'error', 'WHICH_DOCTOR',
      'doctors', (select jsonb_agg(clinic.doctor_label(id, 'ar')) from clinic.doctors where tenant_id = p_tenant and is_active));
  end if;
  if v_min is null or v_min < 5 or v_min > 240 then
    return jsonb_build_object('ok', false, 'error', 'MINUTES_NEEDED', 'fact', 'how many minutes late (5 to 240)?');
  end if;
  if nullif(p ->> 'location', '') is not null then v_loc := clinic.match_location(p_tenant, p ->> 'location'); end if;
  if nullif(p ->> 'from_time', '') is not null then v_from := (v_date + (p ->> 'from_time')::time) at time zone tz; end if;

  for a in
    select * from clinic.appointments x
     where x.tenant_id = p_tenant and x.doctor_id = v_doc and x.session_date = v_date
       and x.status in ('booked', 'confirmed') and (v_loc is null or x.location_id = v_loc)
       and (v_from is null or coalesce(x.est_at, x.starts_at) >= v_from)
     order by coalesce(x.est_at, x.starts_at)
  loop
    v_items := v_items || jsonb_build_object('appointment_id', a.id, 'ref_no', a.ref_no,
      'patient', (select full_name from clinic.patients where id = a.patient_id),
      'old_time', to_char(coalesce(a.est_at, a.starts_at) at time zone tz, 'HH24:MI'),
      'new_time', to_char((coalesce(a.est_at, a.starts_at) + make_interval(mins => v_min)) at time zone tz, 'HH24:MI'),
      'queue_no', a.queue_no, 'whatsapp', a.wa_id is not null);
  end loop;

  if v_prev then
    return jsonb_build_object('ok', true, 'status', 'PREVIEW', 'doctor', clinic.doctor_label(v_doc, 'ar'), 'date', v_date,
                              'minutes', v_min, 'count', jsonb_array_length(v_items), 'items', v_items,
                              'fact', format('%s patients would be told the new time — send only after a yes', jsonb_array_length(v_items)));
  end if;

  insert into clinic.delay_notices (tenant_id, doctor_id, location_id, session_date, kind, minutes, from_at, reason, via,
                                    created_by, created_by_name)
  values (p_tenant, v_doc, v_loc, v_date, 'delay', v_min, v_from, nullif(btrim(coalesce(p ->> 'reason', '')), ''),
          coalesce(nullif(p ->> 'via', ''), 'dashboard'), clinic.current_user_id(), coalesce(nullif(p ->> 'by_name', ''), clinic.my_name(p_tenant)))
  returning id into v_notice;

  -- everyone moves together; the overlap checks run at the end
  set constraints clinic.appointments_doctor_free, clinic.appointments_resource_free deferred;
  for a in
    select * from clinic.appointments x
     where x.tenant_id = p_tenant and x.doctor_id = v_doc and x.session_date = v_date
       and x.status in ('booked', 'confirmed', 'held') and (v_loc is null or x.location_id = v_loc)
       and (v_from is null or coalesce(x.est_at, x.starts_at) >= v_from)
     order by coalesce(x.est_at, x.starts_at) desc
  loop
    v_old := coalesce(a.original_starts_at, a.est_at, a.starts_at);
    update clinic.appointments
       set starts_at = case when mode = 'slot' then starts_at + make_interval(mins => v_min) else starts_at end,
           ends_at = case when mode = 'slot' then ends_at + make_interval(mins => v_min) else ends_at end,
           est_at = coalesce(est_at, starts_at) + make_interval(mins => v_min),
           original_starts_at = coalesce(original_starts_at, est_at, starts_at),
           delay_minutes = delay_minutes + v_min
     where id = a.id returning * into a;
    if a.status = 'held' then continue; end if;
    perform clinic.log_appt(a.id, 'delayed', jsonb_build_object('minutes', v_min, 'notice_id', v_notice));
    -- the reminders follow the new time
    update clinic.appointment_reminders set due_at = due_at + make_interval(mins => v_min)
     where appointment_id = a.id and status = 'scheduled' and key = 'hours_before';
    v_due := clinic.reply_wait(p_tenant, v_old);
    insert into clinic.delay_notice_items (tenant_id, notice_id, appointment_id, wa_id, old_at, new_at, status, reply_due_at)
    values (p_tenant, v_notice, a.id, a.wa_id, v_old, coalesce(a.est_at, a.starts_at),
            case when a.wa_id is null then 'skipped' else 'sent' end, case when a.wa_id is not null then v_due end)
    returning id into v_item;
    n := n + 1;
    if a.wa_id is not null then
      v_lang := clinic.contact_language(p_tenant, a.wa_id);
      perform clinic.queue_message(p_tenant, a.wa_id, 'delay_notice',
        clinic.render_template(st -> 'templates' ->> ('delay_notice_' || v_lang), clinic.message_vars(a, v_lang) || jsonb_build_object(
          'minutes', a.delay_minutes,
          'new_time', clinic.clock_text((coalesce(a.est_at, a.starts_at) at time zone tz)::time, v_lang),
          'old_time', clinic.clock_text((v_old at time zone tz)::time, v_lang))),
        p_not_before => now() + make_interval(secs => v_sent * 3), p_template => 'delay_notice',
        p_meta => jsonb_build_object('appointment_id', a.id, 'delay_item_id', v_item));
      update clinic.conversations set state = state || jsonb_build_object('pending_delay', jsonb_build_object(
               'item_id', v_item, 'appointment_id', a.id, 'ref_no', a.ref_no, 'minutes', a.delay_minutes,
               'new_time', to_char(coalesce(a.est_at, a.starts_at) at time zone tz, 'HH24:MI'),
               'old_time', to_char(v_old at time zone tz, 'HH24:MI'), 'at', now()))
       where tenant_id = p_tenant and wa_id = a.wa_id;
      v_sent := v_sent + 1;
    end if;
  end loop;
  update clinic.delay_notices set counts = jsonb_build_object('affected', n, 'messaged', v_sent) where id = v_notice;
  return jsonb_build_object('ok', true, 'status', 'SENT', 'notice_id', v_notice, 'doctor', clinic.doctor_label(v_doc, 'ar'),
                            'minutes', v_min, 'affected', n, 'messaged', v_sent, 'items', v_items,
                            'fact', format('%s patients are being told; you will see who accepted on the dashboard', v_sent));
end $$;

create or replace function clinic.delay_followups_due()
returns int language plpgsql as $$
declare
  r      record;
  st     jsonb;
  v_lang text;
  n      int := 0;
  tz     text;
begin
  for r in
    select i.id as iid, i.followed_up_at, i.new_at, i.wa_id as iwa, a.*
      from clinic.delay_notice_items i join clinic.appointments a on a.id = i.appointment_id
     where i.status = 'sent' and i.reply_due_at <= now()
     order by i.reply_due_at
     for update of i skip locked
     limit 200
  loop
    if r.status not in ('booked', 'confirmed') or coalesce(r.est_at, r.starts_at) < now() then
      update clinic.delay_notice_items set status = 'skipped' where id = r.iid;
      continue;
    end if;
    if r.status = 'confirmed' and r.confirmed_at > (select created_at from clinic.delay_notice_items where id = r.iid) then
      update clinic.delay_notice_items set status = 'accepted', replied_at = r.confirmed_at where id = r.iid;
      continue;
    end if;
    tz := clinic.tenant_tz(r.tenant_id);
    if r.followed_up_at is null then
      select clinic.merged_settings(settings) into st from clinic.tenants where id = r.tenant_id;
      v_lang := clinic.contact_language(r.tenant_id, r.iwa);
      perform clinic.queue_message(r.tenant_id, r.iwa, 'delay_followup',
        clinic.render_template(st -> 'templates' ->> ('delay_followup_' || v_lang),
          clinic.message_vars((select x from clinic.appointments x where x.id = r.id), v_lang)
          || jsonb_build_object('new_time', clinic.clock_text((coalesce(r.est_at, r.starts_at) at time zone tz)::time, v_lang))),
        p_template => 'delay_followup', p_meta => jsonb_build_object('appointment_id', r.id, 'delay_item_id', r.iid));
      update clinic.delay_notice_items
         set followed_up_at = now(),
             reply_due_at = greatest(least(now() + greatest(interval '10 minutes', (coalesce(r.est_at, r.starts_at) - now()) * 0.3),
                                           coalesce(r.est_at, r.starts_at) - interval '10 minutes'), now() + interval '5 minutes')
       where id = r.iid;
      n := n + 1;
    else
      update clinic.delay_notice_items set status = 'no_reply' where id = r.iid;
      perform clinic.raise_alert(jsonb_build_object('tenant_id', r.tenant_id, 'kind', 'no_reply', 'appointment_id', r.id,
        'body', coalesce((select full_name from clinic.patients where id = r.patient_id), 'مريض') || ' — '
                || to_char(coalesce(r.est_at, r.starts_at) at time zone tz, 'HH24:MI')));
    end if;
  end loop;
  return n;
end $$;

-- ---------------------------------------------------------------------
-- A session that cannot happen: cancel it and offer each patient their two nearest times
-- ---------------------------------------------------------------------
create or replace function clinic.cancel_session(p_tenant uuid, p jsonb)
returns jsonb language plpgsql as $$
declare
  t        clinic.tenants%rowtype;
  st       jsonb;
  tz       text;
  v_doc    uuid := clinic.resolve_doctor(p_tenant, p);
  v_loc    uuid := nullif(p ->> 'location_id', '')::uuid;
  v_date   date := coalesce(nullif(p ->> 'date', '')::date, clinic.local_today(p_tenant));
  v_from   time := nullif(p ->> 'from_time', '')::time;
  v_prev   boolean := coalesce((p ->> 'preview')::boolean, false);
  v_reason text := nullif(btrim(coalesce(p ->> 'reason', '')), '');
  a        clinic.appointments%rowtype;
  v_items  jsonb := '[]'::jsonb;
  v_notice bigint;
  v_opts   jsonb;
  v_lang   text;
  v_txt    text;
  n        int := 0;
  v_sent   int := 0;
begin
  select * into t from clinic.tenants where id = p_tenant;
  st := clinic.merged_settings(t.settings);
  tz := t.timezone;
  if v_doc is null then return jsonb_build_object('ok', false, 'error', 'WHICH_DOCTOR'); end if;
  if nullif(p ->> 'location', '') is not null then v_loc := clinic.match_location(p_tenant, p ->> 'location'); end if;
  for a in select * from clinic.appointments x
            where x.tenant_id = p_tenant and x.doctor_id = v_doc and x.session_date = v_date
              and x.status in ('booked', 'confirmed') and (v_loc is null or x.location_id = v_loc)
              and (v_from is null or (coalesce(x.est_at, x.starts_at) at time zone tz)::time >= v_from)
            order by coalesce(x.est_at, x.starts_at) loop
    v_items := v_items || jsonb_build_object('appointment_id', a.id, 'ref_no', a.ref_no,
                 'patient', (select full_name from clinic.patients where id = a.patient_id),
                 'time', to_char(coalesce(a.est_at, a.starts_at) at time zone tz, 'HH24:MI'), 'whatsapp', a.wa_id is not null);
  end loop;
  if v_prev then
    return jsonb_build_object('ok', true, 'status', 'PREVIEW', 'doctor', clinic.doctor_label(v_doc, 'ar'), 'date', v_date,
                              'count', jsonb_array_length(v_items), 'items', v_items,
                              'fact', format('%s bookings would be cancelled, each patient offered their nearest times — only after a yes', jsonb_array_length(v_items)));
  end if;

  insert into clinic.schedule_exceptions (tenant_id, doctor_id, location_id, on_date, kind, start_time, end_time, reason, created_by)
  values (p_tenant, v_doc, v_loc, v_date, 'off', v_from, case when v_from is not null then '23:59'::time end, coalesce(v_reason, 'session cancelled'),
          clinic.current_user_id());
  insert into clinic.delay_notices (tenant_id, doctor_id, location_id, session_date, kind, reason, via, created_by, created_by_name)
  values (p_tenant, v_doc, v_loc, v_date, 'cancel_session', v_reason, coalesce(nullif(p ->> 'via', ''), 'dashboard'),
          clinic.current_user_id(), coalesce(nullif(p ->> 'by_name', ''), clinic.my_name(p_tenant)))
  returning id into v_notice;

  for a in select * from clinic.appointments x
            where x.tenant_id = p_tenant and x.doctor_id = v_doc and x.session_date = v_date
              and x.status in ('booked', 'confirmed') and (v_loc is null or x.location_id = v_loc)
              and (v_from is null or (coalesce(x.est_at, x.starts_at) at time zone tz)::time >= v_from)
            order by coalesce(x.est_at, x.starts_at) loop
    perform clinic.cancel_appointment(a.id, 'clinic', coalesce(v_reason, 'the doctor cancelled the session'), false);
    n := n + 1;
    if a.wa_id is null then continue; end if;
    v_opts := clinic.available_slots(p_tenant, jsonb_build_object('doctor_id', v_doc, 'service_id', a.service_id,
                                     'patient_id', a.patient_id, 'from', v_date, 'limit', 40)) -> 'suggested';
    select coalesce(jsonb_agg(x || jsonb_build_object('option', k)), '[]'::jsonb) into v_opts
      from jsonb_array_elements(v_opts) with ordinality as s(x, k) where k <= 2;
    v_lang := clinic.contact_language(p_tenant, a.wa_id);
    select string_agg(format(E'\n%s) %s', x ->> 'option', x ->> case when v_lang = 'en' then 'label_en' else 'label_ar' end), '')
      into v_txt from jsonb_array_elements(v_opts) x;
    perform clinic.queue_message(p_tenant, a.wa_id, 'session_cancelled',
      clinic.render_template(st -> 'templates' ->> ('session_cancelled_' || v_lang), clinic.message_vars(a, v_lang) || jsonb_build_object(
        'reason', case when v_reason is not null then ' (' || v_reason || ')' else '' end,
        'options', coalesce(v_txt, case when v_lang = 'en' then ' (tell us a day that suits you)' else ' (قولنا يوم يناسبك)' end))),
      p_not_before => now() + make_interval(secs => v_sent * 3), p_template => 'session_cancelled',
      p_meta => jsonb_build_object('appointment_id', a.id, 'notice_id', v_notice));
    insert into clinic.delay_notice_items (tenant_id, notice_id, appointment_id, wa_id, old_at, status, options)
    values (p_tenant, v_notice, a.id, a.wa_id, coalesce(a.est_at, a.starts_at), 'sent', v_opts);
    -- "1" / "2" books one: the booking in progress already has the doctor, the service, the patient and the options
    insert into clinic.booking_drafts as b (tenant_id, wa_id, data)
    values (p_tenant, a.wa_id, jsonb_build_object('doctor_id', v_doc, 'service_id', a.service_id, 'location_id', a.location_id,
                                                 'patient', jsonb_build_object('patient_id', a.patient_id), 'reason', a.reason,
                                                 'last_offered', v_opts, 'replacing', a.ref_no))
    on conflict (tenant_id, wa_id) do update set data = excluded.data, changed_at = clock_timestamp(), summary_at = null, updated_at = now();
    update clinic.conversations set state = state || jsonb_build_object('last_offered', v_opts, 'pending_reschedule',
             jsonb_build_object('cancelled_ref', a.ref_no, 'options', v_opts, 'at', now()))
     where tenant_id = p_tenant and wa_id = a.wa_id;
    v_sent := v_sent + 1;
  end loop;
  update clinic.delay_notices set counts = jsonb_build_object('affected', n, 'messaged', v_sent) where id = v_notice;
  return jsonb_build_object('ok', true, 'status', 'CANCELLED', 'notice_id', v_notice, 'affected', n, 'messaged', v_sent,
                            'fact', format('%s bookings cancelled; %s patients offered new times', n, v_sent));
end $$;

-- time off (a few hours or a day) — bookings already there are listed, not cancelled
create or replace function clinic.block_time(p_tenant uuid, p jsonb)
returns jsonb language plpgsql as $$
declare
  tz     text := clinic.tenant_tz(p_tenant);
  v_doc  uuid := clinic.resolve_doctor(p_tenant, p);
  v_loc  uuid := nullif(p ->> 'location_id', '')::uuid;
  v_date date := nullif(p ->> 'date', '')::date;
  v_to_date date := coalesce(nullif(p ->> 'to_date', '')::date, nullif(p ->> 'date', '')::date);
  v_from time := nullif(p ->> 'from_time', '')::time;
  v_to   time := nullif(p ->> 'to_time', '')::time;
  v_n    int;
  d      date;
begin
  if v_doc is null then return jsonb_build_object('ok', false, 'error', 'WHICH_DOCTOR'); end if;
  if v_date is null then return jsonb_build_object('ok', false, 'error', 'DATE_NEEDED'); end if;
  if v_to_date < v_date or v_to_date - v_date > 60 then return jsonb_build_object('ok', false, 'error', 'BAD_RANGE'); end if;
  select count(*) into v_n from clinic.appointments a
   where a.doctor_id = v_doc and a.session_date between v_date and v_to_date and a.status in ('booked', 'confirmed')
     and (v_loc is null or a.location_id = v_loc)
     and (v_from is null or (coalesce(a.est_at, a.starts_at) at time zone tz)::time >= v_from)
     and (v_to is null or (coalesce(a.est_at, a.starts_at) at time zone tz)::time < v_to);
  if coalesce((p ->> 'preview')::boolean, false) then
    return jsonb_build_object('ok', true, 'status', 'PREVIEW', 'doctor', clinic.doctor_label(v_doc, 'ar'), 'from', v_date, 'to', v_to_date,
                              'hours', case when v_from is not null then v_from::text || '–' || coalesce(v_to::text, 'end') end,
                              'bookings_inside', v_n,
                              'fact', case when v_n > 0 then format('%s bookings are already inside that time — they stay until cancelled', v_n)
                                           else 'no bookings inside' end);
  end if;
  d := v_date;
  while d <= v_to_date loop
    insert into clinic.schedule_exceptions (tenant_id, doctor_id, location_id, on_date, kind, start_time, end_time, reason, created_by)
    values (p_tenant, v_doc, v_loc, d, 'off', v_from, coalesce(v_to, case when v_from is not null then '23:59'::time end),
            nullif(p ->> 'reason', ''), clinic.current_user_id());
    d := d + 1;
  end loop;
  return jsonb_build_object('ok', true, 'status', 'BLOCKED', 'bookings_inside', v_n,
                            'fact', 'no new bookings in that time' || case when v_n > 0 then format(' — %s existing bookings still need a decision', v_n) else '' end);
end $$;

-- ---------------------------------------------------------------------
-- When a visit is done: the patient's numbers, aftercare, the plan's next session
-- ---------------------------------------------------------------------
create or replace function clinic.appointment_done(p_appt bigint)
returns void language plpgsql as $$
declare
  a      clinic.appointments%rowtype;
  st     jsonb;
  s      clinic.services%rowtype;
  v_lang text;
  i      clinic.treatment_plan_items%rowtype;
  v_next jsonb;
  v_opts jsonb;
  v_txt  text;
begin
  select * into a from clinic.appointments where id = p_appt;
  if a.patient_id is not null then
    update clinic.patients set visits_count = visits_count + 1, last_visit_at = coalesce(a.visit_started_at, a.starts_at),
                               first_visit_at = coalesce(first_visit_at, coalesce(a.visit_started_at, a.starts_at))
     where id = a.patient_id;
  end if;
  select clinic.merged_settings(settings) into st from clinic.tenants where id = a.tenant_id;
  select * into s from clinic.services where id = a.service_id;
  if a.wa_id is not null and coalesce((st ->> 'aftercare_messages')::boolean, true) and coalesce(s.aftercare_ar, s.aftercare_en, '') <> '' then
    v_lang := clinic.contact_language(a.tenant_id, a.wa_id);
    perform clinic.queue_message(a.tenant_id, a.wa_id, 'aftercare',
      clinic.render_template(st -> 'templates' ->> ('aftercare_' || v_lang), clinic.message_vars(a, v_lang)
        || jsonb_build_object('aftercare', case when v_lang = 'en' then coalesce(s.aftercare_en, s.aftercare_ar) else coalesce(s.aftercare_ar, s.aftercare_en) end)),
      p_not_before => now() + interval '20 minutes', p_template => 'aftercare', p_meta => jsonb_build_object('appointment_id', a.id));
  end if;
  -- a treatment plan session
  if a.plan_item_id is not null then
    update clinic.treatment_plan_items
       set done_sessions = done_sessions + 1,
           status = case when done_sessions + 1 >= sessions then 'done' else 'in_progress' end
     where id = a.plan_item_id returning * into i;
    update clinic.treatment_plans pl
       set status = case when not exists (select 1 from clinic.treatment_plan_items x where x.plan_id = pl.id and x.status not in ('done', 'cancelled'))
                         then 'done' else 'in_progress' end
     where pl.id = i.plan_id;
    v_next := clinic.plan_next(i.plan_id);
    if v_next is not null and a.wa_id is not null then
      v_opts := clinic.available_slots(a.tenant_id, jsonb_build_object('doctor_id', v_next ->> 'doctor_id', 'service_id', v_next ->> 'service_id',
                                       'patient_id', a.patient_id, 'from', v_next ->> 'earliest', 'limit', 40)) -> 'suggested';
      select coalesce(jsonb_agg(x || jsonb_build_object('option', k)), '[]'::jsonb) into v_opts
        from jsonb_array_elements(v_opts) with ordinality as s2(x, k) where k <= 2;
      v_lang := clinic.contact_language(a.tenant_id, a.wa_id);
      select string_agg(format(E'\n%s) %s', x ->> 'option', x ->> case when v_lang = 'en' then 'label_en' else 'label_ar' end), '')
        into v_txt from jsonb_array_elements(v_opts) x;
      if v_txt is not null then
        perform clinic.queue_message(a.tenant_id, a.wa_id, 'plan_next',
          case when v_lang = 'en' then format(E'The next session (%s, %s of %s) — shall we book one of these?%s\nReply with the number, or tell us another day.',
                                              v_next ->> 'label', v_next ->> 'session', v_next ->> 'of', v_txt)
               else format(E'الجلسة الجاية (%s — %s من %s). نحجزلك واحد من دول؟%s\nابعت رقم الميعاد أو قولنا يوم تاني.',
                           v_next ->> 'label', v_next ->> 'session', v_next ->> 'of', v_txt) end,
          p_not_before => now() + interval '30 minutes', p_template => 'plan_next', p_meta => jsonb_build_object('plan_id', i.plan_id));
        insert into clinic.booking_drafts as b (tenant_id, wa_id, data)
        values (a.tenant_id, a.wa_id, jsonb_build_object('doctor_id', v_next ->> 'doctor_id', 'service_id', v_next ->> 'service_id',
                                                        'patient', jsonb_build_object('patient_id', a.patient_id),
                                                        'plan_item_id', (v_next ->> 'item_id')::bigint, 'last_offered', v_opts,
                                                        'reason', (v_next ->> 'label') || ' — ' || (v_next ->> 'session') || '/' || (v_next ->> 'of')))
        on conflict (tenant_id, wa_id) do update set data = excluded.data, changed_at = clock_timestamp(), summary_at = null, hold_id = null;
        update clinic.conversations set state = state || jsonb_build_object('last_offered', v_opts, 'pending_plan_session', v_next)
         where tenant_id = a.tenant_id and wa_id = a.wa_id;
      end if;
    end if;
  end if;
end $$;

-- ---------------------------------------------------------------------
-- The doctor's (or the front desk's) own WhatsApp
-- p_staff = intake's `staff` ({kind, user_id, role, doctor_id, clinical, name})
-- actions: today · delay · cancel_session · block_time · catalog · confirm · discard · undo · patient
-- ---------------------------------------------------------------------
create or replace function clinic.staff_tool(p_tenant uuid, p_wa text, p_staff jsonb, p_action text, p_details text)
returns jsonb language plpgsql as $$
declare
  tz       text := clinic.tenant_tz(p_tenant);
  v        jsonb;
  v_action text := lower(btrim(coalesce(p_action, '')));
  conv     clinic.conversations%rowtype;
  v_pend   jsonb;
  v_res    jsonb;
  v_role   text := coalesce(p_staff ->> 'role', 'receptionist');
  v_doc    uuid;
  v_date   date;
begin
  begin
    v := coalesce(nullif(btrim(coalesce(p_details, '')), '')::jsonb, '{}'::jsonb);
  exception when others then v := '{}'::jsonb;
  end;
  if jsonb_typeof(v) <> 'object' then v := '{}'::jsonb; end if;
  select * into conv from clinic.conversations where tenant_id = p_tenant and wa_id = p_wa;
  v_pend := conv.state -> 'staff_pending';
  -- "my" schedule: a doctor's own number means their own sessions unless they name another doctor
  v_doc := coalesce(case when nullif(v ->> 'doctor', '') is not null then clinic.match_doctor(p_tenant, v ->> 'doctor') end,
                    nullif(p_staff ->> 'doctor_id', '')::uuid);
  v_date := coalesce(nullif(v ->> 'date', '')::date, clinic.local_today(p_tenant));

  if v_action = 'today' then
    return jsonb_build_object('ok', true, 'date', v_date,
      'appointments', coalesce((select jsonb_agg(jsonb_build_object(
                          'time', to_char(coalesce(a.est_at, a.starts_at) at time zone tz, 'HH24:MI'), 'queue_no', a.queue_no,
                          'patient', p.full_name, 'service', s.name_ar, 'status', a.status, 'doctor', clinic.doctor_label(a.doctor_id, 'ar'),
                          'reason', case when coalesce((p_staff ->> 'clinical')::boolean, false) then a.reason end,
                          'new', a.is_new_patient, 'delay', a.delay_minutes) order by coalesce(a.est_at, a.starts_at))
                          from clinic.appointments a left join clinic.patients p on p.id = a.patient_id
                          left join clinic.services s on s.id = a.service_id
                         where a.tenant_id = p_tenant and a.session_date = v_date
                           and a.status in ('booked', 'confirmed', 'arrived', 'in_visit', 'done', 'no_show')
                           and (v_doc is null or a.doctor_id = v_doc)), '[]'::jsonb),
      'sessions', coalesce((select jsonb_agg(jsonb_build_object('doctor', clinic.doctor_label(x.doctor_id, 'ar'),
                              'location', clinic.location_label(x.location_id, 'ar'),
                              'from', to_char(x.starts_at at time zone tz, 'HH24:MI'), 'to', to_char(x.ends_at at time zone tz, 'HH24:MI'), 'mode', x.mode))
                              from clinic.doctor_sessions(p_tenant, v_date, v_date, v_doc) x), '[]'::jsonb));
  end if;

  if v_action in ('delay', 'cancel_session', 'block_time') then
    v := v || jsonb_build_object('doctor_id', v_doc, 'preview', true, 'via', 'whatsapp', 'by_name', p_staff ->> 'name');
    v_res := case v_action when 'delay' then clinic.announce_delay(p_tenant, v)
                           when 'cancel_session' then clinic.cancel_session(p_tenant, v)
                           else clinic.block_time(p_tenant, v) end;
    if (v_res ->> 'ok')::boolean then
      update clinic.conversations set state = state || jsonb_build_object('staff_pending',
               jsonb_build_object('action', v_action, 'params', v - 'preview', 'at', now()))
       where id = conv.id;
    end if;
    return v_res || jsonb_build_object('waiting_for', 'a yes from the doctor (then action confirm)');
  end if;

  if v_action = 'catalog' then
    if v_role not in ('owner', 'manager', 'doctor') then
      return jsonb_build_object('ok', false, 'error', 'NOT_ALLOWED', 'fact', 'prices and services are changed by the doctor or the clinic manager');
    end if;
    v_res := clinic.catalog_change(p_tenant, coalesce(v -> 'changes', v), false, 'whatsapp');
    if (v_res ->> 'ok')::boolean then
      update clinic.catalog_changes set created_by = nullif(p_staff ->> 'user_id', '')::uuid, created_by_name = p_staff ->> 'name'
       where id = (v_res ->> 'change_id')::bigint;
      update clinic.conversations set state = state || jsonb_build_object('staff_pending',
               jsonb_build_object('action', 'catalog', 'change_id', v_res ->> 'change_id', 'at', now()))
       where id = conv.id;
    end if;
    return v_res || jsonb_build_object('waiting_for', 'a yes from the doctor (then action confirm)');
  end if;

  if v_action = 'confirm' then
    if v_pend is null or (v_pend ->> 'at')::timestamptz < now() - interval '30 minutes' then
      return jsonb_build_object('ok', false, 'error', 'NOTHING_WAITING', 'fact', 'nothing is waiting for a yes (or it is older than 30 minutes) — ask again');
    end if;
    update clinic.conversations set state = state - 'staff_pending' where id = conv.id;
    v_res := case v_pend ->> 'action'
      when 'delay' then clinic.announce_delay(p_tenant, (v_pend -> 'params') || '{"preview": false}')
      when 'cancel_session' then clinic.cancel_session(p_tenant, (v_pend -> 'params') || '{"preview": false}')
      when 'block_time' then clinic.block_time(p_tenant, (v_pend -> 'params') || '{"preview": false}')
      when 'catalog' then clinic.catalog_apply((v_pend ->> 'change_id')::bigint)
    end;
    if v_pend ->> 'action' = 'catalog' then
      update clinic.conversations set state = state || jsonb_build_object('staff_last_change', v_pend ->> 'change_id') where id = conv.id;
    end if;
    return coalesce(v_res, jsonb_build_object('ok', false, 'error', 'UNKNOWN_PENDING'));
  end if;

  if v_action = 'discard' then
    if v_pend ->> 'action' = 'catalog' then perform clinic.catalog_undo((v_pend ->> 'change_id')::bigint); end if;
    update clinic.conversations set state = state - 'staff_pending' where id = conv.id;
    return jsonb_build_object('ok', true, 'status', 'DISCARDED');
  end if;

  if v_action = 'undo' then
    if v_role not in ('owner', 'manager', 'doctor') then return jsonb_build_object('ok', false, 'error', 'NOT_ALLOWED'); end if;
    return clinic.catalog_undo(coalesce(nullif(v ->> 'change_id', '')::bigint, nullif(conv.state ->> 'staff_last_change', '')::bigint,
      (select id from clinic.catalog_changes where tenant_id = p_tenant and source = 'whatsapp' and status = 'applied' order by applied_at desc limit 1)));
  end if;

  if v_action = 'patient' then
    return jsonb_build_object('ok', true, 'patients', coalesce((
      select jsonb_agg(clinic.patient_brief(p.id) || jsonb_build_object('phone', p.phone,
               'next', (select clinic.appointment_view(a) from clinic.appointments a where a.patient_id = p.id
                          and a.status in ('booked', 'confirmed') and a.starts_at > now() order by a.starts_at limit 1)))
        from (select * from clinic.patients x where x.tenant_id = p_tenant and x.is_active
                and (clinic.norm(x.full_name) like '%' || clinic.norm(coalesce(v ->> 'q', '')) || '%'
                     or x.file_no = btrim(coalesce(v ->> 'q', '')) or x.phone like '%' || clinic.digits(coalesce(v ->> 'q', 'x')) || '%')
              order by x.last_visit_at desc nulls last limit 5) p), '[]'::jsonb));
  end if;

  return jsonb_build_object('ok', false, 'error', 'UNKNOWN_ACTION',
                            'fact', 'action is one of: today, delay, cancel_session, block_time, catalog, confirm, discard, undo, patient');
end $$;

-- ---------------------------------------------------------------------
-- Housekeeping (every minute, from the n8n outbox workflow)
-- ---------------------------------------------------------------------
create or replace function clinic.housekeeping()
returns jsonb language plpgsql as $$
declare
  n_release int; n_locks int; n_stuck int; n_buf int; n_hold int; n_rem int; n_delay int; n_noshow int; n_wait int;
begin
  with idle as (
    select c.id, c.human_since from clinic.conversations c join clinic.tenants t on t.id = c.tenant_id
     where c.mode = 'human'
       and coalesce((clinic.merged_settings(t.settings) ->> 'human_auto_release_minutes')::int, 0) > 0
       and coalesce(c.human_last_activity_at, c.human_since, c.updated_at)
           < now() - make_interval(mins => (clinic.merged_settings(t.settings) ->> 'human_auto_release_minutes')::int))
  update clinic.conversations c
     set mode = 'agent', assigned_user_id = null, human_reason = null, human_last_activity_at = null, human_since = null,
         state = c.state || jsonb_build_object('handback', jsonb_build_object('at', now(), 'by', 'auto', 'human_since', idle.human_since))
    from idle where c.id = idle.id;
  get diagnostics n_release = row_count;

  delete from clinic.conversation_locks where expires_at < now() - interval '1 minute';
  get diagnostics n_locks = row_count;
  update clinic.outbox set status = 'queued', not_before = now() where status = 'sending' and claimed_at < now() - interval '5 minutes';
  get diagnostics n_stuck = row_count;
  delete from clinic.inbound_buffer
   where (claimed_by_run_id is not null and received_at < now() - interval '1 hour')
      or (claimed_by_run_id is null and received_at < now() - interval '15 minutes');
  get diagnostics n_buf = row_count;

  -- holds nobody confirmed
  with gone as (
    update clinic.appointments set status = 'cancelled', cancelled_at = now(), cancelled_by = 'system', cancel_reason = 'hold expired'
     where status = 'held' and hold_expires_at < now() returning id)
  update clinic.booking_drafts b set hold_id = null, data = b.data - 'slot' from gone where b.hold_id = gone.id;
  get diagnostics n_hold = row_count;

  n_rem := clinic.reminders_due();
  n_delay := clinic.delay_followups_due();

  -- nobody came: a no-show, once the session (or the visit) is well over
  with ns as (
    update clinic.appointments a set status = 'no_show'
      from clinic.tenants t
     where t.id = a.tenant_id and a.status in ('booked', 'confirmed')
       and coalesce((clinic.merged_settings(t.settings) ->> 'auto_no_show')::boolean, true)
       and case when a.mode = 'queue' then a.ends_at else a.ends_at end
           < now() - make_interval(mins => coalesce((clinic.merged_settings(t.settings) ->> 'no_show_grace_minutes')::int, 60))
    returning a.patient_id)
  update clinic.patients p set no_show_count = p.no_show_count + 1 from ns where p.id = ns.patient_id;
  get diagnostics n_noshow = row_count;

  -- waitlist offers that went unanswered go back to waiting; old wishes expire
  update clinic.waitlist set status = 'waiting', offered_slot = null where status = 'offered' and offered_at < now() - interval '3 hours';
  update clinic.waitlist set status = 'expired' where status in ('waiting', 'offered') and to_date is not null and to_date < current_date;
  get diagnostics n_wait = row_count;

  return jsonb_build_object('takeovers_released', n_release, 'locks_cleared', n_locks, 'outbox_requeued', n_stuck,
                            'buffer_cleared', n_buf, 'holds_expired', n_hold, 'reminders_sent', n_rem,
                            'delay_followups', n_delay, 'no_shows', n_noshow, 'waitlist_expired', n_wait);
end $$;

-- ================= 008_dashboard.sql =================

-- =====================================================================
-- Everwake Clinic · 008 · the dashboard
--
-- Signing a clinic up and its speciality presets, the team, the day
-- (today_board), the calendar, the front desk's bookings and status
-- changes, patients and their records, the dental chart and treatment
-- plans, the catalogue import, and the "running late" / "cancel the
-- session" / "time off" buttons. Every function checks the caller's
-- role first; medical records also need the member to be clinical.
-- =====================================================================

-- ---------------------------------------------------------------------
-- Signing a clinic up. The caller becomes its owner (and, when they say
-- so, its first doctor).
-- ---------------------------------------------------------------------
create or replace function clinic.apply_preset(p_tenant uuid, p_specialty text, p_doctor uuid default null)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare
  sp    clinic.specialty_presets%rowtype;
  x     jsonb;
  n     int := 0;
  v_sort int;
begin
  perform clinic.require_role(p_tenant, array['owner', 'manager', 'doctor']);
  select * into sp from clinic.specialty_presets where code = p_specialty;
  if not found then return jsonb_build_object('ok', false, 'error', 'UNKNOWN_SPECIALTY'); end if;
  select coalesce(max(sort), 0) into v_sort from clinic.services where tenant_id = p_tenant;
  for x in select * from jsonb_array_elements(sp.starter_services) loop
    if exists (select 1 from clinic.services s where s.tenant_id = p_tenant and s.is_active
                and clinic.norm(s.name_ar) = clinic.norm(x ->> 'name_ar')
                and (s.specialty is null or s.specialty = p_specialty)) then
      continue;
    end if;
    v_sort := v_sort + 10;
    insert into clinic.services (tenant_id, category, specialty, name_ar, name_en, aliases, description_ar, duration_min,
                                 price_kind, price, price_max, price_unit, sessions, session_gap_days, prep_ar, aftercare_ar,
                                 resource_kind, needs_consult_first, bookable, min_age, max_age, doctor_ids, sort)
    values (p_tenant, coalesce(x ->> 'category', 'procedure'), p_specialty, x ->> 'name_ar', x ->> 'name_en',
            coalesce((select array_agg(a) from jsonb_array_elements_text(x -> 'aliases') a), '{}'),
            x ->> 'description_ar', coalesce((x ->> 'duration')::int, 20),
            coalesce(x ->> 'price_kind', 'fixed'), (x ->> 'price')::numeric, (x ->> 'price_max')::numeric,
            coalesce(x ->> 'unit', 'visit'), coalesce((x ->> 'sessions')::int, 1), (x ->> 'session_gap_days')::int,
            x ->> 'prep_ar', x ->> 'aftercare_ar', x ->> 'resource_kind', coalesce((x ->> 'needs_consult_first')::boolean, false),
            coalesce((x ->> 'bookable')::boolean, true), (x ->> 'min_age')::numeric, (x ->> 'max_age')::numeric,
            case when p_doctor is not null then array[p_doctor] else '{}' end, v_sort);
    n := n + 1;
  end loop;
  if sp.form_template <> '{}'::jsonb and not exists (select 1 from clinic.form_templates where tenant_id = p_tenant and specialty = p_specialty) then
    insert into clinic.form_templates (tenant_id, specialty, name, schema)
    values (p_tenant, p_specialty, sp.name_en, sp.form_template);
  end if;
  return jsonb_build_object('ok', true, 'services_added', n);
end $$;

create or replace function clinic.create_tenant(p_name_ar text, p_name_en text, p_slug text default null,
                                                p_specialty text default 'general', p_doctor_name text default null,
                                                p_doctor_gender text default null)
returns uuid language plpgsql security definer set search_path = clinic, pg_temp as $$
declare
  v_uid   uuid := clinic.current_user_id();
  v_slug  text;
  v_base  text;
  v_i     int := 1;
  v_id    uuid;
  v_doc   uuid;
  v_email text := nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'email';
begin
  if coalesce(btrim(p_name_ar), '') = '' and coalesce(btrim(p_name_en), '') = '' then
    raise exception 'the clinic needs a name';
  end if;
  v_base := coalesce(nullif(clinic.slugify(p_slug), ''), nullif(clinic.slugify(p_name_en), ''), 'clinic_' || substr(md5(random()::text), 1, 6));
  if length(v_base) < 2 or v_base !~ '^[a-z]' then v_base := 'c_' || v_base; end if;
  v_slug := v_base;
  while exists (select 1 from clinic.tenants where slug = v_slug) loop
    v_i := v_i + 1; v_slug := left(v_base, 36) || '_' || v_i;
  end loop;
  insert into clinic.tenants (slug, name_ar, name_en, specialty, ref_prefix)
  values (v_slug, coalesce(nullif(btrim(p_name_ar), ''), btrim(p_name_en)), coalesce(nullif(btrim(p_name_en), ''), btrim(p_name_ar)),
          coalesce(nullif(p_specialty, ''), 'general'),
          coalesce(nullif(upper(left(regexp_replace(v_slug, '[^a-z]', '', 'g'), 3)), ''), 'CL'))
  returning id into v_id;
  if nullif(btrim(coalesce(p_doctor_name, '')), '') is not null then
    insert into clinic.doctors (tenant_id, user_id, name_ar, specialty, gender)
    values (v_id, v_uid, btrim(p_doctor_name), coalesce(nullif(p_specialty, ''), 'general'),
            case when p_doctor_gender in ('male', 'female') then p_doctor_gender end)
    returning id into v_doc;
  end if;
  if v_uid is not null then
    insert into clinic.tenant_members (tenant_id, user_id, role, clinical, doctor_id, email, display_name)
    values (v_id, v_uid, 'owner', true, v_doc, v_email, coalesce(nullif(btrim(p_doctor_name), ''), split_part(coalesce(v_email, ''), '@', 1)));
  end if;
  perform clinic.apply_preset(v_id, coalesce(nullif(p_specialty, ''), 'general'), v_doc);
  perform clinic.rebuild_snapshot(v_id);
  return v_id;
end $$;

create or replace function clinic.my_tenants()
returns jsonb language sql stable security definer set search_path = clinic, pg_temp as $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', t.id, 'slug', t.slug, 'name_ar', t.name_ar, 'name_en', t.name_en, 'status', t.status,
           'agent_enabled', t.agent_enabled, 'currency', t.currency, 'currency_symbol', t.currency_symbol_ar,
           'timezone', t.timezone, 'default_language', t.default_language, 'specialty', t.specialty,
           'role', clinic.member_role(t.id), 'clinical', clinic.can_see_clinical(t.id),
           'doctor_id', (select m.doctor_id from clinic.tenant_members m where m.tenant_id = t.id and m.user_id = clinic.current_user_id()))
         order by t.name_en), '[]'::jsonb)
    from clinic.tenants t
   where clinic.member_role(t.id) is not null
$$;

create or replace function clinic.onboarding_checklist(p_tenant uuid)
returns jsonb language plpgsql stable security definer set search_path = clinic, pg_temp as $$
declare
  t   clinic.tenants%rowtype;
  pr  jsonb;
  n_doc int; n_sched int; n_loc int; n_svc int; n_priced int; n_ch int; n_ch_ok int; n_test int; n_know int;
  items jsonb;
begin
  perform clinic.require_role(p_tenant, array['owner', 'manager', 'doctor', 'nurse', 'receptionist']);
  select * into t from clinic.tenants where id = p_tenant;
  pr := clinic.merged_profile(t.profile);
  select count(*) into n_doc from clinic.doctors where tenant_id = p_tenant and is_active;
  select count(distinct doctor_id) into n_sched from clinic.schedules where tenant_id = p_tenant and is_active;
  select count(*) into n_loc from clinic.locations where tenant_id = p_tenant and is_active and coalesce(address_ar, '') <> '';
  select count(*), count(*) filter (where price is not null or price_kind in ('after_exam', 'free'))
    into n_svc, n_priced from clinic.services where tenant_id = p_tenant and is_active and agent_visible;
  select count(*), count(*) filter (where status = 'connected') into n_ch, n_ch_ok from clinic.whatsapp_channels where tenant_id = p_tenant and is_active;
  select count(*) into n_test from clinic.appointments where tenant_id = p_tenant and source = 'whatsapp' and ref_no is not null;
  select count(*) into n_know from clinic.knowledge_entries where tenant_id = p_tenant and is_active;
  items := jsonb_build_array(
    jsonb_build_object('key', 'profile', 'label', 'Clinic profile and the assistant''s name', 'required', true,
                       'done', coalesce(pr ->> 'about_ar', '') <> '' or coalesce(pr ->> 'about_en', '') <> '', 'href', 'settings/agent'),
    jsonb_build_object('key', 'locations', 'label', 'Clinic address', 'required', true, 'done', n_loc > 0, 'href', 'settings/locations'),
    jsonb_build_object('key', 'doctors', 'label', 'Doctors and their schedules', 'required', true,
                       'done', n_doc > 0 and n_sched = n_doc, 'detail', n_sched || ' of ' || n_doc || ' doctors have a schedule', 'href', 'settings/schedules'),
    jsonb_build_object('key', 'services', 'label', 'Services and prices', 'required', true,
                       'done', n_svc > 0 and n_priced = n_svc, 'detail', n_priced || ' of ' || n_svc || ' services have a price', 'href', 'services'),
    jsonb_build_object('key', 'knowledge', 'label', 'Answers to common questions', 'required', false, 'done', n_know > 0, 'href', 'knowledge'),
    jsonb_build_object('key', 'whatsapp', 'label', 'WhatsApp number connected', 'required', true, 'done', n_ch_ok > 0, 'href', 'settings/whatsapp'),
    jsonb_build_object('key', 'test', 'label', 'A test booking from a test number', 'required', false, 'done', n_test > 0, 'href', 'settings/whatsapp'));
  return jsonb_build_object('status', t.status, 'live_at', t.live_at, 'items', items,
    'ready', not exists (select 1 from jsonb_array_elements(items) i where (i ->> 'required')::boolean and not (i ->> 'done')::boolean));
end $$;

create or replace function clinic.go_live(p_tenant uuid, p_force boolean default false)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare c jsonb;
begin
  perform clinic.require_role(p_tenant, array['owner']);
  c := clinic.onboarding_checklist(p_tenant);
  if not (c ->> 'ready')::boolean and not p_force then return jsonb_build_object('live', false, 'checklist', c); end if;
  update clinic.tenants set status = 'live', live_at = coalesce(live_at, now()) where id = p_tenant;
  return jsonb_build_object('live', true);
end $$;

-- ---------------------------------------------------------------------
-- The team
-- ---------------------------------------------------------------------
create or replace function clinic.invite_member(p_tenant uuid, p_email text, p_role text default 'receptionist',
                                                p_clinical boolean default null, p_doctor uuid default null)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare v_id uuid;
begin
  perform clinic.require_role(p_tenant, array['owner']);
  if p_role not in ('owner', 'manager', 'doctor', 'nurse', 'receptionist') then raise exception 'unknown role'; end if;
  insert into clinic.tenant_invites (tenant_id, email, role, clinical, doctor_id, invited_by)
  values (p_tenant, lower(btrim(p_email)), p_role, p_clinical, p_doctor, clinic.current_user_id())
  on conflict (tenant_id, email) do update
    set role = excluded.role, clinical = excluded.clinical, doctor_id = excluded.doctor_id, accepted_at = null, accepted_by = null
  returning id into v_id;
  return jsonb_build_object('invite_id', v_id);
end $$;

create or replace function clinic.accept_invites()
returns int language plpgsql security definer set search_path = clinic, pg_temp as $$
declare
  v_uid   uuid := clinic.current_user_id();
  v_email text := lower(nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'email');
  r       record;
  n       int := 0;
begin
  if v_uid is null or v_email is null then return 0; end if;
  for r in select * from clinic.tenant_invites where email = v_email and accepted_at is null loop
    insert into clinic.tenant_members (tenant_id, user_id, role, clinical, doctor_id, email, display_name)
    values (r.tenant_id, v_uid, r.role, coalesce(r.clinical, r.role in ('owner', 'doctor', 'nurse')), r.doctor_id, v_email,
            coalesce((select name_ar from clinic.doctors where id = r.doctor_id), split_part(v_email, '@', 1)))
    on conflict (tenant_id, user_id) do update set role = excluded.role, clinical = excluded.clinical, doctor_id = excluded.doctor_id;
    if r.doctor_id is not null then update clinic.doctors set user_id = v_uid where id = r.doctor_id and user_id is null; end if;
    update clinic.tenant_invites set accepted_at = now(), accepted_by = v_uid where id = r.id;
    n := n + 1;
  end loop;
  return n;
end $$;

create or replace function clinic.update_member(p_tenant uuid, p_user uuid, p jsonb)
returns void language plpgsql security definer set search_path = clinic, pg_temp as $$
declare v_role text := nullif(p ->> 'role', '');
begin
  perform clinic.require_role(p_tenant, array['owner']);
  if v_role is not null and v_role not in ('owner', 'manager', 'doctor', 'nurse', 'receptionist') then raise exception 'unknown role'; end if;
  if v_role is not null and v_role <> 'owner'
     and (select role from clinic.tenant_members where tenant_id = p_tenant and user_id = p_user) = 'owner'
     and (select count(*) from clinic.tenant_members where tenant_id = p_tenant and role = 'owner') = 1 then
    raise exception 'a clinic always keeps at least one owner';
  end if;
  update clinic.tenant_members
     set role = coalesce(v_role, role),
         clinical = coalesce((p ->> 'clinical')::boolean, clinical),
         doctor_id = case when p ? 'doctor_id' then nullif(p ->> 'doctor_id', '')::uuid else doctor_id end,
         phone = case when p ? 'phone' then clinic.wa_phone(p ->> 'phone') else phone end,
         display_name = coalesce(nullif(btrim(p ->> 'display_name'), ''), display_name)
   where tenant_id = p_tenant and user_id = p_user;
end $$;

-- a member's own WhatsApp number (for staff commands) — they may set their own
create or replace function clinic.set_my_phone(p_tenant uuid, p_phone text)
returns text language plpgsql security definer set search_path = clinic, pg_temp as $$
declare v text := clinic.wa_phone(p_phone);
begin
  perform clinic.require_role(p_tenant, array['owner', 'manager', 'doctor', 'nurse', 'receptionist']);
  update clinic.tenant_members set phone = v where tenant_id = p_tenant and user_id = clinic.current_user_id();
  return v;
end $$;

create or replace function clinic.remove_member(p_tenant uuid, p_user uuid)
returns void language plpgsql security definer set search_path = clinic, pg_temp as $$
begin
  perform clinic.require_role(p_tenant, array['owner']);
  if (select role from clinic.tenant_members where tenant_id = p_tenant and user_id = p_user) = 'owner'
     and (select count(*) from clinic.tenant_members where tenant_id = p_tenant and role = 'owner') = 1 then
    raise exception 'a clinic always keeps at least one owner';
  end if;
  delete from clinic.tenant_members where tenant_id = p_tenant and user_id = p_user;
end $$;

-- ---------------------------------------------------------------------
-- The day
-- ---------------------------------------------------------------------
create or replace function clinic.appt_card(a clinic.appointments, p_clinical boolean)
returns jsonb language sql stable as $$
  select jsonb_build_object(
    'id', a.id, 'ref_no', a.ref_no, 'status', a.status, 'mode', a.mode, 'source', a.source,
    'doctor_id', a.doctor_id, 'location_id', a.location_id, 'resource_id', a.resource_id,
    'resource', (select name_ar from clinic.resources where id = a.resource_id),
    'service_id', a.service_id, 'service', s.name_ar, 'service_en', s.name_en, 'category', s.category,
    'patient_id', a.patient_id, 'patient', p.full_name, 'file_no', p.file_no, 'sex', p.sex,
    'age', clinic.age_text(p.birth_date, 'ar'), 'age_en', clinic.age_text(p.birth_date, 'en'),
    'phone', coalesce(p.phone, (select c.phone from clinic.contacts c where c.id = a.contact_id)),
    'whatsapp', a.wa_id is not null, 'wa_id', a.wa_id,
    'conversation_id', (select id from clinic.conversations c where c.tenant_id = a.tenant_id and c.wa_id = a.wa_id),
    'starts_at', a.starts_at, 'ends_at', a.ends_at, 'est_at', a.est_at, 'queue_no', a.queue_no, 'session_date', a.session_date,
    'original_starts_at', a.original_starts_at, 'delay_minutes', a.delay_minutes,
    'reason', a.reason, 'urgency', a.urgency, 'is_new', a.is_new_patient, 'is_follow_up', a.is_follow_up,
    'price_text', a.price_text, 'price', a.price, 'payment_status', a.payment_status,
    'confirmed_at', a.confirmed_at, 'arrived_at', a.arrived_at, 'visit_started_at', a.visit_started_at,
    'visit_ended_at', a.visit_ended_at, 'staff_notes', a.staff_notes, 'plan_item_id', a.plan_item_id,
    'allergies', case when p_clinical then (select jsonb_agg(al.substance) from clinic.allergies al
                                             where al.patient_id = a.patient_id and al.status = 'active') end,
    'visits_count', p.visits_count, 'last_visit_at', p.last_visit_at, 'no_show_count', p.no_show_count,
    'delay_reply', (select i.status from clinic.delay_notice_items i where i.appointment_id = a.id order by i.id desc limit 1))
  from (select 1) one
  left join clinic.services s on s.id = a.service_id
  left join clinic.patients p on p.id = a.patient_id
$$;

create or replace function clinic.today_board(p_tenant uuid, p_date date default null, p_doctor uuid default null)
returns jsonb language plpgsql stable security definer set search_path = clinic, pg_temp as $$
declare
  v_date date;
  tz     text := clinic.tenant_tz(p_tenant);
  v_cl   boolean;
  v_next clinic.appointments%rowtype;
begin
  perform clinic.require_role(p_tenant, array['owner', 'manager', 'doctor', 'nurse', 'receptionist']);
  v_date := coalesce(p_date, clinic.local_today(p_tenant));
  v_cl := clinic.can_see_clinical(p_tenant);
  select * into v_next from clinic.appointments a
   where a.tenant_id = p_tenant and a.session_date = v_date and (p_doctor is null or a.doctor_id = p_doctor)
     and a.status in ('in_visit', 'arrived', 'confirmed', 'booked')
   order by (a.status = 'in_visit') desc, (a.status = 'arrived') desc, coalesce(a.est_at, a.starts_at) limit 1;

  return jsonb_build_object(
    'date', v_date, 'now', now(), 'timezone', tz, 'clinical', v_cl,
    'sessions', coalesce((select jsonb_agg(jsonb_build_object(
        'doctor_id', s.doctor_id, 'doctor', clinic.doctor_label(s.doctor_id, 'ar'), 'doctor_en', clinic.doctor_label(s.doctor_id, 'en'),
        'color', d.color, 'specialty', d.specialty, 'location_id', s.location_id,
        'location', clinic.location_label(s.location_id, 'ar'), 'location_en', clinic.location_label(s.location_id, 'en'),
        'starts_at', s.starts_at, 'ends_at', s.ends_at, 'mode', s.mode, 'capacity', s.capacity,
        'delay_minutes', (select coalesce(sum(dn.minutes), 0) from clinic.delay_notices dn where dn.doctor_id = s.doctor_id
                           and dn.session_date = v_date and dn.kind = 'delay' and dn.status = 'sent'
                           and (dn.location_id is null or dn.location_id = s.location_id)),
        'appointments', coalesce((select jsonb_agg(clinic.appt_card(a, v_cl) order by coalesce(a.queue_no, 0), a.starts_at)
                                    from clinic.appointments a
                                   where a.doctor_id = s.doctor_id and a.location_id = s.location_id and a.session_date = v_date
                                     and a.status <> 'held' and a.ref_no is not null
                                     and tstzrange(s.starts_at - interval '1 hour', s.ends_at + interval '4 hours') @> a.starts_at), '[]'::jsonb))
        order by s.starts_at)
      from clinic.doctor_sessions(p_tenant, v_date, v_date, p_doctor) s join clinic.doctors d on d.id = s.doctor_id), '[]'::jsonb),
    'outside', coalesce((select jsonb_agg(clinic.appt_card(a, v_cl) order by a.starts_at) from clinic.appointments a
                          where a.tenant_id = p_tenant and a.session_date = v_date and a.ref_no is not null and a.status <> 'held'
                            and (p_doctor is null or a.doctor_id = p_doctor)
                            and not exists (select 1 from clinic.doctor_sessions(p_tenant, v_date, v_date, a.doctor_id, a.location_id) s
                                             where tstzrange(s.starts_at - interval '1 hour', s.ends_at + interval '4 hours') @> a.starts_at)), '[]'::jsonb),
    'waiting_room', coalesce((select jsonb_agg(clinic.appt_card(a, v_cl) || jsonb_build_object(
                                 'waiting_minutes', floor(extract(epoch from now() - a.arrived_at) / 60)) order by a.arrived_at)
                                from clinic.appointments a
                               where a.tenant_id = p_tenant and a.session_date = v_date and a.status = 'arrived'
                                 and (p_doctor is null or a.doctor_id = p_doctor)), '[]'::jsonb),
    'next', case when v_next.id is not null then clinic.appt_card(v_next, v_cl) || jsonb_build_object(
               'conditions', case when v_cl then (select jsonb_agg(c.name) from clinic.conditions c where c.patient_id = v_next.patient_id and c.status <> 'resolved') end,
               'medications', case when v_cl then (select jsonb_agg(m.name || coalesce(' ' || m.dose, '')) from clinic.medications m where m.patient_id = v_next.patient_id and m.status = 'active') end,
               'last_visit', (select jsonb_build_object('date', x.session_date, 'service', s.name_ar, 'doctor', clinic.doctor_label(x.doctor_id, 'ar'))
                                from clinic.appointments x left join clinic.services s on s.id = x.service_id
                               where x.patient_id = v_next.patient_id and x.status = 'done' order by x.starts_at desc limit 1),
               'documents', (select count(*) from clinic.documents dd where dd.patient_id = v_next.patient_id and dd.created_at > now() - interval '30 days'),
               'pre_visit', v_next.pre_visit) end,
    'counts', (select jsonb_build_object(
                 'total', count(*) filter (where a.status not in ('cancelled', 'held')),
                 'booked', count(*) filter (where a.status = 'booked'),
                 'confirmed', count(*) filter (where a.status = 'confirmed'),
                 'arrived', count(*) filter (where a.status = 'arrived'),
                 'in_visit', count(*) filter (where a.status = 'in_visit'),
                 'done', count(*) filter (where a.status = 'done'),
                 'no_show', count(*) filter (where a.status = 'no_show'),
                 'cancelled', count(*) filter (where a.status = 'cancelled' and a.ref_no is not null),
                 'new_patients', count(*) filter (where a.is_new_patient and a.status not in ('cancelled', 'held')),
                 'by_agent', count(*) filter (where a.source = 'whatsapp' and a.status not in ('cancelled', 'held')),
                 'expected', coalesce(sum(a.price) filter (where a.status not in ('cancelled', 'held', 'no_show')), 0),
                 'collected', coalesce(sum(a.price) filter (where a.status = 'done'), 0))
                 from clinic.appointments a where a.tenant_id = p_tenant and a.session_date = v_date and (p_doctor is null or a.doctor_id = p_doctor)),
    'tomorrow_unconfirmed', (select count(*) from clinic.appointments a where a.tenant_id = p_tenant and a.session_date = v_date + 1
                               and a.status = 'booked' and (p_doctor is null or a.doctor_id = p_doctor)),
    'agent_today', coalesce((select jsonb_agg(clinic.appt_card(a, v_cl) || jsonb_build_object('created_at', a.created_at) order by a.created_at desc)
                               from (select * from clinic.appointments x where x.tenant_id = p_tenant and x.source = 'whatsapp' and x.ref_no is not null
                                       and x.created_at >= (v_date::timestamp at time zone tz) and x.created_at < ((v_date + 1)::timestamp at time zone tz)
                                     order by x.created_at desc limit 8) a), '[]'::jsonb),
    'delays', coalesce((select jsonb_agg(jsonb_build_object('id', dn.id, 'kind', dn.kind, 'doctor', clinic.doctor_label(dn.doctor_id, 'ar'),
                                 'doctor_id', dn.doctor_id, 'minutes', dn.minutes, 'reason', dn.reason, 'via', dn.via, 'by', dn.created_by_name, 'at', dn.sent_at,
                                 'tally', (select jsonb_object_agg(z.status, z.n) from (select i.status, count(*) n from clinic.delay_notice_items i
                                                                                          where i.notice_id = dn.id group by i.status) z))
                                 order by dn.sent_at desc)
                          from clinic.delay_notices dn where dn.tenant_id = p_tenant and dn.session_date = v_date
                           and (p_doctor is null or dn.doctor_id = p_doctor)), '[]'::jsonb),
    'alerts', coalesce((select jsonb_agg(to_jsonb(al) order by (al.severity = 'critical') desc, al.created_at desc)
                          from (select * from clinic.alerts x where x.tenant_id = p_tenant and x.status = 'open' order by x.created_at desc limit 12) al), '[]'::jsonb));
end $$;

create or replace function clinic.calendar_range(p_tenant uuid, p_from date, p_to date, p_doctor uuid default null)
returns jsonb language plpgsql stable security definer set search_path = clinic, pg_temp as $$
declare v_cl boolean;
begin
  perform clinic.require_role(p_tenant, array['owner', 'manager', 'doctor', 'nurse', 'receptionist']);
  if p_to < p_from or p_to - p_from > 62 then raise exception 'pick up to two months'; end if;
  v_cl := clinic.can_see_clinical(p_tenant);
  return jsonb_build_object(
    'from', p_from, 'to', p_to, 'timezone', clinic.tenant_tz(p_tenant),
    'appointments', coalesce((select jsonb_agg(clinic.appt_card(a, v_cl) order by a.starts_at) from clinic.appointments a
                               where a.tenant_id = p_tenant and a.session_date between p_from and p_to and a.ref_no is not null
                                 and (p_doctor is null or a.doctor_id = p_doctor)), '[]'::jsonb),
    'sessions', coalesce((select jsonb_agg(jsonb_build_object('doctor_id', s.doctor_id, 'location_id', s.location_id, 'date', s.session_date,
                                                               'starts_at', s.starts_at, 'ends_at', s.ends_at, 'mode', s.mode,
                                                               'slot_minutes', s.slot_minutes, 'capacity', s.capacity, 'online', s.online)
                                           order by s.starts_at)
                           from clinic.doctor_sessions(p_tenant, p_from, p_to, p_doctor) s), '[]'::jsonb),
    'exceptions', coalesce((select jsonb_agg(to_jsonb(e) order by e.on_date) from clinic.schedule_exceptions e
                             where e.tenant_id = p_tenant and e.on_date between p_from and p_to
                               and (p_doctor is null or e.doctor_id = p_doctor)), '[]'::jsonb),
    'resources', coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'name', r.name_ar, 'kind', r.kind, 'location_id', r.location_id) order by r.sort)
                            from clinic.resources r where r.tenant_id = p_tenant and r.is_active), '[]'::jsonb));
end $$;

-- the sidebar's numbers
create or replace function clinic.dashboard_counts(p_tenant uuid)
returns jsonb language plpgsql stable security definer set search_path = clinic, pg_temp as $$
begin
  perform clinic.require_role(p_tenant, array['owner', 'manager', 'doctor', 'nurse', 'receptionist']);
  return jsonb_build_object(
    'alerts', (select count(*) from clinic.alerts where tenant_id = p_tenant and status = 'open'),
    'emergencies', (select count(*) from clinic.alerts where tenant_id = p_tenant and status = 'open' and kind = 'emergency'),
    'inbox', (select count(*) from clinic.conversations where tenant_id = p_tenant and (needs_attention or questions_open > 0 or (mode = 'human' and unread_count > 0))),
    'waiting_room', (select count(*) from clinic.appointments where tenant_id = p_tenant and session_date = clinic.local_today(p_tenant) and status = 'arrived'),
    'waitlist', (select count(*) from clinic.waitlist where tenant_id = p_tenant and status in ('waiting', 'offered')));
end $$;

-- ---------------------------------------------------------------------
-- The front desk
-- ---------------------------------------------------------------------
-- p = {doctor_id, location_id?, service_id?, kind, starts_at | date, patient_id | patient{full_name, phone, age, sex},
--      reason?, source? ('phone' · 'walk_in' · 'dashboard'), notify?, force?, notes?, plan_item_id?}
create or replace function clinic.staff_book(p_tenant uuid, p jsonb)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare
  co     clinic.contacts%rowtype;
  v_pat  bigint := nullif(p ->> 'patient_id', '')::bigint;
  v_res  jsonb;
  a      clinic.appointments%rowtype;
  st     jsonb;
  v_lang text;
begin
  perform clinic.require_role(p_tenant, array['owner', 'manager', 'doctor', 'nurse', 'receptionist']);
  if v_pat is not null then
    select c.* into co from clinic.patient_contacts pc join clinic.contacts c on c.id = pc.contact_id
     where pc.patient_id = v_pat order by (pc.relation = 'self') desc limit 1;
    if co.id is null then
      co := clinic.ensure_contact(p_tenant, (select phone from clinic.patients where id = v_pat), (select full_name from clinic.patients where id = v_pat));
      if co.id is not null then
        insert into clinic.patient_contacts (patient_id, contact_id, tenant_id, relation) values (v_pat, co.id, p_tenant, 'self') on conflict do nothing;
      end if;
    end if;
  elsif jsonb_typeof(p -> 'patient') = 'object' then
    co := clinic.ensure_contact(p_tenant, p -> 'patient' ->> 'phone', p -> 'patient' ->> 'full_name');
    v_pat := clinic.resolve_patient(p_tenant, co.id, (p -> 'patient') || jsonb_build_object('created_via', 'dashboard',
               'relation', coalesce(nullif(p -> 'patient' ->> 'relation', ''), 'self')));
    if v_pat is not null and co.id is null then
      update clinic.patients set phone = clinic.wa_phone(p -> 'patient' ->> 'phone') where id = v_pat and phone is null;
    end if;
  end if;
  if v_pat is null then return jsonb_build_object('ok', false, 'error', 'PATIENT_NEEDED'); end if;
  v_res := clinic.book_appointment(p_tenant, p || jsonb_build_object(
             'patient_id', v_pat, 'contact_id', co.id, 'wa_id', co.wa_id, 'staff', true,
             'source', coalesce(nullif(p ->> 'source', ''), 'dashboard'), 'status', 'booked'));
  if (v_res ->> 'ok')::boolean and coalesce((p ->> 'notify')::boolean, true) and co.wa_id is not null then
    select * into a from clinic.appointments where id = (v_res -> 'appointment' ->> 'id')::bigint;
    select clinic.merged_settings(settings) into st from clinic.tenants where id = p_tenant;
    v_lang := clinic.contact_language(p_tenant, co.wa_id);
    perform clinic.queue_message(p_tenant, co.wa_id, 'booking_confirmed',
      clinic.render_template(st -> 'templates' ->> ('booking_confirmed_' || v_lang), clinic.message_vars(a, v_lang)),
      p_sender => 'staff', p_user => clinic.current_user_id(), p_template => 'booking_confirmed',
      p_meta => jsonb_build_object('appointment_id', a.id));
    v_res := v_res || jsonb_build_object('notified', true);
  end if;
  return v_res;
end $$;

create or replace function clinic.move_appointment(p_appt bigint, p jsonb)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare v_tenant uuid;
begin
  select tenant_id into v_tenant from clinic.appointments where id = p_appt;
  perform clinic.require_role(v_tenant, array['owner', 'manager', 'doctor', 'nurse', 'receptionist']);
  return clinic.reschedule_appointment(p_appt, p || jsonb_build_object('staff', true, 'by_role', 'staff'));
end $$;

-- confirmed (by phone) · arrived · in_visit · done · no_show · cancelled · booked (undo)
create or replace function clinic.set_appointment_status(p_appt bigint, p_status text, p_note text default null, p_notify boolean default false)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare
  a clinic.appointments%rowtype;
begin
  select * into a from clinic.appointments where id = p_appt for update;
  if not found then raise exception 'appointment not found'; end if;
  perform clinic.require_role(a.tenant_id, array['owner', 'manager', 'doctor', 'nurse', 'receptionist']);
  if p_status = 'cancelled' then
    return clinic.cancel_appointment(a.id, 'clinic', p_note, p_notify);
  end if;
  if p_status not in ('booked', 'confirmed', 'arrived', 'in_visit', 'done', 'no_show') then raise exception 'unknown status'; end if;
  if a.status in ('cancelled') then raise exception 'this appointment was cancelled'; end if;
  update clinic.appointments
     set status = p_status,
         confirmed_at = case when p_status = 'confirmed' then coalesce(confirmed_at, now()) else confirmed_at end,
         arrived_at = case when p_status = 'arrived' then coalesce(arrived_at, now()) when p_status = 'booked' then null else arrived_at end,
         visit_started_at = case when p_status = 'in_visit' then coalesce(visit_started_at, now())
                                 when p_status in ('booked', 'arrived') then null else visit_started_at end,
         visit_ended_at = case when p_status = 'done' then coalesce(visit_ended_at, now()) else visit_ended_at end,
         staff_notes = coalesce(nullif(btrim(coalesce(p_note, '')), ''), staff_notes)
   where id = a.id returning * into a;
  if p_status in ('arrived', 'in_visit', 'done') then
    update clinic.appointment_reminders set status = 'cancelled' where appointment_id = a.id and status = 'scheduled';
    update clinic.delay_notice_items set status = 'accepted', replied_at = coalesce(replied_at, now()) where appointment_id = a.id and status = 'sent';
  end if;
  if p_status = 'done' then perform clinic.appointment_done(a.id); end if;
  if p_status = 'no_show' and a.patient_id is not null then
    update clinic.patients set no_show_count = no_show_count + 1 where id = a.patient_id;
  end if;
  perform clinic.log_appt(a.id, p_status, jsonb_build_object('note', p_note));
  return jsonb_build_object('ok', true, 'appointment', clinic.appt_card(a, clinic.can_see_clinical(a.tenant_id)));
end $$;

