create or replace function clinic.add_waitlist(p_tenant uuid, p jsonb)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare
  v_id bigint;
  co   clinic.contacts%rowtype;
begin
  perform clinic.require_role(p_tenant, array['owner', 'manager', 'doctor', 'nurse', 'receptionist']);
  select c.* into co from clinic.patient_contacts pc join clinic.contacts c on c.id = pc.contact_id
   where pc.patient_id = (p ->> 'patient_id')::bigint order by (pc.relation = 'self') desc limit 1;
  insert into clinic.waitlist (tenant_id, patient_id, contact_id, wa_id, doctor_id, location_id, service_id, from_date, to_date, band, notes, created_by)
  values (p_tenant, (p ->> 'patient_id')::bigint, co.id, co.wa_id, nullif(p ->> 'doctor_id', '')::uuid, nullif(p ->> 'location_id', '')::uuid,
          nullif(p ->> 'service_id', '')::uuid, coalesce(nullif(p ->> 'from_date', '')::date, current_date), nullif(p ->> 'to_date', '')::date,
          case when p ->> 'band' in ('morning', 'afternoon', 'evening') then p ->> 'band' else 'any' end, nullif(p ->> 'notes', ''), clinic.current_user_id())
  returning id into v_id;
  return jsonb_build_object('ok', true, 'id', v_id);
end $$;

-- ---------------------------------------------------------------------
-- Patients and records
-- ---------------------------------------------------------------------
create or replace function clinic.patient_search(p_tenant uuid, p_q text, p_limit int default 20)
returns jsonb language plpgsql stable security definer set search_path = clinic, pg_temp as $$
declare v_q text := clinic.norm(p_q); v_d text := clinic.digits(p_q);
begin
  perform clinic.require_role(p_tenant, array['owner', 'manager', 'doctor', 'nurse', 'receptionist']);
  return coalesce((select jsonb_agg(x) from (
    select jsonb_build_object('id', p.id, 'file_no', p.file_no, 'full_name', p.full_name, 'sex', p.sex,
                              'age', clinic.age_text(p.birth_date, 'ar'), 'phone', p.phone, 'last_visit_at', p.last_visit_at,
                              'visits_count', p.visits_count, 'tags', p.tags,
                              'next', (select jsonb_build_object('id', a.id, 'starts_at', coalesce(a.est_at, a.starts_at), 'doctor', clinic.doctor_label(a.doctor_id, 'ar'))
                                         from clinic.appointments a where a.patient_id = p.id and a.status in ('booked', 'confirmed') and a.ends_at > now()
                                        order by a.starts_at limit 1)) as x
      from clinic.patients p
     where p.tenant_id = p_tenant and p.is_active
       and (v_q = '' or clinic.norm(p.full_name) like '%' || v_q || '%' or p.file_no = btrim(coalesce(p_q, ''))
            or (length(v_d) >= 4 and (p.phone like '%' || v_d || '%'
                                      or exists (select 1 from clinic.patient_contacts pc join clinic.contacts c on c.id = pc.contact_id
                                                  where pc.patient_id = p.id and c.phone like '%' || v_d || '%'))))
     order by (clinic.norm(p.full_name) like v_q || '%') desc, p.last_visit_at desc nulls last, p.id desc
     limit least(coalesce(p_limit, 20), 100)) q), '[]'::jsonb);
end $$;

create or replace function clinic.patient_profile(p_patient bigint)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare
  p    clinic.patients%rowtype;
  v_cl boolean;
begin
  select * into p from clinic.patients where id = p_patient;
  if not found then raise exception 'patient not found'; end if;
  perform clinic.require_role(p.tenant_id, array['owner', 'manager', 'doctor', 'nurse', 'receptionist']);
  v_cl := clinic.can_see_clinical(p.tenant_id);
  insert into clinic.record_access_log (tenant_id, user_id, patient_id, action, detail)
  values (p.tenant_id, clinic.current_user_id(), p.id, 'view', case when v_cl then 'record' else 'contact details' end);
  return jsonb_build_object(
    'patient', to_jsonb(p) || jsonb_build_object('age', clinic.age_text(p.birth_date, 'ar'), 'age_en', clinic.age_text(p.birth_date, 'en'),
                                                 'age_years', clinic.age_years(p.birth_date)),
    'clinical', v_cl,
    'contacts', coalesce((select jsonb_agg(jsonb_build_object('contact_id', c.id, 'relation', pc.relation, 'name', coalesce(c.full_name, c.display_name),
                                                              'phone', c.phone, 'wa_id', c.wa_id,
                                                              'conversation_id', (select id from clinic.conversations x where x.tenant_id = c.tenant_id and x.wa_id = c.wa_id)))
                            from clinic.patient_contacts pc join clinic.contacts c on c.id = pc.contact_id where pc.patient_id = p.id), '[]'::jsonb),
    'family', coalesce((select jsonb_agg(distinct jsonb_build_object('id', o.id, 'full_name', o.full_name, 'relation', pc2.relation))
                          from clinic.patient_contacts pc join clinic.patient_contacts pc2 on pc2.contact_id = pc.contact_id and pc2.patient_id <> p.id
                          join clinic.patients o on o.id = pc2.patient_id where pc.patient_id = p.id), '[]'::jsonb),
    'appointments', coalesce((select jsonb_agg(clinic.appt_card(a, v_cl) order by a.starts_at desc) from clinic.appointments a
                               where a.patient_id = p.id and a.ref_no is not null), '[]'::jsonb),
    'conditions', case when v_cl then coalesce((select jsonb_agg(to_jsonb(x) order by x.status, x.created_at desc) from clinic.conditions x where x.patient_id = p.id), '[]'::jsonb) end,
    'allergies', case when v_cl then coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from clinic.allergies x where x.patient_id = p.id), '[]'::jsonb) end,
    'medications', case when v_cl then coalesce((select jsonb_agg(to_jsonb(x) order by x.status, x.created_at desc) from clinic.medications x where x.patient_id = p.id), '[]'::jsonb) end,
    'history', case when v_cl then coalesce((select jsonb_agg(to_jsonb(x) order by x.kind, x.created_at desc) from clinic.patient_history x where x.patient_id = p.id), '[]'::jsonb) end,
    'vitals', case when v_cl then coalesce((select jsonb_agg(to_jsonb(x) order by x.taken_at desc) from (select * from clinic.vitals where patient_id = p.id order by taken_at desc limit 30) x), '[]'::jsonb) end,
    'encounters', case when v_cl then coalesce((select jsonb_agg(to_jsonb(x) || jsonb_build_object('doctor', clinic.doctor_label(x.doctor_id, 'ar')) order by x.started_at desc)
                                                  from clinic.encounters x where x.patient_id = p.id), '[]'::jsonb) end,
    'documents', case when v_cl then coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from clinic.documents x where x.patient_id = p.id), '[]'::jsonb) end,
    'dental_chart', case when v_cl then coalesce((select jsonb_agg(to_jsonb(x) order by x.tooth) from clinic.dental_chart x where x.patient_id = p.id), '[]'::jsonb) end,
    'plans', case when v_cl then coalesce((select jsonb_agg(to_jsonb(pl) || jsonb_build_object(
                     'doctor', clinic.doctor_label(pl.doctor_id, 'ar'), 'total', clinic.plan_total(pl.id),
                     'items', coalesce((select jsonb_agg(to_jsonb(i) order by i.seq, i.id) from clinic.treatment_plan_items i where i.plan_id = pl.id), '[]'::jsonb))
                     order by pl.created_at desc) from clinic.treatment_plans pl where pl.patient_id = p.id), '[]'::jsonb) end,
    'templates', case when v_cl then coalesce((select jsonb_agg(jsonb_build_object('id', f.id, 'name', f.name, 'specialty', f.specialty, 'schema', f.schema))
                                                 from clinic.form_templates f where f.tenant_id = p.tenant_id), '[]'::jsonb) end);
end $$;

create or replace function clinic.save_patient(p_tenant uuid, p jsonb)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare
  v_id   bigint := nullif(p ->> 'id', '')::bigint;
  v_birth date; v_est boolean;
  co     clinic.contacts%rowtype;
begin
  perform clinic.require_role(p_tenant, array['owner', 'manager', 'doctor', 'nurse', 'receptionist']);
  if nullif(p ->> 'birth_date', '') is not null then v_birth := (p ->> 'birth_date')::date; v_est := false;
  elsif nullif(p ->> 'age', '') is not null then select b.birth_date, b.estimated into v_birth, v_est from clinic.parse_birth(p ->> 'age') b;
  end if;
  if v_id is null then
    if coalesce(btrim(p ->> 'full_name'), '') = '' then raise exception 'the patient needs a name'; end if;
    insert into clinic.patients (tenant_id, full_name, sex, birth_date, birth_date_estimated, phone, national_id, blood_group,
                                 marital_status, occupation, address, insurance, tags, notes)
    values (p_tenant, btrim(p ->> 'full_name'), nullif(p ->> 'sex', ''), v_birth, coalesce(v_est, false),
            clinic.wa_phone(p ->> 'phone'), nullif(p ->> 'national_id', ''), nullif(p ->> 'blood_group', ''),
            nullif(p ->> 'marital_status', ''), nullif(p ->> 'occupation', ''), nullif(p ->> 'address', ''), nullif(p ->> 'insurance', ''),
            coalesce((select array_agg(x) from jsonb_array_elements_text(p -> 'tags') x), '{}'), nullif(p ->> 'notes', ''))
    returning id into v_id;
  else
    update clinic.patients
       set full_name = coalesce(nullif(btrim(p ->> 'full_name'), ''), full_name),
           sex = case when p ? 'sex' then nullif(p ->> 'sex', '') else sex end,
           birth_date = case when v_birth is not null then v_birth else birth_date end,
           birth_date_estimated = case when v_birth is not null then coalesce(v_est, false) else birth_date_estimated end,
           phone = case when p ? 'phone' then clinic.wa_phone(p ->> 'phone') else phone end,
           national_id = case when p ? 'national_id' then nullif(p ->> 'national_id', '') else national_id end,
           blood_group = case when p ? 'blood_group' then nullif(p ->> 'blood_group', '') else blood_group end,
           marital_status = case when p ? 'marital_status' then nullif(p ->> 'marital_status', '') else marital_status end,
           occupation = case when p ? 'occupation' then nullif(p ->> 'occupation', '') else occupation end,
           address = case when p ? 'address' then nullif(p ->> 'address', '') else address end,
           insurance = case when p ? 'insurance' then nullif(p ->> 'insurance', '') else insurance end,
           tags = case when p ? 'tags' then coalesce((select array_agg(x) from jsonb_array_elements_text(p -> 'tags') x), '{}') else tags end,
           notes = case when p ? 'notes' then nullif(p ->> 'notes', '') else notes end
     where id = v_id and tenant_id = p_tenant;
    if not found then raise exception 'patient not found'; end if;
  end if;
  if nullif(p ->> 'phone', '') is not null then
    co := clinic.ensure_contact(p_tenant, p ->> 'phone', p ->> 'full_name');
    if co.id is not null then
      insert into clinic.patient_contacts (patient_id, contact_id, tenant_id, relation)
      values (v_id, co.id, p_tenant, coalesce(nullif(p ->> 'relation', ''), 'self')) on conflict do nothing;
    end if;
  end if;
  return jsonb_build_object('ok', true, 'id', v_id);
end $$;

-- conditions · allergies · medications · patient_history · vitals: add, change or remove one row
create or replace function clinic.save_record(p_patient bigint, p_table text, p jsonb)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare
  v_tenant uuid;
  v_row    jsonb;
  v_id     bigint := nullif(p ->> 'id', '')::bigint;
  cols     text;
  ex       text;
begin
  if p_table not in ('conditions', 'allergies', 'medications', 'patient_history', 'vitals') then raise exception 'not a record table'; end if;
  select tenant_id into v_tenant from clinic.patients where id = p_patient;
  if v_tenant is null then raise exception 'patient not found'; end if;
  perform clinic.require_role(v_tenant, array['owner', 'manager', 'doctor', 'nurse']);
  perform clinic.require_clinical(v_tenant);
  if coalesce((p ->> 'delete')::boolean, false) then
    execute format('delete from clinic.%I where id = $1 and patient_id = $2', p_table) using v_id, p_patient;
    return jsonb_build_object('ok', true, 'deleted', v_id);
  end if;
  v_row := (p - 'id' - 'tenant_id' - 'patient_id' - 'created_at' - 'created_by' - 'delete')
           || jsonb_build_object('tenant_id', v_tenant, 'patient_id', p_patient);
  if v_id is null then v_row := v_row || jsonb_build_object('created_by', clinic.current_user_id()); end if;
  select string_agg(format('%I', a.attname), ', ' order by a.attnum),
         string_agg(format('excluded.%I', a.attname), ', ' order by a.attnum)
    into cols, ex
    from pg_attribute a
   where a.attrelid = ('clinic.' || p_table)::regclass and a.attnum > 0 and not a.attisdropped
     and a.attidentity = '' and a.attname not in ('id', 'created_at', 'updated_at') and v_row ? a.attname;
  if v_id is null then
    execute format('insert into clinic.%I (%s) select %s from jsonb_populate_record(null::clinic.%I, $1) returning id', p_table, cols, cols, p_table)
      into v_id using v_row;
  else
    execute format('update clinic.%I t set (%s) = (select %s from jsonb_populate_record(null::clinic.%I, $1)) where t.id = $2 and t.patient_id = $3',
                   p_table, cols, cols, p_table) using v_row, v_id, p_patient;
  end if;
  insert into clinic.record_access_log (tenant_id, user_id, patient_id, action, detail) values (v_tenant, clinic.current_user_id(), p_patient, 'edit', p_table);
  return jsonb_build_object('ok', true, 'id', v_id);
end $$;

-- a visit's record (draft until signed)
create or replace function clinic.save_encounter(p_patient bigint, p jsonb)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare
  v_tenant uuid;
  v_id     bigint := nullif(p ->> 'id', '')::bigint;
  e        clinic.encounters%rowtype;
begin
  select tenant_id into v_tenant from clinic.patients where id = p_patient;
  perform clinic.require_role(v_tenant, array['owner', 'manager', 'doctor', 'nurse']);
  perform clinic.require_clinical(v_tenant);
  if v_id is null then
    insert into clinic.encounters (tenant_id, patient_id, appointment_id, doctor_id, template_id, chief_complaint, data, sources,
                                   assessment, plan, diagnoses, follow_up_date, created_by)
    values (v_tenant, p_patient, nullif(p ->> 'appointment_id', '')::bigint,
            coalesce(nullif(p ->> 'doctor_id', '')::uuid, (select doctor_id from clinic.tenant_members where tenant_id = v_tenant and user_id = clinic.current_user_id())),
            nullif(p ->> 'template_id', '')::uuid, nullif(p ->> 'chief_complaint', ''), coalesce(p -> 'data', '{}'::jsonb),
            coalesce(p -> 'sources', '{}'::jsonb), nullif(p ->> 'assessment', ''), nullif(p ->> 'plan', ''),
            coalesce(p -> 'diagnoses', '[]'::jsonb), nullif(p ->> 'follow_up_date', '')::date, clinic.current_user_id())
    returning * into e;
  else
    select * into e from clinic.encounters where id = v_id and patient_id = p_patient for update;
    if e.status = 'signed' then raise exception 'a signed visit cannot be changed'; end if;
    update clinic.encounters
       set chief_complaint = case when p ? 'chief_complaint' then nullif(p ->> 'chief_complaint', '') else chief_complaint end,
           data = case when p ? 'data' then p -> 'data' else data end,
           sources = case when p ? 'sources' then p -> 'sources' else sources end,
           assessment = case when p ? 'assessment' then nullif(p ->> 'assessment', '') else assessment end,
           plan = case when p ? 'plan' then nullif(p ->> 'plan', '') else plan end,
           diagnoses = case when p ? 'diagnoses' then p -> 'diagnoses' else diagnoses end,
           follow_up_date = case when p ? 'follow_up_date' then nullif(p ->> 'follow_up_date', '')::date else follow_up_date end,
           template_id = coalesce(nullif(p ->> 'template_id', '')::uuid, template_id)
     where id = e.id returning * into e;
  end if;
  if coalesce((p ->> 'sign')::boolean, false) then
    update clinic.encounters set status = 'signed', signed_at = now(), signed_by = clinic.current_user_id(), ended_at = coalesce(ended_at, now())
     where id = e.id returning * into e;
  end if;
  return jsonb_build_object('ok', true, 'encounter', to_jsonb(e));
end $$;

create or replace function clinic.set_teeth(p_patient bigint, p_teeth jsonb)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare
  v_tenant uuid;
  x jsonb;
  n int := 0;
begin
  select tenant_id into v_tenant from clinic.patients where id = p_patient;
  perform clinic.require_role(v_tenant, array['owner', 'manager', 'doctor', 'nurse']);
  perform clinic.require_clinical(v_tenant);
  for x in select * from jsonb_array_elements(case jsonb_typeof(p_teeth) when 'array' then p_teeth else jsonb_build_array(p_teeth) end) loop
    if coalesce((x ->> 'clear')::boolean, false) then
      delete from clinic.dental_chart where patient_id = p_patient and tooth = (x ->> 'tooth')::smallint;
    else
      insert into clinic.dental_chart (tenant_id, patient_id, tooth, condition, surfaces, planned, notes, updated_by)
      values (v_tenant, p_patient, (x ->> 'tooth')::smallint, coalesce(nullif(x ->> 'condition', ''), 'healthy'),
              coalesce((select array_agg(s) from jsonb_array_elements_text(x -> 'surfaces') s), '{}'),
              nullif(x ->> 'planned', ''), nullif(x ->> 'notes', ''), clinic.current_user_id())
      on conflict (patient_id, tooth) do update
        set condition = excluded.condition, surfaces = excluded.surfaces, planned = excluded.planned, notes = excluded.notes,
            updated_by = excluded.updated_by, updated_at = now();
    end if;
    n := n + 1;
  end loop;
  return jsonb_build_object('ok', true, 'teeth', n);
end $$;

-- a treatment plan and its items, saved as a whole
create or replace function clinic.save_plan(p_patient bigint, p jsonb)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare
  v_tenant uuid;
  v_id     bigint := nullif(p ->> 'id', '')::bigint;
  x        jsonb;
  n        int := 0;
  v_svc    uuid;
begin
  select tenant_id into v_tenant from clinic.patients where id = p_patient;
  perform clinic.require_role(v_tenant, array['owner', 'manager', 'doctor', 'nurse']);
  perform clinic.require_clinical(v_tenant);
  if v_id is null then
    insert into clinic.treatment_plans (tenant_id, patient_id, doctor_id, title, discount, notes, created_by)
    values (v_tenant, p_patient,
            coalesce(nullif(p ->> 'doctor_id', '')::uuid, (select doctor_id from clinic.tenant_members where tenant_id = v_tenant and user_id = clinic.current_user_id()),
                     (select id from clinic.doctors where tenant_id = v_tenant and is_active order by sort limit 1)),
            coalesce(nullif(p ->> 'title', ''), 'خطة العلاج'), coalesce((p ->> 'discount')::numeric, 0), nullif(p ->> 'notes', ''),
            clinic.current_user_id())
    returning id into v_id;
  else
    update clinic.treatment_plans
       set title = coalesce(nullif(p ->> 'title', ''), title), discount = coalesce((p ->> 'discount')::numeric, discount),
           notes = case when p ? 'notes' then nullif(p ->> 'notes', '') else notes end,
           doctor_id = coalesce(nullif(p ->> 'doctor_id', '')::uuid, doctor_id),
           status = case when p ->> 'status' in ('draft', 'quoted', 'accepted', 'in_progress', 'done', 'cancelled') then p ->> 'status' else status end
     where id = v_id and patient_id = p_patient;
  end if;
  if jsonb_typeof(p -> 'items') = 'array' then
    delete from clinic.treatment_plan_items i where i.plan_id = v_id and i.status = 'planned'
       and not exists (select 1 from jsonb_array_elements(p -> 'items') y where (y ->> 'id')::bigint = i.id);
    for x in select * from jsonb_array_elements(p -> 'items') loop
      n := n + 1;
      v_svc := nullif(x ->> 'service_id', '')::uuid;
      if nullif(x ->> 'id', '') is null then
        insert into clinic.treatment_plan_items (tenant_id, plan_id, seq, tooth, service_id, label, price, sessions, session_gap_days, notes)
        values (v_tenant, v_id, n, nullif(x ->> 'tooth', '')::smallint, v_svc,
                coalesce(nullif(x ->> 'label', ''), (select name_ar from clinic.services where id = v_svc), 'علاج'),
                coalesce((x ->> 'price')::numeric, (select price from clinic.services where id = v_svc)),
                coalesce((x ->> 'sessions')::int, (select sessions from clinic.services where id = v_svc), 1),
                coalesce((x ->> 'session_gap_days')::int, (select session_gap_days from clinic.services where id = v_svc)),
                nullif(x ->> 'notes', ''));
      else
        update clinic.treatment_plan_items
           set seq = n, tooth = nullif(x ->> 'tooth', '')::smallint, service_id = v_svc,
               label = coalesce(nullif(x ->> 'label', ''), label), price = (x ->> 'price')::numeric,
               sessions = coalesce((x ->> 'sessions')::int, sessions), session_gap_days = (x ->> 'session_gap_days')::int,
               notes = nullif(x ->> 'notes', ''),
               status = case when x ->> 'status' in ('planned', 'booked', 'in_progress', 'done', 'cancelled') then x ->> 'status' else status end
         where id = (x ->> 'id')::bigint and plan_id = v_id;
      end if;
    end loop;
  end if;
  return jsonb_build_object('ok', true, 'id', v_id, 'total', clinic.plan_total(v_id), 'text', clinic.plan_text(v_id));
end $$;

-- ---------------------------------------------------------------------
-- Publishing a reviewed price-list import — through catalog_change, so it can be undone
-- p_items = [{name_ar, name_en?, category?, price?, price_max?, price_kind?, unit?, duration?, sessions?,
--             session_gap_days?, description_ar?, aliases?}]
-- ---------------------------------------------------------------------
create or replace function clinic.publish_catalog_import(p_import uuid, p_items jsonb, p_mode text default 'merge')
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare
  im      clinic.catalog_imports%rowtype;
  x       jsonb;
  v_sid   uuid;
  v_changes jsonb := '[]'::jsonb;
  v_seen  uuid[] := '{}';
  v_doc   text;
  r       jsonb;
begin
  select * into im from clinic.catalog_imports where id = p_import for update;
  if not found then raise exception 'import not found'; end if;
  perform clinic.require_role(im.tenant_id, array['owner', 'manager', 'doctor']);
  v_doc := (select code from clinic.doctors where id = im.doctor_id);
  for x in select * from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) loop
    v_sid := clinic.match_service(im.tenant_id, coalesce(x ->> 'name_ar', x ->> 'name_en'), im.doctor_id);
    if v_sid is not null and clinic.norm((select name_ar from clinic.services where id = v_sid)) <> clinic.norm(coalesce(x ->> 'name_ar', x ->> 'name_en')) then
      v_sid := null;   -- only an exact name match updates; everything else is new
    end if;
    if v_sid is not null then
      v_seen := v_seen || v_sid;
      v_changes := v_changes || jsonb_build_object('op', 'update_service', 'service', (select code from clinic.services where id = v_sid),
        'fields', jsonb_strip_nulls(jsonb_build_object('price', (x ->> 'price')::numeric, 'price_max', (x ->> 'price_max')::numeric,
                    'price_kind', nullif(x ->> 'price_kind', ''), 'price_unit', nullif(x ->> 'unit', ''),
                    'duration_min', (x ->> 'duration')::int, 'sessions', (x ->> 'sessions')::int,
                    'description_ar', nullif(x ->> 'description_ar', ''), 'name_en', nullif(x ->> 'name_en', ''), 'is_active', true)));
    else
      v_changes := v_changes || (x || jsonb_build_object('op', 'add_service', 'doctor', v_doc));
    end if;
  end loop;
  if p_mode = 'replace' then
    for v_sid in select s.id from clinic.services s
                  where s.tenant_id = im.tenant_id and s.is_active and not (s.id = any(v_seen))
                    and (im.doctor_id is null or im.doctor_id = any(s.doctor_ids)) loop
      v_changes := v_changes || jsonb_build_object('op', 'remove_service', 'service', (select code from clinic.services where id = v_sid));
    end loop;
  end if;
  r := clinic.catalog_change(im.tenant_id, v_changes, true, 'import');
  update clinic.catalog_imports set status = 'published', published_by = clinic.current_user_id(), published_at = now() where id = im.id;
  update clinic.services set source_import_id = im.id
   where id in (select (e ->> 'id')::uuid from clinic.catalog_changes c, jsonb_array_elements(c.entries) e
                 where c.id = (r ->> 'change_id')::bigint and e ->> 'op' = 'add_service');
  return r;
end $$;

-- what the agent reads, for the "how the assistant sees it" preview in Services & prices
create or replace function clinic.agent_digest(p_tenant uuid)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
begin
  perform clinic.require_role(p_tenant, array['owner', 'manager', 'doctor', 'nurse', 'receptionist']);
  perform clinic.ensure_snapshot(p_tenant);
  return (select jsonb_build_object('digest', digest_text, 'built_at', built_at, 'rev', source_rev, 'lookup', lookup)
            from clinic.catalog_snapshot where tenant_id = p_tenant);
end $$;

-- ================= 009_security.sql =================

-- =====================================================================
-- Everwake Clinic · 009 · who can see and change what
--
-- Three kinds of caller:
--   · the n8n engine and maintenance scripts — a database role (or the
--     Supabase service role): full access, no user
--   · a dashboard user — Supabase role `authenticated` with a JWT: sees
--     only the clinics they belong to (row level security), and does
--     everything sensitive through the SECURITY DEFINER functions of
--     002–008, each of which checks the role first
--   · anon — nothing at all (the patient's manage page goes through the
--     dashboard's server with the service role)
--
-- The medical record (encounters, conditions, allergies, medications,
-- history, vitals, documents, dental chart, treatment plans) is readable
-- only by members marked clinical. A receptionist books, checks in and
-- answers chats, and never reads it.
-- =====================================================================

do $$
begin
  if not exists (select 1 from pg_roles where rolname = 'anon') then create role anon nologin; end if;
  if not exists (select 1 from pg_roles where rolname = 'authenticated') then create role authenticated nologin; end if;
  if not exists (select 1 from pg_roles where rolname = 'service_role') then create role service_role nologin bypassrls; end if;
end $$;

revoke all on schema clinic from public;
grant usage on schema clinic to authenticated, service_role;

revoke all on all tables in schema clinic from public, anon, authenticated;
revoke all on all sequences in schema clinic from public, anon, authenticated;
revoke execute on all functions in schema clinic from public, anon, authenticated;
alter default privileges in schema clinic revoke execute on functions from public;

grant all on all tables in schema clinic to service_role;
grant all on all sequences in schema clinic to service_role;
grant execute on all functions in schema clinic to service_role;

-- ---------------------------------------------------------------------
-- Reading
-- ---------------------------------------------------------------------
grant select on clinic.tenants, clinic.tenant_members, clinic.tenant_invites, clinic.platform_admins, clinic.specialty_presets,
                clinic.doctors, clinic.locations, clinic.resources, clinic.schedules, clinic.schedule_exceptions,
                clinic.services, clinic.service_prices, clinic.offers, clinic.knowledge_entries, clinic.agent_rules,
                clinic.catalog_imports, clinic.catalog_changes, clinic.catalog_snapshot,
                clinic.contacts, clinic.contact_identities, clinic.conversations, clinic.messages, clinic.outbox,
                clinic.team_questions, clinic.agent_pauses, clinic.pause_contacts, clinic.agent_events,
                clinic.patients, clinic.patient_contacts, clinic.form_templates, clinic.encounters, clinic.conditions,
                clinic.allergies, clinic.medications, clinic.patient_history, clinic.vitals, clinic.documents,
                clinic.dental_chart, clinic.treatment_plans, clinic.treatment_plan_items, clinic.record_access_log,
                clinic.appointments, clinic.appointment_events, clinic.waitlist, clinic.alerts,
                clinic.appointment_reminders, clinic.delay_notices, clinic.delay_notice_items, clinic.audit_log
  to authenticated;
grant select (id, tenant_id, provider, label, phone_number, instance_name, base_url, cloud_phone_number_id,
              status, is_active, last_inbound_at, connected_at, created_at, updated_at)
  on clinic.whatsapp_channels to authenticated;

-- ---------------------------------------------------------------------
-- Writing what the clinic sets up (RLS narrows it to owners, managers, doctors)
-- ---------------------------------------------------------------------
grant insert, update, delete on clinic.doctors, clinic.locations, clinic.resources, clinic.schedules, clinic.schedule_exceptions,
                                clinic.services, clinic.service_prices, clinic.offers, clinic.knowledge_entries, clinic.agent_rules,
                                clinic.form_templates
  to authenticated;
grant insert, update on clinic.catalog_imports to authenticated;
grant update (name_ar, name_en, timezone, currency, currency_symbol_ar, default_language, specialty, ref_prefix, profile, settings)
  on clinic.tenants to authenticated;
grant update (full_name, notes, tags, is_blocked, language) on clinic.contacts to authenticated;
grant update (tags, notes, preferences) on clinic.patients to authenticated;
grant insert, update, delete on clinic.waitlist to authenticated;
grant update (staff_notes, pre_visit) on clinic.appointments to authenticated;

-- ---------------------------------------------------------------------
-- The functions the dashboard calls
-- ---------------------------------------------------------------------
grant execute on function
  clinic.current_user_id(), clinic.member_role(uuid), clinic.is_platform_admin(), clinic.my_tenant_ids(),
  clinic.my_editor_tenant_ids(), clinic.my_clinical_tenant_ids(), clinic.can_see_clinical(uuid), clinic.my_name(uuid),
  clinic.norm(text), clinic.digits(text), clinic.fmt_money(numeric), clinic.wa_phone(text, text),
  clinic.default_settings(), clinic.default_profile(), clinic.merged_settings(jsonb), clinic.merged_profile(jsonb),
  clinic.render_template(text, jsonb), clinic.doctor_label(uuid, text), clinic.location_label(uuid, text),
  clinic.day_name(int, text), clinic.clock_text(time, text), clinic.unit_text(text, text),
  clinic.price_words(text, numeric, numeric, text, text, text), clinic.service_offered(uuid, uuid, uuid),
  clinic.service_price(uuid, uuid, uuid), clinic.match_service(uuid, text, uuid), clinic.match_doctor(uuid, text),
  clinic.match_location(uuid, text), clinic.age_years(date, date), clinic.age_text(date, text),
  clinic.catalog_change(uuid, jsonb, boolean, text), clinic.catalog_apply(bigint), clinic.catalog_undo(bigint),
  clinic.set_agent_enabled(uuid, boolean, text, boolean), clinic.take_over(bigint, text), clinic.hand_back(bigint),
  clinic.send_staff_message(bigint, text, text, text, text, text), clinic.mark_read(bigint), clinic.resolve_attention(bigint),
  clinic.answer_team_question(bigint, text, text), clinic.dismiss_team_question(bigint),
  clinic.save_channel(uuid, jsonb), clinic.remove_channel(uuid), clinic.channel_webhook_token(uuid),
  clinic.log_record_access(bigint, text, text), clinic.acknowledge_alert(bigint, boolean), clinic.plan_quote(bigint),
  clinic.plan_total(bigint), clinic.plan_text(bigint, text),
  clinic.apply_preset(uuid, text, uuid), clinic.create_tenant(text, text, text, text, text, text), clinic.my_tenants(),
  clinic.onboarding_checklist(uuid), clinic.go_live(uuid, boolean),
  clinic.invite_member(uuid, text, text, boolean, uuid), clinic.accept_invites(), clinic.update_member(uuid, uuid, jsonb),
  clinic.set_my_phone(uuid, text), clinic.remove_member(uuid, uuid),
  clinic.today_board(uuid, date, uuid), clinic.calendar_range(uuid, date, date, uuid), clinic.dashboard_counts(uuid),
  clinic.staff_book(uuid, jsonb), clinic.move_appointment(bigint, jsonb), clinic.set_appointment_status(bigint, text, text, boolean),
  clinic.dashboard_delay(uuid, jsonb), clinic.dashboard_cancel_session(uuid, jsonb), clinic.dashboard_block_time(uuid, jsonb),
  clinic.dashboard_slots(uuid, jsonb), clinic.add_waitlist(uuid, jsonb),
  clinic.patient_search(uuid, text, int), clinic.patient_profile(bigint), clinic.save_patient(uuid, jsonb),
  clinic.save_record(bigint, text, jsonb), clinic.save_encounter(bigint, jsonb), clinic.set_teeth(bigint, jsonb),
  clinic.save_plan(bigint, jsonb), clinic.publish_catalog_import(uuid, jsonb, text), clinic.agent_digest(uuid)
  to authenticated;

-- ---------------------------------------------------------------------
-- Row level security
-- ---------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array['tenants', 'platform_admins', 'tenant_members', 'tenant_invites', 'doctors', 'locations', 'resources',
                           'schedules', 'schedule_exceptions', 'services', 'service_prices', 'offers', 'knowledge_entries',
                           'agent_rules', 'catalog_imports', 'catalog_changes', 'catalog_snapshot', 'whatsapp_channels', 'contacts',
                           'contact_identities', 'conversations', 'messages', 'outbox', 'inbound_buffer', 'conversation_locks',
                           'team_questions', 'agent_pauses', 'pause_contacts', 'agent_events', 'patients', 'patient_contacts',
                           'form_templates', 'encounters', 'conditions', 'allergies', 'medications', 'patient_history', 'vitals',
                           'documents', 'dental_chart', 'treatment_plans', 'treatment_plan_items', 'record_access_log',
                           'appointments', 'appointment_events', 'booking_drafts', 'waitlist', 'alerts', 'appointment_reminders',
                           'delay_notices', 'delay_notice_items', 'audit_log'] loop
    execute format('alter table clinic.%I enable row level security', t);
  end loop;

  -- members read their clinic's rows
  foreach t in array array['tenant_members', 'doctors', 'locations', 'resources', 'schedules', 'schedule_exceptions', 'services',
                           'service_prices', 'offers', 'knowledge_entries', 'agent_rules', 'catalog_imports', 'catalog_changes',
                           'catalog_snapshot', 'whatsapp_channels', 'contacts', 'contact_identities', 'conversations', 'messages',
                           'outbox', 'team_questions', 'agent_pauses', 'pause_contacts', 'patients', 'patient_contacts',
                           'form_templates', 'appointments', 'appointment_events', 'waitlist', 'alerts', 'appointment_reminders',
                           'delay_notices', 'delay_notice_items'] loop
    execute format('create policy member_read on clinic.%I for select to authenticated
                      using (tenant_id = any ((select clinic.my_tenant_ids())::uuid[]))', t);
  end loop;

  -- the medical record: clinical members only
  foreach t in array array['encounters', 'conditions', 'allergies', 'medications', 'patient_history', 'vitals', 'documents',
                           'dental_chart', 'treatment_plans', 'treatment_plan_items'] loop
    execute format('create policy clinical_read on clinic.%I for select to authenticated
                      using (tenant_id = any ((select clinic.my_clinical_tenant_ids())::uuid[]))', t);
  end loop;

  -- owners, managers and doctors change the set-up and the catalogue
  foreach t in array array['doctors', 'locations', 'resources', 'schedules', 'schedule_exceptions', 'services', 'service_prices',
                           'offers', 'knowledge_entries', 'agent_rules', 'catalog_imports', 'form_templates'] loop
    execute format('create policy editor_write on clinic.%I for all to authenticated
                      using (tenant_id = any ((select clinic.my_editor_tenant_ids())::uuid[]))
                      with check (tenant_id = any ((select clinic.my_editor_tenant_ids())::uuid[]))', t);
  end loop;

  -- any member: the patient's tags and notes, a contact's note, the waitlist, a visit's front-desk note
  foreach t in array array['patients', 'contacts', 'waitlist', 'appointments'] loop
    execute format('create policy member_write on clinic.%I for update to authenticated
                      using (tenant_id = any ((select clinic.my_tenant_ids())::uuid[]))
                      with check (tenant_id = any ((select clinic.my_tenant_ids())::uuid[]))', t);
  end loop;
end $$;

create policy member_insert on clinic.waitlist for insert to authenticated
  with check (tenant_id = any ((select clinic.my_tenant_ids())::uuid[]));
create policy member_delete on clinic.waitlist for delete to authenticated
  using (tenant_id = any ((select clinic.my_tenant_ids())::uuid[]));

create policy member_read on clinic.tenants for select to authenticated
  using (id = any ((select clinic.my_tenant_ids())::uuid[]));
create policy editor_update on clinic.tenants for update to authenticated
  using (id = any ((select clinic.my_editor_tenant_ids())::uuid[]))
  with check (id = any ((select clinic.my_editor_tenant_ids())::uuid[]));
create policy self_read on clinic.platform_admins for select to authenticated using (user_id = clinic.current_user_id());
create policy owner_read on clinic.tenant_invites for select to authenticated using (clinic.member_role(tenant_id) = 'owner');
create policy anyone_read on clinic.specialty_presets for select to authenticated using (true);
alter table clinic.specialty_presets enable row level security;

-- telemetry, the audit trail and who opened which record: owners and managers
create policy owner_read on clinic.agent_events for select to authenticated
  using (clinic.member_role(tenant_id) in ('owner', 'manager'));
create policy owner_read on clinic.audit_log for select to authenticated
  using (clinic.member_role(tenant_id) in ('owner', 'manager'));
create policy owner_read on clinic.record_access_log for select to authenticated
  using (clinic.member_role(tenant_id) in ('owner', 'manager'));

-- ================= 010_engine_extras.sql =================

-- =====================================================================
-- Everwake Clinic · 010 · what the engine's other paths read
--
--   staff_context()      the doctor's (or the front desk's) own WhatsApp:
--                        who they are, today's sessions and visits, what
--                        is waiting for their yes, the catalogue
--   test_chat_prepare()  the Test Runner: a pretend patient chats with a
--   test_chat_result()   clinic's agent; nothing goes out on WhatsApp
-- =====================================================================

create or replace function clinic.staff_context(p_tenant uuid, p_wa text, p_staff jsonb)
returns jsonb language plpgsql as $$
declare
  t    clinic.tenants%rowtype;
  conv clinic.conversations%rowtype;
  v_doc uuid := nullif(p_staff ->> 'doctor_id', '')::uuid;
begin
  perform clinic.ensure_snapshot(p_tenant);
  select * into t from clinic.tenants where id = p_tenant;
  select * into conv from clinic.conversations where tenant_id = p_tenant and wa_id = p_wa;
  return jsonb_build_object(
    'tenant', jsonb_build_object('id', t.id, 'name_ar', t.name_ar, 'name_en', t.name_en, 'timezone', t.timezone,
                                 'currency_symbol', t.currency_symbol_ar),
    'staff', p_staff,
    'doctor', case when v_doc is not null then jsonb_build_object('id', v_doc, 'name', clinic.doctor_label(v_doc, 'ar'),
                                                                  'specialty', (select specialty from clinic.doctors where id = v_doc)) end,
    'state', coalesce(conv.state, '{}'::jsonb),
    'pending', conv.state -> 'staff_pending',
    'today', clinic.staff_tool(p_tenant, p_wa, p_staff, 'today', '{}'),
    'tomorrow', clinic.staff_tool(p_tenant, p_wa, p_staff, 'today',
                                  jsonb_build_object('date', clinic.local_today(p_tenant) + 1)::text),
    'delays_today', coalesce((select jsonb_agg(jsonb_build_object('doctor', clinic.doctor_label(dn.doctor_id, 'ar'), 'minutes', dn.minutes,
                                                                  'kind', dn.kind, 'counts', dn.counts, 'at', dn.sent_at,
                                                                  'tally', (select jsonb_object_agg(z.status, z.n) from (
                                                                              select i.status, count(*) n from clinic.delay_notice_items i
                                                                               where i.notice_id = dn.id group by i.status) z)))
                                from clinic.delay_notices dn where dn.tenant_id = p_tenant and dn.session_date = clinic.local_today(p_tenant)),
                              '[]'::jsonb),
    'doctors', coalesce((select jsonb_agg(jsonb_build_object('code', d.code, 'name', clinic.doctor_label(d.id, 'ar'), 'specialty', d.specialty) order by d.sort)
                           from clinic.doctors d where d.tenant_id = p_tenant and d.is_active), '[]'::jsonb),
    'locations', coalesce((select jsonb_agg(l.name_ar order by l.sort) from clinic.locations l where l.tenant_id = p_tenant and l.is_active), '[]'::jsonb),
    'open_alerts', (select count(*) from clinic.alerts where tenant_id = p_tenant and status = 'open'),
    'last_change', (select jsonb_build_object('id', c.id, 'summary', c.summary_ar, 'status', c.status, 'at', coalesce(c.applied_at, c.created_at))
                      from clinic.catalog_changes c where c.tenant_id = p_tenant and c.source = 'whatsapp' order by c.id desc limit 1),
    'catalog_digest', (select digest_text from clinic.catalog_snapshot where tenant_id = p_tenant),
    'recent_messages', coalesce((select jsonb_agg(jsonb_build_object('direction', m.direction, 'text', coalesce(m.meta ->> 'understood', m.body), 'at', m.created_at)
                                                  order by m.created_at)
                                   from (select * from clinic.messages where tenant_id = p_tenant and wa_id = p_wa and status not in ('failed', 'cancelled')
                                         order by created_at desc limit 12) m), '[]'::jsonb));
end $$;

create or replace function clinic.test_chat_prepare(p_clinic text, p_wa text, p_reset boolean default false,
                                                    p_later_hours numeric default 0)
returns jsonb language plpgsql as $$
declare
  t      clinic.tenants%rowtype;
  ch     clinic.whatsapp_channels%rowtype;
  v_co   bigint[];
  v_pat  bigint[];
  v_back interval := make_interval(secs => greatest(coalesce(p_later_hours, 0), 0) * 3600);
  n      int;
begin
  if not clinic.is_test_number(p_wa) then
    raise exception 'The test chat only uses the pretend numbers 200000000001 to 200000000099, not %', p_wa;
  end if;
  select count(*) into n from clinic.tenants
   where slug = lower(btrim(p_clinic)) or slug ilike btrim(p_clinic) || '%' or name_en ilike btrim(p_clinic) || '%' or name_ar = btrim(p_clinic);
  if n <> 1 then raise exception '% clinics match "%" — use the clinic''s exact slug', n, p_clinic; end if;
  select * into t from clinic.tenants
   where slug = lower(btrim(p_clinic)) or slug ilike btrim(p_clinic) || '%' or name_en ilike btrim(p_clinic) || '%' or name_ar = btrim(p_clinic);
  select * into ch from clinic.whatsapp_channels
   where tenant_id = t.id and provider = 'evolution' and is_active and instance_name is not null order by created_at limit 1;
  if ch.id is null then raise exception '% has no WhatsApp number connected yet (Settings → WhatsApp)', t.name_ar; end if;
  select coalesce(array_agg(id), '{}') into v_co from clinic.contacts where tenant_id = t.id and wa_id = p_wa;
  select coalesce(array_agg(patient_id), '{}') into v_pat from clinic.patient_contacts where contact_id = any (v_co);

  if p_reset then
    delete from clinic.appointments       where tenant_id = t.id and (wa_id = p_wa or contact_id = any (v_co));
    delete from clinic.booking_drafts     where tenant_id = t.id and wa_id = p_wa;
    delete from clinic.waitlist           where tenant_id = t.id and wa_id = p_wa;
    delete from clinic.alerts             where tenant_id = t.id and wa_id = p_wa;
    delete from clinic.outbox             where tenant_id = t.id and wa_id = p_wa;
    delete from clinic.messages           where tenant_id = t.id and wa_id = p_wa;
    delete from clinic.conversations      where tenant_id = t.id and wa_id = p_wa;
    delete from clinic.inbound_buffer     where tenant_id = t.id and wa_id = p_wa;
    delete from clinic.conversation_locks where tenant_id = t.id and wa_id = p_wa;
    delete from clinic.pause_contacts     where tenant_id = t.id and wa_id = p_wa;
    delete from clinic.agent_events       where tenant_id = t.id and wa_id = p_wa;
    delete from clinic.patients           where id = any (v_pat)
       and not exists (select 1 from clinic.patient_contacts pc where pc.patient_id = clinic.patients.id and not (pc.contact_id = any (v_co)));
    delete from clinic.contacts           where id = any (v_co);
  elsif v_back > interval '0' then
    update clinic.messages set created_at = created_at - v_back, sent_at = sent_at - v_back where tenant_id = t.id and wa_id = p_wa;
    update clinic.conversations
       set last_message_at = last_message_at - v_back, last_inbound_at = last_inbound_at - v_back,
           last_outbound_at = last_outbound_at - v_back, updated_at = updated_at - v_back
     where tenant_id = t.id and wa_id = p_wa;
    update clinic.booking_drafts set updated_at = updated_at - v_back where tenant_id = t.id and wa_id = p_wa;
    update clinic.agent_events set created_at = created_at - v_back where tenant_id = t.id and wa_id = p_wa;
  end if;
  return jsonb_build_object('tenant_id', t.id, 'clinic', t.name_ar, 'slug', t.slug, 'status', t.status,
                            'instance', ch.instance_name, 'token', ch.webhook_token, 'wa_id', p_wa,
                            'reset', coalesce(p_reset, false), 'later_hours', greatest(coalesce(p_later_hours, 0), 0), 'since', now(),
                            'last_message_at', (select max(created_at) from clinic.messages where tenant_id = t.id and wa_id = p_wa and direction = 'inbound'));
end $$;

create or replace function clinic.test_chat_result(p_tenant uuid, p_wa text, p_since timestamptz)
returns jsonb language plpgsql stable as $$
declare
  conv clinic.conversations%rowtype;
  ev   clinic.agent_events%rowtype;
begin
  if not clinic.is_test_number(p_wa) then raise exception 'not a test chat: %', p_wa; end if;
  select * into conv from clinic.conversations where tenant_id = p_tenant and wa_id = p_wa;
  select * into ev from clinic.agent_events
   where tenant_id = p_tenant and wa_id = p_wa and created_at >= p_since and stage in ('turn_complete', 'staff_turn')
   order by id desc limit 1;
  return jsonb_build_object(
    'patient', (select string_agg(body, E'\n' order by id) from clinic.messages
                 where tenant_id = p_tenant and wa_id = p_wa and direction = 'inbound' and created_at >= p_since),
    'replies', coalesce((select jsonb_agg(jsonb_build_object('kind', kind, 'text', body, 'sender', sender) order by id)
                           from clinic.messages where tenant_id = p_tenant and wa_id = p_wa and direction = 'outbound' and created_at >= p_since), '[]'),
    'turn', case when ev.id is null then null else jsonb_build_object(
              'stage', ev.booking_stage, 'seconds', round(ev.duration_total_ms / 1000.0, 1),
              'tokens', coalesce(ev.prompt_tokens, 0) + coalesce(ev.completion_tokens, 0),
              'plan', ev.output -> 'brain', 'tools', ev.output -> 'tools_used', 'calls', ev.output -> 'tool_calls',
              'caught', ev.output -> 'violations', 'rewritten', ev.repair_used, 'agent_error', ev.output ->> 'agent_error',
              'booked', ev.output ->> 'booked_ref', 'urgency', ev.output -> 'urgency', 'handoff', ev.output -> 'handoff',
              'ask_team', ev.output -> 'ask_team') end,
    'mode', conv.mode, 'urgency', conv.urgency,
    'draft', (select data - 'last_offered' from clinic.booking_drafts where tenant_id = p_tenant and wa_id = p_wa),
    'appointments', (select jsonb_agg(concat_ws(' ', a.ref_no, a.status, clinic.appt_when(a), clinic.doctor_label(a.doctor_id, 'ar')) order by a.id)
                       from clinic.appointments a where a.tenant_id = p_tenant and a.wa_id = p_wa and a.ref_no is not null));
end $$;

revoke execute on function clinic.staff_context(uuid, text, jsonb), clinic.is_test_number(text),
  clinic.test_chat_prepare(text, text, boolean, numeric), clinic.test_chat_result(uuid, text, timestamptz)
  from public, anon, authenticated;
grant execute on all functions in schema clinic to service_role;

-- ================= 011_dashboard_reads.sql =================

-- =====================================================================
-- Everwake Clinic · 011 · what the dashboard reads in one call
--
-- Small read functions the dashboard's pages use, so a page asks once and
-- gets names along with the ids (the patient behind an alert, the doctor of
-- a waitlist entry). Each checks the caller's role first.
-- =====================================================================

-- alerts with who they are about: the emergency banner, Today, the Alerts page
create or replace function clinic.alert_list(p_tenant uuid, p_status text default 'open', p_kind text default null, p_limit int default 50)
returns jsonb language plpgsql stable security definer set search_path = clinic, pg_temp as $$
begin
  perform clinic.require_role(p_tenant, array['owner', 'manager', 'doctor', 'nurse', 'receptionist']);
  return coalesce((select jsonb_agg(x order by (x ->> 'severity' = 'critical') desc, (x ->> 'created_at') desc) from (
    select to_jsonb(al) || jsonb_build_object(
             'who', coalesce(p.full_name, co.full_name, co.display_name),
             'phone', coalesce(co.phone, p.phone),
             'doctor', clinic.doctor_label(al.doctor_id, 'ar'),
             'appointment', (select clinic.appt_when(a) from clinic.appointments a where a.id = al.appointment_id)) as x
      from clinic.alerts al
      left join clinic.patients p on p.id = al.patient_id
      left join clinic.contacts co on co.id = al.contact_id
     where al.tenant_id = p_tenant
       and (p_status is null or p_status = 'all' or al.status = p_status)
       and (p_kind is null or al.kind = p_kind)
     order by al.created_at desc
     limit least(coalesce(p_limit, 50), 200)) q), '[]'::jsonb);
end $$;

grant execute on function clinic.alert_list(uuid, text, text, int) to authenticated;

-- the inbox: chats with who they are, the ones that need someone first
-- p_filter: 'attention' (an emergency, a question for the team, a taken-over chat with unread) · 'human' · 'all'
create or replace function clinic.inbox_list(p_tenant uuid, p_filter text default 'all', p_q text default null, p_limit int default 80)
returns jsonb language plpgsql stable security definer set search_path = clinic, pg_temp as $$
declare v_q text := clinic.norm(p_q); v_d text := clinic.digits(p_q);
begin
  perform clinic.require_role(p_tenant, array['owner', 'manager', 'doctor', 'nurse', 'receptionist']);
  return coalesce((select jsonb_agg(x) from (
    select jsonb_build_object(
             'id', c.id, 'wa_id', c.wa_id, 'mode', c.mode, 'needs_attention', c.needs_attention, 'attention_reason', c.attention_reason,
             'urgency', c.urgency, 'questions_open', c.questions_open, 'unread_count', c.unread_count, 'last_message_at', c.last_message_at,
             'last_message_preview', c.last_message_preview, 'human_since', c.human_since,
             'name', coalesce(co.full_name, co.display_name), 'phone', co.phone,
             'patients', (select jsonb_agg(jsonb_build_object('id', p.id, 'full_name', p.full_name, 'relation', pc.relation) order by pc.relation = 'self' desc)
                            from clinic.patient_contacts pc join clinic.patients p on p.id = pc.patient_id where pc.contact_id = co.id),
             'next', (select jsonb_build_object('id', a.id, 'starts_at', coalesce(a.est_at, a.starts_at))
                        from clinic.appointments a where a.tenant_id = c.tenant_id and a.wa_id = c.wa_id and a.status in ('booked', 'confirmed')
                         and a.ends_at > now() order by a.starts_at limit 1)) as x
      from clinic.conversations c left join clinic.contacts co on co.id = c.contact_id
     where c.tenant_id = p_tenant and c.kind = 'patient'
       and (coalesce(p_filter, 'all') = 'all'
            or (p_filter = 'attention' and (c.needs_attention or c.questions_open > 0 or c.urgency is not null or (c.mode = 'human' and c.unread_count > 0)))
            or (p_filter = 'human' and c.mode = 'human'))
       and (v_q = '' or clinic.norm(coalesce(co.full_name, co.display_name, '')) like '%' || v_q || '%'
            or (length(v_d) >= 4 and c.wa_id like '%' || v_d || '%'))
     order by (c.urgency = 'emergency') desc nulls last, (c.questions_open > 0 or c.needs_attention) desc, c.last_message_at desc nulls last
     limit least(coalesce(p_limit, 80), 200)) q), '[]'::jsonb);
end $$;

-- one chat: the messages, the questions the assistant asked the team, and who it is
create or replace function clinic.inbox_thread(p_conversation bigint, p_limit int default 120)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare c clinic.conversations%rowtype;
begin
  select * into c from clinic.conversations where id = p_conversation;
  if not found then raise exception 'conversation not found'; end if;
  perform clinic.require_role(c.tenant_id, array['owner', 'manager', 'doctor', 'nurse', 'receptionist']);
  update clinic.conversations set unread_count = 0 where id = c.id and unread_count > 0;
  return jsonb_build_object(
    'conversation', (select to_jsonb(c) - 'state' || jsonb_build_object('name', coalesce(co.full_name, co.display_name), 'phone', co.phone,
                                                                        'language', co.language, 'contact_id', co.id)
                       from (select 1) one left join clinic.contacts co on co.id = c.contact_id),
    'messages', coalesce((select jsonb_agg(to_jsonb(m) - 'raw_payload' order by m.created_at, m.id) from (
                  select * from clinic.messages where conversation_id = c.id order by created_at desc, id desc limit least(coalesce(p_limit, 120), 400)) m), '[]'::jsonb),
    'questions', coalesce((select jsonb_agg(to_jsonb(q) order by q.asked_at) from clinic.team_questions q
                            where q.conversation_id = c.id and (q.status = 'open' or q.answered_at > now() - interval '2 days')), '[]'::jsonb),
    'patients', coalesce((select jsonb_agg(jsonb_build_object('id', p.id, 'full_name', p.full_name, 'relation', pc.relation, 'file_no', p.file_no,
                                                              'age', clinic.age_text(p.birth_date, 'ar'), 'age_en', clinic.age_text(p.birth_date, 'en')))
                            from clinic.patient_contacts pc join clinic.patients p on p.id = pc.patient_id where pc.contact_id = c.contact_id), '[]'::jsonb),
    'appointments', coalesce((select jsonb_agg(clinic.appt_card(a, clinic.can_see_clinical(c.tenant_id)) order by a.starts_at)
                               from clinic.appointments a where a.tenant_id = c.tenant_id and a.wa_id = c.wa_id
                                and a.status in ('booked', 'confirmed', 'arrived', 'in_visit') and a.ends_at > now() - interval '2 hours'), '[]'::jsonb));
end $$;

grant execute on function clinic.inbox_list(uuid, text, text, int), clinic.inbox_thread(bigint, int) to authenticated;

-- the waitlist: who is waiting for an earlier time, with whom and when
create or replace function clinic.waitlist_list(p_tenant uuid, p_status text default 'open')
returns jsonb language plpgsql stable security definer set search_path = clinic, pg_temp as $$
begin
  perform clinic.require_role(p_tenant, array['owner', 'manager', 'doctor', 'nurse', 'receptionist']);
  return coalesce((select jsonb_agg(to_jsonb(w) || jsonb_build_object(
             'patient', p.full_name, 'phone', coalesce(p.phone, w.wa_id), 'doctor', clinic.doctor_label(w.doctor_id, 'ar'),
             'doctor_en', clinic.doctor_label(w.doctor_id, 'en'), 'location', clinic.location_label(w.location_id, 'ar'),
             'service', s.name_ar, 'service_en', s.name_en,
             'holds', (select jsonb_build_object('id', a.id, 'starts_at', coalesce(a.est_at, a.starts_at)) from clinic.appointments a where a.id = w.appointment_id))
           order by (w.status = 'offered') desc, w.created_at)
    from clinic.waitlist w left join clinic.patients p on p.id = w.patient_id left join clinic.services s on s.id = w.service_id
   where w.tenant_id = p_tenant and (p_status = 'all' or (p_status = 'open' and w.status in ('waiting', 'offered')) or w.status = p_status)), '[]'::jsonb);
end $$;

grant execute on function clinic.waitlist_list(uuid, text) to authenticated;

-- ---------------------------------------------------------------------
-- The patient's own page, from the link in every reminder (/a/<token>):
-- see the appointment, confirm it, pick another time, or cancel. No sign-in:
-- the token is the key. Called by the dashboard's server with the service
-- role only (never granted to anon).
-- ---------------------------------------------------------------------
create or replace function clinic.manage_view(p_token text, p_lang text default 'ar')
returns jsonb language plpgsql stable security definer set search_path = clinic, pg_temp as $$
declare
  a  clinic.appointments%rowtype;
  t  clinic.tenants%rowtype;
  l  clinic.locations%rowtype;
  st jsonb;
  v_lang text := case when p_lang = 'en' then 'en' else 'ar' end;
begin
  select * into a from clinic.appointments where manage_token = p_token and ref_no is not null;
  if not found then return jsonb_build_object('ok', false, 'error', 'NOT_FOUND'); end if;
  select * into t from clinic.tenants where id = a.tenant_id;
  select * into l from clinic.locations where id = a.location_id;
  st := clinic.merged_settings(t.settings);
  return jsonb_build_object('ok', true,
    'appointment', clinic.appointment_view(a, v_lang),
    'clinic', jsonb_build_object('name', case when v_lang = 'en' then t.name_en else t.name_ar end, 'brand', clinic.merged_profile(t.profile) -> 'brand',
                                 'phone', clinic.merged_profile(t.profile) -> 'contacts' ->> 'phone', 'timezone', t.timezone),
    'place', jsonb_build_object('name', case when v_lang = 'en' then coalesce(l.name_en, l.name_ar) else l.name_ar end,
                                'address', case when v_lang = 'en' then coalesce(l.address_en, l.address_ar) else l.address_ar end,
                                'directions', l.directions_ar, 'maps_url', coalesce(l.maps_url, case when l.lat is not null then format('https://maps.google.com/?q=%s,%s', l.lat, l.lng) end),
                                'phone', l.phone),
    'first_name', clinic.first_name((select full_name from clinic.patients where id = a.patient_id), null),
    'can_change', a.status in ('booked', 'confirmed') and coalesce(a.est_at, a.starts_at) > now()
                  and (coalesce((st -> 'booking' ->> 'cancel_hours')::int, 0) = 0
                       or coalesce(a.est_at, a.starts_at) > now() + make_interval(hours => (st -> 'booking' ->> 'cancel_hours')::int)),
    'cancel_hours', coalesce((st -> 'booking' ->> 'cancel_hours')::int, 0));
end $$;

create or replace function clinic.manage_slots(p_token text, p_from date default null)
returns jsonb language plpgsql stable security definer set search_path = clinic, pg_temp as $$
declare a clinic.appointments%rowtype;
begin
  select * into a from clinic.appointments where manage_token = p_token and ref_no is not null and status in ('booked', 'confirmed');
  if not found then return jsonb_build_object('slots', '[]'::jsonb); end if;
  return clinic.available_slots(a.tenant_id, jsonb_build_object('doctor_id', a.doctor_id, 'service_id', a.service_id, 'patient_id', a.patient_id,
           'from', p_from, 'limit', 120, 'ignore_appointment', a.id));
end $$;

-- p_action: confirm · cancel {reason} · move {starts_at | date, kind, location_id}
create or replace function clinic.manage_action(p_token text, p_action text, p jsonb default '{}'::jsonb)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare
  a clinic.appointments%rowtype;
  v jsonb;
  r jsonb;
begin
  select * into a from clinic.appointments where manage_token = p_token and ref_no is not null for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'NOT_FOUND'); end if;
  v := clinic.manage_view(p_token);
  if not (v ->> 'can_change')::boolean then return jsonb_build_object('ok', false, 'error', 'TOO_LATE_TO_CHANGE'); end if;
  if p_action = 'confirm' then
    update clinic.appointments set status = 'confirmed', confirmed_at = coalesce(confirmed_at, now()) where id = a.id;
    update clinic.delay_notice_items set status = 'accepted', replied_at = coalesce(replied_at, now()) where appointment_id = a.id and status = 'sent';
    perform clinic.log_appt(a.id, 'confirmed', jsonb_build_object('via', 'link'), 'patient');
    return jsonb_build_object('ok', true, 'status', 'CONFIRMED');
  elsif p_action = 'cancel' then
    r := clinic.cancel_appointment(a.id, 'patient', coalesce(nullif(p ->> 'reason', ''), 'from the link'), false);
    if (r ->> 'ok')::boolean then
      perform clinic.raise_alert(jsonb_build_object('tenant_id', a.tenant_id, 'kind', 'cancelled', 'severity', 'low', 'appointment_id', a.id,
        'title', 'مريض لغى من الرابط', 'body', clinic.appt_when(a), 'notify_doctor', false));
    end if;
    return r;
  elsif p_action = 'move' then
    r := clinic.reschedule_appointment(a.id, jsonb_build_object('starts_at', p ->> 'starts_at', 'date', p ->> 'date', 'kind', p ->> 'kind',
           'location_id', p ->> 'location_id', 'staff', false, 'notify', false, 'by_role', 'patient'));
    return r;
  end if;
  return jsonb_build_object('ok', false, 'error', 'UNKNOWN_ACTION');
end $$;

revoke all on function clinic.manage_view(text, text), clinic.manage_slots(text, date), clinic.manage_action(text, text, jsonb) from public;
grant execute on function clinic.manage_view(text, text), clinic.manage_slots(text, date), clinic.manage_action(text, text, jsonb) to service_role;

-- ================= 012_doctor_ai.sql =================

-- =====================================================================
-- Everwake Clinic · 012 · the doctor's AI (stage 2)
--
--   recordings          "listen to the visit": consent first, then the
--                       audio in 20-second chunks, the live transcript,
--                       and the diarised one (doctor · patient)
--   scribe_runs         what the AI filled in, with a quote from the
--                       transcript behind every field, and what the check
--                       found unsupported (left empty and flagged)
--   assistant_threads   the doctor's chats with their assistant
--   assistant_messages
--   assistant_actions   every change the assistant proposed, shown as a
--                       card to confirm, and what happened to it
--
-- Signing a visit writes the encounter and, only for what the doctor
-- ticked, the record (allergies, medicines, conditions), the teeth and the
-- treatment plan. Audio is deleted after settings.scribe.audio_days
-- (default 30); the transcript stays with the visit.
-- =====================================================================

set local client_min_messages = warning;

create table if not exists clinic.recordings (
  id                 bigint generated always as identity primary key,
  tenant_id          uuid not null references clinic.tenants(id) on delete cascade,
  patient_id         bigint references clinic.patients(id) on delete cascade,
  appointment_id     bigint references clinic.appointments(id) on delete set null,
  encounter_id       bigint references clinic.encounters(id) on delete set null,
  doctor_id          uuid references clinic.doctors(id) on delete set null,
  consent_at         timestamptz not null,
  consent_by         uuid,
  consent_text       text not null,
  status             text not null default 'recording'
                     check (status in ('recording', 'processing', 'review', 'signed', 'failed', 'discarded')),
  chunks             jsonb not null default '[]'::jsonb,      -- [{seq, path, ms, text}]
  duration_ms        int not null default 0,
  transcript         jsonb not null default '{"segments": []}'::jsonb,  -- {segments:[{id, speaker, start, end, text}]}
  diarized           boolean not null default false,
  language           text,
  audio_delete_after timestamptz,
  audio_deleted_at   timestamptz,
  error              text,
  created_by         uuid,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);
create index if not exists recordings_appt_idx on clinic.recordings (appointment_id);
create index if not exists recordings_purge_idx on clinic.recordings (audio_delete_after) where audio_deleted_at is null;

create table if not exists clinic.scribe_runs (
  id           bigint generated always as identity primary key,
  tenant_id    uuid not null references clinic.tenants(id) on delete cascade,
  recording_id bigint not null references clinic.recordings(id) on delete cascade,
  models       jsonb not null default '{}'::jsonb,
  extraction   jsonb not null default '{}'::jsonb,   -- {fields:{"section.field":{value, quote, segment_ids, confidence, speaker}}, record:{...}, teeth:[...], plan:{...}}
  verification jsonb not null default '{}'::jsonb,   -- {supported:[], unsupported:[], flags:[{field, why}]}
  outputs      jsonb not null default '{}'::jsonb,   -- {soap, summary_ar, prescription, letters}
  usage        jsonb,
  created_by   uuid,
  created_at   timestamptz not null default now()
);
create index if not exists scribe_runs_rec_idx on clinic.scribe_runs (recording_id, created_at desc);

create table if not exists clinic.assistant_threads (
  id         bigint generated always as identity primary key,
  tenant_id  uuid not null references clinic.tenants(id) on delete cascade,
  user_id    uuid not null,
  title      text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists assistant_threads_user_idx on clinic.assistant_threads (tenant_id, user_id, updated_at desc);

create table if not exists clinic.assistant_messages (
  id         bigint generated always as identity primary key,
  tenant_id  uuid not null references clinic.tenants(id) on delete cascade,
  thread_id  bigint not null references clinic.assistant_threads(id) on delete cascade,
  user_id    uuid not null,
  role       text not null check (role in ('user', 'assistant')),
  content    text not null default '',
  parts      jsonb not null default '[]'::jsonb,     -- chips, tool steps, action card ids
  context    jsonb not null default '{}'::jsonb,     -- the page it was asked on
  created_at timestamptz not null default now()
);
create index if not exists assistant_messages_thread_idx on clinic.assistant_messages (thread_id, id);

create table if not exists clinic.assistant_actions (
  id         bigint generated always as identity primary key,
  tenant_id  uuid not null references clinic.tenants(id) on delete cascade,
  thread_id  bigint references clinic.assistant_threads(id) on delete cascade,
  user_id    uuid not null,
  tool       text not null,
  params     jsonb not null default '{}'::jsonb,
  preview    jsonb not null default '{}'::jsonb,
  summary    text,
  status     text not null default 'proposed' check (status in ('proposed', 'done', 'failed', 'dismissed')),
  result     jsonb,
  created_at timestamptz not null default now(),
  decided_at timestamptz
);
create index if not exists assistant_actions_user_idx on clinic.assistant_actions (tenant_id, user_id, created_at desc);

do $$ declare t text; begin
  foreach t in array array['recordings', 'assistant_threads'] loop
    execute format('drop trigger if exists touch on clinic.%I', t);
    execute format('create trigger touch before update on clinic.%I for each row execute function clinic.touch_updated_at()', t);
  end loop;
end $$;

-- ---------------------------------------------------------------------
-- Listening to the visit
-- ---------------------------------------------------------------------
-- p = {consent: true, consent_text?}
create or replace function clinic.recording_start(p_appt bigint, p jsonb default '{}'::jsonb)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare
  a   clinic.appointments%rowtype;
  st  jsonb;
  r   clinic.recordings%rowtype;
begin
  select * into a from clinic.appointments where id = p_appt;
  if not found then raise exception 'appointment not found'; end if;
  perform clinic.require_role(a.tenant_id, array['owner', 'manager', 'doctor', 'nurse']);
  perform clinic.require_clinical(a.tenant_id);
  if not coalesce((p ->> 'consent')::boolean, false) then
    return jsonb_build_object('ok', false, 'error', 'CONSENT_NEEDED');
  end if;
  select clinic.merged_settings(settings) into st from clinic.tenants where id = a.tenant_id;
  insert into clinic.recordings (tenant_id, patient_id, appointment_id, doctor_id, consent_at, consent_by, consent_text,
                                 audio_delete_after, created_by)
  values (a.tenant_id, a.patient_id, a.id, a.doctor_id, now(), clinic.current_user_id(),
          coalesce(nullif(p ->> 'consent_text', ''), 'The patient agreed to the visit being recorded for the medical record.'),
          now() + make_interval(days => coalesce((st -> 'scribe' ->> 'audio_days')::int, 30)), clinic.current_user_id())
  returning * into r;
  if a.status in ('booked', 'confirmed', 'arrived') then
    perform clinic.set_appointment_status(a.id, 'in_visit', null, false);
  end if;
  return jsonb_build_object('ok', true, 'id', r.id, 'tenant_id', r.tenant_id, 'patient_id', r.patient_id);
end $$;

-- one chunk: where its audio is, how long it is, what it said
create or replace function clinic.recording_chunk(p_rec bigint, p jsonb)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare r clinic.recordings%rowtype; v_seq int := (p ->> 'seq')::int;
begin
  select * into r from clinic.recordings where id = p_rec for update;
  if not found then raise exception 'recording not found'; end if;
  perform clinic.require_clinical(r.tenant_id);
  if r.status not in ('recording', 'processing') then return jsonb_build_object('ok', false, 'error', 'RECORDING_CLOSED'); end if;
  update clinic.recordings
     set chunks = (select coalesce(jsonb_agg(c order by (c ->> 'seq')::int), '[]'::jsonb)
                     from (select c from jsonb_array_elements(chunks) c where (c ->> 'seq')::int <> v_seq
                           union all select jsonb_build_object('seq', v_seq, 'path', p ->> 'path', 'ms', coalesce((p ->> 'ms')::int, 0),
                                                               'text', coalesce(p ->> 'text', ''), 'at', now())) z(c)),
         duration_ms = (select coalesce(sum((c ->> 'ms')::int), 0) from jsonb_array_elements(chunks) c where (c ->> 'seq')::int <> v_seq)
                       + coalesce((p ->> 'ms')::int, 0)
   where id = r.id;
  return jsonb_build_object('ok', true);
end $$;

-- the whole transcript, once the doctor stops (diarised, or the chunks joined)
create or replace function clinic.recording_transcript(p_rec bigint, p jsonb)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare r clinic.recordings%rowtype;
begin
  select * into r from clinic.recordings where id = p_rec for update;
  if not found then raise exception 'recording not found'; end if;
  perform clinic.require_clinical(r.tenant_id);
  update clinic.recordings
     set transcript = jsonb_build_object('segments', coalesce(p -> 'segments', '[]'::jsonb)),
         diarized = coalesce((p ->> 'diarized')::boolean, false), language = nullif(p ->> 'language', ''),
         status = case when status = 'recording' then 'processing' else status end
   where id = r.id;
  return jsonb_build_object('ok', true);
end $$;

-- what the AI filled in and what the check found
create or replace function clinic.scribe_save(p_rec bigint, p jsonb)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare r clinic.recordings%rowtype; v_id bigint;
begin
  select * into r from clinic.recordings where id = p_rec for update;
  if not found then raise exception 'recording not found'; end if;
  perform clinic.require_clinical(r.tenant_id);
  insert into clinic.scribe_runs (tenant_id, recording_id, models, extraction, verification, outputs, usage, created_by)
  values (r.tenant_id, r.id, coalesce(p -> 'models', '{}'::jsonb), coalesce(p -> 'extraction', '{}'::jsonb),
          coalesce(p -> 'verification', '{}'::jsonb), coalesce(p -> 'outputs', '{}'::jsonb), p -> 'usage', clinic.current_user_id())
  returning id into v_id;
  update clinic.recordings set status = case when status in ('recording', 'processing', 'failed') then 'review' else status end, error = null where id = r.id;
  return jsonb_build_object('ok', true, 'run_id', v_id);
end $$;

create or replace function clinic.recording_failed(p_rec bigint, p_error text)
returns void language plpgsql security definer set search_path = clinic, pg_temp as $$
declare r clinic.recordings%rowtype;
begin
  select * into r from clinic.recordings where id = p_rec;
  perform clinic.require_clinical(r.tenant_id);
  update clinic.recordings set status = 'failed', error = left(p_error, 500) where id = p_rec and status <> 'signed';
end $$;

-- everything the visit workspace needs for one appointment
create or replace function clinic.visit_context(p_appt bigint)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare a clinic.appointments%rowtype; v_tpl jsonb; v_spec text;
begin
  select * into a from clinic.appointments where id = p_appt;
  if not found then raise exception 'appointment not found'; end if;
  perform clinic.require_role(a.tenant_id, array['owner', 'manager', 'doctor', 'nurse']);
  perform clinic.require_clinical(a.tenant_id);
  select specialty into v_spec from clinic.doctors where id = a.doctor_id;
  select jsonb_build_object('id', f.id, 'name', f.name, 'specialty', f.specialty, 'schema', f.schema) into v_tpl
    from clinic.form_templates f where f.tenant_id = a.tenant_id
   order by (f.specialty = v_spec) desc, f.created_at limit 1;
  return jsonb_build_object(
    'appointment', clinic.appt_card(a, true),
    'doctor', jsonb_build_object('id', a.doctor_id, 'name', clinic.doctor_label(a.doctor_id, 'ar'), 'name_en', clinic.doctor_label(a.doctor_id, 'en'), 'specialty', v_spec),
    'template', v_tpl,
    'patient', (select to_jsonb(p) - 'tenant_id' || jsonb_build_object('age', clinic.age_text(p.birth_date, 'ar'), 'age_en', clinic.age_text(p.birth_date, 'en'))
                  from clinic.patients p where p.id = a.patient_id),
    'record', jsonb_build_object(
      'allergies', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'substance', x.substance, 'reaction', x.reaction)) from clinic.allergies x where x.patient_id = a.patient_id and x.status = 'active'), '[]'::jsonb),
      'medications', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'name', x.name, 'dose', x.dose)) from clinic.medications x where x.patient_id = a.patient_id and x.status = 'active'), '[]'::jsonb),
      'conditions', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'name', x.name)) from clinic.conditions x where x.patient_id = a.patient_id and x.status <> 'resolved'), '[]'::jsonb),
      'teeth', coalesce((select jsonb_agg(to_jsonb(x) order by x.tooth) from clinic.dental_chart x where x.patient_id = a.patient_id), '[]'::jsonb)),
    'recording', (select to_jsonb(r) - 'tenant_id' from clinic.recordings r where r.appointment_id = a.id and r.status <> 'discarded' order by r.id desc limit 1),
    'run', (select to_jsonb(s) - 'tenant_id' from clinic.scribe_runs s join clinic.recordings r on r.id = s.recording_id
             where r.appointment_id = a.id and r.status <> 'discarded' order by s.id desc limit 1),
    'encounter', (select to_jsonb(e) from clinic.encounters e where e.appointment_id = a.id order by e.id desc limit 1),
    'terms', clinic.doctor_terms(a.tenant_id, a.doctor_id));
end $$;

-- the words this doctor says often (medicines, diagnoses), so the transcription spells them right
create or replace function clinic.doctor_terms(p_tenant uuid, p_doctor uuid)
returns jsonb language sql stable security definer set search_path = clinic, pg_temp as $$
  select coalesce(jsonb_agg(w), '[]'::jsonb) from (
    select w from (
      select m.name as w, count(*) n from clinic.medications m where m.tenant_id = p_tenant group by m.name
      union all
      select d ->> 'name', count(*) from clinic.encounters e, jsonb_array_elements(e.diagnoses) d
       where e.tenant_id = p_tenant and (p_doctor is null or e.doctor_id = p_doctor) group by d ->> 'name'
      union all
      select s.name_ar, 1 from clinic.services s where s.tenant_id = p_tenant and s.is_active
    ) z where w is not null group by w order by sum(n) desc limit 60) q
$$;

-- Signing. p = {template_id, chief_complaint, data, sources, assessment, plan, diagnoses, follow_up_date,
--              add:{allergies:[{substance, reaction}], medications:[{name, dose, frequency}], conditions:[{name}]},
--              teeth:[{tooth, condition, planned, surfaces}], treatment:{title, items:[{tooth, service_id, label, price, sessions}]}}
create or replace function clinic.scribe_sign(p_rec bigint, p jsonb)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare
  r      clinic.recordings%rowtype;
  v_enc  jsonb;
  x      jsonb;
  n      int := 0;
  v_plan jsonb;
begin
  select * into r from clinic.recordings where id = p_rec for update;
  if not found then raise exception 'recording not found'; end if;
  perform clinic.require_role(r.tenant_id, array['owner', 'manager', 'doctor', 'nurse']);
  perform clinic.require_clinical(r.tenant_id);
  if r.status = 'signed' then return jsonb_build_object('ok', false, 'error', 'ALREADY_SIGNED', 'encounter_id', r.encounter_id); end if;

  v_enc := clinic.save_encounter(r.patient_id, jsonb_strip_nulls(jsonb_build_object(
             'id', (select id from clinic.encounters where appointment_id = r.appointment_id and status = 'draft' order by id desc limit 1),
             'appointment_id', r.appointment_id, 'doctor_id', r.doctor_id, 'template_id', p ->> 'template_id',
             'chief_complaint', p ->> 'chief_complaint', 'data', coalesce(p -> 'data', '{}'::jsonb),
             'sources', coalesce(p -> 'sources', '{}'::jsonb) || jsonb_build_object('recording_id', r.id),
             'assessment', p ->> 'assessment', 'plan', p ->> 'plan', 'diagnoses', p -> 'diagnoses',
             'follow_up_date', p ->> 'follow_up_date', 'sign', true)));

  for x in select * from jsonb_array_elements(coalesce(p -> 'add' -> 'allergies', '[]'::jsonb)) loop
    perform clinic.save_record(r.patient_id, 'allergies', jsonb_build_object('substance', x ->> 'substance', 'reaction', x ->> 'reaction',
              'source', 'scribe', 'encounter_id', (v_enc -> 'encounter' ->> 'id')::bigint)); n := n + 1;
  end loop;
  for x in select * from jsonb_array_elements(coalesce(p -> 'add' -> 'medications', '[]'::jsonb)) loop
    perform clinic.save_record(r.patient_id, 'medications', jsonb_build_object('name', x ->> 'name', 'dose', x ->> 'dose', 'frequency', x ->> 'frequency',
              'duration', x ->> 'duration', 'prescribed_here', coalesce((x ->> 'prescribed_here')::boolean, false), 'source', 'scribe',
              'encounter_id', (v_enc -> 'encounter' ->> 'id')::bigint)); n := n + 1;
  end loop;
  for x in select * from jsonb_array_elements(coalesce(p -> 'add' -> 'conditions', '[]'::jsonb)) loop
    perform clinic.save_record(r.patient_id, 'conditions', jsonb_build_object('name', x ->> 'name', 'source', 'scribe',
              'encounter_id', (v_enc -> 'encounter' ->> 'id')::bigint)); n := n + 1;
  end loop;
  if jsonb_typeof(p -> 'teeth') = 'array' and jsonb_array_length(p -> 'teeth') > 0 then
    perform clinic.set_teeth(r.patient_id, p -> 'teeth');
  end if;
  if jsonb_typeof(p -> 'treatment') = 'object' and jsonb_array_length(coalesce(p -> 'treatment' -> 'items', '[]'::jsonb)) > 0 then
    v_plan := clinic.save_plan(r.patient_id, (p -> 'treatment') || jsonb_build_object('doctor_id', r.doctor_id));
  end if;

  update clinic.recordings set status = 'signed', encounter_id = (v_enc -> 'encounter' ->> 'id')::bigint where id = r.id;
  return jsonb_build_object('ok', true, 'encounter_id', (v_enc -> 'encounter' ->> 'id')::bigint, 'records_added', n, 'plan_id', v_plan ->> 'id');
end $$;

-- after the visit: the patient's summary on WhatsApp, in the doctor's (edited) words
create or replace function clinic.visit_summary_send(p_appt bigint, p_text text)
returns jsonb language plpgsql security definer set search_path = clinic, pg_temp as $$
declare a clinic.appointments%rowtype; v_wa text;
begin
  select * into a from clinic.appointments where id = p_appt;
  if not found then raise exception 'appointment not found'; end if;
  perform clinic.require_role(a.tenant_id, array['owner', 'manager', 'doctor', 'nurse']);
  if coalesce(btrim(p_text), '') = '' then return jsonb_build_object('ok', false, 'error', 'EMPTY'); end if;
  v_wa := coalesce(a.wa_id, (select c.wa_id from clinic.patient_contacts pc join clinic.contacts c on c.id = pc.contact_id
                              where pc.patient_id = a.patient_id order by (pc.relation = 'self') desc limit 1));
  if v_wa is null then return jsonb_build_object('ok', false, 'error', 'NO_WHATSAPP'); end if;
  perform clinic.queue_message(a.tenant_id, v_wa, 'visit_summary', btrim(p_text), p_sender => 'staff', p_user => clinic.current_user_id(),
                               p_template => 'visit_summary', p_meta => jsonb_build_object('appointment_id', a.id));
  perform clinic.log_appt(a.id, 'summary_sent', '{}'::jsonb);
  return jsonb_build_object('ok', true, 'sent_to', v_wa);
end $$;

-- audio past its days: the dashboard's server deletes the files, then marks them
create or replace function clinic.recordings_to_purge(p_limit int default 200)
returns jsonb language sql stable security definer set search_path = clinic, pg_temp as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'paths', (select jsonb_agg(c ->> 'path') from jsonb_array_elements(r.chunks) c where c ->> 'path' is not null))), '[]'::jsonb)
    from (select * from clinic.recordings where audio_deleted_at is null and audio_delete_after < now() order by audio_delete_after limit p_limit) r
$$;
create or replace function clinic.recordings_purged(p_ids bigint[])
returns int language sql security definer set search_path = clinic, pg_temp as $$
  with u as (update clinic.recordings set audio_deleted_at = now(), chunks = (select coalesce(jsonb_agg(c - 'path'), '[]'::jsonb) from jsonb_array_elements(chunks) c)
              where id = any(p_ids) and audio_deleted_at is null returning 1)
  select count(*)::int from u
$$;

-- ---------------------------------------------------------------------
-- The assistant
-- ---------------------------------------------------------------------
-- the clinic's numbers for a period, for "how was this week?"
create or replace function clinic.assistant_stats(p_tenant uuid, p_from date, p_to date)
returns jsonb language plpgsql stable security definer set search_path = clinic, pg_temp as $$
begin
  perform clinic.require_role(p_tenant, array['owner', 'manager', 'doctor', 'nurse', 'receptionist']);
  if p_to < p_from or p_to - p_from > 370 then raise exception 'pick up to a year'; end if;
  return (select jsonb_build_object(
    'from', p_from, 'to', p_to,
    'bookings', count(*) filter (where a.status <> 'held'),
    'done', count(*) filter (where a.status = 'done'),
    'no_show', count(*) filter (where a.status = 'no_show'),
    'cancelled', count(*) filter (where a.status = 'cancelled'),
    'new_patients', count(*) filter (where a.is_new_patient and a.status not in ('cancelled', 'held')),
    'by_source', (select jsonb_object_agg(s, n) from (select x.source s, count(*) n from clinic.appointments x
                    where x.tenant_id = p_tenant and x.session_date between p_from and p_to and x.status not in ('held', 'cancelled') group by x.source) z),
    'by_doctor', (select jsonb_object_agg(clinic.doctor_label(d, 'ar'), n) from (select x.doctor_id d, count(*) n from clinic.appointments x
                    where x.tenant_id = p_tenant and x.session_date between p_from and p_to and x.status = 'done' group by x.doctor_id) z),
    'collected', coalesce(sum(a.price) filter (where a.status = 'done'), 0),
    'delays', (select count(*) from clinic.delay_notices dn where dn.tenant_id = p_tenant and dn.session_date between p_from and p_to and dn.kind = 'delay'))
    from clinic.appointments a where a.tenant_id = p_tenant and a.session_date between p_from and p_to);
end $$;

-- ---------------------------------------------------------------------
-- Pre-visit questions: the speciality's few, minus what is already known
-- ---------------------------------------------------------------------
create or replace function clinic.pre_visit_pending(p_appt bigint)
returns jsonb language plpgsql stable security definer set search_path = clinic, pg_temp as $$
declare a clinic.appointments%rowtype; v_spec text; v_sex text; v_out jsonb := '[]'::jsonb; q jsonb;
begin
  select * into a from clinic.appointments where id = p_appt;
  if not found then return '[]'::jsonb; end if;
  select specialty into v_spec from clinic.doctors where id = a.doctor_id;
  select sex into v_sex from clinic.patients where id = a.patient_id;
  for q in select * from jsonb_array_elements(coalesce((select pre_visit from clinic.specialty_presets where code = v_spec),
                                                       (select pre_visit from clinic.specialty_presets where code = 'general'), '[]'::jsonb)) loop
    continue when a.pre_visit ? (q ->> 'ask_ar');
    continue when q ->> 'sex' = 'female' and v_sex is distinct from 'female';
    continue when q ->> 'on_file' = 'allergies' and exists (select 1 from clinic.allergies x where x.patient_id = a.patient_id);
    continue when q ->> 'on_file' = 'medications' and exists (select 1 from clinic.medications x where x.patient_id = a.patient_id);
    continue when q ->> 'on_file' = 'conditions' and exists (select 1 from clinic.conditions x where x.patient_id = a.patient_id);
    v_out := v_out || jsonb_build_object('key', q ->> 'key', 'ask_ar', q ->> 'ask_ar', 'ask_en', q ->> 'ask_en');
  end loop;
  return v_out;
end $$;

-- ---------------------------------------------------------------------
-- Security
-- ---------------------------------------------------------------------
alter table clinic.recordings enable row level security;
alter table clinic.scribe_runs enable row level security;
alter table clinic.assistant_threads enable row level security;
alter table clinic.assistant_messages enable row level security;
alter table clinic.assistant_actions enable row level security;

drop policy if exists clinical_read on clinic.recordings;
create policy clinical_read on clinic.recordings for select to authenticated
  using (tenant_id = any ((select clinic.my_clinical_tenant_ids())::uuid[]));
drop policy if exists clinical_read on clinic.scribe_runs;
create policy clinical_read on clinic.scribe_runs for select to authenticated
  using (tenant_id = any ((select clinic.my_clinical_tenant_ids())::uuid[]));
do $$ declare t text; begin
  foreach t in array array['assistant_threads', 'assistant_messages', 'assistant_actions'] loop
    execute format('drop policy if exists own_rows on clinic.%I', t);
    execute format('create policy own_rows on clinic.%I for all to authenticated
                      using (user_id = clinic.current_user_id() and tenant_id = any ((select clinic.my_tenant_ids())::uuid[]))
                      with check (user_id = clinic.current_user_id() and tenant_id = any ((select clinic.my_tenant_ids())::uuid[]))', t);
  end loop;
end $$;

grant select on clinic.recordings, clinic.scribe_runs to authenticated;
grant select, insert, update on clinic.assistant_threads, clinic.assistant_messages, clinic.assistant_actions to authenticated;
grant all on clinic.recordings, clinic.scribe_runs, clinic.assistant_threads, clinic.assistant_messages, clinic.assistant_actions to service_role;
grant execute on function
  clinic.recording_start(bigint, jsonb), clinic.recording_chunk(bigint, jsonb), clinic.recording_transcript(bigint, jsonb),
  clinic.scribe_save(bigint, jsonb), clinic.recording_failed(bigint, text), clinic.visit_context(bigint), clinic.doctor_terms(uuid, uuid),
  clinic.scribe_sign(bigint, jsonb), clinic.visit_summary_send(bigint, text), clinic.assistant_stats(uuid, date, date),
  clinic.pre_visit_pending(bigint)
  to authenticated;
revoke all on function clinic.recordings_to_purge(int), clinic.recordings_purged(bigint[]) from public;
grant execute on function clinic.recordings_to_purge(int), clinic.recordings_purged(bigint[]) to service_role;

